#[derive(Debug, Clone)]
pub struct SemanticResult {
    pub ok: bool,
    pub warnings: Vec<String>,
    pub phase_timings: Vec<SemanticPhaseTiming>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SemanticPhaseTiming {
    pub phase: &'static str,
    pub elapsed_us: u128,
}

pub fn analyze_canonical(
    program: &Program,
) -> Result<SemanticResult, ncc_diagnostics::CanonicalDiagnostic> {
    analyze(program).map_err(|message| {
        ncc_diagnostics::CanonicalDiagnostic::from_legacy(&message, "sema", 0, 0)
    })
}

#[cfg(test)]
mod material_v2_manual_abi_tests {
    use super::*;

    #[test]
    fn validates_manual_abi_and_symbol_binding() {
        let source = r#"
sample :: program {
    host :: abi {
        target <- "x86_64-pc-windows-msvc";
        pointer.bits <- 64;
        stack.align <- 16;
        stack.shadow <- 32;
        stack.redzone <- 0;
        args.int <- [rcx, rdx, r8, r9];
        args.float <- [xmm0, xmm1, xmm2, xmm3];
        returns.int <- [rax];
        returns.float <- [xmm0];
        preserve <- [rbx, rbp, rdi, rsi, r12, r13, r14, r15];
        clobber <- [rax, rcx, rdx, r8, r9, r10, r11];
        sret <- rcx;
    }
    run :: in() -> bool { return true; }
    bind runtime.main <- run using host;
    ref main ->> run;
}
"#;
        let program =
            ncc_parser::parse(ncc_lexer::lex(source).expect("lex")).expect("parse material v2 ABI");
        analyze(&program).expect("manual ABI must pass sema");
    }
}

#[cfg(test)]
mod source_execution_contract_sema_tests {
    use super::*;

    fn parse_source(source: &str) -> Program {
        let tokens = ncc_lexer::lex(source).expect("source contract fixture must lex");
        ncc_parser::parse(tokens).expect("source contract fixture must parse")
    }

    fn analyze_source(source: &str) -> Result<SemanticResult, String> {
        let program = parse_source(source);
        analyze(&program)
    }

    fn uninitialized_free_source(package: &str) -> String {
        format!(
            r#"
{package}
use memory.heap.manager;

rawPointerContract[@] {{
    stc:
        address: addr;

    fn:
        run() -> bool {{
            public:
                memory.heap.manager.free(@address);
                return true;
        }}

    ref main ->> @fn(run);

    fa:
        return true;
}}
"#
        )
    }

    #[test]
    fn manual_raw_default_permits_uninitialized_pointer_operations() {
        analyze_source(&uninitialized_free_source(""))
            .expect("manual/raw must preserve C-like unchecked pointer behavior");
    }

    #[test]
    fn arbitrary_package_profile_keeps_manual_raw_pointer_behavior() {
        analyze_source(&uninitialized_free_source(
            "package checked { profile: vendor_debug; }",
        ))
        .expect("package profiles must not enable hidden pointer checks");
    }

    #[test]
    fn canonical_raw_pointer_hazards_compile_without_authority_sections() {
        let sources = [
            r#"
rawNull {
    fn:
        run() -> bool {
            public:
                p >> p<int> = null;
                value >> int = pRead(p);
                return value == value;
        }
    ref main ->> @fn(run);
    fa:
        return true;
}
"#,
            r#"
rawMisalignedAlias {
    fn:
        run() -> bool {
            public:
                address >> addr = 0x1003;
                wide !> p<qword> : address;
                narrow !> p<byte> : wide;
                pWrite(narrow, 1);
                return true;
        }
    ref main ->> @fn(run);
    fa:
        return true;
}
"#,
            r#"
rawLifetime {
    fn:
        run() -> bool {
            public:
                owner !> p<byte> : alloc(8);
                alias >> p<byte> = owner;
                free(owner);
                free(owner);
                pWrite(alias, 7);
                stale >> byte = pRead(alias);
                return stale == stale;
        }
    ref main ->> @fn(run);
    fa:
        return true;
}
"#,
            r#"
rawOverflow {
    fn:
        run() -> bool {
            public:
                base !> p<int> : 0xfffffffffffffff8;
                wrapped >> p<int> = pOffset(base, 4);
                return pDiff(wrapped, base) == 4;
        }
    ref main ->> @fn(run);
    fa:
        return true;
}
"#,
        ];

        for source in sources {
            analyze_source(source)
                .unwrap_or_else(|error| panic!("canonical raw source must compile: {error}"));
        }
    }

    #[test]
    fn compact_raw_declarations_and_pointer_aliases_preserve_unchecked_semantics() {
        let source = r#"
compactRawHazards {
    run() -> bool {
        owner <- alloc(8);
        alias: p<byte> = off<byte>(owner, 4096);
        wr<byte>(alias, 0xFF);
        free(owner);
        wr<byte>(owner, 1);
        free(owner);
        stale <- rd<byte>(alias);
        address <- adr(alias);
        recovered <- from<byte>(address);
        return stale == stale && !nil(recovered);
    }

    main: run;
}
"#;

        analyze_source(source)
            .expect("compact raw source must admit out-of-range access, UAF and double free");
    }

    #[test]
    fn explicit_pointer_audit_is_opt_in_and_does_not_change_normal_sema() {
        let source = r#"
use memory.heap.manager;

rawAudit {
    stc:
        owner: addr;

    fn:
        run() -> bool {
            public:
                @owner >> addr : memory.heap.manager.alloc(8);
                memory.heap.manager.free(@owner);
                memory.heap.manager.free(@owner);
                return true;
        }
    ref main ->> @fn(run);
    fa:
        return true;
}
"#;
        let program = parse_source(source);

        analyze(&program).expect("normal compilation must admit double free");
        let audit = analyze_with_explicit_pointer_checks(&program)
            .expect_err("the optional auditor must still detect the tracked hazard");
        assert!(
            audit.contains(E_PTR_STALE_SITE),
            "unexpected audit: {audit}"
        );
        analyze(&program).expect("auditing must not leak strict state into later compilation");
    }

    #[test]
    fn bounded_memregion_is_not_reclassified_as_a_raw_pointer() {
        let source = r#"
use nC.runtime.region;
use nC.heap.core;

boundedRegion {
    stc:
        owner: ptr<int>;
        region: memRegion<int>;

    fn:
        run() -> bool {
            public:
                @owner !> ptr<int> : alloc(4);
                @region >> memRegion<int> : regionFromPtr<int>(@owner, 1);
                return @region[1] == @region[1];
        }
    ref main ->> @fn(run);
    fa:
        return true;
}
"#;
        let error =
            analyze_source(source).expect_err("memRegion keeps its explicit bounded-view contract");
        assert!(
            error.contains(E_PTR_OUT_OF_BOUNDS),
            "unexpected error: {error}"
        );
    }
}

#[cfg(test)]
mod native_prelude_sema_tests {
    use super::*;

    fn analyze_source(source: &str) -> Result<SemanticResult, String> {
        let tokens = ncc_lexer::lex(source).expect("native prelude fixture must lex");
        let program = ncc_parser::parse(tokens).expect("native prelude fixture must parse");
        analyze(&program)
    }

    #[test]
    fn checked_add_int64_is_typed_without_an_import() {
        let source = r#"
checkedArithmetic {
    fn:
        run(left: int64, right: int64) -> int64 {
            public:
                return checkedAdd<int64>(@left, @right);
        }
    fa:
        return true;
}
"#;
        analyze_source(source).expect("checkedAdd<int64> must be a typed native intrinsic");
    }

    #[test]
    fn checked_add_rejects_a_lossy_int32_surface() {
        let source = r#"
checkedArithmeticWrongWidth {
    fn:
        run(left: int, right: int) -> int {
            public:
                return checkedAdd(@left, @right);
        }
    fa:
        return true;
}
"#;
        let error = analyze_source(source).expect_err("checkedAdd must keep its closed int64 ABI");
        assert!(
            error.contains(ncc_diagnostics::codes::E_HIGH_CHECKED_ADD_TYPE_001),
            "{error}"
        );
    }

    #[test]
    fn memory_layout_atomic_and_time_names_resolve_without_imports() {
        let source = r#"
nativePrelude {
    type:
        Pair {
            public:
                left: int;
                right: byte;
            layout:
                repr(C);
        }

    stc:
        p: ptr<byte> | null;
        q: ptr<byte> | null;
        r: ptr<byte>;
        value: byte;
        now: int;

    fn:
        run() -> bool {
            public:
                @p >> ptr<byte> | null : alloc(8);
                @q >> ptr<byte> | null : calloc(2, 8);
                @p >> ptr<byte> | null : realloc(@p, 32);
                @r >> ptr<byte> : ptrOffset<byte>(@p, 1);
                ptrWrite<byte>(@r, 7);
                @value >> byte : ptrRead<byte>(@r);
                @size >> int : sizeOf<Pair>();
                @align >> int : alignOf<Pair>();
                @offset >> int : offsetOf<Pair>(right);
                atomicLoad(0);
                atomicStore(0, 1);
                fence();
                @now >> int : monotonicMs();
                sleepMs(0);
                free(@q);
                free(@p);
                return @value == 7 && @size >= 5 && @align >= 1 && @offset >= 4;
        }

    ref main ->> @fn(run);

    fa:
        return true;
}
"#;
        analyze_source(source).expect("the complete native prelude must resolve without use");
    }

    #[test]
    fn material_string_addition_and_explicit_buffer_forms_are_both_valid() {
        let material = r#"
manualMaterialString {
    fn:
        run() -> bool {
            public:
                @joined >> str : "n" + "C";
                return true;
        }
    ref main ->> @fn(run);
    fa:
        return true;
}
"#;
        analyze_source(material).expect("str + str must lower through the native backend");

        let explicit = r#"
manualExplicitString {
    fn:
        run() -> bool {
            public:
                @buffer !> p<byte> : alloc(16);
                @written >> int : cat(@buffer, 16, "n", "C");
                free(@buffer);
                return @written == 2;
        }
    ref main ->> @fn(run);
    fa:
        return true;
}
"#;
        analyze_source(explicit).expect("cat must use caller-provided storage");
    }

    #[test]
    fn print_string_addition_is_a_non_material_stream() {
        let source = r#"
use nC.runtime.output;

streamingString {
    fn:
        run() -> bool {
            public:
                println("n" + "C");
                return true;
        }
    ref main ->> @fn(run);
    fa:
        return true;
}
"#;
        analyze_source(source).expect("println concatenation must remain a streaming operation");
    }

    #[test]
    fn closure_and_async_frames_are_named_by_source_storage() {
        let closure = r#"
manualClosure {
    fn:
        run() -> bool {
            public:
                @memory !> p<byte> : alloc(256);
                @plusOne >> fn(int) -> int : closureAt(@memory, |value: int| -> int {
                    return @value + 1;
                });
                @answer >> int : plusOne(41);
                free(@memory);
                return @answer == 42;
        }
    ref main ->> @fn(run);
    fa:
        return true;
}
"#;
        analyze_source(closure).expect("closureAt must make descriptor storage explicit");

        let bare = r#"
bareClosure {
    fn:
        run() -> bool {
            public:
                @f >> fn(int) -> int : |value: int| -> int { return @value; };
                return f(1) == 1;
        }
    ref main ->> @fn(run);
    fa:
        return true;
}
"#;
        let error = analyze_source(bare).expect_err("bare closures must be rejected");
        assert!(error.contains("E_MANUAL_CLOSURE_STORAGE_001"), "{error}");

        let asynchronous = r#"
manualAsync {
    fn:
        async answer(value: int) -> int {
            public:
                return @value + 1;
        }
        run() -> bool
        effects(async.await)
        {
            public:
                @memory !> p<byte> : alloc(512);
                @future >> Future<int> : asyncAt(@memory, answer(41));
                @value >> int : await @future;
                free(@memory);
                return @value == 42;
        }
    ref main ->> @fn(run);
    fa:
        return true;
}
"#;
        analyze_source(asynchronous).expect("asyncAt must pass caller storage to the frame");
    }

    #[test]
    fn canonical_compact_manual_raw_example_passes_sema() {
        let source = include_str!("../../../examples/06_memory/manual_raw_api_abi_layout.n");
        analyze_source(source).expect(
            "the official compact raw syntax must type-check without hidden storage or ownership",
        );
    }

    #[test]
    fn aggregate_copy_requires_an_explicit_address_and_byte_count() {
        let implicit = r#"
manualAggregateCopy {
    type:
        Pair {
            public:
                left: int;
                right: int;
            layout:
                repr(C);
        }
    fn:
        run() -> bool {
            public:
                @left >> Pair : Pair(left: 1, right: 2);
                @right >> Pair : @left;
                return true;
        }
    ref main ->> @fn(run);
    fa:
        return true;
}
"#;
        let error = analyze_source(implicit).expect_err("aggregate assignment must not copy bytes");
        assert!(error.contains("E_MANUAL_AGGREGATE_COPY_001"), "{error}");

        let explicit = r#"
manualAggregateCopy {
    type:
        Pair {
            public:
                left: int;
                right: int;
            layout:
                repr(C);
        }
    fn:
        run() -> bool {
            public:
                @left >> Pair : Pair(left: 1, right: 2);
                @right >> Pair : Pair(left: 0, right: 0);
                cp(&@right, &@left, sizeOf<Pair>());
                return true;
        }
    ref main ->> @fn(run);
    fa:
        return true;
}
"#;
        analyze_source(explicit).expect("cp must expose destination, source and bytes");
    }

    #[test]
    fn a_package_profile_never_changes_native_prelude_or_raw_semantics() {
        let source = r#"
package profile_probe { profile: arbitrary_vendor_profile; }

profileProbe[@] {
    stc:
        p: ptr<int> | null;
    fn:
        run() -> bool {
            public:
                @p >> ptr<int> | null : alloc(4);
                ptrWrite<int>(@p, 9);
                free(@p);
                return true;
        }
    ref main ->> @fn(run);
    fa:
        return true;
}
"#;
        analyze_source(source).expect("root code must receive compiler-native prelude names");
    }

    #[test]
    fn raw_pointer_address_spaces_widths_casts_and_comparisons_reach_sema() {
        let source = r#"
pointerTargetSema {
    type:
        Packet {
            public:
                tag: int;
                flags: byte;
            layout:
                repr(C);
        }

    fn:
        run(base: int, index: int) -> isize {
            public:
                @cpu >> p<Packet> : ptrFromAddr<Packet>(@base);
                @mmio >> p<Packet, mmio> : ptrCast<Packet, mmio>(@cpu);
                @dma >> p<Packet, dma, 32> : ptrCast<Packet, dma, 32>(@mmio);
                @next >> p<Packet, mmio> : ptrOffset<Packet>(@mmio, @index);
                @distance >> isize : ptrDiff<Packet>(@next, @mmio);
                @same >> bool : @cpu == @dma;
                return @distance;
        }

    fa:
        return true;
}
"#;
        analyze_source(source)
            .expect("all raw pointer domains, widths and casts must pass normal sema");
    }
}

#[cfg(test)]
mod hosted_runtime_prelude_v1_tests {
    use super::*;

    fn analyze_source(source: &str) -> Result<SemanticResult, String> {
        let tokens = ncc_lexer::lex(source).expect("hosted prelude fixture must lex");
        let program = ncc_parser::parse(tokens).expect("hosted prelude fixture must parse");
        analyze(&program)
    }

    #[test]
    fn string_json_terminal_and_time_are_implicit_in_hosted_and_runtime_contexts() {
        for (name, context) in [("hostedPrelude", ""), ("runtimePrelude", "[@runtime]")] {
            let source = format!(
                r#"
{name}{context} {{
    fn:
        run() -> bool {{
            public:
                @root >> int : jsonParse("{{\"element\":\"Cm\"}}");
                @node >> int : jsonObjectGet(@root, "element");
                @text >> str : strToUpper(jsonGetString(@node));
                @cursorHidden >> bool : hideCursor();
                @tick >> int : monotonicMs();
                return strEq(@text, "CM") && @cursorHidden == @cursorHidden && @tick >= 0;
        }}

    ref main ->> @fn(run);

    fa:
        return true;
}}
"#
            );
            analyze_source(&source)
                .unwrap_or_else(|error| panic!("{name} must resolve hidden prelude: {error}"));
        }
    }

    #[test]
    fn math_and_random_are_typed_without_source_imports() {
        let source = r#"
manualMathRandomPrelude :: runtime {
    fn:
        run() -> bool {
            seed(2026);
            integer >> int <- randomInt();
            truth >> bool <- randomBool();
            floating >> ft64 <- randomFloat();
            ranged >> int <- randomRange(9, 3);
            return integer >= 0 && truth == truth && floating >= 0.0 &&
                floating < 1.0 && ranged >= 3 && ranged <= 9 &&
                sign(-7) == -1 && abs(-7) == 7;
        }

    ref main ->> run;

    fa:
        return true;
}
"#;
        analyze_source(source).expect("math/random backend prelude must resolve without use");
    }

    #[test]
    fn local_function_precedes_hosted_runtime_prelude() {
        let source = r#"
shadowPrelude {
    fn:
        jsonParse(text: str) -> bool {
            public:
                return strEq(@text, "local");
        }

        run() -> bool {
            public:
                return jsonParse("local");
        }

    ref main ->> @fn(run);

    fa:
        return true;
}
"#;
        analyze_source(source).expect("local jsonParse must shadow the hosted prelude");
    }

    #[test]
    fn known_prelude_name_reports_catalog_arity() {
        let source = r#"
badPreludeArity {
    fn:
        run() -> int {
            public:
                return jsonParse();
        }

    ref main ->> @fn(run);

    fa:
        return true;
}
"#;
        let error = analyze_source(source).expect_err("wrong prelude arity must fail");
        assert!(error.contains("E_RUNTIME_PRELUDE_ARITY_001"), "{error}");
    }

    #[test]
    fn owned_string_release_is_typed_by_the_hosted_prelude() {
        let positive = r#"
ownedStringRelease {
    fn:
        run() -> bool {
            public:
                @owned >> str : strConcat("n", "C");
                return strRelease(@owned);
        }

    ref main ->> @fn(run);

    fa:
        return true;
}
"#;
        analyze_source(positive).expect("owned string release must resolve without visible use");

        let wrong_type = r#"
badOwnedStringRelease {
    fn:
        run() -> bool {
            public:
                return strRelease(7);
        }

    ref main ->> @fn(run);

    fa:
        return true;
}
"#;
        let error = analyze_source(wrong_type).expect_err("strRelease(int) must fail sema");
        assert!(
            error.contains("E_RUNTIME_GENERIC_ARG_MISMATCH_001"),
            "{error}"
        );
        assert!(error.contains("expected str, got int"), "{error}");
    }

    #[test]
    fn hidden_prelude_is_available_only_to_hosted_root_and_runtime() {
        assert!(hosted_runtime_prelude_allowed_in_context(&None));
        assert!(hosted_runtime_prelude_allowed_in_context(&Some(
            Context::Root
        )));
        assert!(hosted_runtime_prelude_allowed_in_context(&Some(
            Context::Runtime
        )));
        for context in [
            Context::Machine,
            Context::Primitive,
            Context::Kernel,
            Context::System,
        ] {
            assert!(!hosted_runtime_prelude_allowed_in_context(&Some(context)));
        }

        let source = r#"
rootPrelude[@] {
    fn:
        run() -> int {
            public:
                return jsonParse("{}");
        }

    ref main ->> @fn(run);

    fa:
        return true;
}
"#;
        analyze_source(source).expect("explicit root is a hosted prelude context");
    }

    #[test]
    fn mobile_and_permission_namespaces_resolve_with_or_without_source_imports() {
        let mobile = include_str!("../../../examples/12_apps/geocaller_mobile_backend.n");
        analyze_source(mobile)
            .unwrap_or_else(|error| panic!("mobile native string surface failed: {error}"));

        let explicit = include_str!("../../../examples/12_apps/mobile_backend_smoke_no_imports.n");
        analyze_source(explicit)
            .unwrap_or_else(|error| panic!("explicit mobile backend surface failed: {error}"));
    }

    #[test]
    fn blockmaster_struct_strings_accept_native_string_operators() {
        let source = include_str!("../../../examples/12_apps/blockmaster_remote_backend.n");
        analyze_source(source)
            .unwrap_or_else(|error| panic!("BlockMaster string surface failed: {error}"));
    }

    #[test]
    fn blockmaster_urgency_accepts_native_string_operators() {
        let source = include_str!("../../../examples/12_apps/blockmaster_android_core.n");
        analyze_source(source)
            .unwrap_or_else(|error| panic!("BlockMaster urgency string surface failed: {error}"));
    }
}

#[cfg(test)]
mod permissive_return_abi_tests {
    use super::*;

    #[test]
    fn void_discards_and_scalar_returns_coerce_to_the_declared_abi() {
        let source = r#"
returnAbi {
    discardText() -> void {
        return "discarded";
    }

    intAsBool() -> bool {
        return 7;
    }

    charAsBool() -> bool {
        return 'A';
    }

    textAsInt() -> int {
        return "raw-address";
    }

    run() -> bool {
        discardText();
        bits >> int = textAsInt();
        return intAsBool() && charAsBool() && bits != 0;
    }

    main: run;
}
"#;
        let tokens = ncc_lexer::lex(source).expect("return ABI fixture must lex");
        let program = ncc_parser::parse(tokens).expect("return ABI fixture must parse");
        analyze(&program).expect("scalar return coercions must be valid");
    }
}

#[cfg(test)]
mod compact_kernel_system_surface_tests {
    use super::*;

    const SOURCE: &str = r#"
kernelApicSmpGuestBoot {
    configureXapic() -> bool {
        lapic  at 0xFEE00000;
        ioapic at 0xFEC00000;
        hpet   at 0xFED00000;

        guard load32(lapic + 0x30) >= 0 else return false;
        *32(lapic + 0xF0, 0x1FF);
        *32(lapic + 0x320, 0x61);
        *32(lapic + 0x3E0, 0x0B);
        route = load32(ioapic + 0x10);
        *32(ioapic + 0x10, route);
        counter = load64(hpet + 0xF0);
        *64(hpet + 0xF0, counter);
        sendIpi(lapic, 1, 0x4042);
        32(lapic + 0xB0, 0);
        return true;
    }

    configureX2apic() -> bool {
        guard msrRead(0x803) >= 0 else return false;
        msrWrite(0x80F, 0x1FF);
        tscDeadline(tscRead() + 1_000_000);
        return true;
    }

    main: configureXapic;
}
"#;

    #[test]
    fn kernel_compact_surface_is_semantically_native_and_import_free() {
        let tokens = ncc_lexer::lex(SOURCE).expect("kernel compact fixture must lex");
        let program = ncc_parser::parse(tokens).expect("kernel compact fixture must parse");
        assert!(program.uses.is_empty());
        analyze(&program).expect("kernel compact MMIO/APIC/MSR/TSC surface must pass sema");
    }
}

#[cfg(test)]
fn example_fixture_path(dir: &str, name: &str) -> std::path::PathBuf {
    let manifest_dir = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let current = manifest_dir.join("../../examples").join(dir).join(name);
    if current.exists() {
        return current;
    }

    let archived = manifest_dir
        .join("../../_archive/old_examples")
        .join(dir)
        .join(name);
    if archived.exists() {
        return archived;
    }

    let public_fixture = manifest_dir
        .join("../../tests/fixtures/old_examples")
        .join(dir)
        .join(name);
    if public_fixture.exists() {
        return public_fixture;
    }

    current
}

#[cfg(test)]
mod complete_control_flow_sema_tests {
    use super::*;

    fn analyze_source(src: &str) -> Result<SemanticResult, String> {
        let tokens = ncc_lexer::lex(src).expect("control-flow fixture must lex");
        let program = ncc_parser::parse(tokens).expect("control-flow fixture must parse");
        analyze(&program)
    }

    #[test]
    fn break_and_continue_require_real_active_targets() {
        let break_src = r#"
badBreak {
    fn:
        run() -> bool {
            public:
                break;
                return true;
        }
}
"#;
        let err = analyze_source(break_src).expect_err("break outside a loop must fail in sema");
        assert!(err.contains("E_CONTROL_BREAK_SCOPE_001"), "{err}");

        let continue_src = r#"
badContinue {
    fn:
        run() -> bool {
            public:
                loop {
                    continue missing;
                }
        }
}
"#;
        let err =
            analyze_source(continue_src).expect_err("unknown continue label must fail in sema");
        assert!(err.contains("E_CONTROL_CONTINUE_LABEL_001"), "{err}");
    }

    #[test]
    fn nested_labeled_loops_and_condition_chains_pass() {
        let src = r#"
goodFlow {
    fn:
        run(limit: int) -> int {
            public:
                @out >> int : 0;
                outer: for (@i >> int : 0; @i < @limit; @i = @i + 1) {
                    inner: loop {
                        if (@i == 0) {
                            continue outer;
                        } elseIf (@i == 1) {
                            @out = @out + 1;
                            break inner;
                        } else {
                            break outer;
                        }
                    }
                }
                return @out;
        }
}
"#;
        analyze_source(src).expect("nested labels and elseIf chain must pass sema");
    }

    #[test]
    fn negative_repeat_count_is_rejected_before_lowering() {
        let src = r#"
badRepeat {
    fn:
        run() -> bool {
            public:
                same for (-1) {
                    return false;
                }
                return true;
        }
}
"#;
        let err = analyze_source(src).expect_err("negative repeat count must fail");
        assert!(err.contains("E_HIGH_REPEAT_COUNT_NEGATIVE_001"), "{err}");
    }
}

#[cfg(test)]
mod null_void_visibility_sema_tests {
    use super::*;

    fn parse_program(src: &str) -> ncc_parser::Program {
        let tokens = ncc_lexer::lex(src).expect("fixture lex");
        ncc_parser::parse(tokens).expect("fixture parse")
    }

    #[test]
    fn compact_pointer_bytes_runtime_surface_passes_sema() {
        let src = r#"
use::stoud::io::<fswrite>;
use::stoud::memory::<ptr, heap>;

compactPointerBytes[@runtime] {
    stc:
        bytes: array<int, 4>;
        p: p<int>;
        i >> int = 0;
        ok >> bool = false;
    fn:
        run() -> bool {
            public:
                p = alloc(4)!;
                guard i < 4 else {
                    return false;
                }
                match (i) {
                    0 => bytes[i] = 0x48;
                    _ => bytes[i] = 0;
                }
                *(p + i) = bytes[i];
                p++;
                ok = fswrite("target/ncc_compact_pointer_bytes_sema.txt", "ok");
                free(p);
                return ok;
        }
    ref main ->> @fn(run);
    fa:
        return true;
}
"#;
        let program = parse_program(src);
        let result = analyze(&program);
        assert!(
            result.is_ok(),
            "compact pointer byte runtime surface should pass sema, got {:?}",
            result
        );
    }

    #[test]
    fn compact_raw_pointer_compares_with_null() {
        let src = r#"
rawPointerNullComparison {
    fn:
        isSet(value: p<int>) -> bool {
            public:
                return value != null;
        }
}
"#;
        let program = parse_program(src);
        analyze(&program).expect("raw pointer equality with null must pass sema");
    }

    #[test]
    fn null_condition_reports_official_diag_in_sema() {
        let src = r#"
entry[@] {
    fn:
        boot() -> bool {
            public:
                if (null) {
                    return true;
                }
                return false;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let program = parse_program(src);
        let result = analyze(&program);
        assert!(result.is_err());
        let msg = result.unwrap_err();
        assert!(
            msg.contains("E_NULL_CONDITION_001"),
            "unexpected error: {}",
            msg
        );
    }

    #[test]
    fn void_return_null_is_evaluated_and_discarded_in_sema() {
        let src = r#"
entry[@] {
    fn:
        sink() -> void {
            public:
                return null;
        }

        boot() -> bool {
            public:
                sink();
                return true;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let program = parse_program(src);
        let result = analyze(&program);
        assert!(
            result.is_ok(),
            "void must accept and discard every material return value, got {:?}",
            result
        );
    }

    #[test]
    fn void_return_discard_null_nullable_passes_in_sema() {
        let src = r#"
entry[@] {
    stc:
        maybe: ptr<byte> | null;

    fn:
        sink() -> void {
            public:
                return discardNull(@maybe);
        }

        boot() -> bool {
            public:
                @maybe >> ptr<byte> | null : null;
                sink();
                return true;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let program = parse_program(src);
        let result = analyze(&program);
        assert!(
            result.is_ok(),
            "expected discardNull(nullable) void-return contract to pass, got {:?}",
            result
        );
    }

    #[test]
    fn void_value_used_as_non_void_return_fails_in_sema() {
        let src = r#"
entry[@] {
    stc:
        maybe: ptr<byte> | null;

    fn:
        sink() -> void {
            public:
                return discardNull(@maybe);
        }

        boot() -> int {
            public:
                @maybe >> ptr<byte> | null : null;
                return sink();
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let program = parse_program(src);
        let result = analyze(&program);
        assert!(result.is_err());
        let msg = result.unwrap_err();
        assert!(
            msg.contains("E_VOID_VALUE_001"),
            "unexpected error: {}",
            msg
        );
    }

    #[test]
    fn nominal_destructure_move_null_fails_in_sema() {
        let src = r#"
entry[@] {
    fn:
        boot() -> bool {
            public:
                destructure.move(null);
                return true;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let program = parse_program(src);
        let result = analyze(&program);
        assert!(result.is_err());
        let msg = result.unwrap_err();
        assert!(
            msg.contains("E_DESTRUCTURE_MOVE_001"),
            "unexpected error: {}",
            msg
        );
    }

    #[test]
    fn nominal_destructure_region_bounds_fails_in_sema() {
        let src = r#"
entry[@] {
    fn:
        boot() -> bool {
            public:
                destructure.region(1, -1, 0);
                return true;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let program = parse_program(src);
        let result = analyze(&program);
        assert!(result.is_err());
        let msg = result.unwrap_err();
        assert!(
            msg.contains("E_DESTRUCTURE_REGION_BOUNDS_001"),
            "unexpected error: {}",
            msg
        );
    }

    #[test]
    fn nominal_constructure_binary_layout_fails_in_sema() {
        let src = r#"
entry[@] {
    fn:
        boot() -> bool {
            public:
                constructure.binary(null);
                return true;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let program = parse_program(src);
        let result = analyze(&program);
        assert!(result.is_err());
        let msg = result.unwrap_err();
        assert!(
            msg.contains("E_CONSTRUCTURE_BINARY_LAYOUT_001"),
            "unexpected error: {}",
            msg
        );
    }

    #[test]
    fn nominal_destructure_constructure_static_passes_in_sema() {
        let src = r#"
entry[@] {
    fn:
        boot() -> bool {
            public:
                destructure.static([1, 2, 3]);
                constructure.static(1);
                return true;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let program = parse_program(src);
        let result = analyze(&program);
        assert!(
            result.is_ok(),
            "expected nominal destructure/constructure static forms to pass, got {:?}",
            result
        );
    }
}

#[cfg(test)]
mod deprecation_warning_tests {
    use super::*;

    fn parse_program(src: &str) -> Program {
        let tokens = ncc_lexer::lex(src).expect("lex");
        ncc_parser::parse(tokens).expect("parse")
    }

    #[test]
    fn removed_print_spacing_forms_stop_in_parser() {
        for statement in ["print.sp();", "print.nl();"] {
            let src = format!("entry[@] {{ to main {{ {statement} }} fa: return true; }}");
            let tokens = ncc_lexer::lex(&src).expect("removed print form must still lex");
            let error = ncc_parser::parse(tokens).expect_err("removed print form must fail");
            assert!(
                error.message.contains("E_PRINT_SURFACE_001")
                    && error.message.contains("use print(...) or println(...)"),
                "unexpected parser diagnostic: {error:?}"
            );
        }
    }

    #[test]
    fn official_print_family_has_no_deprecation_warnings() {
        let src = r#"
entry[@] {
    fn:
        public boot() -> bool {
            public:
                print("ok");
                println("ok");
                return true;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let program = parse_program(src);
        let result = analyze(&program).expect("sema should pass");
        assert!(
            result
                .warnings
                .iter()
                .all(|w| !w.contains("NCC-DEPRECATION-")),
            "official print usage must not emit deprecation warnings, got {:?}",
            result.warnings
        );
    }
}

#[cfg(test)]
mod projection_v1_0_1_tests {
    use super::*;

    fn parse_program(src: &str) -> ncc_parser::Program {
        let tokens = ncc_lexer::lex(src).expect("lex");
        ncc_parser::parse(tokens).expect("parse")
    }

    #[test]
    fn projection_reproject_strictly_target_reports_official_diag() {
        let src = r#"
entry[@] {
    stc:
        strictly: locked: int;

    fn:
        boot() -> bool {
            public:
                @locked >> int : 1;
                return true;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let program = parse_program(src);
        let result = analyze(&program);
        assert!(result.is_err());
        let msg = result.unwrap_err();
        assert!(
            msg.contains("cannot reproject strictly protected target"),
            "unexpected error: {}",
            msg
        );
    }

    #[test]
    fn projection_null_into_non_nullable_reports_official_diag() {
        let src = r#"
entry[@] {
    fn:
        boot() -> bool {
            public:
                @x >> int : null;
                return true;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let program = parse_program(src);
        let result = analyze(&program);
        assert!(result.is_err());
        let msg = result.unwrap_err();
        assert!(
            msg.contains("cannot project null into non-nullable target"),
            "unexpected error: {}",
            msg
        );
    }

    #[test]
    fn projection_unresolved_union_source_reports_official_diag() {
        let src = r#"
entry[@] {
    stc:
        y: int | str;

    fn:
        boot() -> bool {
            public:
                @x >> int : @y;
                return true;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let program = parse_program(src);
        let result = analyze(&program);
        assert!(result.is_err());
        let msg = result.unwrap_err();
        assert!(
            msg.contains("projection source has unresolved union type"),
            "unexpected error: {}",
            msg
        );
    }

    #[test]
    fn projection_implicit_narrowing_reports_official_diag() {
        let src = r#"
entry[@] {
    fn:
        boot() -> bool {
            public:
                @src >> int64 : 9;
                @dst >> int8 : @src;
                return true;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let program = parse_program(src);
        let result = analyze(&program);
        assert!(result.is_err());
        let msg = result.unwrap_err();
        assert!(
            msg.contains("implicit narrowing projection is not allowed"),
            "unexpected error: {}",
            msg
        );
    }

    #[test]
    fn projection_missing_nested_target_reports_official_diag() {
        let src = r#"
entry[@] {
    fn:
        boot() -> bool {
            public:
                @ghost.field >> int : 1;
                return true;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let program = parse_program(src);
        let result = analyze(&program);
        assert!(result.is_err());
        let msg = result.unwrap_err();
        assert!(
            msg.contains("projection target 'ghost.field' does not exist"),
            "unexpected error: {}",
            msg
        );
    }

    #[test]
    fn at_ref_unresolved_resource_kind_is_reported() {
        let src = r#"
entry[@] {
    fn:
        boot() -> bool {
            public:
                @system.ghost;
                return true;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let program = parse_program(src);
        let result = analyze(&program);
        assert!(result.is_err());
        let msg = result.unwrap_err();
        assert!(
            msg.contains("unresolved reference '@system.ghost'"),
            "unexpected error: {}",
            msg
        );
        assert!(
            msg.contains("(resource)"),
            "expected kind annotation in unresolved @ diagnostic, got: {}",
            msg
        );
    }

    #[test]
    fn at_ref_unresolved_function_kind_is_reported() {
        let src = r#"
entry[@] {
    fn:
        boot() -> bool {
            public:
                @worker;
                return true;
        }

        worker() -> bool {
            public:
                return true;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let program = parse_program(src);
        let result = analyze(&program);
        assert!(result.is_err());
        let msg = result.unwrap_err();
        assert!(
            msg.contains("unresolved reference '@worker'"),
            "unexpected error: {}",
            msg
        );
        assert!(
            msg.contains("(function)"),
            "expected function kind annotation in unresolved @ diagnostic, got: {}",
            msg
        );
    }

    #[test]
    fn siteof_returns_typed_siteinfo_and_fields_in_root_context() {
        let src = r#"
entry[@] {
    stc:
        x: int;
        meta: siteInfo;

    fn:
        boot() -> bool {
            public:
                @x >> int : 1;
                @meta >> siteInfo : siteOf(@x);
                @kind >> str : @meta.class;
                return true;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let program = parse_program(src);
        let result = analyze(&program);
        assert!(
            result.is_ok(),
            "expected siteOf/siteInfo root fixture to pass in sema, got {:?}",
            result
        );
    }

    #[test]
    fn siteof_is_restricted_outside_sovereign_runtime_modes() {
        let src = r#"
entry[@system] {
    fn:
        boot() -> bool {
            public:
                @meta >> siteInfo : siteOf(1);
                return true;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let program = parse_program(src);
        let result = analyze(&program);
        assert!(result.is_err());
        let msg = result.unwrap_err();
        assert!(
            msg.contains("site introspection is not allowed in current mode"),
            "unexpected error: {}",
            msg
        );
    }

    #[test]
    fn site_projection_print_sugar_passes_in_root_context() {
        let src = r#"
entry[@] {
    stc:
        x: int;

    fn:
        boot() -> bool {
            public:
                @x >> int : 9;
                @x >> site.region.print;
                @x >> site.addr.print;
                @x >> site.class.print;
                @x >> site.type.print;
                @x >> site.state.print;
                @x >> site.owner.print;
                @x >> site.size.print;
                @x >> site.align.print;
                return true;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let program = parse_program(src);
        let result = analyze(&program);
        assert!(
            result.is_ok(),
            "expected site projection print sugar in [@] to pass sema, got {:?}",
            result
        );
    }

    #[test]
    fn site_projection_print_sugar_is_restricted_outside_allowed_modes() {
        let src = r#"
entry[@system] {
    stc:
        x: int;

    fn:
        boot() -> bool {
            public:
                @x >> int : 1;
                @x >> site.region.print;
                return true;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let program = parse_program(src);
        let result = analyze(&program);
        assert!(result.is_err());
        let msg = result.unwrap_err();
        assert!(
            msg.contains("site introspection is not allowed in current mode"),
            "unexpected error: {}",
            msg
        );
    }
}

#[cfg(test)]
mod security_f8_sema_tests {
    use super::*;
    use std::path::PathBuf;

    fn fixture_path(name: &str) -> PathBuf {
        super::example_fixture_path("security_at", name)
    }

    fn load_fixture(name: &str) -> ncc_parser::Program {
        let src = std::fs::read_to_string(fixture_path(name)).expect("fixture must exist");
        let tokens = ncc_lexer::lex(&src).expect("fixture must lex");
        ncc_parser::parse(tokens).expect("fixture must parse")
    }

    #[test]
    fn security_at_minimal_ok_passes_in_sema() {
        let program = load_fixture("security_at_minimal_ok.n");
        let result = analyze(&program);
        assert!(
            result.is_ok(),
            "expected minimal [@security] fixture to pass in sema, got {:?}",
            result
        );
    }

    #[test]
    fn security_at_entities_ok_passes_in_sema() {
        let program = load_fixture("security_at_entities_ok.n");
        let result = analyze(&program);
        assert!(
            result.is_ok(),
            "expected entity-rich [@security] fixture to pass in sema, got {:?}",
            result
        );
    }

    #[test]
    fn security_at_attack_import_without_lab_fails_sec047() {
        let program = load_fixture("security_at_attack_import_without_lab_fail.n");
        let result = analyze(&program);
        assert!(result.is_err());
        let msg = result.unwrap_err();
        assert!(
            msg.contains("SEC047"),
            "expected SEC047 diagnostic for offensive import gate, got {}",
            msg
        );
    }

    #[test]
    fn security_at_attack_import_with_lab_passes_in_sema() {
        let program = load_fixture("security_at_attack_import_with_lab_ok.n");
        let result = analyze(&program);
        assert!(
            result.is_ok(),
            "expected lab-enabled [@security] attack fixture to pass in sema, got {:?}",
            result
        );
    }

    #[test]
    fn security_at_runtime_allow_ok_passes_in_sema() {
        let program = load_fixture("security_at_runtime_allow_ok.n");
        let result = analyze(&program);
        assert!(
            result.is_ok(),
            "expected runtime [@] security allow fixture to pass in sema, got {:?}",
            result
        );
    }

    #[test]
    fn security_at_runtime_deny_block_fixture_passes_in_sema() {
        let program = load_fixture("security_at_runtime_deny_blocks_send_fail.n");
        let result = analyze(&program);
        assert!(
            result.is_ok(),
            "expected runtime deny enforcement fixture to pass sema before runtime, got {:?}",
            result
        );
    }

    #[test]
    fn security_context_output_missing_import_fails_in_sema() {
        let program = load_fixture("security_at_inspect_contract_missing_import_fail.n");
        let error = analyze(&program).expect_err("security context output requires its import");
        assert!(
            error.contains("requires security runtime contract import"),
            "unexpected context/security contract diagnostic: {error}"
        );
    }

    #[test]
    fn security_missing_default_action_fails_in_sema() {
        let src = r#"
securityNoDefault[@security] {
    stc:
        audit >> bool : true;

    asset:
        paymentApi;

    final:
        return true;
}
"#;
        let tokens = ncc_lexer::lex(src).unwrap();
        let program = ncc_parser::parse(tokens).unwrap();
        let result = analyze(&program);
        assert!(result.is_err());
        let msg = result.unwrap_err();
        assert!(
            msg.contains(
                "missing stc declaration 'defaultAction >> action : ...' in [@security] container"
            ),
            "unexpected error: {}",
            msg
        );
    }

    #[test]
    fn security_duplicate_asset_fails_in_sema() {
        let src = r#"
securityDupAsset[@security] {
    stc:
        defaultAction >> action : deny;
        audit >> bool : true;

    asset:
        paymentApi;
        paymentApi;

    final:
        return true;
}
"#;
        let tokens = ncc_lexer::lex(src).unwrap();
        let program = ncc_parser::parse(tokens).unwrap();
        let result = analyze(&program);
        assert!(result.is_err());
        let msg = result.unwrap_err();
        assert!(
            msg.contains("duplicate asset symbol 'paymentApi' in [@security] container"),
            "unexpected error: {}",
            msg
        );
    }

    #[test]
    fn security_import_context_mismatch_fails_in_sema() {
        let src = r#"
use security.policy.strict;

entry[@runtime] {
    stc:
        defaultAction >> action : deny;

    fn:
        public boot() -> bool {
            public:
                security.policy.strict.evaluate(@defaultAction);
                return true;
        }

    final:
        return true;
}
"#;
        let tokens = ncc_lexer::lex(src).unwrap();
        let program = ncc_parser::parse(tokens).unwrap();
        let result = analyze(&program);
        assert!(result.is_err());
        let msg = result.unwrap_err();
        assert!(
            msg.contains(
                "invalid import declaration 'security.policy.strict' for context 'entry[@runtime]'"
            ),
            "unexpected error: {}",
            msg
        );
        assert!(
            msg.contains("[@security]"),
            "expected security declaration authority set, got: {}",
            msg
        );
    }
}

