#[cfg(test)]
mod ffi_call_resolution_tests {
    use super::*;

    fn analyze_src(src: &str) -> Result<SemanticResult, String> {
        let tokens = ncc_lexer::lex(src).expect("lex");
        let program = ncc_parser::parse(tokens).expect("parse");
        analyze(&program)
    }

    #[test]
    fn ffi_symbol_call_resolves_from_foreign_contract_block() {
        let src = r#"
use foreign.c;

entry[@runtime] {

    foreign:
        c symbol "validate_amount" {
            abi: C;
            header: "bank_validation.h";
            library: "bank_validation";
            linkage: dynamic;
            layout: stable;
            ownership: borrowed;
            sideEffects: none;
            signature: fn(int) -> bool;
        }

    stc:
        ok: bool;

    fn:
        run() -> bool {
            public:
                @ok >> bool : validate_amount(1000);
                return @ok;
        }

    ref main ->> @fn(run);
    fa:
        return true;
}
"#;
        analyze_src(src).expect("foreign symbol call should resolve from contract");
    }

    #[test]
    fn ffi_symbol_call_argument_arity_mismatch_fails() {
        let src = r#"
use foreign.c;

entry[@runtime] {

    foreign:
        c symbol "validate_amount" {
            abi: C;
            header: "bank_validation.h";
            library: "bank_validation";
            linkage: dynamic;
            layout: stable;
            ownership: borrowed;
            sideEffects: none;
            signature: fn(int) -> bool;
        }

    stc:
        ok: bool;

    fn:
        run() -> bool {
            public:
                @ok >> bool : validate_amount();
                return @ok;
        }

    ref main ->> @fn(run);
    fa:
        return true;
}
"#;
        let err = analyze_src(src).expect_err("arity mismatch must fail");
        assert!(
            err.contains("no matching function"),
            "unexpected error: {err}"
        );
    }
}

