        let src = r#"
entry[@] {
    stc:
        schedulerOpen >> bool : false;
        panicState >> bool : false;
        quarantineCount >> int : 0;
        lastTask >> str : "none";
        lastEvent >> str : "boot";

    fn:
        boot() -> bool {
            public:
                register(7, "idle");
                open();
                next();
                quarantine(7);
                return true;
        }

    ref main ->> @fn(boot);

    final:
        return true;
}
"#;
        let program = parse_src(src);
        let result = analyze(&program);
        assert!(
            result.is_ok(),
            "expected kernel profile in normal .n to pass without imports, got {:?}",
            result
        );
