fn has_use_path(program: &Program, path: &[&str]) -> bool {
    program.uses.iter().any(|u| {
        if u.wildcard {
            u.path.len() <= path.len()
                && u.path
                    .iter()
                    .zip(path.iter())
                    .all(|(a, b)| a.eq_ignore_ascii_case(b))
        } else {
            u.path.len() == path.len()
                && u.path
                    .iter()
                    .zip(path.iter())
                    .all(|(a, b)| a.eq_ignore_ascii_case(b))
        }
    })
}

