fn path_prefix_matches(path: &[String], prefix: &[&str]) -> bool {
    path.len() >= prefix.len()
        && path
            .iter()
            .zip(prefix.iter())
            .all(|(segment, expected)| segment.eq_ignore_ascii_case(expected))
}

fn use_path_targets_list_family(path: &[String]) -> bool {
    (path.len() >= 3
        && path[0].eq_ignore_ascii_case("nC")
        && path[1].eq_ignore_ascii_case("runtime")
        && (path[2].eq_ignore_ascii_case("list") || path[2].eq_ignore_ascii_case("queue")))
        || (path.len() >= 2
            && path[0].eq_ignore_ascii_case("runtime")
            && (path[1].eq_ignore_ascii_case("list") || path[1].eq_ignore_ascii_case("queue")))
        || (path.len() >= 2
            && path[0].eq_ignore_ascii_case("nC")
            && path[1].eq_ignore_ascii_case("list"))
        || (!path.is_empty() && path[0].eq_ignore_ascii_case("list"))
}

fn runtime_family_suffix_lookup(segment: &str) -> Option<&'static str> {
    if segment.eq_ignore_ascii_case("list") {
        return Some("queue");
    }
    ncc_parser::official_runtime_families()
        .iter()
        .find_map(|entry| {
            let mut parts = entry.split('.');
            let head = parts.next()?;
            let mid = parts.next()?;
            let suffix = parts.next()?;
            if head.eq_ignore_ascii_case("nC")
                && mid.eq_ignore_ascii_case("runtime")
                && suffix.eq_ignore_ascii_case(segment)
            {
                Some(suffix)
            } else {
                None
            }
        })
}

fn use_decl_runtime_family_suffix(use_path: &[String]) -> Option<&'static str> {
    if use_path.len() == 3
        && use_path[0].eq_ignore_ascii_case("nC")
        && use_path[1].eq_ignore_ascii_case("runtime")
    {
        return runtime_family_suffix_lookup(&use_path[2]);
    }
    if use_path.len() == 2 && use_path[0].eq_ignore_ascii_case("runtime") {
        return runtime_family_suffix_lookup(&use_path[1]);
    }
    None
}

fn use_decl_targets_runtime_family_or_namespace(use_decl: &UseDecl) -> bool {
    if use_decl_runtime_family_suffix(&use_decl.path).is_some() {
        return true;
    }

    use_decl.wildcard
        && ((use_decl.path.len() == 2
            && use_decl.path[0].eq_ignore_ascii_case("nC")
            && use_decl.path[1].eq_ignore_ascii_case("runtime"))
            || (use_decl.path.len() == 1 && use_decl.path[0].eq_ignore_ascii_case("runtime")))
}

fn runtime_family_allowed_in_root(suffix: &str) -> bool {
    suffix.eq_ignore_ascii_case("heap")
        || suffix.eq_ignore_ascii_case("region")
        || suffix.eq_ignore_ascii_case("trace")
        || suffix.eq_ignore_ascii_case("alias")
        || suffix.eq_ignore_ascii_case("net")
        || suffix.eq_ignore_ascii_case("time")
}

fn is_runtime_family_module_path(path: &[String]) -> bool {
    path.len() == 2
        && path[0].eq_ignore_ascii_case("runtime")
        && runtime_family_suffix_lookup(&path[1]).is_some()
}

fn module_path_targets_runtime_family_or_namespace(module_path: &[String]) -> bool {
    if use_decl_runtime_family_suffix(module_path).is_some() {
        return true;
    }

    (module_path.len() == 2
        && module_path[0].eq_ignore_ascii_case("nC")
        && module_path[1].eq_ignore_ascii_case("runtime"))
        || (module_path.len() == 1 && module_path[0].eq_ignore_ascii_case("runtime"))
}

