fn validate_inspect_runtime_path_contract_imports(
    program: &Program,
    raw_path: &[String],
    path: InspectRuntimePath,
) -> Result<(), String> {
    let rendered = raw_path.join(".");

    if inspect_runtime_path_needs_heap_contract(path) && !has_heap_inspect_contract_import(program)
    {
        return Err(format!(
            "inspect path '{}' requires heap runtime contract import: use memory.heap.manager; or use nC.runtime.heap;",
            rendered
        ));
    }

    if inspect_runtime_path_needs_net_contract(path) && !has_net_inspect_contract_import(program) {
        return Err(format!(
            "inspect path '{}' requires network runtime contract import: use system.net.core; use alt.net.core; or use nC.runtime.net;",
            rendered
        ));
    }

    if inspect_runtime_path_needs_security_contract(path)
        && !has_security_inspect_contract_import(program)
    {
        return Err(format!(
            "inspect path '{}' requires security runtime contract import: use security.policy.strict; or use security.intel.attack;",
            rendered
        ));
    }

    if inspect_runtime_path_needs_system_contract(path)
        && !has_system_inspect_contract_import(program)
    {
        return Err(format!(
            "inspect path '{}' requires system runtime contract import: use system.service.core; use system.proc.core; or use system.io.core;",
            rendered
        ));
    }

    if inspect_runtime_path_needs_tooling_contract(path)
        && !has_tooling_inspect_contract_import(program)
    {
        return Err(format!(
            "inspect path '{}' requires tooling runtime contract import: use tooling.build.core; use tooling.lint.core; use tooling.fmt.core; use tooling.pkg.core; or use nC.tooling.*;",
            rendered
        ));
    }

    if inspect_runtime_path_needs_compiler_contract(path)
        && !has_compiler_inspect_contract_import(program)
    {
        return Err(format!(
            "inspect path '{}' requires compiler runtime contract import: use compiler.parse.ast; use compiler.semantic.core; use compiler.backend.machine; or use nC.compiler.*;",
            rendered
        ));
    }

    let _ = inspect_runtime_path_needs_kernel_contract(path);

    if inspect_runtime_path_needs_ai_contract(path) && !has_ai_inspect_contract_import(program) {
        return Err(format!(
            "inspect path '{}' requires ai runtime contract import: use ai.session.core; use ai.model.core; use ai.agent.core; use ai.chat.core; use ai.memory.core; or use nC.ai.*;",
            rendered
        ));
    }

    Ok(())
}

fn is_mutating_method(name: &str) -> bool {
    matches!(
        name,
        "push"
            | "pop"
            | "set"
            | "insert"
            | "removeAt"
            | "clear"
            | "enqueue"
            | "dequeue"
            | "pushFront"
            | "pushBack"
            | "popFront"
            | "popBack"
            | "rotateLeft"
            | "rotateRight"
            | "writeAt"
            | "zero"
            | "bind"
            | "watch"
            | "unwatch"
            | "append"
            | "mark"
            | "pushWithPriority"
            | "arrayWrite"
            | "arrayFieldWrite"
    )
}

fn program_has_runtime_container(program: &Program) -> bool {
    program
        .containers
        .iter()
        .any(|container| matches!(container.context, Some(Context::Runtime)))
}

fn validate_list_imports(program: &Program, ty: &SemaType) -> Result<(), String> {
    match ty {
        SemaType::Generic { base, args } if is_list_family(base) => {
            let has_runtime_region_import = base == "memRegion"
                && (has_use_path(program, &["nC", "runtime", "region"])
                    || program_has_runtime_container(program));

            let has_list_import = program
                .uses
                .iter()
                .any(|use_decl| use_path_targets_list_family(&use_decl.path))
                || has_runtime_region_import;

            if !has_list_import {
                let required_use = if base == "memRegion" {
                    "nC.runtime.region"
                } else {
                    "nC.runtime.list"
                };
                return Err(format!(
                    "E_RUNTIME_USE_001: runtime type '{}' requires explicit use/import '{}'; E_LIST_IMPORT_001: list runtime import unresolved",
                    base, required_use
                ));
            }

            for arg in args {
                validate_list_imports(program, arg)?;
            }

            Ok(())
        }

        SemaType::Union(items) => {
            for item in items {
                validate_list_imports(program, item)?;
            }
            Ok(())
        }

        SemaType::Array(inner) => validate_list_imports(program, inner),

        SemaType::Generic { args, .. } => {
            for arg in args {
                validate_list_imports(program, arg)?;
            }
            Ok(())
        }

        _ => Ok(()),
    }
}

fn is_binary_literal(expr: &Expr) -> bool {
    if is_number_literal_expr(expr) {
        return true;
    }

    match expr {
        Expr::Bool(_) | Expr::String(_) => true,
        Expr::Identifier(name) if name == "null" => true,
        Expr::Unary { op, expr } => {
            matches!(op, UnaryOp::Plus | UnaryOp::Minus) && is_number_literal_expr(expr)
        }
        _ => false,
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PointerState {
    Uninit,
    Null,
    Bound,
    Invalid,
}

const E_PTR_NULL_DEREF: &str = "E_PTR_NULL_DEREF_001";
const E_PTR_OUT_OF_BOUNDS: &str = "E_PTR_OUT_OF_BOUNDS_001";
const E_PTR_STALE_SITE: &str = "E_PTR_STALE_SITE_001";
const E_PTR_ALIAS_MUT: &str = "E_PTR_ALIAS_MUT_001";
const E_PTR_ALIGNMENT: &str = "E_PTR_ALIGNMENT_001";
const E_PTR_PROVENANCE: &str = "E_PTR_PROVENANCE_001";
const E_PTR_TYPE: &str = "E_PTR_TYPE_001";
#[allow(dead_code)]
const E_PTR_FFI_CONTRACT: &str = "E_PTR_FFI_CONTRACT_001";

fn pointer_diag(code: &str, message: impl AsRef<str>) -> String {
    format!("{}: {}", code, message.as_ref())
}

fn is_null_expr(expr: &Expr) -> bool {
    matches!(expr, Expr::Identifier(name) if name == "null")
}

type AliasMap = HashMap<String, String>;
type FlowAliasMap = HashMap<String, String>;

fn register_alias(alias_map: &mut AliasMap, target: &str, source: &str) {
    alias_map.insert(target.to_string(), source.to_string());
}

#[derive(Debug, Clone, PartialEq)]
enum CompatKind {
    Exact,
    Upcast,
    Downcast,
    Forbidden,
}

#[derive(Clone, Copy)]
enum PtrKind<'a> {
    Bare,
    Typed { base: &'a str, inner: &'a SemaType },
}

fn is_pointer_generic_base(base: &str) -> bool {
    matches!(
        base,
        "ptr"
            | "ptr mut"
            | "ref"
            | "ref mut"
            | "site"
            | "memRegion"
            | "cap"
            | "member"
            | "pm"
            | "fn"
    )
}

fn pointer_base_compat_kind(target: &str, source: &str) -> CompatKind {
    if target == source {
        return CompatKind::Exact;
    }

    match (target, source) {
        ("ptr", "ptr mut") | ("ref", "ref mut") | ("memRegion", "site") => CompatKind::Upcast,
        _ => CompatKind::Forbidden,
    }
}

fn ptr_kind(ty: &SemaType) -> Option<PtrKind<'_>> {
    match ty {
        SemaType::Simple(name) if name == "ptr" => Some(PtrKind::Bare),
        SemaType::Generic { base, args } if is_pointer_generic_base(base) && !args.is_empty() => {
            Some(PtrKind::Typed {
                base,
                inner: &args[0],
            })
        }
        _ => None,
    }
}

fn is_addr_type(ty: &SemaType) -> bool {
    matches!(ty, SemaType::Simple(name) if name == "addr")
}

fn is_raw_pointer_type(ty: &SemaType) -> bool {
    match ty {
        SemaType::Simple(name) => matches!(name.as_str(), "addr" | "ptr" | "skk*" | "skk**"),
        SemaType::Generic { base, args } => {
            matches!(
                base.as_str(),
                "ptr" | "ptr mut" | "cap" | "member" | "pm" | "fn"
            ) && !args.is_empty()
        }
        SemaType::Union(items) => {
            !items.is_empty()
                && items
                    .iter()
                    .all(|item| is_bind_null_type(item) || is_raw_pointer_type(item))
                && items.iter().any(is_raw_pointer_type)
        }
        _ => false,
    }
}

fn is_skk_star_type(ty: &SemaType) -> bool {
    matches!(ty, SemaType::Simple(name) if name == "skk*")
}

fn ptr_inner_types_match(target: &SemaType, source: &SemaType) -> bool {
    type_compatible(target, source) && type_compatible(source, target)
}

fn scalar_byte_width(ty: &SemaType) -> Option<usize> {
    let SemaType::Simple(name) = ty else {
        return None;
    };
    match normalize_type_name(name) {
        "bool" | "byte" | "int8" | "uint8" | "sbyte" => Some(1),
        "int16" | "uint16" | "word" | "sword" => Some(2),
        "int32" | "uint32" | "dword" | "ft32" | "int" | "uint" => Some(4),
        "int64" | "uint64" | "qword" | "ft64" | "ft" | "addr" | "sqword" => Some(8),
        _ => None,
    }
}

fn is_byte_view_scalar(ty: &SemaType) -> bool {
    matches!(
        ty,
        SemaType::Simple(name)
            if matches!(normalize_type_name(name), "byte" | "sbyte" | "int8" | "uint8")
    )
}

fn ptr_byte_view_reinterpret_compat(target: &SemaType, source: &SemaType) -> bool {
    if !is_byte_view_scalar(target) && !is_byte_view_scalar(source) {
        return false;
    }

    scalar_byte_width(target).is_some() && scalar_byte_width(source).is_some()
}

fn pointer_compat_kind(target: &SemaType, source: &SemaType) -> CompatKind {
    if let (Some(target_ptr), Some(source_ptr)) = (ptr_kind(target), ptr_kind(source)) {
        return match (target_ptr, source_ptr) {
            (PtrKind::Bare, PtrKind::Bare) => CompatKind::Exact,
            (PtrKind::Bare, PtrKind::Typed { .. }) => CompatKind::Upcast,
            (PtrKind::Typed { .. }, PtrKind::Bare) => CompatKind::Downcast,
            (
                PtrKind::Typed {
                    base: target_base,
                    inner: target_inner,
                },
                PtrKind::Typed {
                    base: source_base,
                    inner: source_inner,
                },
            ) => {
                if ptr_inner_types_match(target_inner, source_inner)
                    || ptr_byte_view_reinterpret_compat(target_inner, source_inner)
                {
                    pointer_base_compat_kind(target_base, source_base)
                } else {
                    CompatKind::Forbidden
                }
            }
        };
    }

    if is_addr_type(target) && ptr_kind(source).is_some() {
        return CompatKind::Upcast;
    }

    if ptr_kind(target).is_some() && is_addr_type(source) {
        return CompatKind::Downcast;
    }

    if ptr_kind(target).is_some() && is_skk_star_type(source) {
        return CompatKind::Exact;
    }

    match (target, source) {
        (SemaType::Simple(t), SemaType::Simple(s)) if t == s => CompatKind::Exact,

        (SemaType::Simple(t), SemaType::Simple(s)) if t == "addr" && s == "ptr" => {
            CompatKind::Upcast
        }

        (SemaType::Simple(t), SemaType::Simple(s)) if t == "ptr" && s == "addr" => {
            CompatKind::Downcast
        }

        (SemaType::Simple(t), SemaType::Simple(s)) if t == "ptr" && s == "skk*" => {
            CompatKind::Exact
        }

        (SemaType::Simple(t), SemaType::Simple(s)) if t == "region" && s == "region" => {
            CompatKind::Exact
        }

        _ => CompatKind::Forbidden,
    }
}

fn resolve_alias(name: &str, alias_map: &AliasMap) -> Result<String, String> {
    let mut current = name.to_string();
    let mut visited = std::collections::HashSet::new();

    while let Some(next) = alias_map.get(&current) {
        if !visited.insert(current.clone()) {
            return Err(format!("alias cycle detected at '{}'", current));
        }
        current = next.clone();
    }

    Ok(current)
}

fn check_alias_compat(target_ty: &SemaType, source_ty: &SemaType) -> bool {
    if let SemaType::Union(items) = target_ty {
        return items.iter().any(|item| {
            if is_bind_null_type(item) {
                return false;
            }
            check_alias_compat(item, source_ty)
        });
    }

    if let SemaType::Union(items) = source_ty {
        return items.iter().all(|item| {
            if is_bind_null_type(item) {
                return true;
            }
            check_alias_compat(target_ty, item)
        });
    }

    if bind_source_matches_mem_region_target(target_ty, source_ty) {
        return true;
    }

    !matches!(
        pointer_compat_kind(target_ty, source_ty),
        CompatKind::Forbidden | CompatKind::Downcast
    )
}

fn bind_source_matches_mem_region_target(target_ty: &SemaType, source_ty: &SemaType) -> bool {
    let SemaType::Generic { base, args } = target_ty else {
        return false;
    };
    if base != "memRegion" || args.len() != 1 {
        return false;
    }
    let target_elem = &args[0];

    match source_ty {
        SemaType::Union(items) => items.iter().all(|item| {
            is_bind_null_type(item) || bind_source_matches_mem_region_target(target_ty, item)
        }),
        SemaType::Simple(s) => {
            s == "addr" || s == "ptr" || s == "skk*" || s == "skk**" || s == "region"
        }
        SemaType::Generic { base, args } if is_pointer_generic_base(base) && args.len() == 1 => {
            type_compatible(&args[0], target_elem) || type_compatible(target_elem, &args[0])
        }
        SemaType::Generic { base, args } if base == "memRegion" && args.len() == 1 => {
            type_compatible(&args[0], target_elem) && type_compatible(target_elem, &args[0])
        }
        _ => false,
    }
}

fn source_pointer_state_for_alias_projection(
    source_name: &str,
    target_ty: &SemaType,
    pointer_states: &HashMap<String, PointerState>,
) -> Result<PointerState, String> {
    if silent_pointer_acceptance_enabled() && is_raw_pointer_type(target_ty) {
        return Ok(PointerState::Bound);
    }

    match pointer_states.get(source_name) {
        Some(PointerState::Invalid) => Err(pointer_diag(
            E_PTR_STALE_SITE,
            format!("use of invalid pointer '{}' (stale site)", source_name),
        )),
        Some(PointerState::Uninit) if ptr_kind(target_ty).is_some() || is_addr_type(target_ty) => {
            Err(pointer_diag(
                E_PTR_PROVENANCE,
                format!("use of uninitialized pointer '{}'", source_name),
            ))
        }
        Some(PointerState::Uninit) => Ok(PointerState::Uninit),
        Some(PointerState::Null) => Ok(PointerState::Null),
        Some(PointerState::Bound) => Ok(PointerState::Bound),
        None => Ok(PointerState::Bound),
    }
}

fn pointer_state_for_self_bootstrap(
    name: &str,
    target_ty: &SemaType,
    pointer_states: &HashMap<String, PointerState>,
) -> Result<PointerState, String> {
    if silent_pointer_acceptance_enabled() && is_raw_pointer_type(target_ty) {
        return Ok(PointerState::Bound);
    }
    match pointer_states.get(name) {
        Some(PointerState::Invalid) => Err(pointer_diag(
            E_PTR_STALE_SITE,
            format!("use of invalid pointer '{}' (stale site)", name),
        )),
        Some(PointerState::Null) => Ok(PointerState::Null),
        _ => Ok(PointerState::Bound),
    }
}

fn flow_alias_root(name: &str, alias_map: &FlowAliasMap) -> String {
    let mut current = name.to_string();
    let mut visited = std::collections::HashSet::new();

    while let Some(next) = alias_map.get(&current) {
        if !visited.insert(current.clone()) {
            break;
        }
        current = next.clone();
    }

    current
}

fn flow_set_alias(target: &str, source: &str, alias_map: &mut FlowAliasMap) {
    let source_root = flow_alias_root(source, alias_map);
    if target == source_root {
        alias_map.remove(target);
        return;
    }
    alias_map.insert(target.to_string(), source_root);
}

fn flow_clear_alias(target: &str, alias_map: &mut FlowAliasMap) {
    alias_map.remove(target);
}

fn invalidate_pointer_alias_group(
    source_name: &str,
    pointer_states: &mut HashMap<String, PointerState>,
    alias_map: &FlowAliasMap,
) {
    let root = flow_alias_root(source_name, alias_map);
    let symbols: Vec<String> = pointer_states.keys().cloned().collect();

    for sym in symbols {
        if flow_alias_root(&sym, alias_map) == root {
            pointer_states.insert(sym, PointerState::Invalid);
        }
    }
}

fn validate_heap_manager_pointer_state(
    op: &str,
    source_name: &str,
    pointer_states: &HashMap<String, PointerState>,
) -> Result<(), String> {
    if silent_pointer_acceptance_enabled() {
        return Ok(());
    }

    match pointer_states.get(source_name) {
        Some(PointerState::Uninit) => Err(pointer_diag(
            E_PTR_PROVENANCE,
            format!("{} cannot use uninitialized pointer '{}'", op, source_name),
        )),
        Some(PointerState::Invalid) => Err(pointer_diag(
            E_PTR_STALE_SITE,
            format!(
                "{} cannot use invalid pointer '{}' (stale site)",
                op, source_name
            ),
        )),
        Some(PointerState::Null) => Err(pointer_diag(
            E_PTR_NULL_DEREF,
            format!("{} cannot use null pointer '{}'", op, source_name),
        )),
        _ => Ok(()),
    }
}

fn native_prelude_heap_manager_op(callee: &str) -> Option<HeapManagerOp> {
    match callee.split('<').next().unwrap_or(callee) {
        name if name.eq_ignore_ascii_case("alloc") => Some(HeapManagerOp::Alloc),
        name if name.eq_ignore_ascii_case("free") => Some(HeapManagerOp::Free),
        name if name.eq_ignore_ascii_case("realloc") => Some(HeapManagerOp::Realloc),
        name if name.eq_ignore_ascii_case("zero") => Some(HeapManagerOp::Zero),
        _ => None,
    }
}

fn apply_heap_manager_pointer_effect(
    op: HeapManagerOp,
    args: &[Expr],
    pointer_states: &mut HashMap<String, PointerState>,
    alias_map: &FlowAliasMap,
) -> Result<(), String> {
    if !op.requires_valid_pointer() {
        return Ok(());
    }

    if let Some(Expr::ContextRef(ctx)) = args.first() {
        if ctx.path.len() == 1 {
            let source_name = &ctx.path[0];
            validate_heap_manager_pointer_state(op.official_path(), source_name, pointer_states)?;
            if op.invalidates_alias_group() {
                invalidate_pointer_alias_group(source_name, pointer_states, alias_map);
            }
        }
    }

    Ok(())
}

fn validate_return_pointer_state(
    source_name: &str,
    return_ty: &SemaType,
    pointer_states: &HashMap<String, PointerState>,
) -> Result<(), String> {
    if silent_pointer_acceptance_enabled() && is_raw_pointer_type(return_ty) {
        return Ok(());
    }

    match pointer_states.get(source_name) {
        Some(PointerState::Uninit) => Err(pointer_diag(
            E_PTR_PROVENANCE,
            format!("return cannot use uninitialized pointer '{}'", source_name),
        )),
        Some(PointerState::Invalid) => Err(pointer_diag(
            E_PTR_STALE_SITE,
            format!(
                "return cannot use invalid pointer '{}' (stale site)",
                source_name
            ),
        )),
        _ => Ok(()),
    }
}

#[allow(clippy::too_many_arguments)]
fn apply_call_pointer_effects(
    program: &Program,
    current_container_name: &str,
    callee: &str,
    args: &[Expr],
    scope: &HashMap<String, SemaType>,
    current_context: &Option<Context>,
    pointer_states: &mut HashMap<String, PointerState>,
    alias_map: &FlowAliasMap,
) -> Result<(), String> {
    let callee_base = callee.split('<').next().unwrap_or(callee);
    if current_context.is_none()
        && matches!(
            callee_base,
            "await"
                | "spawn"
                | "join"
                | "channelCreate"
                | "send"
                | "sendBlocking"
                | "trySend"
                | "recv"
                | "tryRecv"
                | "recvBlocking"
        )
    {
        return Ok(());
    }
    let may_have_pointer_effects =
        FN_POINTER_EFFECT_NAMES.with(|cell| cell.borrow().contains(callee_base));
    if !may_have_pointer_effects {
        return Ok(());
    }
    let target_sig = resolve_call_target_signature(
        program,
        current_container_name,
        callee,
        args,
        scope,
        current_context,
    )?;
    apply_signature_pointer_effects(&target_sig, args, pointer_states, alias_map)
}

fn apply_signature_pointer_effects(
    target_sig: &FnSig,
    args: &[Expr],
    pointer_states: &mut HashMap<String, PointerState>,
    alias_map: &FlowAliasMap,
) -> Result<(), String> {
    let target_key = function_signature_key(target_sig);
    let call_effects = FN_POINTER_EFFECTS.with(|cell| cell.borrow().get(&target_key).cloned());
    let Some(call_effects) = call_effects else {
        return Ok(());
    };

    let op_name = format!("call '{}.{}'", target_sig.container, target_sig.name);

    let mut require_indices: Vec<usize> =
        call_effects.require_valid_params.iter().copied().collect();
    require_indices.sort_unstable();
    for idx in require_indices {
        if let Some(Expr::ContextRef(ctx)) = args.get(idx) {
            if ctx.path.len() == 1 {
                let source_name = &ctx.path[0];
                validate_heap_manager_pointer_state(&op_name, source_name, pointer_states)?;
            }
        }
    }

    let mut alias_conflicts: Vec<(usize, usize)> = call_effects
        .invalidates_then_requires
        .iter()
        .copied()
        .collect();
    alias_conflicts.sort_unstable();
    for (invalidated_idx, required_idx) in alias_conflicts {
        let Some(invalidated_arg) = args.get(invalidated_idx) else {
            continue;
        };
        let Some(required_arg) = args.get(required_idx) else {
            continue;
        };

        let Some(invalidated_symbol) = call_arg_simple_pointer_symbol(invalidated_arg) else {
            continue;
        };
        let Some(required_symbol) = call_arg_simple_pointer_symbol(required_arg) else {
            continue;
        };

        let invalidated_root = flow_alias_root(invalidated_symbol, alias_map);
        let required_root = flow_alias_root(required_symbol, alias_map);
        if invalidated_root == required_root {
            return Err(format!(
                "{} aliases consumed parameter #{} with later-required parameter #{} via pointer root '{}'",
                op_name,
                invalidated_idx + 1,
                required_idx + 1,
                invalidated_root
            ));
        }
    }

    let mut return_conflicts: Vec<(usize, usize)> = call_effects
        .invalidates_then_returns
        .iter()
        .copied()
        .collect();
    return_conflicts.sort_unstable();
    for (invalidated_idx, returned_idx) in return_conflicts {
        let Some(invalidated_arg) = args.get(invalidated_idx) else {
            continue;
        };
        let Some(returned_arg) = args.get(returned_idx) else {
            continue;
        };

        let Some(invalidated_symbol) = call_arg_simple_pointer_symbol(invalidated_arg) else {
            continue;
        };
        let Some(returned_symbol) = call_arg_simple_pointer_symbol(returned_arg) else {
            continue;
        };

        let invalidated_root = flow_alias_root(invalidated_symbol, alias_map);
        let returned_root = flow_alias_root(returned_symbol, alias_map);
        if invalidated_root == returned_root {
            return Err(format!(
                "{} returns pointer alias of consumed parameter #{} via parameter #{} (root '{}')",
                op_name,
                invalidated_idx + 1,
                returned_idx + 1,
                invalidated_root
            ));
        }
    }

    let mut invalidated_indices: Vec<usize> =
        call_effects.invalidated_params.iter().copied().collect();
    invalidated_indices.sort_unstable();
    for idx in invalidated_indices {
        let Some(arg) = args.get(idx) else {
            continue;
        };

        let Some(source_name) = call_arg_simple_pointer_symbol(arg) else {
            return Err(format!(
                "{} requires simple pointer symbol argument for ownership-sensitive parameter #{}",
                op_name,
                idx + 1
            ));
        };

        invalidate_pointer_alias_group(source_name, pointer_states, alias_map);
    }

    Ok(())
}

fn call_arg_simple_pointer_symbol(arg: &Expr) -> Option<&str> {
    match arg {
        Expr::ContextRef(ctx) if ctx.path.len() == 1 => Some(ctx.path[0].as_str()),
        _ => None,
    }
}

fn resolve_qualified_call_target_signature(
    program: &Program,
    current_container_name: &str,
    path: &[String],
    args: &[Expr],
    scope: &HashMap<String, SemaType>,
    current_context: &Option<Context>,
) -> Result<Option<FnSig>, String> {
    if path.len() != 2 {
        return Ok(None);
    }

    let container_name = &path[0];
    let func_name = &path[1];

    let arg_types: Vec<SemaType> = args
        .iter()
        .map(|a| infer_expr_type(program, current_container_name, a, scope, current_context))
        .collect::<Result<Vec<_>, _>>()?;

    let sig = FN_SIGS.with(|cell| {
        let index = cell.borrow();
        let Some(candidates) = index.get(func_name) else {
            return Ok(None);
        };

        let matches: Vec<&FnSig> = candidates
            .iter()
            .filter(|sig| sig.container == *container_name)
            .filter(|sig| sig.params.len() == arg_types.len())
            .filter(|sig| {
                sig.params
                    .iter()
                    .zip(&arg_types)
                    .all(|(expected, got)| type_compatible(got, expected))
            })
            .collect();

        if matches.len() > 1 {
            let rendered: Vec<String> = matches
                .iter()
                .map(|m| format!("{}::{}::{:?}", m.container, m.name, m.params))
                .collect();
            return Err(format!(
                "ambiguous qualified call '{}.{}' with candidates {}",
                container_name,
                func_name,
                rendered.join(", ")
            ));
        }

        Ok(matches.first().map(|sig| (*sig).clone()))
    })?;

    Ok(sig)
}

fn apply_heap_manager_effects_in_expr(
    program: &Program,
    current_container_name: &str,
    expr: &Expr,
    scope: &HashMap<String, SemaType>,
    current_context: &Option<Context>,
    pointer_states: &mut HashMap<String, PointerState>,
    alias_map: &FlowAliasMap,
) -> Result<(), String> {
    // With no tracked pointer there is no provenance state to validate or
    // invalidate. Scalar-heavy programs should not pay for a second AST walk.
    let program_has_pointer_effect_calls =
        FN_POINTER_EFFECT_NAMES.with(|cell| !cell.borrow().is_empty());
    if pointer_states.is_empty() && !program_has_pointer_effect_calls {
        return Ok(());
    }

    match expr {
        Expr::QualifiedCall { path, args } => {
            for arg in args {
                apply_heap_manager_effects_in_expr(
                    program,
                    current_container_name,
                    arg,
                    scope,
                    current_context,
                    pointer_states,
                    alias_map,
                )?;
            }

            if let Some(op) = HeapManagerOp::from_qualified_path(path) {
                apply_heap_manager_pointer_effect(op, args, pointer_states, alias_map)?;
            }

            if let Some(target_sig) = resolve_qualified_call_target_signature(
                program,
                current_container_name,
                path,
                args,
                scope,
                current_context,
            )? {
                apply_signature_pointer_effects(&target_sig, args, pointer_states, alias_map)?;
            }

            Ok(())
        }

        Expr::Call { callee, args } => {
            for arg in args {
                apply_heap_manager_effects_in_expr(
                    program,
                    current_container_name,
                    arg,
                    scope,
                    current_context,
                    pointer_states,
                    alias_map,
                )?;
            }
            if phase7_constructor_name(expr).is_some()
                || matches!(callee.as_str(), "isSome" | "isNone" | "isOk" | "isErr")
            {
                return Ok(());
            }
            if explicit_pointer_checks_enabled() {
                if let Some(op) = native_prelude_heap_manager_op(callee) {
                    apply_heap_manager_pointer_effect(op, args, pointer_states, alias_map)?;
                }
            }
            apply_call_pointer_effects(
                program,
                current_container_name,
                callee,
                args,
                scope,
                current_context,
                pointer_states,
                alias_map,
            )?;
            Ok(())
        }

        Expr::MethodCall { receiver, args, .. } => {
            apply_heap_manager_effects_in_expr(
                program,
                current_container_name,
                receiver,
                scope,
                current_context,
                pointer_states,
                alias_map,
            )?;
            for arg in args {
                apply_heap_manager_effects_in_expr(
                    program,
                    current_container_name,
                    arg,
                    scope,
                    current_context,
                    pointer_states,
                    alias_map,
                )?;
            }
            Ok(())
        }

        Expr::Index { target, index } => {
            apply_heap_manager_effects_in_expr(
                program,
                current_container_name,
                target,
                scope,
                current_context,
                pointer_states,
                alias_map,
            )?;
            apply_heap_manager_effects_in_expr(
                program,
                current_container_name,
                index,
                scope,
                current_context,
                pointer_states,
                alias_map,
            )
        }

        Expr::StrictCheckExpr { value, .. } => apply_heap_manager_effects_in_expr(
            program,
            current_container_name,
            value,
            scope,
            current_context,
            pointer_states,
            alias_map,
        ),

        Expr::VectorLiteral(items) | Expr::ArrayLiteral(items) => {
            for item in items {
                apply_heap_manager_effects_in_expr(
                    program,
                    current_container_name,
                    item,
                    scope,
                    current_context,
                    pointer_states,
                    alias_map,
                )?;
            }
            Ok(())
        }

        Expr::Binary { left, right, .. } => {
            apply_heap_manager_effects_in_expr(
                program,
                current_container_name,
                left,
                scope,
                current_context,
                pointer_states,
                alias_map,
            )?;
            apply_heap_manager_effects_in_expr(
                program,
                current_container_name,
                right,
                scope,
                current_context,
                pointer_states,
                alias_map,
            )
        }

        _ => Ok(()),
    }
}

fn analyze_binary_section(
    stmts: &[Stmt],
    scope: &mut HashMap<String, SemaType>,
    pointer_states: &mut HashMap<String, PointerState>,
) -> Result<(), String> {
    for stmt in stmts {
        match stmt {
            Stmt::Projection { target, ty, value } => {
                if !is_binary_literal(value) {
                    return Err(format!(
                        "binary section only accepts scalar literals, got {:?}",
                        value
                    ));
                }

                let AssignTarget::Context(target_ctx) = target else {
                    return Err("binary section does not allow mem[...] projection targets".into());
                };
                let target_ty = lower_type(ty);
                if target_ctx.path.len() == 1 {
                    let name = target_ctx.path[0].clone();
                    scope.insert(name.clone(), target_ty.clone());
                    if is_pointer_family_type(&target_ty) {
                        pointer_states.insert(name, PointerState::Bound);
                    }
                }
            }
            Stmt::Expr(Expr::String(value))
                if value.starts_with("profile ") || value.starts_with("target ") =>
            {
                // Compatibility surface in v1.0.1:
                // binary:
                //   profile stable;
                //   target x86_64;
            }
            other => {
                return Err(format!(
                    "binary section only accepts projection statements, got {:?}",
                    other
                ));
            }
        }
    }
    Ok(())
}

fn is_bind_null_type(ty: &SemaType) -> bool {
    matches!(ty, SemaType::Simple(s) if s == "null")
}

fn is_bind_pointer_like_type(ty: &SemaType) -> bool {
    match ty {
        SemaType::Simple(s) => {
            s == "ptr" || s == "addr" || s == "region" || s == "skk*" || s == "skk**" || s == "ref"
        }
        SemaType::Generic { base, args } => {
            (is_pointer_generic_base(base) || base == "memRegion") && args.len() == 1
        }
        _ => false,
    }
}

fn is_bind_base_type(ty: &SemaType) -> bool {
    match ty {
        SemaType::Union(items) => {
            !items.is_empty()
                && items
                    .iter()
                    .all(|item| is_bind_pointer_like_type(item) || is_bind_null_type(item))
        }
        _ => is_bind_pointer_like_type(ty),
    }
}

fn allows_null_assignment_type(ty: &SemaType) -> bool {
    type_explicitly_allows_null(ty)
}

fn type_explicitly_allows_null(ty: &SemaType) -> bool {
    matches!(ty, SemaType::Union(items) if items.iter().any(is_bind_null_type))
}

fn is_memory_addr_like(ty: &SemaType) -> bool {
    is_addr_type(ty) || is_integer_like(ty)
}

fn validate_bind_memory_addr_expr(
    expr: &Expr,
    scope: &HashMap<String, SemaType>,
) -> Result<(), String> {
    match expr {
        Expr::Number(_) => Ok(()),
        Expr::ContextRef(ctx) if ctx.path.len() == 1 => {
            let name = &ctx.path[0];
            let Some(ty) = scope.get(name) else {
                return Err(format!(
                    "bind mem target index '{}' not declared in stc",
                    name
                ));
            };
            if is_memory_addr_like(ty) {
                Ok(())
            } else {
                Err(format!(
                    "bind mem target index '{}' must be addr/int-like, got {:?}",
                    name, ty
                ))
            }
        }
        _ => Err(format!(
            "bind mem target index must be number or simple context ref, got {:?}",
            expr
        )),
    }
}

fn analyze_bind_section(
    program: &Program,
    current_container_name: &str,
    current_context: &Option<Context>,
    stmts: &[Stmt],
    scope: &mut HashMap<String, SemaType>,
    pointer_states: &mut HashMap<String, PointerState>,
    alias_map: &mut AliasMap,
) -> Result<(), String> {
    for stmt in stmts {
        match stmt {
            Stmt::Projection { target, ty, value } => {
                let target_ty = lower_type(ty);

                if let AssignTarget::Mem { addr } = target {
                    validate_bind_memory_addr_expr(addr, scope)?;
                    continue;
                }

                if !is_bind_base_type(&target_ty) {
                    return Err(format!(
                        "bind section only allows base pointer/address types, got {:?}",
                        target_ty
                    ));
                }

                let AssignTarget::Context(target_ctx) = target else {
                    return Err("bind target must be a simple declared symbol".into());
                };

                if target_ctx.path.len() != 1 {
                    return Err(format!(
                        "bind target must be a simple declared symbol, got {:?}",
                        target_ctx.path
                    ));
                }

                let target_name = target_ctx.path[0].clone();
                if !scope.contains_key(&target_name) {
                    return Err(format!("bind target '{}' not declared in stc", target_name));
                }

                if is_null_expr(value) {
                    match &target_ty {
                        SemaType::Simple(t) if t == "region" => {
                            return Err("region cannot be null".into());
                        }
                        _ if allows_null_assignment_type(&target_ty)
                            || silent_pointer_accepts_null_target(&target_ty) =>
                        {
                            scope.insert(target_name.clone(), target_ty.clone());
                            pointer_states.insert(target_name.clone(), PointerState::Null);
                            continue;
                        }
                        _ => {
                            return Err(pointer_diag(
                                E_PTR_NULL_DEREF,
                                format!(
                                    "null requires an explicit nullable pointer/address type, got {:?}",
                                    target_ty
                                ),
                            ));
                        }
                    }
                }

                let resulting_state = match &target_ty {
                    SemaType::Simple(t) if t == "skk**" => match value {
                        Expr::ContextRef(ctx) => {
                            if ctx.path.len() != 1 {
                                return Err(
                                    "bind skk** requires simple context reference source".into()
                                );
                            }

                            let source_name = &ctx.path[0];
                            if !scope.contains_key(source_name) {
                                return Err(format!(
                                    "bind source '{}' not declared in stc",
                                    source_name
                                ));
                            }

                            if source_name == &target_name {
                                pointer_state_for_self_bootstrap(
                                    &target_name,
                                    &target_ty,
                                    pointer_states,
                                )?
                            } else {
                                let resolved_source = match resolve_alias(source_name, alias_map) {
                                    Ok(v) => v,
                                    Err(_) => {
                                        pointer_states
                                            .insert(target_name.clone(), PointerState::Invalid);
                                        return Err(format!(
                                            "alias cycle detected at '{}'",
                                            source_name
                                        ));
                                    }
                                };
                                let src_ty = scope.get(&resolved_source).unwrap();
                                if src_ty != &target_ty {
                                    return Err(
                                        "bind skk** requires source to also be skk**".into()
                                    );
                                }

                                if resolved_source == target_name {
                                    pointer_states
                                        .insert(target_name.clone(), PointerState::Invalid);
                                    pointer_states
                                        .insert(source_name.to_string(), PointerState::Invalid);
                                    return Err(format!(
                                        "alias cycle detected at '{}'",
                                        target_name
                                    ));
                                }

                                register_alias(alias_map, &target_name, source_name);
                                source_pointer_state_for_alias_projection(
                                    &resolved_source,
                                    &target_ty,
                                    pointer_states,
                                )?
                            }
                        }
                        _ => return Err("bind skk** requires context reference source".into()),
                    },

                    SemaType::Simple(t) if t == "region" => match value {
                        Expr::ContextRef(ctx) => {
                            if ctx.path.len() != 1 {
                                return Err(
                                    "bind region requires simple context reference source".into()
                                );
                            }

                            let source_name = &ctx.path[0];
                            if !scope.contains_key(source_name) {
                                return Err(format!(
                                    "bind source '{}' not declared in stc",
                                    source_name
                                ));
                            }

                            if source_name == &target_name {
                                pointer_state_for_self_bootstrap(
                                    &target_name,
                                    &target_ty,
                                    pointer_states,
                                )?
                            } else {
                                let resolved_source = match resolve_alias(source_name, alias_map) {
                                    Ok(v) => v,
                                    Err(_) => {
                                        pointer_states
                                            .insert(target_name.clone(), PointerState::Invalid);
                                        return Err(format!(
                                            "alias cycle detected at '{}'",
                                            source_name
                                        ));
                                    }
                                };
                                let src_ty = scope.get(&resolved_source).unwrap();
                                if src_ty != &target_ty {
                                    return Err(
                                        "bind region requires source to also be region".into()
                                    );
                                }

                                if resolved_source == target_name {
                                    pointer_states
                                        .insert(target_name.clone(), PointerState::Invalid);
                                    pointer_states
                                        .insert(source_name.to_string(), PointerState::Invalid);
                                    return Err(format!(
                                        "alias cycle detected at '{}'",
                                        target_name
                                    ));
                                }

                                register_alias(alias_map, &target_name, source_name);
                                source_pointer_state_for_alias_projection(
                                    &resolved_source,
                                    &target_ty,
                                    pointer_states,
                                )?
                            }
                        }
                        _ => return Err("bind region requires context reference source".into()),
                    },

                    _ => match value {
                        Expr::ContextRef(ctx) => {
                            if ctx.path.len() != 1 {
                                return Err(format!(
                                    "bind source must be a simple declared symbol, got {:?}",
                                    ctx.path
                                ));
                            }

                            let source_name = &ctx.path[0];
                            if !scope.contains_key(source_name) {
                                return Err(format!(
                                    "bind source '{}' not declared in stc",
                                    source_name
                                ));
                            }

                            if source_name == &target_name {
                                pointer_state_for_self_bootstrap(
                                    &target_name,
                                    &target_ty,
                                    pointer_states,
                                )?
                            } else {
                                let resolved_source = match resolve_alias(source_name, alias_map) {
                                    Ok(v) => v,
                                    Err(_) => {
                                        pointer_states
                                            .insert(target_name.clone(), PointerState::Invalid);
                                        return Err(format!(
                                            "alias cycle detected at '{}'",
                                            source_name
                                        ));
                                    }
                                };
                                let src_ty = scope.get(&resolved_source).unwrap();

                                if !check_alias_compat(&target_ty, src_ty)
                                    && !silent_pointer_accepts_pointer_family(&target_ty, src_ty)
                                {
                                    return Err(pointer_diag(
                                        E_PTR_ALIAS_MUT,
                                        format!(
                                            "invalid aliasing between {:?} and {:?}",
                                            target_ty, src_ty
                                        ),
                                    ));
                                }

                                if resolved_source == target_name {
                                    pointer_states
                                        .insert(target_name.clone(), PointerState::Invalid);
                                    pointer_states
                                        .insert(source_name.to_string(), PointerState::Invalid);
                                    return Err(format!(
                                        "alias cycle detected at '{}'",
                                        target_name
                                    ));
                                }

                                register_alias(alias_map, &target_name, source_name);
                                source_pointer_state_for_alias_projection(
                                    &resolved_source,
                                    &target_ty,
                                    pointer_states,
                                )?
                            }
                        }

                        Expr::Number(_) => PointerState::Bound,

                        Expr::Call { .. } | Expr::QualifiedCall { .. } => {
                            let value_ty = infer_expr_type(
                                program,
                                current_container_name,
                                value,
                                scope,
                                current_context,
                            )?;

                            if uses_pointer_compat_path(&target_ty, &value_ty) {
                                if !pointer_types_compatible(&target_ty, &value_ty, value) {
                                    return Err(format!(
                                        "pointer bind type mismatch: cannot assign {:?} to {:?}",
                                        value_ty, target_ty
                                    ));
                                }
                            } else if !type_compatible(&value_ty, &target_ty) {
                                return Err(format!(
                                    "bind type mismatch: cannot assign {:?} to {:?}",
                                    value_ty, target_ty
                                ));
                            }

                            apply_heap_manager_effects_in_expr(
                                program,
                                current_container_name,
                                value,
                                scope,
                                current_context,
                                pointer_states,
                                alias_map,
                            )?;

                            PointerState::Bound
                        }

                        _ => {
                            return Err(format!(
                                "bind value must be context reference, numeric literal, or call expression, got {:?}",
                                value
                            ));
                        }
                    },
                };

                scope.insert(target_name.clone(), target_ty.clone());
                if is_pointer_family_type(&target_ty) {
                    pointer_states.insert(target_name.clone(), resulting_state);
                }
            }
            Stmt::StrictCheck { target, ty, value } => {
                let target_ty = lower_type(ty);

                let AssignTarget::Context(target_ctx) = target else {
                    return Err("bind strict check target must be a simple declared symbol".into());
                };
                if target_ctx.path.len() != 1 {
                    return Err(format!(
                        "bind strict check target must be a simple declared symbol, got {:?}",
                        target_ctx.path
                    ));
                }

                let target_name = target_ctx.path[0].clone();
                let Some(declared_ty) = scope.get(&target_name).cloned() else {
                    return Err(format!(
                        "bind strict check target '{}' not declared in stc",
                        target_name
                    ));
                };

                if !type_compatible(&declared_ty, &target_ty) {
                    return Err(format!(
                        "bind strict check target type mismatch: cannot check {:?} against {:?}",
                        declared_ty, target_ty
                    ));
                }

                if matches!(value, Expr::Dev(_)) {
                    continue;
                }

                let value_ty = infer_expr_type(
                    program,
                    current_container_name,
                    value,
                    scope,
                    current_context,
                )?;

                if uses_pointer_compat_path(&target_ty, &value_ty) {
                    if !pointer_types_compatible(&target_ty, &value_ty, value) {
                        return Err(format!(
                            "pointer bind strict-check type mismatch: cannot check {:?} as {:?}",
                            value_ty, target_ty
                        ));
                    }
                } else if !type_compatible(&value_ty, &target_ty) {
                    return Err(format!(
                        "bind strict-check type mismatch: cannot check {:?} as {:?}",
                        value_ty, target_ty
                    ));
                }

                apply_heap_manager_effects_in_expr(
                    program,
                    current_container_name,
                    value,
                    scope,
                    current_context,
                    pointer_states,
                    alias_map,
                )?;
            }
            Stmt::Expr(Expr::String(path)) => {
                let segments: Vec<String> = path.split('.').map(|part| part.to_string()).collect();
                if segments.len() >= 2 && segments[0] == "root" {
                    resolve_root_binary_kind(program, &segments).map(|_| ())?;
                    continue;
                }
                return Err(format!(
                    "bind section only accepts projection/strict-check statements, got {:?}",
                    Stmt::Expr(Expr::String(path.clone()))
                ));
            }

            other => {
                return Err(format!(
                    "bind section only accepts projection/strict-check statements, got {:?}",
                    other
                ));
            }
        }
    }

    Ok(())
}

fn is_known_list_symbol(name: &str) -> bool {
    matches!(
        name.to_ascii_lowercase().as_str(),
        "listcreate"
            | "listcreatewithcapacity"
            | "listfromarray"
            | "listlen"
            | "listcapacity"
            | "listisempty"
            | "listadd"
            | "listpush"
            | "listpop"
            | "listget"
            | "listset"
            | "listinsert"
            | "listremoveat"
            | "listclear"
            | "listcontains"
            | "listindexof"
            | "listslice"
            | "listasarray"
            | "listasregion"
            | "listclone"
            | "listcopy"
            | "listmove"
            | "listswap"
    )
}

fn unresolved_list_symbol_import(path: &[String]) -> Option<String> {
    fn is_list_namespace_segment(name: &str) -> bool {
        matches!(
            name.to_ascii_lowercase().as_str(),
            "list" | "queue" | "core" | "index" | "memory"
        )
    }

    match path {
        [a, b, c, d]
            if a.eq_ignore_ascii_case("nC")
                && b.eq_ignore_ascii_case("runtime")
                && c.eq_ignore_ascii_case("list")
                && !is_list_namespace_segment(d)
                && !is_known_list_symbol(d) =>
        {
            Some(d.clone())
        }
        _ => None,
    }
}

fn is_known_use_path(path: &[String]) -> bool {
    ncc_parser::is_known_use_import_path(path)
        || matches!(
            path,
            [a, b, c]
                if a.eq_ignore_ascii_case("nC")
                    && b.eq_ignore_ascii_case("list")
                    && is_list_family(c)
        )
        || matches!(
            path,
            [a, b, c, d]
                if a.eq_ignore_ascii_case("nC")
                    && b.eq_ignore_ascii_case("runtime")
                    && c.eq_ignore_ascii_case("list")
                    && is_known_list_symbol(d)
        )
        || matches!(
            path,
            [a, b, c]
                if a.eq_ignore_ascii_case("nC")
                    && b.eq_ignore_ascii_case("list")
                    && is_known_list_symbol(c)
        )
}

fn normalize_ffi_contract_key(raw: &str) -> String {
    raw.chars()
        .filter(|c| c.is_ascii_alphanumeric())
        .collect::<String>()
        .to_ascii_lowercase()
}

fn ffi_field_value<'a>(decl: &'a ForeignSymbolDecl, keys: &[&str]) -> Option<&'a str> {
    decl.fields.iter().find_map(|field| {
        let normalized = normalize_ffi_contract_key(&field.key);
        if keys
            .iter()
            .any(|candidate| normalized == normalize_ffi_contract_key(candidate))
        {
            Some(field.value.as_str())
        } else {
            None
        }
    })
}

fn ffi_has_field(decl: &ForeignSymbolDecl, keys: &[&str]) -> bool {
    ffi_field_value(decl, keys).is_some()
}

fn ffi_require_field(
    decl: &ForeignSymbolDecl,
    keys: &[&str],
    code: &str,
    message: &str,
) -> Result<(), String> {
    if ffi_has_field(decl, keys) {
        Ok(())
    } else {
        Err(format!("{}: {}", code, message))
    }
}

fn ffi_signature_text(decl: &ForeignSymbolDecl) -> String {
    ffi_field_value(decl, &["signature"])
        .unwrap_or_default()
        .to_ascii_lowercase()
}

fn ffi_signature_text_compact(decl: &ForeignSymbolDecl) -> String {
    ffi_signature_text(decl)
        .chars()
        .filter(|ch| !ch.is_whitespace())
        .collect()
}

fn ffi_signature_mentions_pointer_like(decl: &ForeignSymbolDecl) -> bool {
    let sig = ffi_signature_text_compact(decl);
    sig.contains("ptr<")
        || sig.contains("ptrmut<")
        || sig.contains("ref<")
        || sig.contains("refmut<")
        || sig.contains("site<")
        || sig.contains("memregion<")
}

fn validate_foreign_import_form(use_decl: &UseDecl) -> Result<(), String> {
    if use_decl.path.is_empty() || !use_decl.path[0].eq_ignore_ascii_case("foreign") {
        return Ok(());
    }

    if use_decl.path.len() < 2 {
        return Err(
            "E_FFI_IMPORT_CONTRACT_001: foreign import must be 'use foreign.<language>;'".into(),
        );
    }

    let lang = use_decl.path[1].to_ascii_lowercase();
    if lang == "machine" {
        return Err(
            "E_FFI_IMPORT_CONTRACT_001: foreign.machine is not official; use foreign.asm with a [@machine] bridge"
                .into(),
        );
    }

    if !matches!(lang.as_str(), "c" | "cpp" | "rust" | "asm") {
        return Err(format!(
            "E_FFI_IMPORT_UNKNOWN_001: unknown foreign language '{}'",
            use_decl.path[1]
        ));
    }

    if use_decl.path.len() != 2 || use_decl.wildcard {
        return Err(
            "E_FFI_IMPORT_CONTRACT_001: foreign import contracts must be declared in 'foreign:' blocks, not dotted import paths"
                .into(),
        );
    }

    Ok(())
}

fn use_decl_targets_foreign_asm(use_decl: &UseDecl) -> bool {
    matches!(
        use_decl.path.as_slice(),
        [head, language]
            if head.eq_ignore_ascii_case("foreign")
                && language.eq_ignore_ascii_case("asm")
                && !use_decl.wildcard
    )
}

fn program_has_machine_bridge(program: &Program) -> bool {
    program
        .containers
        .iter()
        .any(|container| matches!(container.context, Some(Context::Machine)))
}

fn validate_foreign_asm_bridge(use_decl: &UseDecl, has_machine_bridge: bool) -> Result<(), String> {
    if use_decl_targets_foreign_asm(use_decl) && !has_machine_bridge {
        return Err(
            "E_FFI_ASM_BRIDGE_001: foreign.asm requires a [@machine] bridge container".into(),
        );
    }
    Ok(())
}

fn validate_foreign_section_for_container(
    container: &ncc_parser::Container,
    decls: &[ForeignSymbolDecl],
) -> Result<(), String> {
    if matches!(container.context, Some(Context::Primitive)) {
        return Err("E_FFI_PRIMITIVE_CROSSING_001: FFI cannot cross primitive[@]".into());
    }
    if matches!(container.context, Some(Context::Machine)) {
        return Err(
            "E_FFI_IMPORT_CONTRACT_001: foreign section is not allowed in [@machine]".into(),
        );
    }
    if matches!(container.context, Some(Context::Kernel)) {
        return Err(
            "E_FFI_IMPORT_CONTRACT_001: foreign section is not allowed in [@kernel]".into(),
        );
    }

    for decl in decls {
        if decl.symbol.trim().is_empty() {
            return Err("E_PARSE_FFI_SYMBOL_001: foreign symbol name cannot be empty".into());
        }

        ffi_require_field(
            decl,
            &["abi"],
            "E_FFI_ABI_MISSING_001",
            "ffi symbol requires ABI contract",
        )?;
        ffi_require_field(
            decl,
            &["signature"],
            "E_FFI_SIGNATURE_MISSING_001",
            "ffi symbol requires signature contract",
        )?;
        ffi_require_field(
            decl,
            &["ownership"],
            "E_FFI_OWNERSHIP_001",
            "ffi symbol requires ownership contract",
        )?;
        ffi_require_field(
            decl,
            &["sideEffects", "side_effects"],
            "E_FFI_SIDE_EFFECT_001",
            "ffi symbol requires sideEffects contract",
        )?;

        if ffi_signature_mentions_pointer_like(decl) {
            ffi_require_field(
                decl,
                &["nullability"],
                E_PTR_FFI_CONTRACT,
                "pointer-like ffi signature requires nullability contract",
            )?;
        }

        let sig = ffi_signature_text(decl);
        let sig_compact = ffi_signature_text_compact(decl);
        if sig_compact.contains("list<")
            || sig_compact.contains("dinarray.unbinary")
            || sig_compact.contains("runtimeobject")
        {
            return Err(
                "E_FFI_TYPE_UNSUPPORTED_001: runtime/unbinary/list types cannot cross FFI directly"
                    .into(),
            );
        }
        if sig.contains("str") || sig.contains("text") {
            return Err(
                "E_FFI_STRING_BOUNDARY_001: str/text must use explicit FFI-safe representation"
                    .into(),
            );
        }
        if sig_compact.contains("result<") || sig_compact.contains("option<") {
            return Err(
                "E_FFI_RESULT_OPTION_BOUNDARY_001: Result/Option must use explicit FFI representation"
                    .into(),
            );
        }

        if let Some(side_effects) = ffi_field_value(decl, &["sideEffects", "side_effects"]) {
            let lowered = side_effects.to_ascii_lowercase();
            if lowered.contains("unknown") {
                return Err("E_FFI_SIDE_EFFECT_001: sideEffects=unknown is forbidden".into());
            }
            if lowered.contains("filesystem")
                || lowered.contains("process")
                || lowered.contains("network")
            {
                ffi_require_field(
                    decl,
                    &["capability"],
                    "E_FFI_CAPABILITY_001",
                    "dangerous sideEffects require capability contract",
                )?;
                ffi_require_field(
                    decl,
                    &["policy"],
                    "E_FFI_POLICY_001",
                    "dangerous sideEffects require policy contract",
                )?;
            }
        }

        let ownership = ffi_field_value(decl, &["ownership"])
            .unwrap_or_default()
            .to_ascii_lowercase();
        if ownership.contains("owned") || ownership.contains("moved") {
            ffi_require_field(
                decl,
                &[
                    "freeSymbol",
                    "free_symbol",
                    "destructorPolicy",
                    "destructor_policy",
                ],
                "E_FFI_FREE_CONTRACT_001",
                "owned/moved ffi ownership requires free/destructor contract",
            )?;
        }

        match decl.language {
            ForeignLanguage::C => {
                ffi_require_field(
                    decl,
                    &["layout", "repr"],
                    "E_FFI_LAYOUT_REQUIRED_001",
                    "C ffi requires layout/repr contract",
                )?;
                ffi_require_field(
                    decl,
                    &["header"],
                    "E_FFI_IMPORT_CONTRACT_001",
                    "C ffi requires header contract",
                )?;
                ffi_require_field(
                    decl,
                    &["library"],
                    "E_FFI_IMPORT_CONTRACT_001",
                    "C ffi requires library contract",
                )?;
            }
            ForeignLanguage::Cpp => {
                ffi_require_field(
                    decl,
                    &["exceptionBoundary", "exception_boundary"],
                    "E_FFI_CPP_EXCEPTION_BOUNDARY_001",
                    "C++ ffi requires exceptionBoundary contract",
                )?;
                ffi_require_field(
                    decl,
                    &["layout", "repr"],
                    "E_FFI_LAYOUT_REQUIRED_001",
                    "C++ ffi requires layout/repr contract",
                )?;
                if ffi_field_value(decl, &["exportedAs", "exported_as"])
                    .is_some_and(|value| value.to_ascii_lowercase().contains("mangled"))
                {
                    ffi_require_field(
                        decl,
                        &["cppAbi", "cpp_abi"],
                        "E_FFI_ABI_MISMATCH_001",
                        "mangled C++ symbols require cppAbi contract",
                    )?;
                }
            }
            ForeignLanguage::Rust => {
                ffi_require_field(
                    decl,
                    &["panicBoundary", "panic_boundary"],
                    "E_FFI_RUST_PANIC_BOUNDARY_001",
                    "Rust ffi requires panicBoundary contract",
                )?;
                ffi_require_field(
                    decl,
                    &["repr", "layout"],
                    "E_FFI_REPR_REQUIRED_001",
                    "Rust ffi requires repr/layout contract",
                )?;
            }
        }
    }

    Ok(())
}

fn context_compatible(from_ctx: &Option<Context>, to_ctx: &Option<Context>) -> bool {
    match (from_ctx, to_ctx) {
        (Some(Context::Root), _) => true,
        (_, Some(Context::Root)) => true,
        (Some(Context::Unknown(a)), Some(Context::Unknown(b))) => a == b,
        (Some(Context::Unknown(_)), Some(_)) => false,
        (Some(_), Some(Context::Unknown(_))) => false,
        (Some(a), Some(b)) => std::mem::discriminant(a) == std::mem::discriminant(b),
        _ => true,
    }
}

fn collect_same_file_functions(program: &Program) -> HashMap<String, Vec<String>> {
    let mut out = HashMap::new();

    for container in &program.containers {
        let mut funcs = Vec::new();

        for section in &container.sections {
            if let Section::Fn(items) = section {
                for f in items {
                    funcs.push(f.name.clone());
                }
            }
        }

        out.insert(container.name.clone(), funcs);
    }

    out
}

fn collect_local_functions(container: &ncc_parser::Container) -> Vec<String> {
    let mut out = Vec::new();

    for section in &container.sections {
        if let Section::Fn(items) = section {
            for f in items {
                out.push(f.name.clone());
            }
        }
    }

    out
}

