thread_local! {
    static FN_SIGS: RefCell<HashMap<String, Vec<FnSig>>> = RefCell::new(HashMap::new());
    static FN_RESOLUTION_CACHE: RefCell<HashMap<FnResolutionCacheKey, Result<FnSig, String>>> = RefCell::new(HashMap::new());
    static RECORD_TYPE_LAYOUT_CACHE: RefCell<Option<(RecordLayoutCacheKey, Rc<RecordTypeLayouts>)>> = const { RefCell::new(None) };
    static FN_POINTER_EFFECTS: RefCell<HashMap<String, FnPointerEffects>> = RefCell::new(HashMap::new());
    static FN_POINTER_EFFECT_NAMES: RefCell<HashSet<String>> = RefCell::new(HashSet::new());
    static HIGH_SURFACES: RefCell<HashMap<String, HighSurface>> = RefCell::new(HashMap::new());
    static HIGH_IMPLS: RefCell<Vec<HighImplSig>> = const { RefCell::new(Vec::new()) };
    static CURRENT_HIGH_BOUNDS: RefCell<Vec<GenericBound>> = const { RefCell::new(Vec::new()) };
    static CURRENT_FUNCTION_RETURN: RefCell<Option<SemaType>> = const { RefCell::new(None) };
    static CURRENT_POINTER_REGION_BOUNDS: RefCell<HashMap<String, usize>> = RefCell::new(HashMap::new());
    static CURRENT_POINTER_ADDR_LITERALS: RefCell<HashMap<String, i64>> = RefCell::new(HashMap::new());
    static CURRENT_SILENT_POINTER_ACCEPTANCE: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
    static CURRENT_EXPLICIT_POINTER_CHECKS: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
}

struct SilentPointerAcceptanceGuard {
    previous: bool,
}

impl Drop for SilentPointerAcceptanceGuard {
    fn drop(&mut self) {
        CURRENT_SILENT_POINTER_ACCEPTANCE.with(|cell| cell.set(self.previous));
    }
}

fn enter_silent_pointer_acceptance(enabled: bool) -> SilentPointerAcceptanceGuard {
    let previous = CURRENT_SILENT_POINTER_ACCEPTANCE.with(|cell| {
        let previous = cell.get();
        cell.set(enabled);
        previous
    });
    SilentPointerAcceptanceGuard { previous }
}

fn silent_pointer_acceptance_enabled() -> bool {
    CURRENT_SILENT_POINTER_ACCEPTANCE.with(|cell| cell.get())
}

fn silent_pointer_accepts_null_target(target_ty: &SemaType) -> bool {
    silent_pointer_acceptance_enabled() && is_raw_pointer_type(target_ty)
}

struct ExplicitPointerChecksGuard {
    previous: bool,
}

impl Drop for ExplicitPointerChecksGuard {
    fn drop(&mut self) {
        CURRENT_EXPLICIT_POINTER_CHECKS.with(|cell| cell.set(self.previous));
    }
}

fn enter_explicit_pointer_checks() -> ExplicitPointerChecksGuard {
    let previous = CURRENT_EXPLICIT_POINTER_CHECKS.with(|cell| {
        let previous = cell.get();
        cell.set(true);
        previous
    });
    ExplicitPointerChecksGuard { previous }
}

fn explicit_pointer_checks_enabled() -> bool {
    CURRENT_EXPLICIT_POINTER_CHECKS.with(|cell| cell.get())
}

fn silent_pointer_accepts_pointer_family(target_ty: &SemaType, source_ty: &SemaType) -> bool {
    silent_pointer_acceptance_enabled()
        && (is_raw_pointer_type(target_ty) || is_raw_pointer_type(source_ty))
}

fn function_signature_key(sig: &FnSig) -> String {
    format!(
        "{}::{}::<{:?}>::{:?}::{:?}",
        sig.container, sig.name, sig.type_params, sig.generic_bounds, sig.params
    )
}

fn split_top_level_signature_args(input: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut start = 0usize;
    let mut depth_angle = 0usize;
    let mut depth_paren = 0usize;
    let chars: Vec<char> = input.chars().collect();
    for (idx, ch) in chars.iter().enumerate() {
        match ch {
            '<' => depth_angle = depth_angle.saturating_add(1),
            '>' => depth_angle = depth_angle.saturating_sub(1),
            '(' => depth_paren = depth_paren.saturating_add(1),
            ')' => depth_paren = depth_paren.saturating_sub(1),
            ',' if depth_angle == 0 && depth_paren == 0 => {
                let piece = input[start..idx].trim();
                if !piece.is_empty() {
                    out.push(piece.to_string());
                }
                start = idx + 1;
            }
            _ => {}
        }
    }
    let tail = input[start..].trim();
    if !tail.is_empty() {
        out.push(tail.to_string());
    }
    out
}

fn parse_ffi_signature_type(token: &str) -> SemaType {
    let normalized = token.trim();
    if normalized.is_empty() {
        return SemaType::Unknown;
    }

    if let Some(parameters) = normalized.strip_prefix("fn(") {
        let mut depth = 1usize;
        let mut close = None;
        for (offset, ch) in parameters.char_indices() {
            match ch {
                '(' => depth = depth.saturating_add(1),
                ')' => {
                    depth = depth.saturating_sub(1);
                    if depth == 0 {
                        close = Some(offset);
                        break;
                    }
                }
                _ => {}
            }
        }
        if let Some(close) = close {
            let tail = parameters[close + 1..].trim();
            if let Some(return_type) = tail.strip_prefix("->") {
                let mut args = split_top_level_signature_args(&parameters[..close])
                    .iter()
                    .map(|item| parse_ffi_signature_type(item))
                    .collect::<Vec<_>>();
                args.push(parse_ffi_signature_type(return_type));
                return SemaType::Generic {
                    base: "fn".to_string(),
                    args,
                };
            }
        }
    }

    if let Some(inner) = normalized
        .strip_prefix('(')
        .and_then(|value| value.strip_suffix(')'))
    {
        return parse_ffi_signature_type(inner);
    }

    let union_parts = split_top_level_signature_args(&normalized.replace('|', ","));
    if normalized.contains('|') && union_parts.len() > 1 {
        return SemaType::Union(
            union_parts
                .iter()
                .map(|item| parse_ffi_signature_type(item))
                .collect(),
        );
    }

    if let Some((base, inner)) = normalized.split_once('<') {
        if let Some(inner) = inner.strip_suffix('>') {
            let args = split_top_level_signature_args(inner)
                .iter()
                .map(|item| parse_ffi_signature_type(item))
                .collect::<Vec<_>>();
            return SemaType::Generic {
                base: base.to_string(),
                args,
            };
        }
    }

    SemaType::Simple(normalized.to_string())
}

fn split_generic_callee(callee: &str) -> (String, Vec<SemaType>) {
    let Some((base, suffix)) = callee.split_once('<') else {
        return (callee.to_string(), Vec::new());
    };
    let Some(inner) = suffix.strip_suffix('>') else {
        return (callee.to_string(), Vec::new());
    };
    let args = split_top_level_signature_args(inner)
        .iter()
        .map(|arg| parse_ffi_signature_type(arg))
        .collect::<Vec<_>>();
    (base.trim().to_string(), args)
}

fn bind_high_generic_param(
    param: &str,
    actual: &SemaType,
    bindings: &mut HashMap<String, SemaType>,
) -> Result<(), String> {
    if matches!(actual, SemaType::Unknown) {
        return Err(format!(
            "E_HIGH_GENERIC_INFER_AMBIGUOUS_001: generic parameter '{}' could not be inferred",
            param
        ));
    }
    if matches!(actual, SemaType::Simple(name) if name.eq_ignore_ascii_case("any")) {
        return Err("E_HIGH_GENERIC_ANY_LEAK_001: generic any leak is forbidden".into());
    }
    if let Some(existing) = bindings.get(param) {
        if !type_compatible(actual, existing) || !type_compatible(existing, actual) {
            return Err(format!(
                "E_HIGH_GENERIC_INFER_AMBIGUOUS_001: conflicting inference for '{}': expected {}, got {}",
                param,
                render_sema_type(existing),
                render_sema_type(actual)
            ));
        }
        return Ok(());
    }
    bindings.insert(param.to_string(), actual.clone());
    Ok(())
}

fn bind_high_generic_type(
    expected: &SemaType,
    actual: &SemaType,
    params: &HashSet<String>,
    bindings: &mut HashMap<String, SemaType>,
) -> Result<(), String> {
    match expected {
        SemaType::Simple(name) if params.contains(name) => {
            bind_high_generic_param(name, actual, bindings)
        }
        SemaType::Simple(name) => {
            if name.eq_ignore_ascii_case("any") {
                return Err("E_HIGH_GENERIC_ANY_LEAK_001: generic any leak is forbidden".into());
            }
            if type_compatible(actual, expected) {
                Ok(())
            } else {
                Err(format!(
                    "E_HIGH_GENERIC_TYPE_MISMATCH_001: expected {}, got {}",
                    render_sema_type(expected),
                    render_sema_type(actual)
                ))
            }
        }
        SemaType::Array(expected_inner) => match actual {
            SemaType::Array(actual_inner) | SemaType::Vector(actual_inner) => {
                bind_high_generic_type(expected_inner, actual_inner, params, bindings)
            }
            SemaType::Generic { base, args }
                if base.eq_ignore_ascii_case("array") && !args.is_empty() =>
            {
                bind_high_generic_type(expected_inner, &args[0], params, bindings)
            }
            _ => Err(format!(
                "E_HIGH_GENERIC_TYPE_MISMATCH_001: expected {}, got {}",
                render_sema_type(expected),
                render_sema_type(actual)
            )),
        },
        SemaType::Vector(expected_inner) => match actual {
            SemaType::Vector(actual_inner) | SemaType::Array(actual_inner) => {
                bind_high_generic_type(expected_inner, actual_inner, params, bindings)
            }
            SemaType::Generic { base, args } if is_list_family(base) && !args.is_empty() => {
                bind_high_generic_type(expected_inner, &args[0], params, bindings)
            }
            _ => Err(format!(
                "E_HIGH_GENERIC_TYPE_MISMATCH_001: expected {}, got {}",
                render_sema_type(expected),
                render_sema_type(actual)
            )),
        },
        SemaType::Generic { base, args } => {
            if params.contains(base) {
                return Err(
                    "E_HIGH_GENERIC_HKT_DEFERRED_001: higher-kinded generic parameters are deferred"
                        .into(),
                );
            }
            match actual {
                SemaType::Generic {
                    base: actual_base,
                    args: actual_args,
                } if base.eq_ignore_ascii_case(actual_base) && args.len() == actual_args.len() => {
                    for (expected_arg, actual_arg) in args.iter().zip(actual_args.iter()) {
                        bind_high_generic_type(expected_arg, actual_arg, params, bindings)?;
                    }
                    Ok(())
                }
                SemaType::Vector(actual_inner) if is_list_family(base) && args.len() == 1 => {
                    bind_high_generic_type(&args[0], actual_inner, params, bindings)
                }
                SemaType::Array(actual_inner)
                    if base.eq_ignore_ascii_case("array") && !args.is_empty() =>
                {
                    bind_high_generic_type(&args[0], actual_inner, params, bindings)
                }
                _ => Err(format!(
                    "E_HIGH_GENERIC_TYPE_MISMATCH_001: expected {}, got {}",
                    render_sema_type(expected),
                    render_sema_type(actual)
                )),
            }
        }
        SemaType::Union(items) => match actual {
            SemaType::Union(actual_items) => {
                let mut trial_bindings = bindings.clone();
                for actual_item in actual_items {
                    let mut matched = false;
                    for expected_item in items {
                        let mut candidate_bindings = trial_bindings.clone();
                        if bind_high_generic_type(
                            expected_item,
                            actual_item,
                            params,
                            &mut candidate_bindings,
                        )
                        .is_ok()
                        {
                            trial_bindings = candidate_bindings;
                            matched = true;
                            break;
                        }
                    }
                    if !matched {
                        return Err(format!(
                            "E_HIGH_GENERIC_TYPE_MISMATCH_001: expected {}, got {}",
                            render_sema_type(expected),
                            render_sema_type(actual)
                        ));
                    }
                }
                *bindings = trial_bindings;
                Ok(())
            }
            _ => {
                for expected_item in items {
                    let mut candidate_bindings = bindings.clone();
                    if bind_high_generic_type(
                        expected_item,
                        actual,
                        params,
                        &mut candidate_bindings,
                    )
                    .is_ok()
                    {
                        *bindings = candidate_bindings;
                        return Ok(());
                    }
                }
                Err(format!(
                    "E_HIGH_GENERIC_TYPE_MISMATCH_001: expected {}, got {}",
                    render_sema_type(expected),
                    render_sema_type(actual)
                ))
            }
        },
        SemaType::Unknown => Ok(()),
    }
}

fn resolve_associated_type_for_concrete(
    param: &str,
    item: &str,
    concrete: &SemaType,
    bounds: &[GenericBound],
) -> Result<AssociatedTypeResolved, String> {
    let surfaces = HIGH_SURFACES.with(|cell| cell.borrow().clone());
    let mut matches = Vec::new();
    for bound in bounds.iter().filter(|bound| bound.param == param) {
        let Some(surface_name) = type_name_base(&bound.bound) else {
            continue;
        };
        let Some(surface) = surfaces.get(&surface_name.to_ascii_lowercase()) else {
            continue;
        };
        if !surface.associated_types.iter().any(|name| name == item) {
            continue;
        }
        let resolved = HIGH_IMPLS.with(|cell| {
            cell.borrow()
                .iter()
                .filter(|imp| {
                    imp.surface_name.eq_ignore_ascii_case(surface_name)
                        && type_compatible(&imp.for_type, concrete)
                        && type_compatible(concrete, &imp.for_type)
                })
                .filter_map(|imp| imp.associated_type_bindings.get(item).cloned())
                .collect::<Vec<_>>()
        });
        matches.extend(resolved);
    }
    if matches.is_empty() {
        return Err(format!(
            "E_HIGH_ASSOC_TYPE_UNKNOWN_001: associated type projection '{}.{}' could not be resolved",
            param, item
        ));
    }
    let first = matches[0].clone();
    if matches.iter().any(|candidate| candidate != &first) {
        return Err(format!(
            "E_HIGH_ASSOC_TYPE_AMBIGUOUS_001: associated type projection '{}.{}' is ambiguous",
            param, item
        ));
    }
    Ok(AssociatedTypeResolved {
        projection: format!("{param}.{item}"),
        resolved: first,
    })
}

fn substitute_high_generic_type(
    ty: &SemaType,
    params: &HashSet<String>,
    bindings: &HashMap<String, SemaType>,
    bounds: &[GenericBound],
) -> Result<SemaType, String> {
    match ty {
        SemaType::Simple(name) if name.contains('.') => {
            let Some((param, item)) = name.split_once('.') else {
                return Ok(ty.clone());
            };
            if !params.contains(param) {
                return Ok(ty.clone());
            }
            let Some(concrete) = bindings.get(param) else {
                return Err(format!(
                    "E_HIGH_ASSOC_TYPE_PROJECTION_001: projection '{}.{}' has no concrete receiver",
                    param, item
                ));
            };
            let resolved = resolve_associated_type_for_concrete(param, item, concrete, bounds)?;
            let _projection = resolved.projection.clone();
            Ok(resolved.resolved)
        }
        SemaType::Simple(name) if params.contains(name) => {
            bindings.get(name).cloned().ok_or_else(|| {
                format!(
                    "E_HIGH_GENERIC_INFER_RETURN_ONLY_001: generic parameter '{}' appears only in return position",
                    name
                )
            })
        }
        SemaType::Simple(_) | SemaType::Unknown => Ok(ty.clone()),
        SemaType::Array(inner) => Ok(SemaType::Array(Box::new(substitute_high_generic_type(
            inner, params, bindings, bounds,
        )?))),
        SemaType::Vector(inner) => Ok(SemaType::Vector(Box::new(substitute_high_generic_type(
            inner, params, bindings, bounds,
        )?))),
        SemaType::Union(items) => Ok(SemaType::Union(
            items
                .iter()
                .map(|item| substitute_high_generic_type(item, params, bindings, bounds))
                .collect::<Result<Vec<_>, _>>()?,
        )),
        SemaType::Generic { base, args } => Ok(SemaType::Generic {
            base: base.clone(),
            args: args
                .iter()
                .map(|arg| substitute_high_generic_type(arg, params, bindings, bounds))
                .collect::<Result<Vec<_>, _>>()?,
        }),
    }
}

fn type_name_contains_dynamic_dispatch(ty: &TypeName) -> bool {
    match ty {
        TypeName::Simple(name) => name.eq_ignore_ascii_case("dyn"),
        TypeName::Generic { base, args } => {
            base.eq_ignore_ascii_case("dyn") || args.iter().any(type_name_contains_dynamic_dispatch)
        }
        TypeName::Array(inner) | TypeName::Vector(inner) => {
            type_name_contains_dynamic_dispatch(inner)
        }
        TypeName::Union(items) => items.iter().any(type_name_contains_dynamic_dispatch),
    }
}

fn type_name_mentions_hkt_param(ty: &TypeName, params: &HashSet<String>) -> bool {
    match ty {
        TypeName::Generic { base, args } => {
            params.contains(base)
                || args
                    .iter()
                    .any(|arg| type_name_mentions_hkt_param(arg, params))
        }
        TypeName::Array(inner) | TypeName::Vector(inner) => {
            type_name_mentions_hkt_param(inner, params)
        }
        TypeName::Union(items) => items
            .iter()
            .any(|item| type_name_mentions_hkt_param(item, params)),
        TypeName::Simple(_) => false,
    }
}

fn validate_high_bound_type_arg(
    ty: &TypeName,
    params: &HashSet<String>,
    surfaces: &HashMap<String, HighSurface>,
) -> Result<(), String> {
    match ty {
        TypeName::Simple(name) => {
            if params.contains(name) || high_generic_builtin_type(name) {
                return Ok(());
            }
            if name.eq_ignore_ascii_case("any") {
                return Err("E_HIGH_GENERIC_ANY_LEAK_001: generic any leak is forbidden".into());
            }
            if runtime_generic_param_name(name) {
                return Err(format!(
                    "E_HIGH_BOUND_UNKNOWN_PARAM_001: generic bound references undeclared parameter '{}'",
                    name
                ));
            }
            Ok(())
        }
        TypeName::Array(inner) | TypeName::Vector(inner) => {
            validate_high_bound_type_arg(inner, params, surfaces)
        }
        TypeName::Union(items) => {
            for item in items {
                validate_high_bound_type_arg(item, params, surfaces)?;
            }
            Ok(())
        }
        TypeName::Generic { base, args } => {
            if params.contains(base) {
                return Err(
                    "E_HIGH_BOUND_HKT_DEFERRED_001: higher-kinded bounds are deferred".into(),
                );
            }
            if surfaces.contains_key(&base.to_ascii_lowercase()) {
                return Err(format!(
                    "E_HIGH_BOUND_NESTED_001: nested trait/interface bound '{}' is not part of Phase 4",
                    base
                ));
            }
            if !high_generic_builtin_type(base)
                && !is_list_family(base)
                && !base.eq_ignore_ascii_case("array")
            {
                return Err(format!(
                    "E_HIGH_BOUND_UNKNOWN_TYPE_001: bound type argument '{}' is not known",
                    base
                ));
            }
            for arg in args {
                validate_high_bound_type_arg(arg, params, surfaces)?;
            }
            Ok(())
        }
    }
}

fn validate_high_bound_decl(
    bound: &GenericBound,
    params: &HashSet<String>,
    surfaces: &HashMap<String, HighSurface>,
) -> Result<(), String> {
    if !params.contains(&bound.param) {
        return Err(format!(
            "E_HIGH_BOUND_UNKNOWN_PARAM_001: generic bound references undeclared parameter '{}'",
            bound.param
        ));
    }
    if let Some(value_type) = const_generic_bound_type(bound) {
        return validate_const_generic_decl_type(&bound.param, value_type);
    }
    if type_name_contains_dynamic_dispatch(&bound.bound) {
        return Err(
            "E_HIGH_BOUND_DYNAMIC_DISPATCH_DEFERRED_001: dynamic dispatch is deferred".into(),
        );
    }
    if type_name_mentions_hkt_param(&bound.bound, params) {
        return Err("E_HIGH_BOUND_HKT_DEFERRED_001: higher-kinded bounds are deferred".into());
    }

    let Some(surface_name) = type_name_base(&bound.bound) else {
        return Err("E_HIGH_BOUND_UNKNOWN_TRAIT_001: bound must name a trait/interface".into());
    };
    let Some(surface) = surfaces.get(&surface_name.to_ascii_lowercase()) else {
        return Err(format!(
            "E_HIGH_BOUND_UNKNOWN_TRAIT_001: unknown trait/interface bound '{}'",
            surface_name
        ));
    };
    let args = type_name_args(&bound.bound);
    if args.len() != surface.generic_params.len() {
        return Err(format!(
            "E_HIGH_BOUND_ARITY_001: bound '{}' expects {} arguments, got {}",
            surface.name,
            surface.generic_params.len(),
            args.len()
        ));
    }
    for arg in args {
        validate_high_bound_type_arg(arg, params, surfaces)?;
    }
    Ok(())
}

fn high_impl_satisfies_bound(imp: &HighImplSig, bound: &GenericBound, concrete: &SemaType) -> bool {
    let Some(surface_name) = type_name_base(&bound.bound) else {
        return false;
    };
    if !imp.surface_name.eq_ignore_ascii_case(surface_name) {
        return false;
    }
    type_compatible(&imp.for_type, concrete) && type_compatible(concrete, &imp.for_type)
}

fn validate_resolved_high_bounds(
    bounds: &[GenericBound],
    bindings: &HashMap<String, SemaType>,
) -> Result<(), String> {
    for bound in bounds {
        let Some(concrete) = bindings.get(&bound.param) else {
            return Err(format!(
                "E_HIGH_BOUND_UNSATISFIED_001: bound for '{}' has no inferred concrete type",
                bound.param
            ));
        };
        if let Some(value_type) = const_generic_bound_type(bound) {
            validate_const_generic_value(&bound.param, value_type, concrete)?;
            continue;
        }
        let matches = HIGH_IMPLS.with(|cell| {
            cell.borrow()
                .iter()
                .filter(|imp| high_impl_satisfies_bound(imp, bound, concrete))
                .count()
        });
        if matches == 0 {
            return Err(format!(
                "E_HIGH_BOUND_UNSATISFIED_001: type '{}' does not satisfy bound '{}'",
                render_sema_type(concrete),
                render_type_name(&bound.bound)
            ));
        }
        if matches > 1 {
            return Err(format!(
                "E_HIGH_TRAIT_AMBIGUOUS_IMPL_001: bound '{}' for '{}' has ambiguous impls",
                render_type_name(&bound.bound),
                render_sema_type(concrete)
            ));
        }
    }
    Ok(())
}

fn const_generic_bound_type(bound: &GenericBound) -> Option<&TypeName> {
    match &bound.bound {
        TypeName::Generic { base, args }
            if base.eq_ignore_ascii_case("const") && args.len() == 1 =>
        {
            args.first()
        }
        _ => None,
    }
}

fn const_generic_param_type(bounds: &[GenericBound], param: &str) -> Option<SemaType> {
    bounds
        .iter()
        .find(|bound| bound.param == param)
        .and_then(const_generic_bound_type)
        .map(lower_type)
}

fn validate_const_generic_decl_type(param: &str, value_type: &TypeName) -> Result<(), String> {
    let TypeName::Simple(name) = value_type else {
        return Err(format!(
            "E_HIGH_CONST_GENERIC_TYPE_001: const parameter '{}' requires an integral scalar type",
            param
        ));
    };
    let normalized = normalize_type_name(name);
    if matches!(
        normalized,
        "byte"
            | "sbyte"
            | "word"
            | "sword"
            | "dword"
            | "sdword"
            | "qword"
            | "sqword"
            | "int"
            | "uint"
            | "int8"
            | "uint8"
            | "int16"
            | "uint16"
            | "int32"
            | "uint32"
            | "int64"
            | "uint64"
            | "isize"
            | "usize"
    ) {
        Ok(())
    } else {
        Err(format!(
            "E_HIGH_CONST_GENERIC_TYPE_001: const parameter '{}' requires an integral scalar type, got '{}'",
            param, name
        ))
    }
}

fn validate_const_generic_value(
    param: &str,
    value_type: &TypeName,
    concrete: &SemaType,
) -> Result<(), String> {
    validate_const_generic_decl_type(param, value_type)?;
    let SemaType::Simple(raw) = concrete else {
        return Err(format!(
            "E_HIGH_CONST_GENERIC_VALUE_001: const parameter '{}' requires an integer literal",
            param
        ));
    };
    let value = sema_parse_integer_literal(raw).ok_or_else(|| {
        format!(
            "E_HIGH_CONST_GENERIC_VALUE_001: const parameter '{}' requires an integer literal, got '{}'",
            param, raw
        )
    })?;
    let TypeName::Simple(type_name) = value_type else {
        unreachable!("const declaration type was validated")
    };
    let normalized = normalize_type_name(type_name);
    let fits = match normalized {
        "byte" | "uint8" => (0..=u8::MAX as i64).contains(&value),
        "sbyte" | "int8" => (i8::MIN as i64..=i8::MAX as i64).contains(&value),
        "word" | "uint16" => (0..=u16::MAX as i64).contains(&value),
        "sword" | "int16" => (i16::MIN as i64..=i16::MAX as i64).contains(&value),
        "dword" | "uint32" | "uint" => (0..=u32::MAX as i64).contains(&value),
        "sdword" | "int32" | "int" => (i32::MIN as i64..=i32::MAX as i64).contains(&value),
        "qword" | "uint64" | "usize" => value >= 0,
        "sqword" | "int64" | "isize" => true,
        _ => false,
    };
    if fits {
        Ok(())
    } else {
        Err(format!(
            "E_HIGH_CONST_GENERIC_RANGE_001: value '{}' does not fit const parameter '{}: {}'",
            raw, param, type_name
        ))
    }
}

fn resolve_high_generic_candidate(
    cand: &FnSig,
    arg_types: &[SemaType],
    explicit_type_args: &[SemaType],
) -> Result<FnSig, String> {
    if cand.params.len() != arg_types.len() {
        return Err(format!(
            "no matching function '{}' for {} arguments",
            cand.name,
            arg_types.len()
        ));
    }

    if cand.type_params.is_empty() {
        if !explicit_type_args.is_empty() {
            return Err(format!(
                "E_HIGH_GENERIC_ARITY_001: function '{}' is not generic but received {} type arguments",
                cand.name,
                explicit_type_args.len()
            ));
        }
        for (expected, got) in cand.params.iter().zip(arg_types.iter()) {
            if !type_compatible(got, expected) {
                return Err(format!(
                    "no matching function '{}' for argument: expected {}, got {}",
                    cand.name,
                    render_sema_type(expected),
                    render_sema_type(got)
                ));
            }
        }
        return Ok(cand.clone());
    }

    if !explicit_type_args.is_empty() && explicit_type_args.len() != cand.type_params.len() {
        return Err(format!(
            "E_HIGH_GENERIC_ARITY_001: function '{}' expects {} type arguments, got {}",
            cand.name,
            cand.type_params.len(),
            explicit_type_args.len()
        ));
    }

    let params: HashSet<String> = cand.type_params.iter().cloned().collect();
    let mut bindings: HashMap<String, SemaType> = HashMap::new();
    for (name, explicit) in cand.type_params.iter().zip(explicit_type_args.iter()) {
        bind_high_generic_param(name, explicit, &mut bindings)?;
    }

    for (expected, actual) in cand.params.iter().zip(arg_types.iter()) {
        bind_high_generic_type(expected, actual, &params, &mut bindings)?;
    }

    for name in &cand.type_params {
        if !bindings.contains_key(name) {
            return Err(format!(
                "E_HIGH_GENERIC_INFER_RETURN_ONLY_001: generic parameter '{}' could not be inferred from arguments",
                name
            ));
        }
    }
    validate_resolved_high_bounds(&cand.generic_bounds, &bindings)?;

    Ok(FnSig {
        container: cand.container.clone(),
        name: cand.name.clone(),
        type_params: cand.type_params.clone(),
        generic_bounds: cand.generic_bounds.clone(),
        params: cand
            .params
            .iter()
            .map(|param| {
                substitute_high_generic_type(param, &params, &bindings, &cand.generic_bounds)
            })
            .collect::<Result<Vec<_>, _>>()?,
        return_type: substitute_high_generic_type(
            &cand.return_type,
            &params,
            &bindings,
            &cand.generic_bounds,
        )?,
    })
}

fn parse_ffi_signature_types(decl: &ForeignSymbolDecl) -> (Vec<SemaType>, SemaType) {
    let sig_raw = ffi_signature_text(decl);
    let sig = sig_raw.replace(char::is_whitespace, "").replace('"', "");
    if !sig.starts_with("fn(") {
        return (Vec::new(), SemaType::Unknown);
    }
    let Some(close_idx) = sig.find(')') else {
        return (Vec::new(), SemaType::Unknown);
    };
    let args_slice = &sig["fn(".len()..close_idx];
    let mut params = Vec::new();
    if !args_slice.is_empty() {
        for arg in split_top_level_signature_args(args_slice) {
            params.push(parse_ffi_signature_type(&arg));
        }
    }
    let return_type = sig
        .get(close_idx + 1..)
        .and_then(|tail| tail.strip_prefix("->"))
        .map(parse_ffi_signature_type)
        .unwrap_or(SemaType::Unknown);
    (params, return_type)
}

fn build_fn_sig_index(program: &Program) -> HashMap<String, Vec<FnSig>> {
    let mut out: HashMap<String, Vec<FnSig>> = HashMap::new();

    for container in &program.containers {
        for section in &container.sections {
            if let Section::Fn(funcs) = section {
                for f in funcs {
                    let sig = FnSig {
                        container: container.name.clone(),
                        name: f.name.clone(),
                        type_params: f.generic_params.clone(),
                        generic_bounds: f.generic_bounds.clone(),
                        params: f.params.iter().map(|p| lower_type(&p.ty)).collect(),
                        return_type: phase9_function_call_return_type(f),
                    };
                    out.entry(f.name.clone()).or_default().push(sig);
                }
            }
            if let Section::Foreign(decls) = section {
                for decl in decls {
                    let (params, return_type) = parse_ffi_signature_types(decl);
                    let sig = FnSig {
                        container: container.name.clone(),
                        name: decl.symbol.clone(),
                        type_params: Vec::new(),
                        generic_bounds: Vec::new(),
                        params,
                        return_type,
                    };
                    out.entry(decl.symbol.clone()).or_default().push(sig);
                }
            }
        }
    }

    out
}

fn substitute_type_name_with_maps(
    ty: &TypeName,
    subst: &HashMap<String, TypeName>,
    associated: &HashMap<String, TypeName>,
) -> TypeName {
    match ty {
        TypeName::Simple(name) => subst
            .get(name)
            .or_else(|| associated.get(name))
            .cloned()
            .unwrap_or_else(|| ty.clone()),
        TypeName::Vector(inner) => TypeName::Vector(Box::new(substitute_type_name_with_maps(
            inner, subst, associated,
        ))),
        TypeName::Array(inner) => TypeName::Array(Box::new(substitute_type_name_with_maps(
            inner, subst, associated,
        ))),
        TypeName::Union(items) => TypeName::Union(
            items
                .iter()
                .map(|item| substitute_type_name_with_maps(item, subst, associated))
                .collect(),
        ),
        TypeName::Generic { base, args } => TypeName::Generic {
            base: base.clone(),
            args: args
                .iter()
                .map(|arg| substitute_type_name_with_maps(arg, subst, associated))
                .collect(),
        },
    }
}

fn method_signature_to_fn_sig(
    container: &str,
    method: &MethodSignatureDecl,
    subst: &HashMap<String, TypeName>,
    associated: &HashMap<String, TypeName>,
) -> FnSig {
    FnSig {
        container: container.to_string(),
        name: method.name.clone(),
        type_params: Vec::new(),
        generic_bounds: Vec::new(),
        params: method
            .params
            .iter()
            .map(|param| {
                lower_type(&substitute_type_name_with_maps(
                    &param.ty, subst, associated,
                ))
            })
            .collect(),
        return_type: lower_type(&substitute_type_name_with_maps(
            &method.return_type,
            subst,
            associated,
        )),
    }
}

fn build_high_surfaces(program: &Program) -> Result<HashMap<String, HighSurface>, String> {
    let mut out = HashMap::new();
    for container in &program.containers {
        for section in &container.sections {
            match section {
                Section::Interfaces(items) => {
                    for decl in items {
                        let key = decl.name.to_ascii_lowercase();
                        if out.contains_key(&key) {
                            return Err(format!(
                                "E_HIGH_INTERFACE_DUP_001: duplicate interface '{}'",
                                decl.name
                            ));
                        }
                        let mut seen = HashSet::new();
                        for param in &decl.generic_params {
                            if !seen.insert(param.clone()) {
                                return Err(format!(
                                    "E_HIGH_INTERFACE_DUP_001: duplicate interface type parameter '{}'",
                                    param
                                ));
                            }
                        }
                        out.insert(
                            key,
                            HighSurface {
                                kind: HighSurfaceKind::Interface,
                                name: decl.name.clone(),
                                generic_params: decl.generic_params.clone(),
                                associated_types: Vec::new(),
                                required_methods: decl.methods.clone(),
                                methods: decl.methods.clone(),
                                generic_default_methods: HashSet::new(),
                            },
                        );
                    }
                }
                Section::Traits(items) => {
                    for decl in items {
                        let key = decl.name.to_ascii_lowercase();
                        if out.contains_key(&key) {
                            return Err(format!(
                                "E_HIGH_TRAIT_DUP_001: duplicate trait '{}'",
                                decl.name
                            ));
                        }
                        let mut seen = HashSet::new();
                        for param in &decl.generic_params {
                            if !seen.insert(param.clone()) {
                                return Err(format!(
                                    "E_HIGH_TRAIT_DUP_001: duplicate trait type parameter '{}'",
                                    param
                                ));
                            }
                        }
                        let mut associated_seen = HashSet::new();
                        let mut associated_types = Vec::new();
                        for assoc in &decl.associated_types {
                            if !associated_seen.insert(assoc.name.clone()) {
                                return Err(format!(
                                    "E_HIGH_ASSOC_TYPE_DUP_001: duplicate associated type '{}'",
                                    assoc.name
                                ));
                            }
                            associated_types.push(assoc.name.clone());
                        }
                        let generic_default_methods = decl
                            .default_methods
                            .iter()
                            .filter(|method| !method.generic_params.is_empty())
                            .map(|method| method.name.clone())
                            .collect::<HashSet<_>>();
                        let mut methods = decl.required_methods.clone();
                        methods.extend(decl.default_methods.iter().map(|method| {
                            MethodSignatureDecl {
                                name: method.name.clone(),
                                params: method.params.clone(),
                                return_type: method.return_type.clone(),
                            }
                        }));
                        out.insert(
                            key,
                            HighSurface {
                                kind: HighSurfaceKind::Trait,
                                name: decl.name.clone(),
                                generic_params: decl.generic_params.clone(),
                                associated_types,
                                required_methods: decl.required_methods.clone(),
                                methods,
                                generic_default_methods,
                            },
                        );
                    }
                }
                _ => {}
            }
        }
    }
    Ok(out)
}

fn impl_surface_subst(
    surface: &HighSurface,
    surface_ref: &TypeName,
) -> Result<HashMap<String, TypeName>, String> {
    let args = type_name_args(surface_ref);
    if args.len() != surface.generic_params.len() {
        return Err(format!(
            "E_HIGH_IMPL_ARITY_001: '{}' expects {} generic arguments, got {}",
            surface.name,
            surface.generic_params.len(),
            args.len()
        ));
    }
    let mut subst = HashMap::new();
    for (param, arg) in surface.generic_params.iter().zip(args.iter()) {
        subst.insert(param.clone(), arg.clone());
    }
    Ok(subst)
}

fn build_high_impls(
    program: &Program,
    surfaces: &HashMap<String, HighSurface>,
) -> Result<Vec<HighImplSig>, String> {
    let mut out = Vec::new();
    let mut keys = HashSet::new();
    for container in &program.containers {
        for section in &container.sections {
            let Section::ImplBlocks(items) = section else {
                continue;
            };
            for decl in items {
                let Some(surface_name) = type_name_base(&decl.trait_ref) else {
                    return Err(
                        "E_HIGH_IMPL_UNKNOWN_TRAIT_001: impl target must be a trait/interface"
                            .into(),
                    );
                };
                let Some(surface) = surfaces.get(&surface_name.to_ascii_lowercase()) else {
                    return Err(format!(
                        "E_HIGH_IMPL_UNKNOWN_TRAIT_001: unknown trait/interface '{}'",
                        surface_name
                    ));
                };
                let subst = impl_surface_subst(surface, &decl.trait_ref)?;
                let for_type = lower_type(&decl.for_type);
                let mut associated_type_bindings = HashMap::new();
                let mut associated_type_name_bindings = HashMap::new();
                let mut seen_associated_bindings = HashSet::new();
                for binding in &decl.associated_type_bindings {
                    if !seen_associated_bindings.insert(binding.name.clone()) {
                        return Err(format!(
                            "E_HIGH_ASSOC_TYPE_DUP_001: duplicate associated type binding '{}'",
                            binding.name
                        ));
                    }
                    if !surface
                        .associated_types
                        .iter()
                        .any(|name| name == &binding.name)
                    {
                        return Err(format!(
                            "E_HIGH_ASSOC_TYPE_UNKNOWN_001: associated type '{}' is not declared by '{}'",
                            binding.name, surface.name
                        ));
                    }
                    associated_type_bindings.insert(binding.name.clone(), lower_type(&binding.ty));
                    associated_type_name_bindings.insert(binding.name.clone(), binding.ty.clone());
                }
                for associated in &surface.associated_types {
                    if !associated_type_bindings.contains_key(associated) {
                        return Err(format!(
                            "E_HIGH_ASSOC_TYPE_MISSING_001: impl '{}' for '{}' is missing associated type '{}'",
                            surface_name,
                            render_sema_type(&for_type),
                            associated
                        ));
                    }
                }
                let key = format!(
                    "{}::{}",
                    surface_name.to_ascii_lowercase(),
                    render_sema_type(&for_type)
                );
                if !keys.insert(key) {
                    return Err(format!(
                        "E_HIGH_IMPL_DUP_001: duplicate impl for '{}' on '{}'",
                        surface_name,
                        render_sema_type(&for_type)
                    ));
                }

                let mut method_sigs = Vec::new();
                for default_method in surface.methods.iter().filter(|method| {
                    !surface
                        .required_methods
                        .iter()
                        .any(|required| required.name == method.name)
                }) {
                    method_sigs.push(method_signature_to_fn_sig(
                        surface_name,
                        default_method,
                        &subst,
                        &associated_type_name_bindings,
                    ));
                }
                for requirement in &surface.required_methods {
                    let expected = method_signature_to_fn_sig(
                        surface_name,
                        requirement,
                        &subst,
                        &associated_type_name_bindings,
                    );
                    let Some(actual) = decl
                        .methods
                        .iter()
                        .find(|method| method.name == requirement.name)
                    else {
                        let code = match surface.kind {
                            HighSurfaceKind::Interface => "E_HIGH_INTERFACE_METHOD_MISSING_001",
                            HighSurfaceKind::Trait => "E_HIGH_TRAIT_METHOD_MISSING_001",
                        };
                        return Err(format!(
                            "{}: impl '{}' for '{}' missing required method '{}'",
                            code,
                            surface_name,
                            render_sema_type(&for_type),
                            requirement.name
                        ));
                    };
                    let actual_sig = FnSig {
                        container: container.name.clone(),
                        name: actual.name.clone(),
                        type_params: actual.generic_params.clone(),
                        generic_bounds: actual.generic_bounds.clone(),
                        params: actual
                            .params
                            .iter()
                            .map(|param| lower_type(&param.ty))
                            .collect(),
                        return_type: lower_type(&actual.return_type),
                    };
                    if expected.params.len() != actual_sig.params.len()
                        || expected.params.iter().zip(actual_sig.params.iter()).any(
                            |(expected, actual)| {
                                !type_compatible(actual, expected)
                                    || !type_compatible(expected, actual)
                            },
                        )
                        || !type_compatible(&actual_sig.return_type, &expected.return_type)
                        || !type_compatible(&expected.return_type, &actual_sig.return_type)
                    {
                        let code = match surface.kind {
                            HighSurfaceKind::Interface => "E_HIGH_INTERFACE_METHOD_SIGNATURE_001",
                            HighSurfaceKind::Trait => "E_HIGH_TRAIT_METHOD_SIGNATURE_001",
                        };
                        let code = if !surface.associated_types.is_empty() {
                            "E_HIGH_ASSOC_TYPE_BINDING_001"
                        } else {
                            code
                        };
                        return Err(format!(
                            "{}: impl method '{}' signature mismatch",
                            code, requirement.name
                        ));
                    }
                    method_sigs.push(actual_sig);
                }
                out.push(HighImplSig {
                    surface_name: surface_name.to_string(),
                    for_type,
                    associated_type_bindings,
                    methods: method_sigs,
                });
            }
        }
    }
    Ok(out)
}

fn refresh_high_phase4_indexes(program: &Program) -> Result<(), String> {
    let surfaces = build_high_surfaces(program)?;
    let impls = build_high_impls(program, &surfaces)?;
    HIGH_SURFACES.with(|cell| {
        *cell.borrow_mut() = surfaces;
    });
    HIGH_IMPLS.with(|cell| {
        *cell.borrow_mut() = impls;
    });
    Ok(())
}

fn collect_high_enums(program: &Program) -> Result<HashMap<String, HighEnumInfo>, String> {
    let mut out = HashMap::new();
    out.insert(
        "option".into(),
        HighEnumInfo {
            name: "Option".into(),
            generic_params: vec!["T".into()],
            variants: HashMap::from([
                (
                    "some".into(),
                    HighEnumVariantInfo {
                        name: "Some".into(),
                        payload: vec![("value".into(), SemaType::Simple("T".into()))],
                    },
                ),
                (
                    "none".into(),
                    HighEnumVariantInfo {
                        name: "None".into(),
                        payload: Vec::new(),
                    },
                ),
            ]),
        },
    );
    out.insert(
        "result".into(),
        HighEnumInfo {
            name: "Result".into(),
            generic_params: vec!["T".into(), "E".into()],
            variants: HashMap::from([
                (
                    "ok".into(),
                    HighEnumVariantInfo {
                        name: "Ok".into(),
                        payload: vec![("value".into(), SemaType::Simple("T".into()))],
                    },
                ),
                (
                    "err".into(),
                    HighEnumVariantInfo {
                        name: "Err".into(),
                        payload: vec![("error".into(), SemaType::Simple("E".into()))],
                    },
                ),
            ]),
        },
    );
    for container in &program.containers {
        for section in &container.sections {
            let Section::Enums(decls) = section else {
                continue;
            };
            for decl in decls {
                let key = decl.name.to_ascii_lowercase();
                if out.contains_key(&key) {
                    return Err(format!(
                        "E_HIGH_ENUM_DUP_001: duplicate enum '{}'",
                        decl.name
                    ));
                }
                let mut variants = HashMap::new();
                for variant in &decl.variants {
                    let variant_key = variant.name.to_ascii_lowercase();
                    if variants.contains_key(&variant_key) {
                        return Err(format!(
                            "E_HIGH_ENUM_VARIANT_DUP_001: duplicate variant '{}.{}'",
                            decl.name, variant.name
                        ));
                    }
                    let payload = variant
                        .payload
                        .iter()
                        .map(|field| (field.name.clone(), lower_type(&field.ty)))
                        .collect();
                    variants.insert(
                        variant_key,
                        HighEnumVariantInfo {
                            name: variant.name.clone(),
                            payload,
                        },
                    );
                }
                out.insert(
                    key,
                    HighEnumInfo {
                        name: decl.name.clone(),
                        generic_params: decl.generic_params.clone(),
                        variants,
                    },
                );
            }
        }
    }
    for container in &program.containers {
        for section in &container.sections {
            let Section::TypeContracts(contracts) = section else {
                continue;
            };
            for contract in contracts {
                if !matches!(
                    contract.kind,
                    TypeContractKind::Enum | TypeContractKind::TaggedUnion
                ) {
                    continue;
                }
                let key = contract.name.to_ascii_lowercase();
                if out.contains_key(&key) {
                    return Err(format!(
                        "E_HIGH_ENUM_DUP_001: duplicate enum or tagged union '{}'",
                        contract.name
                    ));
                }
                let mut variants = HashMap::new();
                for variant in &contract.variants {
                    let variant_key = variant.name.to_ascii_lowercase();
                    if variants.contains_key(&variant_key) {
                        return Err(format!(
                            "E_HIGH_ENUM_VARIANT_DUP_001: duplicate variant '{}.{}'",
                            contract.name, variant.name
                        ));
                    }
                    variants.insert(
                        variant_key,
                        HighEnumVariantInfo {
                            name: variant.name.clone(),
                            payload: variant
                                .payload
                                .iter()
                                .map(|field| (field.name.clone(), lower_type(&field.ty)))
                                .collect(),
                        },
                    );
                }
                out.insert(
                    key,
                    HighEnumInfo {
                        name: contract.name.clone(),
                        generic_params: contract.generic_params.clone(),
                        variants,
                    },
                );
            }
        }
    }
    Ok(out)
}

fn high_enum_type_matches(name: &str, ty: &SemaType) -> bool {
    match ty {
        SemaType::Simple(simple) => simple.eq_ignore_ascii_case(name),
        SemaType::Generic { base, .. } => base.eq_ignore_ascii_case(name),
        _ => false,
    }
}

fn phase7_generic_parts<'a>(ty: &'a SemaType, wanted: &str) -> Option<&'a [SemaType]> {
    match ty {
        SemaType::Generic { base, args } if base.eq_ignore_ascii_case(wanted) => {
            Some(args.as_slice())
        }
        _ => None,
    }
}

fn phase7_option_inner(ty: &SemaType) -> Option<&SemaType> {
    phase7_generic_parts(ty, "Option").and_then(|args| (args.len() == 1).then_some(&args[0]))
}

fn phase7_result_parts(ty: &SemaType) -> Option<(&SemaType, &SemaType)> {
    let args = phase7_generic_parts(ty, "Result")?;
    (args.len() == 2).then_some((&args[0], &args[1]))
}

fn phase7_expected_option_inner(ty: &SemaType) -> Option<SemaType> {
    phase7_option_inner(ty).cloned().or_else(|| {
        matches!(ty, SemaType::Simple(name) if name.eq_ignore_ascii_case("option"))
            .then_some(SemaType::Unknown)
    })
}

fn phase7_expected_result_parts(ty: &SemaType) -> Option<(SemaType, SemaType)> {
    phase7_result_parts(ty)
        .map(|(ok, err)| (ok.clone(), err.clone()))
        .or_else(|| {
            matches!(ty, SemaType::Simple(name) if name.eq_ignore_ascii_case("result"))
                .then_some((SemaType::Unknown, SemaType::Unknown))
        })
}

fn inference_hole_count(ty: &SemaType) -> usize {
    match ty {
        SemaType::Unknown => 1,
        SemaType::Simple(name)
            if name.eq_ignore_ascii_case("option") || name.eq_ignore_ascii_case("result") =>
        {
            1
        }
        SemaType::Array(inner) | SemaType::Vector(inner) => inference_hole_count(inner),
        SemaType::Union(items) => items.iter().map(inference_hole_count).sum(),
        SemaType::Generic { args, .. } => args.iter().map(inference_hole_count).sum(),
        SemaType::Simple(_) => 0,
    }
}

fn merge_inferred_types(left: &SemaType, right: &SemaType) -> Result<SemaType, String> {
    if left == right {
        return Ok(left.clone());
    }
    if matches!(left, SemaType::Unknown) {
        return Ok(right.clone());
    }
    if matches!(right, SemaType::Unknown) {
        return Ok(left.clone());
    }
    if matches!(left, SemaType::Simple(name) if name.eq_ignore_ascii_case("option"))
        && phase7_option_inner(right).is_some()
    {
        return Ok(right.clone());
    }
    if matches!(right, SemaType::Simple(name) if name.eq_ignore_ascii_case("option"))
        && phase7_option_inner(left).is_some()
    {
        return Ok(left.clone());
    }
    if matches!(left, SemaType::Simple(name) if name.eq_ignore_ascii_case("result"))
        && phase7_result_parts(right).is_some()
    {
        return Ok(right.clone());
    }
    if matches!(right, SemaType::Simple(name) if name.eq_ignore_ascii_case("result"))
        && phase7_result_parts(left).is_some()
    {
        return Ok(left.clone());
    }
    match (left, right) {
        (SemaType::Array(a), SemaType::Array(b)) => {
            Ok(SemaType::Array(Box::new(merge_inferred_types(a, b)?)))
        }
        (SemaType::Vector(a), SemaType::Vector(b)) => {
            Ok(SemaType::Vector(Box::new(merge_inferred_types(a, b)?)))
        }
        (
            SemaType::Generic {
                base: left_base,
                args: left_args,
            },
            SemaType::Generic {
                base: right_base,
                args: right_args,
            },
        ) if left_base.eq_ignore_ascii_case(right_base) && left_args.len() == right_args.len() => {
            let args = left_args
                .iter()
                .zip(right_args)
                .map(|(a, b)| merge_inferred_types(a, b))
                .collect::<Result<Vec<_>, _>>()?;
            Ok(SemaType::Generic {
                base: left_base.clone(),
                args,
            })
        }
        _ if type_compatible(left, right) || type_compatible(right, left) => {
            if inference_hole_count(left) <= inference_hole_count(right) {
                Ok(left.clone())
            } else {
                Ok(right.clone())
            }
        }
        _ => Err(format!(
            "incompatible inferred types: {} and {}",
            render_sema_type(left),
            render_sema_type(right)
        )),
    }
}

fn refine_projection_container_type(declared: &SemaType, inferred: &SemaType) -> SemaType {
    if matches!(declared, SemaType::Unknown) {
        return inferred.clone();
    }
    let is_option = phase7_expected_option_inner(declared).is_some()
        && phase7_expected_option_inner(inferred).is_some();
    let is_result = phase7_expected_result_parts(declared).is_some()
        && phase7_expected_result_parts(inferred).is_some();
    if is_option || is_result {
        merge_inferred_types(declared, inferred).unwrap_or_else(|_| declared.clone())
    } else {
        declared.clone()
    }
}

fn expected_collection_inner(ty: &SemaType) -> Option<&SemaType> {
    match ty {
        SemaType::Array(inner) | SemaType::Vector(inner) => Some(inner),
        SemaType::Generic { base, args }
            if (base.eq_ignore_ascii_case("array") || is_list_family(base)) && !args.is_empty() =>
        {
            args.first()
        }
        _ => None,
    }
}

fn expected_collection_leaf_type(ty: &SemaType) -> Option<&SemaType> {
    let mut current = expected_collection_inner(ty)?;
    while let Some(inner) = expected_collection_inner(current) {
        current = inner;
    }
    Some(current)
}

fn collection_literal_items(expr: &Expr) -> Option<&[Expr]> {
    match expr {
        Expr::VectorLiteral(items) | Expr::ArrayLiteral(items) => Some(items),
        _ => None,
    }
}

fn infer_collection_literal_with_expected_leaf(
    program: &Program,
    current_container_name: &str,
    expr: &Expr,
    expected_leaf: Option<&SemaType>,
    scope: &HashMap<String, SemaType>,
    current_context: &Option<Context>,
) -> Result<SemaType, String> {
    let items = collection_literal_items(expr)
        .ok_or_else(|| "internal collection inference expected a literal".to_string())?;
    let record_layouts = collect_record_type_layouts(program);
    let expected_zero_aggregate = expected_leaf.filter(|ty| match ty {
        SemaType::Simple(name) => record_layouts.contains_key(name),
        SemaType::Generic { base, .. } => record_layouts.contains_key(base),
        _ => false,
    });
    let contains_nested_literal = items
        .iter()
        .any(|item| collection_literal_items(item).is_some());
    let mut inferred_inner = if contains_nested_literal {
        SemaType::Unknown
    } else {
        expected_leaf.cloned().unwrap_or(SemaType::Unknown)
    };

    for item in items {
        let item_ty = if sema_expr_integer_literal_value(item) == Some(0) {
            if let Some(expected_aggregate) = expected_zero_aggregate {
                expected_aggregate.clone()
            } else {
                infer_expr_type_with_expected(
                    program,
                    current_container_name,
                    item,
                    expected_leaf,
                    scope,
                    current_context,
                )?
            }
        } else if collection_literal_items(item).is_some() {
            infer_collection_literal_with_expected_leaf(
                program,
                current_container_name,
                item,
                expected_leaf,
                scope,
                current_context,
            )?
        } else {
            infer_expr_type_with_expected(
                program,
                current_container_name,
                item,
                expected_leaf,
                scope,
                current_context,
            )?
        };
        inferred_inner = merge_inferred_types(&inferred_inner, &item_ty).map_err(|_| {
            format!(
                "collection literal has incompatible element types: {} vs {}",
                render_sema_type(&inferred_inner),
                render_sema_type(&item_ty)
            )
        })?;
    }

    if matches!(expr, Expr::ArrayLiteral(_)) {
        Ok(SemaType::Array(Box::new(inferred_inner)))
    } else {
        Ok(SemaType::Vector(Box::new(inferred_inner)))
    }
}

fn phase7_constructor_name(expr: &Expr) -> Option<(&str, &[Expr])> {
    fn is_constructor(name: &str) -> bool {
        ["some", "none", "ok", "err"]
            .iter()
            .any(|candidate| name.eq_ignore_ascii_case(candidate))
    }

    fn is_qualified_builtin_constructor(path: &[String]) -> bool {
        let Some(name) = path.last() else {
            return false;
        };
        let Some(family) = path.get(path.len().saturating_sub(2)) else {
            return false;
        };
        (family.eq_ignore_ascii_case("Option")
            && (name.eq_ignore_ascii_case("Some") || name.eq_ignore_ascii_case("None")))
            || (family.eq_ignore_ascii_case("Result")
                && (name.eq_ignore_ascii_case("Ok") || name.eq_ignore_ascii_case("Err")))
    }

    match expr {
        Expr::Identifier(name) if name.eq_ignore_ascii_case("None") => Some(("None", &[])),
        Expr::Call { callee, args } if is_constructor(callee) => {
            Some((callee.as_str(), args.as_slice()))
        }
        Expr::QualifiedCall { path, args }
            if path.last().is_some_and(|name| is_constructor(name))
                && is_qualified_builtin_constructor(path) =>
        {
            Some((path.last()?.as_str(), args.as_slice()))
        }
        _ => None,
    }
}

#[cfg(test)]
mod phase7_constructor_nominal_tests {
    use super::*;

    fn check(source: &str) -> Result<SemanticResult, String> {
        let tokens = ncc_lexer::lex(source).expect("fixture must lex");
        let program = ncc_parser::parse(tokens).expect("fixture must parse");
        analyze(&program)
    }

    #[test]
    fn qualified_some_preserves_user_enum_and_builtin_option() {
        let nominal = r#"nominalMaybe { enum: Maybe<T> { Some(value: T); None; } fn: unwrapInt(value: Maybe<int>) -> int { public: match (@value) { Maybe.Some(x) => return @x; Maybe.None => return 0; } } run() -> bool { public: return unwrapInt(Maybe.Some(9)) == 9; } }"#;
        let builtin = r#"qualifiedOption { fn: accept(value: Option<int>) -> bool { public: return true; } run() -> bool { public: return accept(Option.Some(9)); } }"#;
        assert!(check(nominal).is_ok());
        assert!(check(builtin).is_ok());
    }
}

fn require_phase7_runtime_constructor_import(
    program: &Program,
    constructor: &str,
    current_context: &Option<Context>,
) -> Result<(), String> {
    if !matches!(current_context, Some(Context::Runtime)) {
        return Ok(());
    }
    let family =
        if constructor.eq_ignore_ascii_case("some") || constructor.eq_ignore_ascii_case("none") {
            "option"
        } else {
            "result"
        };
    let module = vec!["runtime".to_string(), family.to_string()];
    if has_visible_import_for_module(&program.uses, &module) {
        Ok(())
    } else {
        Err(format!(
            "E_RUNTIME_USE_001: runtime constructor '{}' requires explicit use/import 'nC.runtime.{}'",
            constructor, family
        ))
    }
}

fn validate_phase7_result_error_type(error_ty: &SemaType) -> Result<(), String> {
    if sema_type_contains_any(error_ty) {
        return Err("E_HIGH_RESULT_ERROR_ANY_001: Result error type cannot be any".into());
    }
    Ok(())
}

fn phase7_runtime_error_accepts_message(error_ty: &SemaType, payload_ty: &SemaType) -> bool {
    let SemaType::Simple(payload) = payload_ty else {
        return false;
    };
    if !payload.eq_ignore_ascii_case("str") && !payload.eq_ignore_ascii_case("text") {
        return false;
    }
    let SemaType::Simple(error) = error_ty else {
        return false;
    };
    [
        "RuntimeError",
        "FsError",
        "TcpError",
        "NetworkError",
        "ProcessError",
        "ThreadError",
        "MemoryError",
        "AsyncError",
    ]
    .iter()
    .any(|known| error.eq_ignore_ascii_case(known))
}

fn infer_phase7_constructor_type(
    program: &Program,
    current_container_name: &str,
    expr: &Expr,
    expected: Option<&SemaType>,
    scope: &HashMap<String, SemaType>,
    current_context: &Option<Context>,
) -> Result<Option<SemaType>, String> {
    let Some((raw_name, args)) = phase7_constructor_name(expr) else {
        return Ok(None);
    };
    require_phase7_runtime_constructor_import(program, raw_name, current_context)?;
    let name = raw_name.to_ascii_lowercase();
    match name.as_str() {
        "some" => {
            if args.len() != 1 {
                return Err(format!(
                    "E_HIGH_OPTION_ARITY_001: Some expects one payload, got {}",
                    args.len()
                ));
            }
            let got = infer_expr_type(
                program,
                current_container_name,
                &args[0],
                scope,
                current_context,
            )?;
            if sema_type_contains_any(&got) {
                return Err("E_HIGH_ANY_LEAK_001: Option payload cannot be any".into());
            }
            if let Some(expected) = expected {
                let Some(inner) = phase7_expected_option_inner(expected) else {
                    return Err(format!(
                        "E_HIGH_OPTION_SOME_TYPE_001: Some requires Option<T> context, got {}",
                        render_sema_type(expected)
                    ));
                };
                if sema_type_contains_any(&inner) {
                    return Err("E_HIGH_ANY_LEAK_001: Option<any> is forbidden".into());
                }
                if !type_compatible(&got, &inner) {
                    return Err(format!(
                        "E_HIGH_OPTION_SOME_TYPE_001: Some payload expected {}, got {}",
                        render_sema_type(&inner),
                        render_sema_type(&got)
                    ));
                }
                Ok(Some(SemaType::Generic {
                    base: "Option".into(),
                    args: vec![merge_inferred_types(&inner, &got)?],
                }))
            } else {
                Ok(Some(SemaType::Generic {
                    base: "Option".into(),
                    args: vec![got],
                }))
            }
        }
        "none" => {
            if !args.is_empty() {
                return Err(format!(
                    "E_HIGH_OPTION_ARITY_001: None expects no payload, got {}",
                    args.len()
                ));
            }
            let expected = match expected {
                Some(expected) => phase7_expected_option_inner(expected).ok_or_else(|| {
                    format!(
                        "E_HIGH_OPTION_NONE_CONTEXT_001: None requires Option<T> context, got {}",
                        render_sema_type(expected)
                    )
                })?,
                None => SemaType::Unknown,
            };
            if sema_type_contains_any(&expected) {
                return Err("E_HIGH_ANY_LEAK_001: Option<any> is forbidden".into());
            }
            Ok(Some(SemaType::Generic {
                base: "Option".into(),
                args: vec![expected],
            }))
        }
        "ok" => {
            if args.len() != 1 {
                return Err(format!(
                    "E_HIGH_RESULT_ARITY_001: Ok expects one payload, got {}",
                    args.len()
                ));
            }
            let got = infer_expr_type(
                program,
                current_container_name,
                &args[0],
                scope,
                current_context,
            )?;
            let (ok_ty, err_ty) = match expected {
                Some(expected) => phase7_expected_result_parts(expected).ok_or_else(|| {
                    format!(
                        "E_HIGH_RESULT_OK_TYPE_001: Ok requires Result<T,E> context, got {}",
                        render_sema_type(expected)
                    )
                })?,
                None => (SemaType::Unknown, SemaType::Unknown),
            };
            validate_phase7_result_error_type(&err_ty)?;
            if !type_compatible(&got, &ok_ty) {
                return Err(format!(
                    "E_HIGH_RESULT_OK_TYPE_001: Ok payload expected {}, got {}",
                    render_sema_type(&ok_ty),
                    render_sema_type(&got)
                ));
            }
            Ok(Some(SemaType::Generic {
                base: "Result".into(),
                args: vec![merge_inferred_types(&ok_ty, &got)?, err_ty],
            }))
        }
        "err" => {
            if args.len() != 1 {
                return Err(format!(
                    "E_HIGH_RESULT_ARITY_001: Err expects one payload, got {}",
                    args.len()
                ));
            }
            let got = infer_expr_type(
                program,
                current_container_name,
                &args[0],
                scope,
                current_context,
            )?;
            let (ok_ty, err_ty) = match expected {
                Some(expected) => phase7_expected_result_parts(expected).ok_or_else(|| {
                    format!(
                        "E_HIGH_ERROR_ERASURE_001: Err cannot flow into non-Result context {}",
                        render_sema_type(expected)
                    )
                })?,
                None => (SemaType::Unknown, SemaType::Unknown),
            };
            validate_phase7_result_error_type(&err_ty)?;
            let got = if phase7_runtime_error_accepts_message(&err_ty, &got) {
                err_ty.clone()
            } else {
                got
            };
            if !type_compatible(&got, &err_ty) {
                return Err(format!(
                    "E_HIGH_RESULT_ERR_TYPE_001: Err payload expected {}, got {}",
                    render_sema_type(&err_ty),
                    render_sema_type(&got)
                ));
            }
            Ok(Some(SemaType::Generic {
                base: "Result".into(),
                args: vec![ok_ty, merge_inferred_types(&err_ty, &got)?],
            }))
        }
        _ => Ok(None),
    }
}

fn infer_expr_type_with_expected(
    program: &Program,
    current_container_name: &str,
    expr: &Expr,
    expected: Option<&SemaType>,
    scope: &HashMap<String, SemaType>,
    current_context: &Option<Context>,
) -> Result<SemaType, String> {
    if matches!(expr, Expr::Call { callee, args } if callee == "__nC_uninit" && args.is_empty()) {
        return Ok(expected.cloned().unwrap_or(SemaType::Unknown));
    }
    if let Some(ty) = infer_phase7_constructor_type(
        program,
        current_container_name,
        expr,
        expected,
        scope,
        current_context,
    )? {
        return Ok(ty);
    }

    match expr {
        Expr::VectorLiteral(_) | Expr::ArrayLiteral(_) => {
            let expected_leaf = expected.and_then(expected_collection_leaf_type);
            let inferred = infer_collection_literal_with_expected_leaf(
                program,
                current_container_name,
                expr,
                expected_leaf,
                scope,
                current_context,
            )?;
            if let Some(expected_collection) =
                expected.filter(|ty| expected_collection_inner(ty).is_some())
            {
                return Ok(expected_collection.clone());
            }
            return Ok(inferred);
        }
        Expr::IfElse {
            condition,
            then_expr,
            else_expr,
        } => {
            let cond_ty = infer_expr_type(
                program,
                current_container_name,
                condition,
                scope,
                current_context,
            )?;
            if !is_bool_like_condition(&cond_ty) {
                return Err(official_condition_type_error("if-expression", &cond_ty));
            }
            let then_ty = infer_expr_type_with_expected(
                program,
                current_container_name,
                then_expr,
                expected,
                scope,
                current_context,
            )?;
            let else_ty = infer_expr_type_with_expected(
                program,
                current_container_name,
                else_expr,
                expected,
                scope,
                current_context,
            )?;
            return merge_inferred_types(&then_ty, &else_ty).map_err(|_| {
                format!(
                    "if-expression branches are incompatible: then {:?}, else {:?}",
                    then_ty, else_ty
                )
            });
        }
        _ => {}
    }

    let inferred = infer_expr_type(
        program,
        current_container_name,
        expr,
        scope,
        current_context,
    )?;
    if let Some(expected) = expected {
        if type_compatible(&inferred, expected) || type_compatible(expected, &inferred) {
            return merge_inferred_types(&inferred, expected).or(Ok(inferred));
        }
    }
    Ok(inferred)
}

fn phase7_type_name_contains_any(ty: &TypeName) -> bool {
    match ty {
        TypeName::Simple(name) => name.eq_ignore_ascii_case("any"),
        TypeName::Array(inner) | TypeName::Vector(inner) => phase7_type_name_contains_any(inner),
        TypeName::Union(items) => items.iter().any(phase7_type_name_contains_any),
        TypeName::Generic { args, .. } => args.iter().any(phase7_type_name_contains_any),
    }
}

fn validate_phase7_type_name(ty: &TypeName) -> Result<(), String> {
    match ty {
        TypeName::Simple(name) if name.eq_ignore_ascii_case("Option") => {
            Err("E_HIGH_OPTION_ARITY_001: Option expects exactly one type argument".into())
        }
        TypeName::Simple(name) if name.eq_ignore_ascii_case("Result") => {
            Err("E_HIGH_RESULT_ARITY_001: Result expects exactly two type arguments".into())
        }
        TypeName::Simple(_) => Ok(()),
        TypeName::Array(inner) | TypeName::Vector(inner) => validate_phase7_type_name(inner),
        TypeName::Union(items) => {
            for item in items {
                validate_phase7_type_name(item)?;
            }
            Ok(())
        }
        TypeName::Generic { base, args } if base.eq_ignore_ascii_case("Option") => {
            if args.len() != 1 {
                return Err(format!(
                    "E_HIGH_OPTION_ARITY_001: Option expects one type argument, got {}",
                    args.len()
                ));
            }
            if phase7_type_name_contains_any(&args[0]) {
                return Err("E_HIGH_ANY_LEAK_001: Option<any> is forbidden".into());
            }
            validate_phase7_type_name(&args[0])
        }
        TypeName::Generic { base, args } if base.eq_ignore_ascii_case("Result") => {
            if args.len() != 2 {
                return Err(format!(
                    "E_HIGH_RESULT_ARITY_001: Result expects two type arguments, got {}",
                    args.len()
                ));
            }
            if phase7_type_name_contains_any(&args[0]) {
                return Err("E_HIGH_ANY_LEAK_001: Result<any,E> is forbidden".into());
            }
            if phase7_type_name_contains_any(&args[1]) {
                return Err("E_HIGH_RESULT_ERROR_ANY_001: Result error type cannot be any".into());
            }
            validate_phase7_type_name(&args[0])?;
            validate_phase7_type_name(&args[1])
        }
        TypeName::Generic { args, .. } => {
            for arg in args {
                validate_phase7_type_name(arg)?;
            }
            Ok(())
        }
    }
}

fn validate_phase7_stmt(stmt: &Stmt) -> Result<(), String> {
    match stmt {
        Stmt::Projection { ty, .. } | Stmt::StrictCheck { ty, .. } => validate_phase7_type_name(ty),
        Stmt::If {
            then_block,
            else_block,
            ..
        } => {
            validate_phase7_stmts(then_block)?;
            validate_phase7_stmts(else_block)
        }
        Stmt::Unless { body, .. }
        | Stmt::While { body, .. }
        | Stmt::DoWhile { body, .. }
        | Stmt::ForIn { body, .. }
        | Stmt::SameIn { body, .. }
        | Stmt::ForRange { body, .. }
        | Stmt::Loop { body }
        | Stmt::RepeatUntil { body, .. }
        | Stmt::RepeatCount { body, .. }
        | Stmt::EachDoWhile { body, .. } => validate_phase7_stmts(body),
        Stmt::ForClassic {
            init, step, body, ..
        } => {
            if let Some(init) = init {
                validate_phase7_stmt(init)?;
            }
            if let Some(step) = step {
                validate_phase7_stmt(step)?;
            }
            validate_phase7_stmts(body)
        }
        Stmt::Switch { cases, default, .. } | Stmt::Match { cases, default, .. } => {
            for (_, block) in cases {
                validate_phase7_stmts(block)?;
            }
            validate_phase7_stmts(default)
        }
        Stmt::PatternMatch { arms, .. } => {
            for arm in arms {
                validate_phase7_stmts(&arm.body)?;
            }
            Ok(())
        }
        Stmt::Select { branches, default } => {
            for (_, block) in branches {
                validate_phase7_stmts(block)?;
            }
            validate_phase7_stmts(default)
        }
        Stmt::Labeled { stmt, .. } => validate_phase7_stmt(stmt),
        _ => Ok(()),
    }
}

fn validate_phase7_stmts(stmts: &[Stmt]) -> Result<(), String> {
    for stmt in stmts {
        validate_phase7_stmt(stmt)?;
    }
    Ok(())
}

fn validate_high_phase7_result_option(program: &Program) -> Result<(), String> {
    for container in &program.containers {
        if matches!(container.context, Some(Context::Runtime)) {
            continue;
        }
        for section in &container.sections {
            let Section::Fn(functions) = section else {
                continue;
            };
            for function in functions {
                for param in &function.params {
                    validate_phase7_type_name(&param.ty)?;
                }
                validate_phase7_type_name(&function.return_type)?;
                validate_phase7_stmts(&function.public_body)?;
            }
        }
    }
    Ok(())
}

fn phase8_protocol_name(name: &str) -> Option<&'static str> {
    if name.eq_ignore_ascii_case("Iterator") {
        Some("Iterator")
    } else if name.eq_ignore_ascii_case("Iterable") {
        Some("Iterable")
    } else if name.eq_ignore_ascii_case("IntoIterator") {
        Some("IntoIterator")
    } else if name.eq_ignore_ascii_case("Collection") {
        Some("Collection")
    } else if name.eq_ignore_ascii_case("Generator") {
        Some("Generator")
    } else if name.eq_ignore_ascii_case("Stream") {
        Some("Stream")
    } else if name.eq_ignore_ascii_case("AsyncStream") {
        Some("AsyncStream")
    } else {
        None
    }
}

fn validate_phase8_type_name(ty: &TypeName) -> Result<(), String> {
    match ty {
        TypeName::Simple(name) if phase8_protocol_name(name).is_some() => Err(format!(
            "E_HIGH_ITERATOR_PROTOCOL_ARITY_001: {} expects exactly one type argument",
            phase8_protocol_name(name).unwrap_or("protocol")
        )),
        TypeName::Simple(_) => Ok(()),
        TypeName::Array(inner) | TypeName::Vector(inner) => validate_phase8_type_name(inner),
        TypeName::Union(items) => {
            for item in items {
                validate_phase8_type_name(item)?;
            }
            Ok(())
        }
        TypeName::Generic { base, args } if phase8_protocol_name(base).is_some() => {
            let protocol = phase8_protocol_name(base).unwrap_or("protocol");
            if args.len() != 1 {
                return Err(format!(
                    "E_HIGH_ITERATOR_PROTOCOL_ARITY_001: {} expects exactly one type argument, got {}",
                    protocol,
                    args.len()
                ));
            }
            if phase7_type_name_contains_any(&args[0]) {
                return Err(format!(
                    "E_HIGH_ANY_LEAK_001: {}<any> is forbidden in High Level Fase 8",
                    protocol
                ));
            }
            validate_phase8_type_name(&args[0])
        }
        TypeName::Generic { args, .. } => {
            for arg in args {
                validate_phase8_type_name(arg)?;
            }
            Ok(())
        }
    }
}

fn phase8_expr_symbol(expr: &Expr) -> Option<&str> {
    match expr {
        Expr::Identifier(name) => Some(name.as_str()),
        Expr::ContextRef(ctx) if ctx.path.len() == 1 => Some(ctx.path[0].as_str()),
        _ => None,
    }
}

fn phase8_rejected_call(callee: &str) -> Option<&'static str> {
    if callee.eq_ignore_ascii_case("lambda") || callee.eq_ignore_ascii_case("closure") {
        Some(
            "E_HIGH_OBSOLETE_CALLABLE_SPELLING_001: lambda(...) and closure(...) are obsolete; use a typed closure literal",
        )
    } else if callee.eq_ignore_ascii_case("infiniteStream")
        || callee.eq_ignore_ascii_case("unboundedRange")
    {
        Some(
            "E_HIGH_STREAM_UNBOUNDED_DEFERRED_001: infinite or unbounded streams are deferred past Phase 8",
        )
    } else {
        None
    }
}

fn validate_phase8_expr(expr: &Expr) -> Result<(), String> {
    match expr {
        Expr::StructLiteral { fields, .. } => {
            for (_, value) in fields {
                validate_phase8_expr(value)?;
            }
            Ok(())
        }
        Expr::VectorLiteral(items) | Expr::ArrayLiteral(items) => {
            for item in items {
                validate_phase8_expr(item)?;
            }
            Ok(())
        }
        Expr::Index { target, index } => {
            validate_phase8_expr(target)?;
            validate_phase8_expr(index)
        }
        Expr::MethodCall {
            receiver,
            method,
            args,
        } => {
            validate_phase8_expr(receiver)?;
            for arg in args {
                validate_phase8_expr(arg)?;
            }
            // Closures close map/filter/fold when a typed closure is supplied; the
            // concrete adapter contract is checked later by the closure pass.
            if matches!(method.as_str(), "map" | "filter" | "fold")
                && !args.iter().any(|arg| matches!(arg, Expr::Closure(_)))
            {
                return Err(
                    "E_HIGH_ITERATOR_ADAPTER_DEFERRED_001: iterator adapters require typed closures past Phase 8"
                        .into(),
                );
            }
            if (method == "next" || method == "iter") && !args.is_empty() {
                return Err(format!(
                    "E_HIGH_ITERATOR_NEXT_001: {} expects zero arguments in High Level Fase 8",
                    method
                ));
            }
            Ok(())
        }
        Expr::QualifiedCall { path, args } => {
            for arg in args {
                validate_phase8_expr(arg)?;
            }
            if let Some(last) = path.last() {
                if let Some(message) = phase8_rejected_call(last) {
                    return Err(message.into());
                }
            }
            Ok(())
        }
        Expr::StrictCheckExpr { ty, value, .. } => {
            validate_phase8_type_name(ty)?;
            validate_phase8_expr(value)
        }
        Expr::PostIncrement { .. }
        | Expr::FieldPostIncrement { .. }
        | Expr::PointerPostIncrementRead { .. } => Ok(()),
        Expr::Unary { expr, .. } => validate_phase8_expr(expr),
        Expr::Binary { left, right, .. } => {
            validate_phase8_expr(left)?;
            validate_phase8_expr(right)
        }
        Expr::Call { callee, args } => {
            for arg in args {
                validate_phase8_expr(arg)?;
            }
            if let Some(message) = phase8_rejected_call(callee) {
                return Err(message.into());
            }
            Ok(())
        }
        Expr::IfElse {
            condition,
            then_expr,
            else_expr,
        } => {
            validate_phase8_expr(condition)?;
            validate_phase8_expr(then_expr)?;
            validate_phase8_expr(else_expr)
        }
        Expr::Closure(closure) => {
            for stmt in &closure.body {
                validate_phase8_stmt(stmt)?;
            }
            Ok(())
        }
        Expr::Bool(_)
        | Expr::Number(_)
        | Expr::Char(_)
        | Expr::String(_)
        | Expr::Identifier(_)
        | Expr::ContextRef(_)
        | Expr::Dev(_) => Ok(()),
    }
}

fn phase8_expr_mutates_symbol(expr: &Expr, symbol: &str) -> bool {
    match expr {
        Expr::MethodCall {
            receiver,
            method,
            args,
        } => {
            if phase8_expr_symbol(receiver.as_ref())
                .is_some_and(|name| name.eq_ignore_ascii_case(symbol))
                && matches!(
                    method.as_str(),
                    "push"
                        | "append"
                        | "pop"
                        | "set"
                        | "insert"
                        | "removeAt"
                        | "clear"
                        | "reserve"
                        | "realloc"
                        | "shrink"
                        | "writeAt"
                        | "arrayWrite"
                )
            {
                return true;
            }
            phase8_expr_mutates_symbol(receiver, symbol)
                || args
                    .iter()
                    .any(|arg| phase8_expr_mutates_symbol(arg, symbol))
        }
        Expr::VectorLiteral(items) | Expr::ArrayLiteral(items) => items
            .iter()
            .any(|item| phase8_expr_mutates_symbol(item, symbol)),
        Expr::Index { target, index } => {
            phase8_expr_mutates_symbol(target, symbol) || phase8_expr_mutates_symbol(index, symbol)
        }
        Expr::QualifiedCall { args, .. } | Expr::Call { args, .. } => args
            .iter()
            .any(|arg| phase8_expr_mutates_symbol(arg, symbol)),
        Expr::StrictCheckExpr { value, .. } | Expr::Unary { expr: value, .. } => {
            phase8_expr_mutates_symbol(value, symbol)
        }
        Expr::Binary { left, right, .. } => {
            phase8_expr_mutates_symbol(left, symbol) || phase8_expr_mutates_symbol(right, symbol)
        }
        Expr::IfElse {
            condition,
            then_expr,
            else_expr,
        } => {
            phase8_expr_mutates_symbol(condition, symbol)
                || phase8_expr_mutates_symbol(then_expr, symbol)
                || phase8_expr_mutates_symbol(else_expr, symbol)
        }
        _ => false,
    }
}

fn phase8_stmt_mutates_symbol(stmt: &Stmt, symbol: &str) -> bool {
    match stmt {
        Stmt::Projection { target, value, .. } | Stmt::StrictCheck { target, value, .. } => {
            matches!(target, AssignTarget::Context(ctx) if ctx.path.len() == 1 && ctx.path[0].eq_ignore_ascii_case(symbol))
                || phase8_expr_mutates_symbol(value, symbol)
        }
        Stmt::Expr(expr) | Stmt::Return(expr) => phase8_expr_mutates_symbol(expr, symbol),
        Stmt::If {
            condition,
            then_block,
            else_block,
        } => {
            phase8_expr_mutates_symbol(condition, symbol)
                || then_block
                    .iter()
                    .any(|stmt| phase8_stmt_mutates_symbol(stmt, symbol))
                || else_block
                    .iter()
                    .any(|stmt| phase8_stmt_mutates_symbol(stmt, symbol))
        }
        Stmt::Unless { condition, body }
        | Stmt::While { condition, body }
        | Stmt::DoWhile { condition, body }
        | Stmt::RepeatUntil { condition, body } => {
            phase8_expr_mutates_symbol(condition, symbol)
                || body
                    .iter()
                    .any(|stmt| phase8_stmt_mutates_symbol(stmt, symbol))
        }
        Stmt::ForIn { iterable, body, .. } | Stmt::SameIn { iterable, body, .. } => {
            phase8_expr_mutates_symbol(iterable, symbol)
                || body
                    .iter()
                    .any(|stmt| phase8_stmt_mutates_symbol(stmt, symbol))
        }
        Stmt::ForRange {
            start,
            end,
            step,
            body,
            ..
        } => {
            phase8_expr_mutates_symbol(start, symbol)
                || phase8_expr_mutates_symbol(end, symbol)
                || step
                    .as_ref()
                    .is_some_and(|expr| phase8_expr_mutates_symbol(expr, symbol))
                || body
                    .iter()
                    .any(|stmt| phase8_stmt_mutates_symbol(stmt, symbol))
        }
        Stmt::ForClassic {
            init,
            condition,
            step,
            body,
        } => {
            init.as_deref()
                .is_some_and(|stmt| phase8_stmt_mutates_symbol(stmt, symbol))
                || condition
                    .as_ref()
                    .is_some_and(|expr| phase8_expr_mutates_symbol(expr, symbol))
                || step
                    .as_deref()
                    .is_some_and(|stmt| phase8_stmt_mutates_symbol(stmt, symbol))
                || body
                    .iter()
                    .any(|stmt| phase8_stmt_mutates_symbol(stmt, symbol))
        }
        Stmt::Switch { cases, default, .. } | Stmt::Match { cases, default, .. } => {
            cases.iter().any(|(expr, block)| {
                phase8_expr_mutates_symbol(expr, symbol)
                    || block
                        .iter()
                        .any(|stmt| phase8_stmt_mutates_symbol(stmt, symbol))
            }) || default
                .iter()
                .any(|stmt| phase8_stmt_mutates_symbol(stmt, symbol))
        }
        Stmt::PatternMatch { arms, .. } => arms.iter().any(|arm| {
            arm.body
                .iter()
                .any(|stmt| phase8_stmt_mutates_symbol(stmt, symbol))
        }),
        Stmt::Select { branches, default } => {
            branches.iter().any(|(_, block)| {
                block
                    .iter()
                    .any(|stmt| phase8_stmt_mutates_symbol(stmt, symbol))
            }) || default
                .iter()
                .any(|stmt| phase8_stmt_mutates_symbol(stmt, symbol))
        }
        Stmt::Labeled { stmt, .. } => phase8_stmt_mutates_symbol(stmt, symbol),
        Stmt::Loop { body } | Stmt::RepeatCount { body, .. } | Stmt::EachDoWhile { body, .. } => {
            body.iter()
                .any(|stmt| phase8_stmt_mutates_symbol(stmt, symbol))
        }
        _ => false,
    }
}

fn phase8_literal_zero(expr: &Expr) -> bool {
    sema_expr_integer_literal_value(expr) == Some(0)
}

fn validate_phase8_stmt(stmt: &Stmt) -> Result<(), String> {
    match stmt {
        Stmt::Return(expr) | Stmt::Expr(expr) => validate_phase8_expr(expr),
        Stmt::Projection { ty, value, .. } | Stmt::StrictCheck { ty, value, .. } => {
            validate_phase8_type_name(ty)?;
            validate_phase8_expr(value)
        }
        Stmt::If {
            condition,
            then_block,
            else_block,
        } => {
            validate_phase8_expr(condition)?;
            validate_phase8_stmts(then_block)?;
            validate_phase8_stmts(else_block)
        }
        Stmt::Unless { condition, body }
        | Stmt::While { condition, body }
        | Stmt::DoWhile { condition, body }
        | Stmt::RepeatUntil { condition, body } => {
            validate_phase8_expr(condition)?;
            validate_phase8_stmts(body)
        }
        Stmt::ForIn { iterable, body, .. } | Stmt::SameIn { iterable, body, .. } => {
            validate_phase8_expr(iterable)?;
            if let Some(symbol) = phase8_expr_symbol(iterable) {
                if body
                    .iter()
                    .any(|stmt| phase8_stmt_mutates_symbol(stmt, symbol))
                {
                    return Err(format!(
                        "E_HIGH_FOR_IN_MUTATION_001: iterable '{}' cannot be structurally mutated during for-in",
                        symbol
                    ));
                }
            }
            validate_phase8_stmts(body)
        }
        Stmt::ForRange {
            start,
            end,
            step,
            body,
            ..
        } => {
            validate_phase8_expr(start)?;
            validate_phase8_expr(end)?;
            if let Some(step) = step {
                validate_phase8_expr(step)?;
                if phase8_literal_zero(step) {
                    return Err(
                        "E_HIGH_RANGE_STEP_ZERO_001: finite ranges cannot use step 0".into(),
                    );
                }
            }
            validate_phase8_stmts(body)
        }
        Stmt::ForClassic {
            init,
            condition,
            step,
            body,
        } => {
            if let Some(init) = init {
                validate_phase8_stmt(init)?;
            }
            if let Some(condition) = condition {
                validate_phase8_expr(condition)?;
            }
            if let Some(step) = step {
                validate_phase8_stmt(step)?;
            }
            validate_phase8_stmts(body)
        }
        Stmt::Switch { cases, default, .. } | Stmt::Match { cases, default, .. } => {
            for (case_expr, block) in cases {
                validate_phase8_expr(case_expr)?;
                validate_phase8_stmts(block)?;
            }
            validate_phase8_stmts(default)
        }
        Stmt::PatternMatch { arms, .. } => {
            for arm in arms {
                if let Some(guard) = &arm.guard {
                    validate_phase8_expr(guard)?;
                }
                validate_phase8_stmts(&arm.body)?;
            }
            Ok(())
        }
        Stmt::Select { branches, default } => {
            for (expr, block) in branches {
                validate_phase8_expr(expr)?;
                validate_phase8_stmts(block)?;
            }
            validate_phase8_stmts(default)
        }
        Stmt::Labeled { stmt, .. } => validate_phase8_stmt(stmt),
        Stmt::RepeatCount { count, body } => {
            validate_phase8_expr(count)?;
            if sema_expr_integer_literal_value(count).is_some_and(|value| value < 0) {
                return Err(
                    "E_HIGH_REPEAT_COUNT_NEGATIVE_001: repeat count cannot be negative".into(),
                );
            }
            validate_phase8_stmts(body)
        }
        Stmt::EachDoWhile {
            iterable,
            body,
            condition,
            ..
        } => {
            validate_phase8_expr(iterable)?;
            validate_phase8_expr(condition)?;
            if let Some(symbol) = phase8_expr_symbol(iterable) {
                if body
                    .iter()
                    .any(|stmt| phase8_stmt_mutates_symbol(stmt, symbol))
                {
                    return Err(format!(
                        "E_HIGH_FOR_IN_MUTATION_001: iterable '{}' cannot be structurally mutated during each-loop",
                        symbol
                    ));
                }
            }
            validate_phase8_stmts(body)
        }
        Stmt::Loop { body } => validate_phase8_stmts(body),
        _ => Ok(()),
    }
}

fn validate_phase8_stmts(stmts: &[Stmt]) -> Result<(), String> {
    for stmt in stmts {
        validate_phase8_stmt(stmt)?;
    }
    Ok(())
}

fn validate_high_phase8_iterators_ranges_collections(program: &Program) -> Result<(), String> {
    for container in &program.containers {
        if container.context.is_some() {
            continue;
        }
        for section in &container.sections {
            match section {
                Section::Stc(decls) => {
                    for decl in decls {
                        let StcDecl::Typed { ty, init, .. } = decl;
                        validate_phase8_type_name(ty)?;
                        if let Some(init) = init {
                            validate_phase8_expr(init)?;
                        }
                    }
                }
                Section::Fn(functions) | Section::MoveFn(functions) => {
                    for function in functions {
                        for param in &function.params {
                            validate_phase8_type_name(&param.ty)?;
                        }
                        validate_phase8_type_name(&function.return_type)?;
                        validate_phase8_stmts(&function.public_body)?;
                    }
                }
                Section::Traits(traits) => {
                    for trait_decl in traits {
                        for method in &trait_decl.required_methods {
                            for param in &method.params {
                                validate_phase8_type_name(&param.ty)?;
                            }
                            validate_phase8_type_name(&method.return_type)?;
                        }
                        for method in &trait_decl.default_methods {
                            for param in &method.params {
                                validate_phase8_type_name(&param.ty)?;
                            }
                            validate_phase8_type_name(&method.return_type)?;
                            validate_phase8_stmts(&method.public_body)?;
                        }
                    }
                }
                Section::ImplBlocks(impls) => {
                    for impl_decl in impls {
                        validate_phase8_type_name(&impl_decl.trait_ref)?;
                        validate_phase8_type_name(&impl_decl.for_type)?;
                        for binding in &impl_decl.associated_type_bindings {
                            validate_phase8_type_name(&binding.ty)?;
                        }
                        for method in &impl_decl.methods {
                            for param in &method.params {
                                validate_phase8_type_name(&param.ty)?;
                            }
                            validate_phase8_type_name(&method.return_type)?;
                            validate_phase8_stmts(&method.public_body)?;
                        }
                    }
                }
                Section::Probe(stmts)
                | Section::Final(stmts)
                | Section::Raw(stmts)
                | Section::Binary(stmts)
                | Section::Bind(stmts)
                | Section::Structure(stmts) => validate_phase8_stmts(stmts)?,
                _ => {}
            }
        }
    }
    Ok(())
}

fn phase9_future_inner(ty: &SemaType) -> Option<SemaType> {
    match ty {
        SemaType::Generic { base, args }
            if base.eq_ignore_ascii_case("Future") && args.len() == 1 =>
        {
            Some(args[0].clone())
        }
        _ => None,
    }
}

fn phase9_task_inner(ty: &SemaType) -> Option<SemaType> {
    match ty {
        SemaType::Generic { base, args }
            if base.eq_ignore_ascii_case("Task") && args.len() == 1 =>
        {
            Some(args[0].clone())
        }
        _ => None,
    }
}

fn phase9_coroutine_protocol_name(name: &str) -> Option<&'static str> {
    if name.eq_ignore_ascii_case("Generator") {
        Some("Generator")
    } else if name.eq_ignore_ascii_case("Stream") {
        Some("Stream")
    } else if name.eq_ignore_ascii_case("AsyncStream") {
        Some("AsyncStream")
    } else {
        None
    }
}

fn phase9_generator_item_type(ty: &TypeName) -> Option<SemaType> {
    match ty {
        TypeName::Generic { base, args }
            if phase9_coroutine_protocol_name(base).is_some() && args.len() == 1 =>
        {
            Some(lower_type(&args[0]))
        }
        _ => None,
    }
}

fn phase9_validate_generator_mode(
    is_async: bool,
    return_type: &TypeName,
    owner: &str,
) -> Result<Option<SemaType>, String> {
    let TypeName::Generic { base, .. } = return_type else {
        return Ok(None);
    };
    let Some(protocol) = phase9_coroutine_protocol_name(base) else {
        return Ok(None);
    };
    if protocol == "AsyncStream" && !is_async {
        return Err(format!(
            "E_HIGH_ASYNC_STREAM_CONTEXT_001: '{}' returns AsyncStream<T> and must be async",
            owner
        ));
    }
    if is_async && protocol != "AsyncStream" {
        return Err(format!(
            "E_HIGH_ASYNC_GENERATOR_KIND_001: async generator '{}' must return AsyncStream<T>, not {}<T>",
            owner, protocol
        ));
    }
    Ok(phase9_generator_item_type(return_type))
}

thread_local! {
    static PHASE9_GENERATOR_ITEM: RefCell<Option<SemaType>> = const { RefCell::new(None) };
}

fn phase9_channel_parts(ty: &SemaType) -> Option<(SemaType, usize)> {
    let SemaType::Generic { base, args } = ty else {
        return None;
    };
    if !base.eq_ignore_ascii_case("channel") || args.len() != 2 {
        return None;
    }
    let SemaType::Simple(raw_capacity) = &args[1] else {
        return None;
    };
    raw_capacity
        .parse::<usize>()
        .ok()
        .map(|capacity| (args[0].clone(), capacity))
}

fn phase9_allowed_effect(effect: &str) -> bool {
    matches!(
        effect.to_ascii_lowercase().as_str(),
        "pure"
            | "io.read"
            | "io.write"
            | "fs.read"
            | "fs.write"
            | "net.read"
            | "net.write"
            | "async.await"
            | "task.spawn"
            | "channel.send"
            | "channel.recv"
            | "state.read"
            | "state.write"
            | "module.init"
            | "module.fini"
            | "unsafe.raw"
    )
}

fn phase9_validate_type_name(ty: &TypeName) -> Result<(), String> {
    match ty {
        TypeName::Simple(name) if name.eq_ignore_ascii_case("Future") => {
            Err("E_HIGH_ASYNC_FN_001: Future expects exactly one type argument".into())
        }
        TypeName::Simple(name) if name.eq_ignore_ascii_case("Task") => {
            Err("E_HIGH_TASK_RESULT_001: Task expects exactly one type argument".into())
        }
        TypeName::Simple(name) if name.eq_ignore_ascii_case("channel") => {
            Err("E_HIGH_CHANNEL_UNBOUNDED_001: channel must be bounded as channel<T,N>".into())
        }
        TypeName::Simple(name) if phase9_coroutine_protocol_name(name).is_some() => Err(format!(
            "E_HIGH_GENERATOR_ARITY_001: {} expects exactly one item type",
            phase9_coroutine_protocol_name(name).unwrap_or("generator protocol")
        )),
        TypeName::Simple(_) => Ok(()),
        TypeName::Array(inner) | TypeName::Vector(inner) => phase9_validate_type_name(inner),
        TypeName::Union(items) => {
            for item in items {
                phase9_validate_type_name(item)?;
            }
            Ok(())
        }
        TypeName::Generic { base, args } if base.eq_ignore_ascii_case("Future") => {
            if args.len() != 1 {
                return Err(format!(
                    "E_HIGH_ASYNC_FN_001: Future expects one type argument, got {}",
                    args.len()
                ));
            }
            if phase7_type_name_contains_any(&args[0]) {
                return Err("E_HIGH_ANY_LEAK_001: Future<any> is forbidden".into());
            }
            phase9_validate_type_name(&args[0])
        }
        TypeName::Generic { base, args } if base.eq_ignore_ascii_case("Task") => {
            if args.len() != 1 {
                return Err(format!(
                    "E_HIGH_TASK_RESULT_001: Task expects one type argument, got {}",
                    args.len()
                ));
            }
            if phase7_type_name_contains_any(&args[0]) {
                return Err("E_HIGH_ANY_LEAK_001: Task<any> is forbidden".into());
            }
            phase9_validate_type_name(&args[0])
        }
        TypeName::Generic { base, args } if base.eq_ignore_ascii_case("channel") => {
            if args.len() != 2 {
                return Err(format!(
                    "E_HIGH_CHANNEL_UNBOUNDED_001: channel expects item type and positive capacity, got {} argument(s)",
                    args.len()
                ));
            }
            if phase7_type_name_contains_any(&args[0]) {
                return Err("E_HIGH_CHANNEL_ITEM_ANY_001: channel<any,N> is forbidden".into());
            }
            let TypeName::Simple(capacity) = &args[1] else {
                return Err("E_HIGH_CHANNEL_CAPACITY_001: channel capacity must be a positive integer literal".into());
            };
            if capacity
                .parse::<usize>()
                .ok()
                .filter(|value| *value > 0)
                .is_none()
            {
                return Err(
                    "E_HIGH_CHANNEL_CAPACITY_001: channel capacity must be greater than zero"
                        .into(),
                );
            }
            phase9_validate_type_name(&args[0])
        }
        TypeName::Generic { base, args } if phase9_coroutine_protocol_name(base).is_some() => {
            if args.len() != 1 {
                return Err(format!(
                    "E_HIGH_GENERATOR_ARITY_001: {} expects one item type, got {}",
                    phase9_coroutine_protocol_name(base).unwrap_or("generator protocol"),
                    args.len()
                ));
            }
            if phase7_type_name_contains_any(&args[0]) {
                return Err(format!(
                    "E_HIGH_ANY_LEAK_001: {}<any> is forbidden",
                    phase9_coroutine_protocol_name(base).unwrap_or("generator protocol")
                ));
            }
            phase9_validate_type_name(&args[0])
        }
        TypeName::Generic { args, .. } => {
            for arg in args {
                phase9_validate_type_name(arg)?;
            }
            Ok(())
        }
    }
}

fn phase9_function_call_return_type(function: &FunctionDecl) -> SemaType {
    let ret = lower_type(&function.return_type);
    if function.is_async && phase9_generator_item_type(&function.return_type).is_none() {
        SemaType::Generic {
            base: "Future".into(),
            args: vec![ret],
        }
    } else {
        ret
    }
}

fn phase9_collect_function_effects(program: &Program) -> HashMap<String, HashSet<String>> {
    let mut out = HashMap::new();
    for container in &program.containers {
        if container.context.is_some() {
            continue;
        }
        for section in &container.sections {
            if let Section::Fn(functions) | Section::MoveFn(functions) = section {
                for function in functions {
                    out.insert(
                        function.name.clone(),
                        function
                            .effects
                            .iter()
                            .map(|effect| effect.to_ascii_lowercase())
                            .collect(),
                    );
                }
            }
        }
    }
    out
}

fn phase9_expr_function_call_name(expr: &Expr) -> Option<&str> {
    match expr {
        Expr::Call { callee, .. } => Some(callee.split('<').next().unwrap_or(callee)),
        Expr::QualifiedCall { path, .. } => path.last().map(String::as_str),
        _ => None,
    }
}

fn phase9_validate_expr(
    program: &Program,
    current_container_name: &str,
    expr: &Expr,
    scope: &HashMap<String, SemaType>,
    current_context: &Option<Context>,
) -> Result<(), String> {
    match expr {
        Expr::StructLiteral { fields, .. } => {
            for (_, value) in fields {
                phase9_validate_expr(
                    program,
                    current_container_name,
                    value,
                    scope,
                    current_context,
                )?;
            }
            Ok(())
        }
        Expr::Call { callee, args } => {
            for arg in args {
                phase9_validate_expr(program, current_container_name, arg, scope, current_context)?;
            }
            let (base, explicit_type_args) = split_generic_callee(callee);
            match base.as_str() {
                "async" => {
                    return Err(
                        "E_HIGH_ASYNC_FN_001: async is function syntax, not a callable value"
                            .into(),
                    )
                }
                "await" => {
                    if args.len() != 1 {
                        return Err("E_HIGH_AWAIT_PARSE_001: await expects one expression".into());
                    }
                    let waited =
                        infer_expr_type(program, current_container_name, &args[0], scope, current_context)?;
                    if phase9_future_inner(&waited).is_none() {
                        return Err(format!(
                            "E_HIGH_AWAIT_NON_FUTURE_001: await expects Future<T>, got {}",
                            render_sema_type(&waited)
                        ));
                    }
                }
                "spawn" => {
                    if args.len() != 1 {
                        return Err("E_HIGH_SPAWN_PARSE_001: spawn expects one async expression".into());
                    }
                    let spawned =
                        infer_expr_type(program, current_container_name, &args[0], scope, current_context)?;
                    if phase9_future_inner(&spawned).is_none() {
                        return Err(format!(
                            "E_HIGH_SPAWN_NON_ASYNC_001: spawn expects async/Future expression, got {}",
                            render_sema_type(&spawned)
                        ));
                    }
                }
                "join" => {
                    if args.len() != 1 {
                        return Err("E_HIGH_JOIN_PARSE_001: join expects one Task<T>".into());
                    }
                    let task =
                        infer_expr_type(program, current_container_name, &args[0], scope, current_context)?;
                    if phase9_task_inner(&task).is_none() {
                        return Err(format!(
                            "E_HIGH_JOIN_NON_TASK_001: join expects Task<T>, got {}",
                            render_sema_type(&task)
                        ));
                    }
                }
                "channelCreate" => {
                    if !args.is_empty() || explicit_type_args.len() != 2 {
                        return Err(
                            "E_HIGH_CHANNEL_PARSE_001: channelCreate<T,N>() expects type and capacity parameters"
                                .into(),
                        );
                    }
                    if matches!(&explicit_type_args[0], SemaType::Simple(name) if name.eq_ignore_ascii_case("any"))
                    {
                        return Err("E_HIGH_CHANNEL_ITEM_ANY_001: channel item cannot be any".into());
                    }
                    let SemaType::Simple(capacity) = &explicit_type_args[1] else {
                        return Err("E_HIGH_CHANNEL_CAPACITY_001: channel capacity must be a positive integer literal".into());
                    };
                    if capacity.parse::<usize>().ok().filter(|value| *value > 0).is_none() {
                        return Err(
                            "E_HIGH_CHANNEL_CAPACITY_001: channel capacity must be greater than zero"
                                .into(),
                        );
                    }
                }
                "send" => {
                    return Err(
                        "E_HIGH_CHANNEL_BACKPRESSURE_001: send requires explicit backpressure policy; use sendBlocking or trySend"
                            .into(),
                    )
                }
                "sendBlocking" | "trySend" => {
                    if args.len() != 2 {
                        return Err("E_HIGH_CHANNEL_SEND_001: channel send expects channel and item".into());
                    }
                    let channel =
                        infer_expr_type(program, current_container_name, &args[0], scope, current_context)?;
                    let Some((item_ty, capacity)) = phase9_channel_parts(&channel) else {
                        return Err(format!(
                            "E_HIGH_CHANNEL_SEND_001: send expects channel<T,N>, got {}",
                            render_sema_type(&channel)
                        ));
                    };
                    if capacity == 0 {
                        return Err(
                            "E_HIGH_CHANNEL_CAPACITY_001: channel capacity must be greater than zero"
                                .into(),
                        );
                    }
                    let value_ty =
                        infer_expr_type(program, current_container_name, &args[1], scope, current_context)?;
                    if !type_compatible(&value_ty, &item_ty) {
                        return Err(format!(
                            "E_HIGH_CHANNEL_SEND_001: send expects {}, got {}",
                            render_sema_type(&item_ty),
                            render_sema_type(&value_ty)
                        ));
                    }
                }
                "recv" | "tryRecv" | "recvBlocking" => {
                    if args.len() != 1 {
                        return Err("E_HIGH_CHANNEL_RECV_001: recv expects one channel".into());
                    }
                    let channel =
                        infer_expr_type(program, current_container_name, &args[0], scope, current_context)?;
                    if phase9_channel_parts(&channel).is_none() {
                        return Err(format!(
                            "E_HIGH_CHANNEL_RECV_001: recv expects channel<T,N>, got {}",
                            render_sema_type(&channel)
                        ));
                    }
                }
                "yield" => {
                    if args.len() != 1 {
                        return Err("E_HIGH_YIELD_ARITY_001: yield expects one value".into());
                    }
                    let expected = PHASE9_GENERATOR_ITEM.with(|cell| cell.borrow().clone());
                    let Some(expected) = expected else {
                        return Err(
                            "E_HIGH_YIELD_CONTEXT_001: yield is only valid inside Generator<T>, Stream<T> or AsyncStream<T>"
                                .into(),
                        );
                    };
                    let actual = infer_expr_type(
                        program,
                        current_container_name,
                        &args[0],
                        scope,
                        current_context,
                    )?;
                    if !type_compatible(&actual, &expected) {
                        return Err(format!(
                            "E_HIGH_YIELD_TYPE_001: yielded value expected {}, got {}",
                            render_sema_type(&expected),
                            render_sema_type(&actual)
                        ));
                    }
                }
                "unboundedChannel" => {
                    return Err(
                        "E_HIGH_CHANNEL_UNBOUNDED_001: unbounded channels are forbidden in Phase 9"
                            .into(),
                    )
                }
                "lambda" | "closure" | "asyncClosure" => {
                    return Err(
                        "E_HIGH_OBSOLETE_CALLABLE_SPELLING_001: lambda(...), closure(...) and asyncClosure(...) are obsolete; use a typed closure literal"
                            .into(),
                    )
                }
                "eraseEffects" => {
                    return Err(
                        "E_HIGH_EFFECT_ERASURE_001: effect erasure is forbidden in Phase 9"
                            .into(),
                    )
                }
                _ => {}
            }
            Ok(())
        }
        Expr::QualifiedCall { args, .. } => {
            for arg in args {
                phase9_validate_expr(program, current_container_name, arg, scope, current_context)?;
            }
            Ok(())
        }
        Expr::MethodCall { receiver, args, .. } => {
            phase9_validate_expr(
                program,
                current_container_name,
                receiver,
                scope,
                current_context,
            )?;
            for arg in args {
                phase9_validate_expr(program, current_container_name, arg, scope, current_context)?;
            }
            Ok(())
        }
        Expr::VectorLiteral(items) | Expr::ArrayLiteral(items) => {
            for item in items {
                phase9_validate_expr(
                    program,
                    current_container_name,
                    item,
                    scope,
                    current_context,
                )?;
            }
            Ok(())
        }
        Expr::Index { target, index } => {
            phase9_validate_expr(
                program,
                current_container_name,
                target,
                scope,
                current_context,
            )?;
            phase9_validate_expr(
                program,
                current_container_name,
                index,
                scope,
                current_context,
            )
        }
        Expr::StrictCheckExpr { ty, value, .. } => {
            phase9_validate_type_name(ty)?;
            phase9_validate_expr(
                program,
                current_container_name,
                value,
                scope,
                current_context,
            )
        }
        Expr::PostIncrement { .. }
        | Expr::FieldPostIncrement { .. }
        | Expr::PointerPostIncrementRead { .. } => {
            infer_expr_type(
                program,
                current_container_name,
                expr,
                scope,
                current_context,
            )?;
            Ok(())
        }
        Expr::Unary { expr, .. } => phase9_validate_expr(
            program,
            current_container_name,
            expr,
            scope,
            current_context,
        ),
        Expr::Binary { left, right, .. } => {
            phase9_validate_expr(
                program,
                current_container_name,
                left,
                scope,
                current_context,
            )?;
            phase9_validate_expr(
                program,
                current_container_name,
                right,
                scope,
                current_context,
            )
        }
        Expr::IfElse {
            condition,
            then_expr,
            else_expr,
        } => {
            phase9_validate_expr(
                program,
                current_container_name,
                condition,
                scope,
                current_context,
            )?;
            phase9_validate_expr(
                program,
                current_container_name,
                then_expr,
                scope,
                current_context,
            )?;
            phase9_validate_expr(
                program,
                current_container_name,
                else_expr,
                scope,
                current_context,
            )
        }
        Expr::Closure(closure) => {
            let mut closure_scope = scope.clone();
            for param in &closure.params {
                phase9_validate_type_name(&param.ty)?;
                closure_scope.insert(param.name.clone(), lower_type(&param.ty));
            }
            phase9_validate_type_name(&closure.return_type)?;
            let generator_item =
                phase9_validate_generator_mode(closure.is_async, &closure.return_type, "closure")?;
            let previous_generator =
                PHASE9_GENERATOR_ITEM.with(|cell| cell.replace(generator_item));
            let validation = (|| {
                for stmt in &closure.body {
                    phase9_validate_stmt(
                        program,
                        current_container_name,
                        stmt,
                        &mut closure_scope,
                        current_context,
                    )?;
                }
                Ok(())
            })();
            PHASE9_GENERATOR_ITEM.with(|cell| {
                cell.replace(previous_generator);
            });
            validation
        }
        Expr::Bool(_)
        | Expr::Number(_)
        | Expr::Char(_)
        | Expr::String(_)
        | Expr::Identifier(_)
        | Expr::ContextRef(_)
        | Expr::Dev(_) => Ok(()),
    }
}

fn phase9_required_effects_expr(
    expr: &Expr,
    function_effects: &HashMap<String, HashSet<String>>,
    out: &mut HashSet<String>,
) {
    match expr {
        Expr::Call { callee, args } => {
            let (base, _) = split_generic_callee(callee);
            match base.as_str() {
                "await" => {
                    out.insert("async.await".into());
                }
                "spawn" => {
                    out.insert("task.spawn".into());
                }
                "join" => {
                    out.insert("async.await".into());
                }
                "sendBlocking" | "trySend" => {
                    out.insert("channel.send".into());
                }
                "recv" | "tryRecv" | "recvBlocking" => {
                    out.insert("channel.recv".into());
                }
                _ => {
                    if let Some(effects) = function_effects.get(base.as_str()) {
                        out.extend(
                            effects
                                .iter()
                                .filter(|effect| effect.as_str() != "pure")
                                .cloned(),
                        );
                    }
                }
            }
            for arg in args {
                phase9_required_effects_expr(arg, function_effects, out);
            }
        }
        Expr::QualifiedCall { path, args } => {
            if let Some(last) = path.last() {
                if let Some(effects) = function_effects.get(last.as_str()) {
                    out.extend(
                        effects
                            .iter()
                            .filter(|effect| effect.as_str() != "pure")
                            .cloned(),
                    );
                }
            }
            for arg in args {
                phase9_required_effects_expr(arg, function_effects, out);
            }
        }
        Expr::MethodCall { receiver, args, .. } => {
            phase9_required_effects_expr(receiver, function_effects, out);
            for arg in args {
                phase9_required_effects_expr(arg, function_effects, out);
            }
        }
        Expr::VectorLiteral(items) | Expr::ArrayLiteral(items) => {
            for item in items {
                phase9_required_effects_expr(item, function_effects, out);
            }
        }
        Expr::Index { target, index } => {
            phase9_required_effects_expr(target, function_effects, out);
            phase9_required_effects_expr(index, function_effects, out);
        }
        Expr::StrictCheckExpr { value, .. } | Expr::Unary { expr: value, .. } => {
            phase9_required_effects_expr(value, function_effects, out);
        }
        Expr::Binary { left, right, .. } => {
            phase9_required_effects_expr(left, function_effects, out);
            phase9_required_effects_expr(right, function_effects, out);
        }
        Expr::IfElse {
            condition,
            then_expr,
            else_expr,
        } => {
            phase9_required_effects_expr(condition, function_effects, out);
            phase9_required_effects_expr(then_expr, function_effects, out);
            phase9_required_effects_expr(else_expr, function_effects, out);
        }
        _ => {}
    }
}

fn phase9_required_effects_stmt(
    stmt: &Stmt,
    function_effects: &HashMap<String, HashSet<String>>,
    out: &mut HashSet<String>,
) {
    match stmt {
        Stmt::Return(expr)
        | Stmt::Expr(expr)
        | Stmt::Print { value: expr, .. }
        | Stmt::StrictCheck { value: expr, .. }
        | Stmt::Projection { value: expr, .. } => {
            phase9_required_effects_expr(expr, function_effects, out);
        }
        Stmt::If {
            condition,
            then_block,
            else_block,
        } => {
            phase9_required_effects_expr(condition, function_effects, out);
            phase9_required_effects_stmts(then_block, function_effects, out);
            phase9_required_effects_stmts(else_block, function_effects, out);
        }
        Stmt::Unless { condition, body }
        | Stmt::While { condition, body }
        | Stmt::DoWhile { condition, body }
        | Stmt::RepeatUntil { condition, body } => {
            phase9_required_effects_expr(condition, function_effects, out);
            phase9_required_effects_stmts(body, function_effects, out);
        }
        Stmt::ForIn { iterable, body, .. } | Stmt::SameIn { iterable, body, .. } => {
            phase9_required_effects_expr(iterable, function_effects, out);
            phase9_required_effects_stmts(body, function_effects, out);
        }
        Stmt::ForRange {
            start,
            end,
            step,
            body,
            ..
        } => {
            phase9_required_effects_expr(start, function_effects, out);
            phase9_required_effects_expr(end, function_effects, out);
            if let Some(step) = step {
                phase9_required_effects_expr(step, function_effects, out);
            }
            phase9_required_effects_stmts(body, function_effects, out);
        }
        Stmt::ForClassic {
            init,
            condition,
            step,
            body,
        } => {
            if let Some(init) = init {
                phase9_required_effects_stmt(init, function_effects, out);
            }
            if let Some(condition) = condition {
                phase9_required_effects_expr(condition, function_effects, out);
            }
            if let Some(step) = step {
                phase9_required_effects_stmt(step, function_effects, out);
            }
            phase9_required_effects_stmts(body, function_effects, out);
        }
        Stmt::Switch {
            value,
            cases,
            default,
        }
        | Stmt::Match {
            value,
            cases,
            default,
        } => {
            phase9_required_effects_expr(value, function_effects, out);
            for (case_expr, block) in cases {
                phase9_required_effects_expr(case_expr, function_effects, out);
                phase9_required_effects_stmts(block, function_effects, out);
            }
            phase9_required_effects_stmts(default, function_effects, out);
        }
        Stmt::PatternMatch { value, arms } => {
            phase9_required_effects_expr(value, function_effects, out);
            for arm in arms {
                if let Pattern::Literal(expr) = &arm.pattern {
                    phase9_required_effects_expr(expr, function_effects, out);
                }
                if let Some(guard) = &arm.guard {
                    phase9_required_effects_expr(guard, function_effects, out);
                }
                phase9_required_effects_stmts(&arm.body, function_effects, out);
            }
        }
        Stmt::Select { branches, default } => {
            for (expr, block) in branches {
                phase9_required_effects_expr(expr, function_effects, out);
                phase9_required_effects_stmts(block, function_effects, out);
            }
            phase9_required_effects_stmts(default, function_effects, out);
        }
        Stmt::Loop { body } | Stmt::RepeatCount { body, .. } | Stmt::EachDoWhile { body, .. } => {
            phase9_required_effects_stmts(body, function_effects, out);
        }
        Stmt::GuardElse {
            condition,
            else_block,
        } => {
            phase9_required_effects_expr(condition, function_effects, out);
            phase9_required_effects_stmts(else_block, function_effects, out);
        }
        Stmt::Labeled { stmt, .. } => phase9_required_effects_stmt(stmt, function_effects, out),
        _ => {}
    }
}

fn phase9_required_effects_stmts(
    stmts: &[Stmt],
    function_effects: &HashMap<String, HashSet<String>>,
    out: &mut HashSet<String>,
) {
    for stmt in stmts {
        phase9_required_effects_stmt(stmt, function_effects, out);
    }
}

fn phase9_spawn_write_target(
    expr: &Expr,
    function_effects: &HashMap<String, HashSet<String>>,
) -> Option<String> {
    let args = match expr {
        Expr::Call { args, .. } | Expr::QualifiedCall { args, .. } => args,
        _ => return None,
    };
    let callee_name = phase9_expr_function_call_name(expr)?;
    let effects = function_effects.get(callee_name)?;
    if !effects.contains("state.write") {
        return None;
    }
    args.first()
        .and_then(phase8_expr_symbol)
        .map(str::to_string)
}

fn phase9_collect_spawn_writes_expr(
    expr: &Expr,
    function_effects: &HashMap<String, HashSet<String>>,
    out: &mut Vec<String>,
) {
    match expr {
        Expr::Call { callee, args } if callee == "spawn" => {
            if let Some(arg) = args.first() {
                if let Some(target) = phase9_spawn_write_target(arg, function_effects) {
                    out.push(target);
                }
                phase9_collect_spawn_writes_expr(arg, function_effects, out);
            }
        }
        Expr::Call { args, .. } | Expr::QualifiedCall { args, .. } => {
            for arg in args {
                phase9_collect_spawn_writes_expr(arg, function_effects, out);
            }
        }
        Expr::MethodCall { receiver, args, .. } => {
            phase9_collect_spawn_writes_expr(receiver, function_effects, out);
            for arg in args {
                phase9_collect_spawn_writes_expr(arg, function_effects, out);
            }
        }
        Expr::VectorLiteral(items) | Expr::ArrayLiteral(items) => {
            for item in items {
                phase9_collect_spawn_writes_expr(item, function_effects, out);
            }
        }
        Expr::Index { target, index } => {
            phase9_collect_spawn_writes_expr(target, function_effects, out);
            phase9_collect_spawn_writes_expr(index, function_effects, out);
        }
        Expr::StrictCheckExpr { value, .. } | Expr::Unary { expr: value, .. } => {
            phase9_collect_spawn_writes_expr(value, function_effects, out);
        }
        Expr::Binary { left, right, .. } => {
            phase9_collect_spawn_writes_expr(left, function_effects, out);
            phase9_collect_spawn_writes_expr(right, function_effects, out);
        }
        Expr::IfElse {
            condition,
            then_expr,
            else_expr,
        } => {
            phase9_collect_spawn_writes_expr(condition, function_effects, out);
            phase9_collect_spawn_writes_expr(then_expr, function_effects, out);
            phase9_collect_spawn_writes_expr(else_expr, function_effects, out);
        }
        _ => {}
    }
}

fn phase9_collect_spawn_writes_stmt(
    stmt: &Stmt,
    function_effects: &HashMap<String, HashSet<String>>,
    out: &mut Vec<String>,
) {
    match stmt {
        Stmt::Return(expr)
        | Stmt::Expr(expr)
        | Stmt::Print { value: expr, .. }
        | Stmt::StrictCheck { value: expr, .. }
        | Stmt::Projection { value: expr, .. } => {
            phase9_collect_spawn_writes_expr(expr, function_effects, out);
        }
        Stmt::If {
            condition,
            then_block,
            else_block,
        } => {
            phase9_collect_spawn_writes_expr(condition, function_effects, out);
            phase9_collect_spawn_writes_stmts(then_block, function_effects, out);
            phase9_collect_spawn_writes_stmts(else_block, function_effects, out);
        }
        Stmt::Unless { condition, body }
        | Stmt::While { condition, body }
        | Stmt::DoWhile { condition, body }
        | Stmt::RepeatUntil { condition, body } => {
            phase9_collect_spawn_writes_expr(condition, function_effects, out);
            phase9_collect_spawn_writes_stmts(body, function_effects, out);
        }
        Stmt::ForIn { iterable, body, .. } | Stmt::SameIn { iterable, body, .. } => {
            phase9_collect_spawn_writes_expr(iterable, function_effects, out);
            phase9_collect_spawn_writes_stmts(body, function_effects, out);
        }
        Stmt::ForRange {
            start,
            end,
            step,
            body,
            ..
        } => {
            phase9_collect_spawn_writes_expr(start, function_effects, out);
            phase9_collect_spawn_writes_expr(end, function_effects, out);
            if let Some(step) = step {
                phase9_collect_spawn_writes_expr(step, function_effects, out);
            }
            phase9_collect_spawn_writes_stmts(body, function_effects, out);
        }
        Stmt::ForClassic {
            init,
            condition,
            step,
            body,
        } => {
            if let Some(init) = init {
                phase9_collect_spawn_writes_stmt(init, function_effects, out);
            }
            if let Some(condition) = condition {
                phase9_collect_spawn_writes_expr(condition, function_effects, out);
            }
            if let Some(step) = step {
                phase9_collect_spawn_writes_stmt(step, function_effects, out);
            }
            phase9_collect_spawn_writes_stmts(body, function_effects, out);
        }
        Stmt::Switch {
            value,
            cases,
            default,
        }
        | Stmt::Match {
            value,
            cases,
            default,
        } => {
            phase9_collect_spawn_writes_expr(value, function_effects, out);
            for (case_expr, block) in cases {
                phase9_collect_spawn_writes_expr(case_expr, function_effects, out);
                phase9_collect_spawn_writes_stmts(block, function_effects, out);
            }
            phase9_collect_spawn_writes_stmts(default, function_effects, out);
        }
        Stmt::PatternMatch { value, arms } => {
            phase9_collect_spawn_writes_expr(value, function_effects, out);
            for arm in arms {
                if let Some(guard) = &arm.guard {
                    phase9_collect_spawn_writes_expr(guard, function_effects, out);
                }
                phase9_collect_spawn_writes_stmts(&arm.body, function_effects, out);
            }
        }
        Stmt::Select { branches, default } => {
            for (expr, block) in branches {
                phase9_collect_spawn_writes_expr(expr, function_effects, out);
                phase9_collect_spawn_writes_stmts(block, function_effects, out);
            }
            phase9_collect_spawn_writes_stmts(default, function_effects, out);
        }
        Stmt::Loop { body } | Stmt::RepeatCount { body, .. } | Stmt::EachDoWhile { body, .. } => {
            phase9_collect_spawn_writes_stmts(body, function_effects, out);
        }
        Stmt::GuardElse {
            condition,
            else_block,
        } => {
            phase9_collect_spawn_writes_expr(condition, function_effects, out);
            phase9_collect_spawn_writes_stmts(else_block, function_effects, out);
        }
        Stmt::Labeled { stmt, .. } => phase9_collect_spawn_writes_stmt(stmt, function_effects, out),
        _ => {}
    }
}

fn phase9_collect_spawn_writes_stmts(
    stmts: &[Stmt],
    function_effects: &HashMap<String, HashSet<String>>,
    out: &mut Vec<String>,
) {
    for stmt in stmts {
        phase9_collect_spawn_writes_stmt(stmt, function_effects, out);
    }
}

fn phase9_validate_stmt(
    program: &Program,
    current_container_name: &str,
    stmt: &Stmt,
    scope: &mut HashMap<String, SemaType>,
    current_context: &Option<Context>,
) -> Result<(), String> {
    match stmt {
        Stmt::Projection { target, ty, value } | Stmt::StrictCheck { target, ty, value } => {
            phase9_validate_type_name(ty)?;
            phase9_validate_expr(
                program,
                current_container_name,
                value,
                scope,
                current_context,
            )?;
            if let AssignTarget::Context(ctx) = target {
                if ctx.path.len() == 1 {
                    scope.insert(ctx.path[0].clone(), lower_type(ty));
                }
            }
            Ok(())
        }
        Stmt::Return(expr) | Stmt::Expr(expr) | Stmt::Print { value: expr, .. } => {
            phase9_validate_expr(
                program,
                current_container_name,
                expr,
                scope,
                current_context,
            )
        }
        Stmt::If {
            condition,
            then_block,
            else_block,
        } => {
            phase9_validate_expr(
                program,
                current_container_name,
                condition,
                scope,
                current_context,
            )?;
            let mut then_scope = scope.clone();
            phase9_validate_stmts(
                program,
                current_container_name,
                then_block,
                &mut then_scope,
                current_context,
            )?;
            let mut else_scope = scope.clone();
            phase9_validate_stmts(
                program,
                current_container_name,
                else_block,
                &mut else_scope,
                current_context,
            )
        }
        Stmt::Unless { condition, body }
        | Stmt::While { condition, body }
        | Stmt::DoWhile { condition, body }
        | Stmt::RepeatUntil { condition, body } => {
            phase9_validate_expr(
                program,
                current_container_name,
                condition,
                scope,
                current_context,
            )?;
            let mut loop_scope = scope.clone();
            phase9_validate_stmts(
                program,
                current_container_name,
                body,
                &mut loop_scope,
                current_context,
            )
        }
        Stmt::ForIn {
            iterable,
            body,
            item,
        }
        | Stmt::SameIn {
            iterable,
            body,
            item,
        } => {
            phase9_validate_expr(
                program,
                current_container_name,
                iterable,
                scope,
                current_context,
            )?;
            let mut loop_scope = scope.clone();
            loop_scope.entry(item.clone()).or_insert(SemaType::Unknown);
            phase9_validate_stmts(
                program,
                current_container_name,
                body,
                &mut loop_scope,
                current_context,
            )
        }
        Stmt::ForRange {
            item,
            start,
            end,
            step,
            body,
            ..
        } => {
            phase9_validate_expr(
                program,
                current_container_name,
                start,
                scope,
                current_context,
            )?;
            phase9_validate_expr(program, current_container_name, end, scope, current_context)?;
            if let Some(step) = step {
                phase9_validate_expr(
                    program,
                    current_container_name,
                    step,
                    scope,
                    current_context,
                )?;
            }
            let mut loop_scope = scope.clone();
            loop_scope.insert(item.clone(), SemaType::Simple("int".into()));
            phase9_validate_stmts(
                program,
                current_container_name,
                body,
                &mut loop_scope,
                current_context,
            )
        }
        Stmt::ForClassic {
            init,
            condition,
            step,
            body,
        } => {
            let mut local_scope = scope.clone();
            if let Some(init) = init {
                phase9_validate_stmt(
                    program,
                    current_container_name,
                    init,
                    &mut local_scope,
                    current_context,
                )?;
            }
            if let Some(condition) = condition {
                phase9_validate_expr(
                    program,
                    current_container_name,
                    condition,
                    &local_scope,
                    current_context,
                )?;
            }
            if let Some(step) = step {
                phase9_validate_stmt(
                    program,
                    current_container_name,
                    step,
                    &mut local_scope,
                    current_context,
                )?;
            }
            phase9_validate_stmts(
                program,
                current_container_name,
                body,
                &mut local_scope,
                current_context,
            )
        }
        Stmt::Switch {
            value,
            cases,
            default,
        }
        | Stmt::Match {
            value,
            cases,
            default,
        } => {
            phase9_validate_expr(
                program,
                current_container_name,
                value,
                scope,
                current_context,
            )?;
            for (case_expr, block) in cases {
                phase9_validate_expr(
                    program,
                    current_container_name,
                    case_expr,
                    scope,
                    current_context,
                )?;
                let mut block_scope = scope.clone();
                phase9_validate_stmts(
                    program,
                    current_container_name,
                    block,
                    &mut block_scope,
                    current_context,
                )?;
            }
            let mut default_scope = scope.clone();
            phase9_validate_stmts(
                program,
                current_container_name,
                default,
                &mut default_scope,
                current_context,
            )
        }
        Stmt::PatternMatch { value, arms } => {
            phase9_validate_expr(
                program,
                current_container_name,
                value,
                scope,
                current_context,
            )?;
            for arm in arms {
                if let Some(guard) = &arm.guard {
                    phase9_validate_expr(
                        program,
                        current_container_name,
                        guard,
                        scope,
                        current_context,
                    )?;
                }
                let mut arm_scope = scope.clone();
                phase9_validate_stmts(
                    program,
                    current_container_name,
                    &arm.body,
                    &mut arm_scope,
                    current_context,
                )?;
            }
            Ok(())
        }
        Stmt::Select { branches, default } => {
            for (expr, block) in branches {
                phase9_validate_expr(
                    program,
                    current_container_name,
                    expr,
                    scope,
                    current_context,
                )?;
                let mut block_scope = scope.clone();
                phase9_validate_stmts(
                    program,
                    current_container_name,
                    block,
                    &mut block_scope,
                    current_context,
                )?;
            }
            let mut default_scope = scope.clone();
            phase9_validate_stmts(
                program,
                current_container_name,
                default,
                &mut default_scope,
                current_context,
            )
        }
        Stmt::GuardElse {
            condition,
            else_block,
        } => {
            phase9_validate_expr(
                program,
                current_container_name,
                condition,
                scope,
                current_context,
            )?;
            let mut else_scope = scope.clone();
            phase9_validate_stmts(
                program,
                current_container_name,
                else_block,
                &mut else_scope,
                current_context,
            )
        }
        Stmt::Loop { body } | Stmt::RepeatCount { body, .. } | Stmt::EachDoWhile { body, .. } => {
            let mut loop_scope = scope.clone();
            phase9_validate_stmts(
                program,
                current_container_name,
                body,
                &mut loop_scope,
                current_context,
            )
        }
        Stmt::Labeled { stmt, .. } => phase9_validate_stmt(
            program,
            current_container_name,
            stmt,
            scope,
            current_context,
        ),
        _ => Ok(()),
    }
}

fn phase9_validate_stmts(
    program: &Program,
    current_container_name: &str,
    stmts: &[Stmt],
    scope: &mut HashMap<String, SemaType>,
    current_context: &Option<Context>,
) -> Result<(), String> {
    for stmt in stmts {
        phase9_validate_stmt(
            program,
            current_container_name,
            stmt,
            scope,
            current_context,
        )?;
    }
    Ok(())
}

fn validate_high_phase9_async_effects_concurrency(program: &Program) -> Result<(), String> {
    let function_effects = phase9_collect_function_effects(program);
    for container in &program.containers {
        if container.context.is_some() {
            continue;
        }

        let mut container_scope: HashMap<String, SemaType> = HashMap::new();
        for section in &container.sections {
            if let Section::Stc(decls) = section {
                for decl in decls {
                    let StcDecl::Typed { name, ty, init, .. } = decl;
                    phase9_validate_type_name(ty)?;
                    container_scope.insert(name.clone(), lower_type(ty));
                    if let Some(init) = init {
                        phase9_validate_expr(
                            program,
                            &container.name,
                            init,
                            &container_scope,
                            &container.context,
                        )?;
                    }
                }
            }
            if let Section::Local(local) = section {
                for decl in &local.decls {
                    if let Some((name, ty, init, _is_const)) = local_decl_value_parts(decl) {
                        phase9_validate_type_name(ty)?;
                        container_scope.insert(name.clone(), lower_type(ty));
                        if let Some(init) = init {
                            phase9_validate_expr(
                                program,
                                &container.name,
                                init,
                                &container_scope,
                                &container.context,
                            )?;
                        }
                    }
                }
            }
        }

        for section in &container.sections {
            match section {
                Section::Fn(functions) | Section::MoveFn(functions) => {
                    for function in functions {
                        for effect in &function.effects {
                            if !phase9_allowed_effect(effect) {
                                return Err(format!(
                                    "E_HIGH_EFFECT_UNKNOWN_001: unknown effect '{}'",
                                    effect
                                ));
                            }
                        }
                        if function
                            .effects
                            .iter()
                            .any(|effect| effect.eq_ignore_ascii_case("pure"))
                            && function.effects.len() > 1
                        {
                            return Err(format!(
                                "E_HIGH_EFFECT_NOT_ALLOWED_001: pure function '{}' cannot declare additional effects",
                                function.name
                            ));
                        }
                        for param in &function.params {
                            phase9_validate_type_name(&param.ty)?;
                        }
                        phase9_validate_type_name(&function.return_type)?;
                        let mut function_scope = container_scope.clone();
                        for param in &function.params {
                            function_scope.insert(param.name.clone(), lower_type(&param.ty));
                        }
                        let generator_item = phase9_validate_generator_mode(
                            function.is_async,
                            &function.return_type,
                            &function.name,
                        )?;
                        let previous_generator =
                            PHASE9_GENERATOR_ITEM.with(|cell| cell.replace(generator_item));
                        let validation = phase9_validate_stmts(
                            program,
                            &container.name,
                            &function.public_body,
                            &mut function_scope,
                            &container.context,
                        );
                        PHASE9_GENERATOR_ITEM.with(|cell| {
                            cell.replace(previous_generator);
                        });
                        validation?;

                        let allowed: HashSet<String> = function
                            .effects
                            .iter()
                            .map(|effect| effect.to_ascii_lowercase())
                            .collect();
                        let mut required = HashSet::new();
                        phase9_required_effects_stmts(
                            &function.public_body,
                            &function_effects,
                            &mut required,
                        );
                        if allowed.contains("pure") && !required.is_empty() {
                            return Err(format!(
                                "E_HIGH_EFFECT_PURE_VIOLATION_001: pure function '{}' requires effect '{}'",
                                function.name,
                                required.iter().next().cloned().unwrap_or_default()
                            ));
                        }
                        for effect in required {
                            if !allowed.contains(&effect) {
                                if effect == "async.await" {
                                    return Err(format!(
                                        "E_HIGH_AWAIT_CONTEXT_001: function '{}' must declare effects(async.await) to await",
                                        function.name
                                    ));
                                }
                                return Err(format!(
                                    "E_HIGH_EFFECT_MISSING_001: function '{}' must declare effect '{}'",
                                    function.name, effect
                                ));
                            }
                        }

                        let mut writes = Vec::new();
                        phase9_collect_spawn_writes_stmts(
                            &function.public_body,
                            &function_effects,
                            &mut writes,
                        );
                        let mut seen = HashSet::new();
                        for write in writes {
                            if !seen.insert(write.clone()) {
                                return Err(format!(
                                    "E_HIGH_RACE_SHARED_MUT_001: shared mutable state '{}' is written by multiple spawned tasks without synchronization",
                                    write
                                ));
                            }
                        }
                    }
                }
                Section::Traits(traits) => {
                    for trait_decl in traits {
                        for method in &trait_decl.required_methods {
                            for param in &method.params {
                                phase9_validate_type_name(&param.ty)?;
                            }
                            phase9_validate_type_name(&method.return_type)?;
                        }
                        for method in &trait_decl.default_methods {
                            for param in &method.params {
                                phase9_validate_type_name(&param.ty)?;
                            }
                            phase9_validate_type_name(&method.return_type)?;
                        }
                    }
                }
                Section::ImplBlocks(impls) => {
                    for impl_decl in impls {
                        phase9_validate_type_name(&impl_decl.trait_ref)?;
                        phase9_validate_type_name(&impl_decl.for_type)?;
                    }
                }
                Section::Probe(stmts)
                | Section::Final(stmts)
                | Section::Raw(stmts)
                | Section::Binary(stmts)
                | Section::Bind(stmts)
                | Section::Structure(stmts) => {
                    let mut scope = container_scope.clone();
                    phase9_validate_stmts(
                        program,
                        &container.name,
                        stmts,
                        &mut scope,
                        &container.context,
                    )?;
                }
                _ => {}
            }
        }
    }
    Ok(())
}

#[cfg(test)]
mod generator_stream_semantics_tests {
    use super::*;

    fn analyze_source(source: &str) -> Result<SemanticResult, String> {
        let tokens = ncc_lexer::lex(source).expect("generator fixture must lex");
        let program = ncc_parser::parse(tokens).expect("generator fixture must parse");
        analyze(&program)
    }

    #[test]
    fn typed_generator_accepts_compact_and_call_yield_forms() {
        let source = r#"
typedGenerator {
    fn:
        values() -> Generator<int> {
            public:
                yield 1;
                yield(2);
        }
}
"#;
        analyze_source(source).expect("typed generator must pass sema");
    }

    #[test]
    fn async_stream_requires_async_and_checks_item_type() {
        let valid = r#"
typedAsyncStream {
    fn:
        async values() -> AsyncStream<int> {
            public:
                yield 7;
        }
}
"#;
        analyze_source(valid).expect("typed async stream must pass sema");

        let wrong_item = valid.replace("yield 7", "yield \"wrong\"");
        let error = analyze_source(&wrong_item).expect_err("wrong item type must fail");
        assert!(error.contains("E_HIGH_YIELD_TYPE_001"), "{error}");

        let not_async = valid.replace("async values", "values");
        let error = analyze_source(&not_async).expect_err("sync AsyncStream must fail");
        assert!(error.contains("E_HIGH_ASYNC_STREAM_CONTEXT_001"), "{error}");
    }

    #[test]
    fn yield_outside_generator_is_rejected() {
        let source = r#"
invalidYield {
    fn:
        run() -> bool {
            public:
                yield true;
                return true;
        }
}
"#;
        let error = analyze_source(source).expect_err("orphan yield must fail");
        assert!(error.contains("E_HIGH_YIELD_CONTEXT_001"), "{error}");
    }
}

#[derive(Debug, Clone)]
struct Phase10Symbol {
    kind: ExportKind,
    visibility: Option<Visibility>,
    function: Option<FunctionDecl>,
}

#[derive(Debug, Clone)]
struct Phase10ModuleInfo {
    path: Vec<String>,
    path_key: String,
    container: String,
    package: Option<String>,
    profile: Option<String>,
    symbols: HashMap<String, Phase10Symbol>,
    exports: HashMap<String, ExportDecl>,
    uses: Vec<UseDecl>,
}

fn phase10_path_key(path: &[String]) -> String {
    path.iter()
        .map(|part| part.to_ascii_lowercase())
        .collect::<Vec<_>>()
        .join(".")
}

fn phase10_visibility_is_private(visibility: &Option<Visibility>) -> bool {
    matches!(visibility, Some(Visibility::Private))
}

fn phase10_visibility_is_internal(visibility: &Option<Visibility>) -> bool {
    matches!(visibility, Some(Visibility::Internal))
}

fn phase10_module_path_valid(path: &[String]) -> bool {
    !path.is_empty()
        && path.iter().all(|part| {
            !part.is_empty()
                && part
                    .chars()
                    .all(|ch| ch.is_ascii_lowercase() || ch.is_ascii_digit() || ch == '_')
                && part
                    .chars()
                    .next()
                    .map(|ch| ch.is_ascii_lowercase() || ch == '_')
                    .unwrap_or(false)
        })
}

fn phase10_package_name_valid(name: &str) -> bool {
    !name.is_empty()
        && name
            .chars()
            .all(|ch| ch.is_ascii_lowercase() || ch.is_ascii_digit() || ch == '_')
        && name
            .chars()
            .next()
            .map(|ch| ch.is_ascii_lowercase() || ch == '_')
            .unwrap_or(false)
}

fn phase10_version_valid(version: &str) -> bool {
    let parts: Vec<&str> = version.split('.').collect();
    parts.len() == 3
        && parts
            .iter()
            .all(|part| !part.is_empty() && part.chars().all(|ch| ch.is_ascii_digit()))
}

fn phase10_container_module_decl(
    container: &ncc_parser::Container,
) -> Option<ncc_parser::ModuleDecl> {
    container.sections.iter().find_map(|section| {
        if let Section::ModuleDecl(decl) = section {
            Some(decl.clone())
        } else {
            None
        }
    })
}

fn phase10_container_use_decls(container: &ncc_parser::Container) -> Vec<UseDecl> {
    let mut out = Vec::new();
    for section in &container.sections {
        if let Section::Use(decls) = section {
            out.extend(decls.clone());
        }
    }
    out
}

fn phase10_container_exports(container: &ncc_parser::Container) -> Vec<ExportDecl> {
    let mut out = Vec::new();
    for section in &container.sections {
        if let Section::Exports(decls) = section {
            out.extend(decls.clone());
        }
    }
    out
}

fn phase10_symbol_name(path: &[String]) -> Option<String> {
    path.last().cloned()
}

fn phase10_collect_symbols(container: &ncc_parser::Container) -> HashMap<String, Phase10Symbol> {
    let mut out = HashMap::new();
    for section in &container.sections {
        match section {
            Section::Fn(functions) | Section::MoveFn(functions) => {
                for function in functions {
                    out.insert(
                        function.name.to_ascii_lowercase(),
                        Phase10Symbol {
                            kind: ExportKind::Function,
                            visibility: function.visibility.clone(),
                            function: Some(function.clone()),
                        },
                    );
                }
            }
            Section::Interfaces(items) => {
                for item in items {
                    out.insert(
                        item.name.to_ascii_lowercase(),
                        Phase10Symbol {
                            kind: ExportKind::Interface,
                            visibility: Some(Visibility::Public),
                            function: None,
                        },
                    );
                }
            }
            Section::Traits(items) => {
                for item in items {
                    out.insert(
                        item.name.to_ascii_lowercase(),
                        Phase10Symbol {
                            kind: ExportKind::Trait,
                            visibility: Some(Visibility::Public),
                            function: None,
                        },
                    );
                }
            }
            Section::Enums(items) => {
                for item in items {
                    out.insert(
                        item.name.to_ascii_lowercase(),
                        Phase10Symbol {
                            kind: ExportKind::Enum,
                            visibility: Some(Visibility::Public),
                            function: None,
                        },
                    );
                }
            }
            Section::Contracts(items) => {
                for item in items {
                    out.insert(
                        item.name.to_ascii_lowercase(),
                        Phase10Symbol {
                            kind: ExportKind::Contract,
                            visibility: Some(Visibility::Public),
                            function: None,
                        },
                    );
                }
            }
            Section::TypeContracts(items) => {
                for item in items {
                    out.insert(
                        item.name.to_ascii_lowercase(),
                        Phase10Symbol {
                            kind: ExportKind::Type,
                            visibility: Some(Visibility::Public),
                            function: None,
                        },
                    );
                }
            }
            _ => {}
        }
    }
    out
}

fn phase10_package_profile(
    package: &Option<String>,
    packages: &HashMap<String, ncc_parser::PackageDecl>,
) -> Option<String> {
    let Some(package) = package else {
        return None;
    };
    packages
        .get(&package.to_ascii_lowercase())
        .and_then(|decl| decl.profile.clone())
}

fn phase10_build_modules(program: &Program) -> Result<HashMap<String, Phase10ModuleInfo>, String> {
    let packages: HashMap<String, ncc_parser::PackageDecl> = program
        .packages
        .iter()
        .cloned()
        .map(|decl| (decl.name.to_ascii_lowercase(), decl))
        .collect();
    let mut modules = HashMap::new();

    for container in &program.containers {
        if container.context.is_some() {
            continue;
        }
        let section_module = phase10_container_module_decl(container);
        let top_module = if program.modules.len() == 1 && program.containers.len() == 1 {
            program.modules.first().cloned()
        } else {
            None
        };
        let module_decl = section_module
            .or(top_module)
            .unwrap_or_else(|| ncc_parser::ModuleDecl {
                path: vec![container.name.to_ascii_lowercase()],
                package: None,
            });

        if !phase10_module_path_valid(&module_decl.path) {
            return Err(format!(
                "E_HIGH_MODULE_PATH_001: invalid module path '{}'",
                module_decl.path.join(".")
            ));
        }

        let key = phase10_path_key(&module_decl.path);
        if modules.contains_key(&key) {
            return Err(format!(
                "E_HIGH_MODULE_DUP_001: duplicate module path '{}'",
                module_decl.path.join(".")
            ));
        }

        let profile = phase10_package_profile(&module_decl.package, &packages);
        modules.insert(
            key.clone(),
            Phase10ModuleInfo {
                path: module_decl.path,
                path_key: key,
                container: container.name.clone(),
                package: module_decl.package,
                profile,
                symbols: phase10_collect_symbols(container),
                exports: HashMap::new(),
                uses: phase10_container_use_decls(container),
            },
        );
    }

    for decl in &program.modules {
        if !phase10_module_path_valid(&decl.path) {
            return Err(format!(
                "E_HIGH_MODULE_PATH_001: invalid module path '{}'",
                decl.path.join(".")
            ));
        }
    }

    Ok(modules)
}

fn phase10_use_target_module_path(use_decl: &UseDecl) -> Vec<String> {
    if use_decl.wildcard {
        use_decl.path.clone()
    } else if use_decl.path.len() > 1 {
        use_decl.path[..use_decl.path.len() - 1].to_vec()
    } else {
        use_decl.path.clone()
    }
}

fn phase10_use_symbol(use_decl: &UseDecl) -> Option<String> {
    if use_decl.wildcard {
        None
    } else {
        use_decl.path.last().cloned()
    }
}

fn phase10_use_may_target_declared_module(program: &Program, use_decl: &UseDecl) -> bool {
    let target = phase10_path_key(&phase10_use_target_module_path(use_decl));
    program
        .modules
        .iter()
        .any(|module| phase10_path_key(&module.path) == target)
        || program.containers.iter().any(|container| {
            phase10_container_module_decl(container)
                .map(|module| phase10_path_key(&module.path) == target)
                .unwrap_or(false)
        })
}

fn phase10_validate_packages(
    program: &Program,
) -> Result<HashMap<String, ncc_parser::PackageDecl>, String> {
    let mut packages = HashMap::new();
    for package in &program.packages {
        if !phase10_package_name_valid(&package.name) {
            return Err(format!(
                "E_HIGH_PACKAGE_NAME_001: invalid package name '{}'",
                package.name
            ));
        }
        if let Some(version) = &package.version {
            if !phase10_version_valid(version) {
                return Err(format!(
                    "E_HIGH_PACKAGE_VERSION_001: invalid package version '{}'",
                    version
                ));
            }
        }
        let mut seen_modules = HashSet::new();
        for module in &package.modules {
            let key = phase10_path_key(module);
            if !seen_modules.insert(key) {
                return Err(format!(
                    "E_HIGH_PACKAGE_MODULE_DUP_001: duplicate module '{}' in package '{}'",
                    module.join("."),
                    package.name
                ));
            }
        }
        packages.insert(package.name.to_ascii_lowercase(), package.clone());
    }
    Ok(packages)
}

fn phase10_export_name(export: &ExportDecl) -> String {
    export
        .alias
        .clone()
        .or_else(|| phase10_symbol_name(&export.path))
        .unwrap_or_default()
}

fn phase10_symbol_exportable_kind(symbol: &Phase10Symbol, export: &ExportDecl) -> bool {
    export.kind == ExportKind::Use
        || export.kind == ExportKind::Module
        || export.kind == symbol.kind
        || (export.kind == ExportKind::Type
            && matches!(
                symbol.kind,
                ExportKind::Enum | ExportKind::Interface | ExportKind::Trait
            ))
}

fn phase10_validate_exports(
    modules: &mut HashMap<String, Phase10ModuleInfo>,
    program: &Program,
) -> Result<(), String> {
    let module_by_container: HashMap<String, String> = modules
        .values()
        .map(|module| (module.container.clone(), module.path_key.clone()))
        .collect();

    for container in &program.containers {
        let Some(module_key) = module_by_container.get(&container.name) else {
            continue;
        };
        let exports = phase10_container_exports(container);
        let mut seen = HashSet::new();
        let mut validated = HashMap::new();
        for export in exports {
            let public_name = phase10_export_name(&export);
            let public_key = public_name.to_ascii_lowercase();
            if !seen.insert(public_key.clone()) {
                return Err(format!(
                    "E_HIGH_EXPORT_DUP_001: duplicate export '{}'",
                    public_name
                ));
            }

            if export.kind == ExportKind::Use {
                phase10_validate_reexport(modules, module_key, &export)?;
                validated.insert(public_key, export);
                continue;
            }

            let Some(symbol_name) = phase10_symbol_name(&export.path) else {
                return Err("E_HIGH_EXPORT_UNKNOWN_001: export path is empty".into());
            };
            let symbol_key = symbol_name.to_ascii_lowercase();
            let Some(module) = modules.get(module_key) else {
                continue;
            };
            let Some(symbol) = module.symbols.get(&symbol_key) else {
                return Err(format!(
                    "E_HIGH_EXPORT_UNKNOWN_001: unknown export '{}'",
                    symbol_name
                ));
            };
            if phase10_visibility_is_private(&symbol.visibility) {
                return Err(format!(
                    "E_HIGH_EXPORT_PRIVATE_001: private symbol '{}' cannot be exported",
                    symbol_name
                ));
            }
            if !phase10_symbol_exportable_kind(symbol, &export) {
                return Err(format!(
                    "E_HIGH_EXPORT_UNKNOWN_001: export kind does not match symbol '{}'",
                    symbol_name
                ));
            }
            validated.insert(public_key, export);
        }
        if let Some(module) = modules.get_mut(module_key) {
            module.exports = validated;
        }
    }

    Ok(())
}

fn phase10_validate_reexport(
    modules: &HashMap<String, Phase10ModuleInfo>,
    source_module_key: &str,
    export: &ExportDecl,
) -> Result<(), String> {
    let target_module_path = if export.path.len() > 1 {
        export.path[..export.path.len() - 1].to_vec()
    } else {
        return Err("E_HIGH_EXPORT_REEXPORT_001: re-export requires module.symbol".into());
    };
    let target_key = phase10_path_key(&target_module_path);
    let Some(target_module) = modules.get(&target_key) else {
        return Err(format!(
            "E_HIGH_EXPORT_REEXPORT_001: unresolved re-export '{}'",
            export.path.join(".")
        ));
    };
    let Some(symbol_name) = export.path.last() else {
        return Err("E_HIGH_EXPORT_REEXPORT_001: re-export requires symbol".into());
    };
    let symbol_key = symbol_name.to_ascii_lowercase();
    let Some(symbol) = target_module.symbols.get(&symbol_key) else {
        return Err(format!(
            "E_HIGH_EXPORT_REEXPORT_001: unresolved re-export '{}'",
            export.path.join(".")
        ));
    };
    if phase10_visibility_is_private(&symbol.visibility) {
        return Err(format!(
            "E_HIGH_EXPORT_REEXPORT_001: private symbol '{}' cannot be re-exported",
            symbol_name
        ));
    }
    let Some(source_module) = modules.get(source_module_key) else {
        return Ok(());
    };
    if phase10_visibility_is_internal(&symbol.visibility)
        && source_module.package != target_module.package
    {
        return Err(format!(
            "E_HIGH_EXPORT_REEXPORT_001: internal symbol '{}' cannot be re-exported outside package",
            symbol_name
        ));
    }
    Ok(())
}

fn phase10_validate_use_decl(
    modules: &HashMap<String, Phase10ModuleInfo>,
    current_module: Option<&Phase10ModuleInfo>,
    imported_names: &mut HashMap<String, String>,
    use_decl: &UseDecl,
) -> Result<Vec<String>, String> {
    let target_module_path = phase10_use_target_module_path(use_decl);
    let target_key = phase10_path_key(&target_module_path);
    let Some(target_module) = modules.get(&target_key) else {
        return Err(format!(
            "E_HIGH_USE_UNRESOLVED_001: unresolved import '{}'",
            use_decl.path.join(".")
        ));
    };

    if use_decl.wildcard {
        if current_module
            .and_then(|module| module.profile.as_deref())
            .map(|profile| profile.eq_ignore_ascii_case("secure"))
            .unwrap_or(false)
        {
            return Err(format!(
                "E_HIGH_USE_WILDCARD_DENIED_001: wildcard import '{}' is denied by profile",
                use_decl.path.join(".")
            ));
        }
        let mut imported = Vec::new();
        for export in target_module.exports.values() {
            let name = phase10_export_name(export);
            let key = name.to_ascii_lowercase();
            if let Some(previous) =
                imported_names.insert(key.clone(), target_module.path_key.clone())
            {
                if previous != target_module.path_key {
                    return Err(format!(
                        "E_HIGH_USE_AMBIGUOUS_001: wildcard import makes symbol '{}' ambiguous",
                        name
                    ));
                }
            }
            imported.push(name);
        }
        return Ok(imported);
    }

    let Some(symbol_name) = phase10_use_symbol(use_decl) else {
        return Err(format!(
            "E_HIGH_USE_UNRESOLVED_001: unresolved import '{}'",
            use_decl.path.join(".")
        ));
    };
    let symbol_key = symbol_name.to_ascii_lowercase();
    let Some(symbol) = target_module.symbols.get(&symbol_key) else {
        return Err(format!(
            "E_HIGH_USE_UNRESOLVED_001: unresolved import '{}'",
            use_decl.path.join(".")
        ));
    };
    let exported = target_module.exports.contains_key(&symbol_key);
    if phase10_visibility_is_private(&symbol.visibility) {
        return Err(format!(
            "E_HIGH_USE_PRIVATE_001: private symbol '{}' cannot be imported",
            symbol_name
        ));
    }
    if phase10_visibility_is_internal(&symbol.visibility)
        && current_module
            .map(|module| module.package != target_module.package)
            .unwrap_or(true)
    {
        return Err(format!(
            "E_HIGH_USE_INTERNAL_001: internal symbol '{}' cannot be imported outside package",
            symbol_name
        ));
    }
    if !exported && !phase10_visibility_is_internal(&symbol.visibility) {
        return Err(format!(
            "E_HIGH_USE_UNRESOLVED_001: symbol '{}' is not exported by module '{}'",
            symbol_name,
            target_module.path.join(".")
        ));
    }

    let import_name = use_decl
        .alias
        .clone()
        .unwrap_or_else(|| symbol_name.clone());
    if let Some(current) = current_module {
        if current
            .symbols
            .contains_key(&import_name.to_ascii_lowercase())
        {
            return Err(format!(
                "E_HIGH_USE_ALIAS_DUP_001: import alias '{}' collides with a local symbol",
                import_name
            ));
        }
    }
    if let Some(previous) = imported_names.insert(
        import_name.to_ascii_lowercase(),
        target_module.path_key.clone(),
    ) {
        if previous != target_module.path_key {
            return Err(format!(
                "E_HIGH_USE_AMBIGUOUS_001: import '{}' is ambiguous",
                import_name
            ));
        }
        return Err(format!(
            "E_HIGH_USE_ALIAS_DUP_001: duplicate import alias '{}'",
            import_name
        ));
    }

    Ok(vec![import_name])
}

fn phase10_validate_imports(
    modules: &HashMap<String, Phase10ModuleInfo>,
    program: &Program,
) -> Result<HashMap<String, Vec<String>>, String> {
    let mut imported_by_module = HashMap::new();
    let mut top_level_imported = HashMap::new();
    for use_decl in &program.uses {
        if !phase10_use_may_target_declared_module(program, use_decl) {
            continue;
        }
        phase10_validate_use_decl(modules, None, &mut top_level_imported, use_decl)?;
    }

    for module in modules.values() {
        let mut imported_names = HashMap::new();
        let mut imported = Vec::new();
        for use_decl in &module.uses {
            let target_key = phase10_path_key(&phase10_use_target_module_path(use_decl));
            if !modules.contains_key(&target_key) && is_known_use_path(&use_decl.path) {
                continue;
            }
            imported.extend(phase10_validate_use_decl(
                modules,
                Some(module),
                &mut imported_names,
                use_decl,
            )?);
        }
        imported_by_module.insert(module.path_key.clone(), imported);
    }
    Ok(imported_by_module)
}

fn phase10_build_use_edges(
    modules: &HashMap<String, Phase10ModuleInfo>,
) -> HashMap<String, Vec<String>> {
    let mut edges: HashMap<String, Vec<String>> = HashMap::new();
    for module in modules.values() {
        for use_decl in &module.uses {
            let target = phase10_path_key(&phase10_use_target_module_path(use_decl));
            if modules.contains_key(&target) {
                edges
                    .entry(module.path_key.clone())
                    .or_default()
                    .push(target);
            }
        }
    }
    edges
}

fn phase10_detect_cycle(
    node: &str,
    edges: &HashMap<String, Vec<String>>,
    visiting: &mut HashSet<String>,
    visited: &mut HashSet<String>,
) -> bool {
    if visiting.contains(node) {
        return true;
    }
    if visited.contains(node) {
        return false;
    }
    visiting.insert(node.to_string());
    if let Some(next) = edges.get(node) {
        for target in next {
            if phase10_detect_cycle(target, edges, visiting, visited) {
                return true;
            }
        }
    }
    visiting.remove(node);
    visited.insert(node.to_string());
    false
}

fn phase10_validate_cycles(modules: &HashMap<String, Phase10ModuleInfo>) -> Result<(), String> {
    let edges = phase10_build_use_edges(modules);
    let mut visited = HashSet::new();
    for node in edges.keys() {
        let mut visiting = HashSet::new();
        if phase10_detect_cycle(node, &edges, &mut visiting, &mut visited) {
            return Err(format!(
                "E_HIGH_MODULE_CYCLE_001: module import cycle detected at '{}'",
                node
            ));
        }
    }
    Ok(())
}

fn phase10_builtin_public_type(name: &str) -> bool {
    matches!(
        name.to_ascii_lowercase().as_str(),
        "int"
            | "bool"
            | "str"
            | "string"
            | "float"
            | "void"
            | "byte"
            | "word"
            | "dword"
            | "qword"
            | "addr"
            | "future"
            | "task"
            | "result"
            | "option"
            | "iterator"
            | "iterable"
            | "collection"
            | "channel"
            | "list"
            | "memregion"
    )
}

fn phase10_type_contains_any(ty: &TypeName) -> bool {
    match ty {
        TypeName::Simple(name) => name.eq_ignore_ascii_case("any"),
        TypeName::Vector(inner) | TypeName::Array(inner) => phase10_type_contains_any(inner),
        TypeName::Union(items) => items.iter().any(phase10_type_contains_any),
        TypeName::Generic { base, args } => {
            base.eq_ignore_ascii_case("any") || args.iter().any(phase10_type_contains_any)
        }
    }
}

fn phase10_type_is_public(
    ty: &TypeName,
    exported_types: &HashSet<String>,
    generic_params: &HashSet<String>,
) -> bool {
    match ty {
        TypeName::Simple(name) => {
            phase10_builtin_public_type(name)
                || generic_params.contains(name)
                || exported_types.contains(&name.to_ascii_lowercase())
        }
        TypeName::Vector(inner) | TypeName::Array(inner) => {
            phase10_type_is_public(inner, exported_types, generic_params)
        }
        TypeName::Union(items) => items
            .iter()
            .all(|item| phase10_type_is_public(item, exported_types, generic_params)),
        TypeName::Generic { base, args } => {
            (phase10_builtin_public_type(base)
                || exported_types.contains(&base.to_ascii_lowercase()))
                && args
                    .iter()
                    .all(|arg| phase10_type_is_public(arg, exported_types, generic_params))
        }
    }
}

fn phase10_exported_type_names(module: &Phase10ModuleInfo) -> HashSet<String> {
    let mut out = HashSet::new();
    for export in module.exports.values() {
        if matches!(
            export.kind,
            ExportKind::Type
                | ExportKind::Enum
                | ExportKind::Trait
                | ExportKind::Interface
                | ExportKind::Contract
        ) {
            if let Some(name) = phase10_symbol_name(&export.path) {
                out.insert(name.to_ascii_lowercase());
            }
        }
    }
    out
}

fn phase10_validate_public_api(modules: &HashMap<String, Phase10ModuleInfo>) -> Result<(), String> {
    for module in modules.values() {
        let exported_types = phase10_exported_type_names(module);
        for export in module.exports.values() {
            if !matches!(export.kind, ExportKind::Function) {
                continue;
            }
            let Some(name) = phase10_symbol_name(&export.path) else {
                continue;
            };
            let Some(symbol) = module.symbols.get(&name.to_ascii_lowercase()) else {
                continue;
            };
            let Some(function) = &symbol.function else {
                continue;
            };
            let generic_params: HashSet<String> = function.generic_params.iter().cloned().collect();
            for param in &function.params {
                if phase10_type_contains_any(&param.ty) {
                    return Err(format!(
                        "E_HIGH_API_ANY_LEAK_001: public API '{}' exposes any",
                        function.name
                    ));
                }
                if !phase10_type_is_public(&param.ty, &exported_types, &generic_params) {
                    return Err(format!(
                        "E_HIGH_API_PRIVATE_TYPE_LEAK_001: public API '{}' exposes private parameter type",
                        function.name
                    ));
                }
            }
            if phase10_type_contains_any(&function.return_type) {
                return Err(format!(
                    "E_HIGH_API_ANY_LEAK_001: public API '{}' exposes any",
                    function.name
                ));
            }
            if !phase10_type_is_public(&function.return_type, &exported_types, &generic_params) {
                return Err(format!(
                    "E_HIGH_API_PRIVATE_TYPE_LEAK_001: public API '{}' exposes private return type",
                    function.name
                ));
            }
            for bound in &function.generic_bounds {
                if !phase10_type_is_public(&bound.bound, &exported_types, &generic_params) {
                    return Err(format!(
                        "E_HIGH_API_UNRESOLVED_BOUND_001: public API '{}' exposes unresolved bound",
                        function.name
                    ));
                }
            }
            if function.is_async && function.effects.is_empty() {
                return Err(format!(
                    "E_HIGH_API_EFFECTS_MISSING_001: public async API '{}' must expose effects",
                    function.name
                ));
            }
        }
    }
    Ok(())
}

fn validate_high_phase10_modules_packages_api_surface(program: &Program) -> Result<(), String> {
    let _packages = phase10_validate_packages(program)?;
    let mut modules = phase10_build_modules(program)?;
    phase10_validate_exports(&mut modules, program)?;
    phase10_validate_imports(&modules, program)?;
    phase10_validate_cycles(&modules)?;
    phase10_validate_public_api(&modules)?;
    Ok(())
}

fn closure_function_type_parts(ty: &SemaType) -> Option<(&[SemaType], &SemaType)> {
    match ty {
        SemaType::Generic { base, args } if base.eq_ignore_ascii_case("fn") && !args.is_empty() => {
            Some((&args[..args.len() - 1], args.last().unwrap()))
        }
        _ => None,
    }
}

fn closure_function_type(param_tys: Vec<SemaType>, return_ty: SemaType) -> SemaType {
    let mut args = param_tys;
    args.push(return_ty);
    SemaType::Generic {
        base: "fn".to_string(),
        args,
    }
}

fn closure_iter_item_type(iter_ty: SemaType) -> Result<SemaType, String> {
    match iter_ty {
        SemaType::Vector(inner) | SemaType::Array(inner) => Ok(*inner),
        SemaType::Generic { base, args }
            if base.eq_ignore_ascii_case("array") && !args.is_empty() =>
        {
            Ok(args[0].clone())
        }
        SemaType::Generic { base, args } if is_list_family(&base) && args.len() == 1 => {
            Ok(args[0].clone())
        }
        other => Err(format!(
            "E_HIGH_FOR_IN_ITERABLE_001: for-in iterable must be list/vector/array-like, got {:?}",
            other
        )),
    }
}

fn closure_type_name_contains_any(ty: &TypeName) -> bool {
    match ty {
        TypeName::Simple(name) => name.eq_ignore_ascii_case("any"),
        TypeName::Vector(inner) | TypeName::Array(inner) => closure_type_name_contains_any(inner),
        TypeName::Union(items) => items.iter().any(closure_type_name_contains_any),
        TypeName::Generic { args, .. } => args.iter().any(closure_type_name_contains_any),
    }
}

fn closure_validate_function_type_name(ty: &TypeName) -> Result<(), String> {
    match ty {
        TypeName::Vector(inner) | TypeName::Array(inner) => {
            closure_validate_function_type_name(inner)
        }
        TypeName::Union(items) => {
            for item in items {
                closure_validate_function_type_name(item)?;
            }
            Ok(())
        }
        TypeName::Generic { base, args } => {
            if base.eq_ignore_ascii_case("fn") {
                if args.is_empty() {
                    return Err(
                        "E_HIGH_FUNCTION_TYPE_PARSE_001: fn type requires return type".into(),
                    );
                }
                for arg in args {
                    closure_validate_function_type_name(arg)?;
                }
                return Ok(());
            }
            for arg in args {
                closure_validate_function_type_name(arg)?;
            }
            Ok(())
        }
        TypeName::Simple(_) => Ok(()),
    }
}

#[derive(Default)]
struct ClosureFunctionState {
    moved: HashSet<String>,
    all_declared: HashSet<String>,
    private_symbols: HashSet<String>,
}

fn closure_capture_refs_expr(expr: &Expr, out: &mut HashSet<String>) {
    match expr {
        Expr::StructLiteral { fields, .. } => {
            for (_, value) in fields {
                closure_capture_refs_expr(value, out);
            }
        }
        Expr::ContextRef(ctx) if ctx.path.len() == 1 => {
            out.insert(ctx.path[0].clone());
        }
        Expr::Closure(_) => {}
        Expr::VectorLiteral(items) | Expr::ArrayLiteral(items) => {
            for item in items {
                closure_capture_refs_expr(item, out);
            }
        }
        Expr::Index { target, index } => {
            closure_capture_refs_expr(target, out);
            closure_capture_refs_expr(index, out);
        }
        Expr::MethodCall { receiver, args, .. } => {
            closure_capture_refs_expr(receiver, out);
            for arg in args {
                closure_capture_refs_expr(arg, out);
            }
        }
        Expr::QualifiedCall { args, .. } | Expr::Call { args, .. } => {
            for arg in args {
                closure_capture_refs_expr(arg, out);
            }
        }
        Expr::StrictCheckExpr { value, .. } | Expr::Unary { expr: value, .. } => {
            closure_capture_refs_expr(value, out);
        }
        Expr::PostIncrement { target }
        | Expr::FieldPostIncrement { target }
        | Expr::PointerPostIncrementRead { target }
            if target.path.len() == 1 =>
        {
            out.insert(target.path[0].clone());
        }
        Expr::PostIncrement { .. }
        | Expr::FieldPostIncrement { .. }
        | Expr::PointerPostIncrementRead { .. } => {}
        Expr::Binary { left, right, .. } => {
            closure_capture_refs_expr(left, out);
            closure_capture_refs_expr(right, out);
        }
        Expr::IfElse {
            condition,
            then_expr,
            else_expr,
        } => {
            closure_capture_refs_expr(condition, out);
            closure_capture_refs_expr(then_expr, out);
            closure_capture_refs_expr(else_expr, out);
        }
        Expr::Bool(_)
        | Expr::Number(_)
        | Expr::Char(_)
        | Expr::String(_)
        | Expr::Identifier(_)
        | Expr::Dev(_) => {}
        Expr::ContextRef(_) => {}
    }
}

fn closure_capture_refs_stmt(stmt: &Stmt, out: &mut HashSet<String>) {
    match stmt {
        Stmt::Return(expr) | Stmt::Print { value: expr, .. } | Stmt::Expr(expr) => {
            closure_capture_refs_expr(expr, out)
        }
        Stmt::Projection { value, .. } | Stmt::StrictCheck { value, .. } => {
            closure_capture_refs_expr(value, out)
        }
        Stmt::If {
            condition,
            then_block,
            else_block,
        } => {
            closure_capture_refs_expr(condition, out);
            for stmt in then_block.iter().chain(else_block) {
                closure_capture_refs_stmt(stmt, out);
            }
        }
        Stmt::Unless { condition, body }
        | Stmt::While { condition, body }
        | Stmt::RepeatUntil { condition, body } => {
            closure_capture_refs_expr(condition, out);
            for stmt in body {
                closure_capture_refs_stmt(stmt, out);
            }
        }
        Stmt::DoWhile { body, condition } => {
            for stmt in body {
                closure_capture_refs_stmt(stmt, out);
            }
            closure_capture_refs_expr(condition, out);
        }
        Stmt::ForClassic {
            init,
            condition,
            step,
            body,
        } => {
            if let Some(init) = init {
                closure_capture_refs_stmt(init, out);
            }
            if let Some(condition) = condition {
                closure_capture_refs_expr(condition, out);
            }
            if let Some(step) = step {
                closure_capture_refs_stmt(step, out);
            }
            for stmt in body {
                closure_capture_refs_stmt(stmt, out);
            }
        }
        Stmt::ForIn {
            item,
            iterable,
            body,
        }
        | Stmt::SameIn {
            item,
            iterable,
            body,
        } => {
            closure_capture_refs_expr(iterable, out);
            let mut body_refs = HashSet::new();
            for stmt in body {
                closure_capture_refs_stmt(stmt, &mut body_refs);
            }
            body_refs.remove(item);
            out.extend(body_refs);
        }
        Stmt::ForRange {
            item,
            start,
            end,
            step,
            body,
            ..
        } => {
            closure_capture_refs_expr(start, out);
            closure_capture_refs_expr(end, out);
            if let Some(step) = step {
                closure_capture_refs_expr(step, out);
            }
            let mut body_refs = HashSet::new();
            for stmt in body {
                closure_capture_refs_stmt(stmt, &mut body_refs);
            }
            body_refs.remove(item);
            out.extend(body_refs);
        }
        Stmt::Loop { body } | Stmt::RepeatCount { body, .. } => {
            for stmt in body {
                closure_capture_refs_stmt(stmt, out);
            }
        }
        Stmt::EachDoWhile {
            item,
            iterable,
            body,
            condition,
        } => {
            closure_capture_refs_expr(iterable, out);
            let mut body_refs = HashSet::new();
            for stmt in body {
                closure_capture_refs_stmt(stmt, &mut body_refs);
            }
            closure_capture_refs_expr(condition, &mut body_refs);
            body_refs.remove(item);
            out.extend(body_refs);
        }
        Stmt::Switch {
            value,
            cases,
            default,
        }
        | Stmt::Match {
            value,
            cases,
            default,
        } => {
            closure_capture_refs_expr(value, out);
            for (case, block) in cases {
                closure_capture_refs_expr(case, out);
                for stmt in block {
                    closure_capture_refs_stmt(stmt, out);
                }
            }
            for stmt in default {
                closure_capture_refs_stmt(stmt, out);
            }
        }
        Stmt::PatternMatch { value, arms } => {
            closure_capture_refs_expr(value, out);
            for arm in arms {
                let mut arm_refs = HashSet::new();
                if let Some(guard) = &arm.guard {
                    closure_capture_refs_expr(guard, &mut arm_refs);
                }
                for stmt in &arm.body {
                    closure_capture_refs_stmt(stmt, &mut arm_refs);
                }
                let mut bindings = Vec::new();
                closure_pattern_bindings(&arm.pattern, &mut bindings);
                for binding in bindings {
                    arm_refs.remove(&binding);
                }
                out.extend(arm_refs);
            }
        }
        Stmt::GuardElse {
            condition,
            else_block,
        } => {
            closure_capture_refs_expr(condition, out);
            for stmt in else_block {
                closure_capture_refs_stmt(stmt, out);
            }
        }
        Stmt::Select { branches, default } => {
            for (condition, block) in branches {
                closure_capture_refs_expr(condition, out);
                for stmt in block {
                    closure_capture_refs_stmt(stmt, out);
                }
            }
            for stmt in default {
                closure_capture_refs_stmt(stmt, out);
            }
        }
        Stmt::Labeled { stmt, .. } => closure_capture_refs_stmt(stmt, out),
        Stmt::Defer { body } => {
            for stmt in body {
                closure_capture_refs_stmt(stmt, out);
            }
        }
        Stmt::Destructure { args, .. } | Stmt::Constructure { args, .. } => {
            for arg in args {
                closure_capture_refs_expr(arg, out);
            }
        }
        Stmt::Dev(_)
        | Stmt::Break { .. }
        | Stmt::Continue { .. }
        | Stmt::MainRefFn { .. }
        | Stmt::FunctionRelation { .. } => {}
    }
}

fn closure_local_declared_symbol(stmt: &Stmt) -> Option<String> {
    match stmt {
        Stmt::Projection {
            target: AssignTarget::Context(ctx),
            ..
        }
        | Stmt::StrictCheck {
            target: AssignTarget::Context(ctx),
            ..
        } if ctx.path.len() == 1 => Some(ctx.path[0].clone()),
        _ => None,
    }
}

fn closure_pattern_bindings(pattern: &Pattern, out: &mut Vec<String>) {
    match pattern {
        Pattern::Binding(name) => out.push(pattern_binding_name(name).to_string()),
        Pattern::Variant { bindings, .. } => out.extend(
            bindings
                .iter()
                .map(|binding| pattern_binding_name(binding).to_string()),
        ),
        Pattern::VariantPattern { items, .. } | Pattern::Array { items, .. } => {
            for item in items {
                closure_pattern_bindings(item, out);
            }
        }
        Pattern::Struct { fields, .. } => {
            for field in fields {
                closure_pattern_bindings(&field.pattern, out);
            }
        }
        Pattern::Wildcard | Pattern::Literal(_) | Pattern::Range { .. } => {}
    }
}

fn pattern_binding_name(raw: &str) -> &str {
    raw.split_once(':').map(|(name, _)| name).unwrap_or(raw)
}

fn pattern_binding_annotation(raw: &str) -> Option<SemaType> {
    raw.split_once(':')
        .map(|(_, ty)| parse_ffi_signature_type(ty.trim()))
}

fn closure_stmt_writes_capture(stmt: &Stmt, name: &str) -> bool {
    match stmt {
        Stmt::Projection {
            target: AssignTarget::Context(ctx),
            ..
        }
        | Stmt::StrictCheck {
            target: AssignTarget::Context(ctx),
            ..
        } => ctx.path.len() == 1 && ctx.path[0] == name,
        Stmt::If {
            then_block,
            else_block,
            ..
        } => then_block
            .iter()
            .chain(else_block)
            .any(|stmt| closure_stmt_writes_capture(stmt, name)),
        Stmt::Unless { body, .. }
        | Stmt::While { body, .. }
        | Stmt::DoWhile { body, .. }
        | Stmt::ForIn { body, .. }
        | Stmt::SameIn { body, .. }
        | Stmt::ForRange { body, .. }
        | Stmt::Loop { body }
        | Stmt::RepeatUntil { body, .. }
        | Stmt::RepeatCount { body, .. }
        | Stmt::EachDoWhile { body, .. } => body
            .iter()
            .any(|stmt| closure_stmt_writes_capture(stmt, name)),
        Stmt::ForClassic {
            init, step, body, ..
        } => {
            init.as_ref()
                .is_some_and(|stmt| closure_stmt_writes_capture(stmt, name))
                || step
                    .as_ref()
                    .is_some_and(|stmt| closure_stmt_writes_capture(stmt, name))
                || body
                    .iter()
                    .any(|stmt| closure_stmt_writes_capture(stmt, name))
        }
        Stmt::Switch { cases, default, .. } | Stmt::Match { cases, default, .. } => {
            cases.iter().any(|(_, body)| {
                body.iter()
                    .any(|stmt| closure_stmt_writes_capture(stmt, name))
            }) || default
                .iter()
                .any(|stmt| closure_stmt_writes_capture(stmt, name))
        }
        Stmt::PatternMatch { arms, .. } => arms.iter().any(|arm| {
            arm.body
                .iter()
                .any(|stmt| closure_stmt_writes_capture(stmt, name))
        }),
        Stmt::GuardElse { else_block, .. } => else_block
            .iter()
            .any(|stmt| closure_stmt_writes_capture(stmt, name)),
        Stmt::Select { branches, default } => {
            branches.iter().any(|(_, body)| {
                body.iter()
                    .any(|stmt| closure_stmt_writes_capture(stmt, name))
            }) || default
                .iter()
                .any(|stmt| closure_stmt_writes_capture(stmt, name))
        }
        Stmt::Labeled { stmt, .. } => closure_stmt_writes_capture(stmt, name),
        _ => false,
    }
}

fn closure_validate_closure_expr(
    program: &Program,
    current_container_name: &str,
    closure: &ClosureExpr,
    scope: &HashMap<String, SemaType>,
    state: &mut ClosureFunctionState,
    current_context: &Option<Context>,
    escaping: bool,
) -> Result<SemaType, String> {
    let mut seen_params = HashSet::new();
    let mut param_tys = Vec::new();
    for param in &closure.params {
        if !seen_params.insert(param.name.clone()) {
            return Err(format!(
                "E_HIGH_CLOSURE_PARAM_001: duplicate closure parameter '{}'",
                param.name
            ));
        }
        if closure_type_name_contains_any(&param.ty) {
            return Err(
                "E_HIGH_CLOSURE_ANY_LEAK_001: closure/function type cannot contain any".into(),
            );
        }
        closure_validate_function_type_name(&param.ty)?;
        param_tys.push(lower_type(&param.ty));
    }
    if closure_type_name_contains_any(&closure.return_type) {
        return Err("E_HIGH_CLOSURE_ANY_LEAK_001: closure/function type cannot contain any".into());
    }
    closure_validate_function_type_name(&closure.return_type)?;
    if closure
        .effects
        .iter()
        .any(|effect| !phase9_allowed_effect(effect))
    {
        return Err("E_HIGH_CLOSURE_EFFECT_MISMATCH_001: closure effect is not supported".into());
    }

    let mut closure_scope = scope.clone();
    for param in &closure.params {
        closure_scope.insert(param.name.clone(), lower_type(&param.ty));
    }

    let mut capture_names = HashSet::new();
    let mut has_mut_capture = false;
    for capture in &closure.captures {
        if !capture_names.insert(capture.name.clone()) {
            return Err(format!(
                "E_HIGH_CAPTURE_ALIAS_001: duplicate capture '{}'",
                capture.name
            ));
        }
        if state.moved.contains(&capture.name) {
            return Err(format!(
                "E_HIGH_CAPTURE_MOVED_001: captured symbol '{}' was already moved",
                capture.name
            ));
        }
        if state.private_symbols.contains(&capture.name) {
            return Err(format!(
                "E_HIGH_CAPTURE_VISIBILITY_001: private symbol '{}' cannot be captured into closure",
                capture.name
            ));
        }
        let Some(capture_ty) = scope.get(&capture.name).cloned() else {
            if state.all_declared.contains(&capture.name) {
                return Err(format!(
                    "E_HIGH_CAPTURE_UNINITIALIZED_001: captured symbol '{}' is declared later and is not initialized",
                    capture.name
                ));
            }
            return Err(format!(
                "E_HIGH_CAPTURE_UNKNOWN_001: captured symbol '{}' does not exist",
                capture.name
            ));
        };
        if closure_function_type_parts(&capture_ty).is_some()
            && matches!(capture.mode, CaptureMode::Mut)
        {
            return Err(format!(
                "E_HIGH_CAPTURE_ALIAS_001: mutable capture '{}' cannot alias callable value",
                capture.name
            ));
        }
        if matches!(capture.mode, CaptureMode::Mut) {
            has_mut_capture = true;
        }
        closure_scope.insert(capture.name.clone(), capture_ty);
    }

    let mut refs = HashSet::new();
    for stmt in &closure.body {
        closure_capture_refs_stmt(stmt, &mut refs);
    }
    for param in &closure.params {
        refs.remove(&param.name);
    }
    for capture in &closure.captures {
        refs.remove(&capture.name);
    }
    let local_names: HashSet<String> = closure
        .body
        .iter()
        .filter_map(closure_local_declared_symbol)
        .collect();
    for local in &local_names {
        refs.remove(local);
    }
    if let Some(name) = refs.into_iter().next() {
        return Err(format!(
            "E_HIGH_CAPTURE_UNKNOWN_001: implicit capture '@{}' is denied; add it to captures(...)",
            name
        ));
    }

    for capture in &closure.captures {
        if closure
            .body
            .iter()
            .any(|stmt| closure_stmt_writes_capture(stmt, &capture.name))
            && !matches!(capture.mode, CaptureMode::Mut)
        {
            return Err(format!(
                "E_HIGH_CAPTURE_MUT_REQUIRED_001: capture '{}' is written and must be declared mut",
                capture.name
            ));
        }
    }

    if has_mut_capture && !closure.effects.iter().any(|effect| effect == "state.write") {
        return Err(
            "E_HIGH_CLOSURE_EFFECT_MISSING_001: mutable capture requires effects(state.write)"
                .into(),
        );
    }

    if escaping
        && closure
            .captures
            .iter()
            .any(|capture| matches!(capture.mode, CaptureMode::Ref | CaptureMode::Mut))
    {
        return Err(
            "E_HIGH_CLOSURE_RETURN_BORROW_001: escaping closure cannot borrow local captures"
                .into(),
        );
    }

    for stmt in &closure.body {
        closure_validate_stmt(
            program,
            current_container_name,
            stmt,
            &mut closure_scope,
            state,
            current_context,
        )?;
    }

    let closure_return = lower_type(&closure.return_type);
    let previous_return =
        CURRENT_FUNCTION_RETURN.with(|cell| cell.replace(Some(closure_return.clone())));
    let mut closure_pointer_states = closure_scope
        .iter()
        .filter_map(|(name, ty)| {
            is_pointer_family_type(ty).then(|| (name.clone(), PointerState::Bound))
        })
        .collect::<HashMap<_, _>>();
    let mut closure_aliases = FlowAliasMap::new();
    let semantic_result = analyze_stmt_block(
        program,
        current_container_name,
        &closure.body,
        &mut closure_scope,
        &mut closure_pointer_states,
        &mut closure_aliases,
        &closure_return,
        &StrictContext::default(),
        current_context,
    );
    CURRENT_FUNCTION_RETURN.with(|cell| {
        cell.replace(previous_return);
    });
    semantic_result?;

    let mut control_scopes = Vec::new();
    let mut control_labels = HashSet::new();
    validate_control_flow_block(&closure.body, &mut control_scopes, &mut control_labels)?;

    let declared_return = lower_type(&closure.return_type);
    let callable_return = if closure.is_async {
        SemaType::Generic {
            base: "Future".into(),
            args: vec![declared_return],
        }
    } else {
        declared_return
    };
    Ok(closure_function_type(param_tys, callable_return))
}

#[cfg(test)]
mod async_closure_semantics_tests {
    use super::*;

    #[test]
    fn async_and_async_move_closures_are_future_typed() {
        let source = r#"
asyncClosureTyped {
    fn:
        run() -> bool
        effects(async.await)
        {
            public:
                @firstStorage !> p<byte> : alloc(512);
                @secondStorage !> p<byte> : alloc(512);
                @firstFrame !> p<byte> : alloc(512);
                @secondFrame !> p<byte> : alloc(512);
                @first >> fn(int) -> Future<int> : closureAt(@firstStorage, async |value: int| -> int {
                    return @value + 1;
                });
                @second >> fn(int) -> Future<int> : closureAt(@secondStorage, async move |value: int| -> int {
                    return @value + 2;
                });
                @firstPending >> Future<int> : asyncAt(@firstFrame, first(40));
                @secondPending >> Future<int> : asyncAt(@secondFrame, second(40));
                @a >> int : await firstPending;
                @b >> int : await secondPending;
                @ok >> bool : @a == 41 && @b == 42;
                free(@secondFrame);
                free(@firstFrame);
                free(@secondStorage);
                free(@firstStorage);
                return @ok;
        }

    ref main ->> @fn(run);

    fa:
        return true;
}
"#;
        let tokens = ncc_lexer::lex(source).expect("async closure fixture must lex");
        let program = ncc_parser::parse(tokens).expect("async closure fixture must parse");
        analyze(&program).expect("async closure fixture must pass sema");
        let closures = program
            .containers
            .iter()
            .flat_map(|container| container.sections.iter())
            .filter_map(|section| match section {
                Section::Fn(functions) => Some(functions),
                _ => None,
            })
            .flat_map(|functions| functions.iter())
            .flat_map(|function| function.public_body.iter())
            .filter_map(|stmt| match stmt {
                Stmt::Projection {
                    value: Expr::Call { callee, args },
                    ..
                } if callee.eq_ignore_ascii_case("closureAt") => match args.get(1) {
                    Some(Expr::Closure(closure)) => Some(closure),
                    _ => None,
                },
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(closures.len(), 2);
        assert!(closures.iter().all(|closure| closure.is_async));
        assert!(!closures[0].is_move);
        assert!(closures[1].is_move);
    }
}

fn closure_validate_expr(
    program: &Program,
    current_container_name: &str,
    expr: &Expr,
    scope: &HashMap<String, SemaType>,
    state: &mut ClosureFunctionState,
    current_context: &Option<Context>,
) -> Result<(), String> {
    match expr {
        Expr::StructLiteral { fields, .. } => {
            for (_, value) in fields {
                closure_validate_expr(
                    program,
                    current_container_name,
                    value,
                    scope,
                    state,
                    current_context,
                )?;
            }
            Ok(())
        }
        Expr::Closure(closure) => {
            let _ = closure_validate_closure_expr(
                program,
                current_container_name,
                closure,
                scope,
                state,
                current_context,
                false,
            )?;
            Ok(())
        }
        Expr::Call { callee, args } if callee.eq_ignore_ascii_case("yield") => {
            for arg in args {
                closure_validate_expr(
                    program,
                    current_container_name,
                    arg,
                    scope,
                    state,
                    current_context,
                )?;
            }
            Ok(())
        }
        Expr::Call { callee, args } if callee.eq_ignore_ascii_case("expectPure") => {
            if let Some(Expr::Closure(closure)) = args.first() {
                if !closure.effects.is_empty() {
                    return Err(
                        "E_HIGH_CLOSURE_EFFECT_MISMATCH_001: effectful closure cannot be used where pure closure is expected"
                            .into(),
                    );
                }
            }
            for arg in args {
                closure_validate_expr(
                    program,
                    current_container_name,
                    arg,
                    scope,
                    state,
                    current_context,
                )?;
            }
            Ok(())
        }
        Expr::Call { callee, args } if value_transfer_op_from_callee(callee).is_some() => {
            let Some(op) = value_transfer_op_from_callee(callee) else {
                unreachable!("guard checked transfer op");
            };
            if args.len() != 1 {
                let code = match op {
                    ValueTransferOp::Copy => "E_TYPE_COPY_001",
                    ValueTransferOp::Clone => "E_TYPE_CLONE_001",
                    ValueTransferOp::Move => "E_TYPE_MOVE_001",
                };
                return Err(format!("{}: {} expects exactly 1 argument", code, callee));
            }
            closure_validate_expr(
                program,
                current_container_name,
                &args[0],
                scope,
                state,
                current_context,
            )?;
            if matches!(op, ValueTransferOp::Move) {
                if let Expr::ContextRef(ctx) = &args[0] {
                    if ctx.path.len() == 1 {
                        state.moved.insert(ctx.path[0].clone());
                    }
                }
            }
            Ok(())
        }
        Expr::Call { callee, args } => {
            if let Some(diag) = closure_moved_symbol_call_diagnostic(callee, args, state) {
                return Err(diag);
            }
            for arg in args {
                closure_validate_expr(
                    program,
                    current_container_name,
                    arg,
                    scope,
                    state,
                    current_context,
                )?;
            }
            Ok(())
        }
        Expr::QualifiedCall { path, args } => {
            if let Some(callee) = path.last() {
                if let Some(diag) = closure_moved_symbol_call_diagnostic(callee, args, state) {
                    return Err(diag);
                }
            }
            for arg in args {
                closure_validate_expr(
                    program,
                    current_container_name,
                    arg,
                    scope,
                    state,
                    current_context,
                )?;
            }
            Ok(())
        }
        Expr::MethodCall { receiver, args, .. } => {
            closure_validate_expr(
                program,
                current_container_name,
                receiver,
                scope,
                state,
                current_context,
            )?;
            for arg in args {
                closure_validate_expr(
                    program,
                    current_container_name,
                    arg,
                    scope,
                    state,
                    current_context,
                )?;
            }
            Ok(())
        }
        Expr::VectorLiteral(items) | Expr::ArrayLiteral(items) => {
            for item in items {
                closure_validate_expr(
                    program,
                    current_container_name,
                    item,
                    scope,
                    state,
                    current_context,
                )?;
            }
            Ok(())
        }
        Expr::Index { target, index } => {
            closure_validate_expr(
                program,
                current_container_name,
                target,
                scope,
                state,
                current_context,
            )?;
            closure_validate_expr(
                program,
                current_container_name,
                index,
                scope,
                state,
                current_context,
            )
        }
        Expr::StrictCheckExpr { ty, value, .. } => {
            closure_validate_function_type_name(ty)?;
            closure_validate_expr(
                program,
                current_container_name,
                value,
                scope,
                state,
                current_context,
            )
        }
        Expr::PostIncrement { target }
        | Expr::FieldPostIncrement { target }
        | Expr::PointerPostIncrementRead { target } => {
            if target.path.len() == 1 && state.moved.contains(&target.path[0]) {
                return Err(format!(
                    "E_TYPE_MOVE_AFTER_MOVE_001: mutation of moved symbol '{}'",
                    target.path[0]
                ));
            }
            infer_expr_type(
                program,
                current_container_name,
                expr,
                scope,
                current_context,
            )?;
            Ok(())
        }
        Expr::Unary { expr, .. } => closure_validate_expr(
            program,
            current_container_name,
            expr,
            scope,
            state,
            current_context,
        ),
        Expr::Binary { left, right, .. } => {
            closure_validate_expr(
                program,
                current_container_name,
                left,
                scope,
                state,
                current_context,
            )?;
            closure_validate_expr(
                program,
                current_container_name,
                right,
                scope,
                state,
                current_context,
            )
        }
        Expr::IfElse {
            condition,
            then_expr,
            else_expr,
        } => {
            closure_validate_expr(
                program,
                current_container_name,
                condition,
                scope,
                state,
                current_context,
            )?;
            closure_validate_expr(
                program,
                current_container_name,
                then_expr,
                scope,
                state,
                current_context,
            )?;
            closure_validate_expr(
                program,
                current_container_name,
                else_expr,
                scope,
                state,
                current_context,
            )
        }
        Expr::Bool(_)
        | Expr::Number(_)
        | Expr::Char(_)
        | Expr::String(_)
        | Expr::Identifier(_)
        | Expr::Dev(_) => Ok(()),
        Expr::ContextRef(ctx) => {
            if ctx.path.len() == 1 && state.moved.contains(&ctx.path[0]) {
                return Err(format!(
                    "E_TYPE_MOVE_AFTER_MOVE_001: use of moved symbol '{}'",
                    ctx.path[0]
                ));
            }
            Ok(())
        }
    }
}

fn closure_validate_stmt(
    program: &Program,
    current_container_name: &str,
    stmt: &Stmt,
    scope: &mut HashMap<String, SemaType>,
    state: &mut ClosureFunctionState,
    current_context: &Option<Context>,
) -> Result<(), String> {
    match stmt {
        Stmt::Projection { target, ty, value } | Stmt::StrictCheck { target, ty, value } => {
            let inferred_projection =
                matches!(stmt, Stmt::Projection { .. }) && ast_type_is_inferred_projection(ty);
            if matches!(value, Expr::Closure(_)) && closure_type_name_contains_any(ty) {
                return Err(
                    "E_HIGH_CLOSURE_ANY_LEAK_001: closure/function type cannot contain any".into(),
                );
            }
            if !inferred_projection {
                closure_validate_function_type_name(ty)?;
            }
            closure_validate_expr(
                program,
                current_container_name,
                value,
                scope,
                state,
                current_context,
            )?;
            let expected = if inferred_projection {
                let declared = resolve_projection_declared_type(program, scope, target)?;
                if matches!(declared, SemaType::Unknown) {
                    infer_expr_type(
                        program,
                        current_container_name,
                        value,
                        scope,
                        current_context,
                    )?
                } else {
                    declared
                }
            } else {
                lower_type(ty)
            };
            let value_callable_from_scope = match value {
                Expr::ContextRef(ctx) if ctx.path.len() == 1 => scope
                    .get(&ctx.path[0])
                    .is_some_and(|ty| closure_function_type_parts(ty).is_some()),
                _ => false,
            };
            let callable_projection = matches!(value, Expr::Closure(_))
                || closure_function_type_parts(&expected).is_some()
                || value_callable_from_scope;
            if callable_projection {
                let got = infer_expr_type(
                    program,
                    current_container_name,
                    value,
                    scope,
                    current_context,
                )?;
                if !type_compatible(&got, &expected) {
                    return Err(format!(
                        "E_HIGH_FUNCTION_TYPE_MISMATCH_001: expected {}, got {}",
                        render_sema_type(&expected),
                        render_sema_type(&got)
                    ));
                }
            }
            if let AssignTarget::Context(ctx) = target {
                if ctx.path.len() == 1 {
                    state.moved.remove(&ctx.path[0]);
                    scope.insert(ctx.path[0].clone(), expected);
                }
            }
            if let Expr::Closure(closure) = value {
                for capture in &closure.captures {
                    if matches!(capture.mode, CaptureMode::Move) || closure.is_move {
                        state.moved.insert(capture.name.clone());
                    }
                }
            }
            Ok(())
        }
        Stmt::Return(Expr::Closure(closure)) => {
            let _ = closure_validate_closure_expr(
                program,
                current_container_name,
                closure,
                scope,
                state,
                current_context,
                true,
            )?;
            Ok(())
        }
        Stmt::Return(expr) | Stmt::Print { value: expr, .. } | Stmt::Expr(expr) => {
            closure_validate_expr(
                program,
                current_container_name,
                expr,
                scope,
                state,
                current_context,
            )
        }
        Stmt::If {
            condition,
            then_block,
            else_block,
        } => {
            closure_validate_expr(
                program,
                current_container_name,
                condition,
                scope,
                state,
                current_context,
            )?;
            for stmt in then_block.iter().chain(else_block) {
                closure_validate_stmt(
                    program,
                    current_container_name,
                    stmt,
                    scope,
                    state,
                    current_context,
                )?;
            }
            Ok(())
        }
        Stmt::Unless { condition, body }
        | Stmt::While { condition, body }
        | Stmt::RepeatUntil { condition, body } => {
            closure_validate_expr(
                program,
                current_container_name,
                condition,
                scope,
                state,
                current_context,
            )?;
            for stmt in body {
                closure_validate_stmt(
                    program,
                    current_container_name,
                    stmt,
                    scope,
                    state,
                    current_context,
                )?;
            }
            Ok(())
        }
        Stmt::DoWhile { body, condition } => {
            for stmt in body {
                closure_validate_stmt(
                    program,
                    current_container_name,
                    stmt,
                    scope,
                    state,
                    current_context,
                )?;
            }
            closure_validate_expr(
                program,
                current_container_name,
                condition,
                scope,
                state,
                current_context,
            )
        }
        Stmt::ForClassic {
            init,
            condition,
            step,
            body,
        } => {
            if let Some(init) = init {
                closure_validate_stmt(
                    program,
                    current_container_name,
                    init,
                    scope,
                    state,
                    current_context,
                )?;
            }
            if let Some(condition) = condition {
                closure_validate_expr(
                    program,
                    current_container_name,
                    condition,
                    scope,
                    state,
                    current_context,
                )?;
            }
            if let Some(step) = step {
                closure_validate_stmt(
                    program,
                    current_container_name,
                    step,
                    scope,
                    state,
                    current_context,
                )?;
            }
            for stmt in body {
                closure_validate_stmt(
                    program,
                    current_container_name,
                    stmt,
                    scope,
                    state,
                    current_context,
                )?;
            }
            Ok(())
        }
        Stmt::ForIn {
            item,
            iterable,
            body,
        }
        | Stmt::SameIn {
            item,
            iterable,
            body,
        } => {
            closure_validate_expr(
                program,
                current_container_name,
                iterable,
                scope,
                state,
                current_context,
            )?;
            let iter_ty = infer_expr_type(
                program,
                current_container_name,
                iterable,
                scope,
                current_context,
            )?;
            let elem_ty = closure_iter_item_type(iter_ty)?;
            let mut loop_scope = scope.clone();
            loop_scope.insert(item.clone(), elem_ty);
            for stmt in body {
                closure_validate_stmt(
                    program,
                    current_container_name,
                    stmt,
                    &mut loop_scope,
                    state,
                    current_context,
                )?;
            }
            Ok(())
        }
        Stmt::ForRange {
            item,
            start,
            end,
            step,
            body,
            ..
        } => {
            closure_validate_expr(
                program,
                current_container_name,
                start,
                scope,
                state,
                current_context,
            )?;
            closure_validate_expr(
                program,
                current_container_name,
                end,
                scope,
                state,
                current_context,
            )?;
            if let Some(step) = step {
                closure_validate_expr(
                    program,
                    current_container_name,
                    step,
                    scope,
                    state,
                    current_context,
                )?;
            }
            let mut loop_scope = scope.clone();
            loop_scope.insert(item.clone(), SemaType::Simple("int".to_string()));
            for stmt in body {
                closure_validate_stmt(
                    program,
                    current_container_name,
                    stmt,
                    &mut loop_scope,
                    state,
                    current_context,
                )?;
            }
            Ok(())
        }
        Stmt::Loop { body } | Stmt::RepeatCount { body, .. } => {
            for stmt in body {
                closure_validate_stmt(
                    program,
                    current_container_name,
                    stmt,
                    scope,
                    state,
                    current_context,
                )?;
            }
            Ok(())
        }
        Stmt::EachDoWhile {
            item,
            iterable,
            body,
            condition,
        } => {
            closure_validate_expr(
                program,
                current_container_name,
                iterable,
                scope,
                state,
                current_context,
            )?;
            let iter_ty = infer_expr_type(
                program,
                current_container_name,
                iterable,
                scope,
                current_context,
            )?;
            let elem_ty = closure_iter_item_type(iter_ty)?;
            let mut loop_scope = scope.clone();
            loop_scope.insert(item.clone(), elem_ty);
            for stmt in body {
                closure_validate_stmt(
                    program,
                    current_container_name,
                    stmt,
                    &mut loop_scope,
                    state,
                    current_context,
                )?;
            }
            closure_validate_expr(
                program,
                current_container_name,
                condition,
                &loop_scope,
                state,
                current_context,
            )
        }
        Stmt::Switch {
            value,
            cases,
            default,
        }
        | Stmt::Match {
            value,
            cases,
            default,
        } => {
            closure_validate_expr(
                program,
                current_container_name,
                value,
                scope,
                state,
                current_context,
            )?;
            for (case, block) in cases {
                closure_validate_expr(
                    program,
                    current_container_name,
                    case,
                    scope,
                    state,
                    current_context,
                )?;
                for stmt in block {
                    closure_validate_stmt(
                        program,
                        current_container_name,
                        stmt,
                        scope,
                        state,
                        current_context,
                    )?;
                }
            }
            for stmt in default {
                closure_validate_stmt(
                    program,
                    current_container_name,
                    stmt,
                    scope,
                    state,
                    current_context,
                )?;
            }
            Ok(())
        }
        Stmt::PatternMatch { value, arms } => {
            closure_validate_expr(
                program,
                current_container_name,
                value,
                scope,
                state,
                current_context,
            )?;
            for arm in arms {
                let mut arm_scope = scope.clone();
                let mut bindings = Vec::new();
                closure_pattern_bindings(&arm.pattern, &mut bindings);
                for binding in bindings {
                    arm_scope.insert(binding, SemaType::Unknown);
                }
                if let Some(guard) = &arm.guard {
                    closure_validate_expr(
                        program,
                        current_container_name,
                        guard,
                        &arm_scope,
                        state,
                        current_context,
                    )?;
                }
                for stmt in &arm.body {
                    closure_validate_stmt(
                        program,
                        current_container_name,
                        stmt,
                        &mut arm_scope,
                        state,
                        current_context,
                    )?;
                }
            }
            Ok(())
        }
        Stmt::GuardElse {
            condition,
            else_block,
        } => {
            closure_validate_expr(
                program,
                current_container_name,
                condition,
                scope,
                state,
                current_context,
            )?;
            for stmt in else_block {
                closure_validate_stmt(
                    program,
                    current_container_name,
                    stmt,
                    scope,
                    state,
                    current_context,
                )?;
            }
            Ok(())
        }
        Stmt::Select { branches, default } => {
            for (condition, block) in branches {
                closure_validate_expr(
                    program,
                    current_container_name,
                    condition,
                    scope,
                    state,
                    current_context,
                )?;
                for stmt in block {
                    closure_validate_stmt(
                        program,
                        current_container_name,
                        stmt,
                        scope,
                        state,
                        current_context,
                    )?;
                }
            }
            for stmt in default {
                closure_validate_stmt(
                    program,
                    current_container_name,
                    stmt,
                    scope,
                    state,
                    current_context,
                )?;
            }
            Ok(())
        }
        Stmt::Labeled { stmt, .. } => closure_validate_stmt(
            program,
            current_container_name,
            stmt,
            scope,
            state,
            current_context,
        ),
        Stmt::Defer { body } => {
            for stmt in body {
                closure_validate_stmt(
                    program,
                    current_container_name,
                    stmt,
                    scope,
                    state,
                    current_context,
                )?;
            }
            Ok(())
        }
        Stmt::Destructure { args, .. } | Stmt::Constructure { args, .. } => {
            for arg in args {
                closure_validate_expr(
                    program,
                    current_container_name,
                    arg,
                    scope,
                    state,
                    current_context,
                )?;
            }
            Ok(())
        }
        Stmt::Dev(_)
        | Stmt::Break { .. }
        | Stmt::Continue { .. }
        | Stmt::MainRefFn { .. }
        | Stmt::FunctionRelation { .. } => Ok(()),
    }
}

fn closure_collect_all_declared(function: &FunctionDecl) -> HashSet<String> {
    let mut out = function
        .params
        .iter()
        .map(|param| param.name.clone())
        .collect::<HashSet<_>>();
    for stmt in &function.public_body {
        if let Some(name) = closure_local_declared_symbol(stmt) {
            out.insert(name);
        }
    }
    out
}

fn validate_high_closures_lambdas_captures(program: &Program) -> Result<(), String> {
    for container in &program.containers {
        let mut container_stc = HashMap::new();
        let mut private_symbols = HashSet::new();
        for section in &container.sections {
            if let Section::Stc(decls) = section {
                for decl in decls {
                    let StcDecl::Typed {
                        visibility,
                        name,
                        ty,
                        ..
                    } = decl;
                    closure_validate_function_type_name(ty)?;
                    container_stc.insert(name.clone(), lower_type(ty));
                    if matches!(visibility, Some(Visibility::Private)) {
                        private_symbols.insert(name.clone());
                    }
                }
            }
            if let Section::Local(local) = section {
                for decl in &local.decls {
                    if let Some((name, ty, _init, _is_const)) = local_decl_value_parts(decl) {
                        closure_validate_function_type_name(ty)?;
                        container_stc.insert(name.clone(), lower_type(ty));
                        if matches!(
                            decl,
                            LocalDecl::Var {
                                visibility: Some(Visibility::Private),
                                ..
                            } | LocalDecl::Const {
                                visibility: Some(Visibility::Private),
                                ..
                            }
                        ) {
                            private_symbols.insert(name.clone());
                        }
                    }
                }
            }
        }
        for section in &container.sections {
            let Section::Fn(functions) = section else {
                continue;
            };
            for function in functions {
                for param in &function.params {
                    closure_validate_function_type_name(&param.ty)?;
                }
                closure_validate_function_type_name(&function.return_type)?;
                let mut scope = container_stc.clone();
                for param in &function.params {
                    scope.insert(param.name.clone(), lower_type(&param.ty));
                }
                let mut state = ClosureFunctionState {
                    moved: HashSet::new(),
                    all_declared: closure_collect_all_declared(function),
                    private_symbols: private_symbols.clone(),
                };
                for stmt in &function.public_body {
                    closure_validate_stmt(
                        program,
                        &container.name,
                        stmt,
                        &mut scope,
                        &mut state,
                        &container.context,
                    )?;
                }
            }
        }
    }
    Ok(())
}

fn phase12_metadata_base(name: &str) -> Option<&'static str> {
    match name.to_ascii_lowercase().as_str() {
        "typeinfo" => Some("TypeInfo"),
        "symbolinfo" => Some("SymbolInfo"),
        "moduleinfo" => Some("ModuleInfo"),
        "packageinfo" => Some("PackageInfo"),
        "apisurfaceinfo" => Some("ApiSurfaceInfo"),
        "traitinfo" => Some("TraitInfo"),
        "interfaceinfo" => Some("InterfaceInfo"),
        "contractinfo" => Some("ContractInfo"),
        "effectinfo" => Some("EffectInfo"),
        "closureinfo" => Some("ClosureInfo"),
        "metadatareport" => Some("MetadataReport"),
        _ => None,
    }
}

fn phase12_is_builtin_visible_type(name: &str) -> bool {
    matches!(
        normalize_type_name(name).to_ascii_lowercase().as_str(),
        "bool"
            | "str"
            | "char"
            | "byte"
            | "word"
            | "dword"
            | "qword"
            | "sbyte"
            | "sword"
            | "sdword"
            | "sqword"
            | "addr"
            | "void"
            | "int"
            | "int8"
            | "int16"
            | "int32"
            | "int64"
            | "uint"
            | "uint8"
            | "uint16"
            | "uint32"
            | "uint64"
            | "ft"
            | "f32"
            | "f64"
            | "usize"
            | "isize"
    )
}

fn phase12_declared_type_exists(program: &Program, name: &str) -> bool {
    for container in &program.containers {
        for section in &container.sections {
            match section {
                Section::TypeContracts(contracts)
                    if contracts
                        .iter()
                        .any(|contract| contract.name.eq_ignore_ascii_case(name)) =>
                {
                    return true;
                }
                Section::Enums(enums)
                    if enums
                        .iter()
                        .any(|item| item.name.eq_ignore_ascii_case(name)) =>
                {
                    return true;
                }
                Section::Traits(traits)
                    if traits
                        .iter()
                        .any(|item| item.name.eq_ignore_ascii_case(name)) =>
                {
                    return true;
                }
                Section::Interfaces(interfaces)
                    if interfaces
                        .iter()
                        .any(|item| item.name.eq_ignore_ascii_case(name)) =>
                {
                    return true;
                }
                Section::Contracts(contracts)
                    if contracts
                        .iter()
                        .any(|item| item.name.eq_ignore_ascii_case(name)) =>
                {
                    return true;
                }
                _ => {}
            }
        }
    }
    false
}

fn phase12_is_unresolved_generic_name(name: &str) -> bool {
    name.len() == 1
        && name
            .chars()
            .next()
            .is_some_and(|ch| ch.is_ascii_uppercase())
        && !phase12_is_builtin_visible_type(name)
}

fn phase12_validate_metadata_target_type(
    program: &Program,
    ty: &SemaType,
    diagnostic_prefix: &str,
) -> Result<(), String> {
    if sema_type_contains_any(ty) {
        return Err(format!(
            "{}_ANY_001: metadata over any is forbidden",
            diagnostic_prefix
        ));
    }
    match ty {
        SemaType::Simple(name) => {
            if phase12_metadata_base(name).is_some() || phase12_is_builtin_visible_type(name) {
                return Ok(());
            }
            if phase12_declared_type_exists(program, name) {
                return Ok(());
            }
            if phase12_is_unresolved_generic_name(name) {
                return Err(format!(
                    "{}_UNRESOLVED_GENERIC_001: metadata for unresolved generic '{}' is deferred",
                    diagnostic_prefix, name
                ));
            }
            Err(format!(
                "{}_UNKNOWN_001: metadata target type '{}' is not visible",
                diagnostic_prefix, name
            ))
        }
        SemaType::Generic { base, args } => {
            let base_ok = phase12_metadata_base(base).is_some()
                || matches!(
                    base.to_ascii_lowercase().as_str(),
                    "option"
                        | "result"
                        | "vector"
                        | "array"
                        | "list"
                        | "fn"
                        | "future"
                        | "task"
                        | "channel"
                        | "iterator"
                        | "iterable"
                        | "collection"
                        | "dyn"
                )
                || phase12_declared_type_exists(program, base);
            if !base_ok {
                return Err(format!(
                    "{}_UNKNOWN_001: metadata target generic base '{}' is not visible",
                    diagnostic_prefix, base
                ));
            }
            for arg in args {
                phase12_validate_metadata_target_type(program, arg, diagnostic_prefix)?;
            }
            Ok(())
        }
        SemaType::Array(inner) | SemaType::Vector(inner) => {
            phase12_validate_metadata_target_type(program, inner, diagnostic_prefix)
        }
        SemaType::Union(items) => {
            for item in items {
                phase12_validate_metadata_target_type(program, item, diagnostic_prefix)?;
            }
            Ok(())
        }
        SemaType::Unknown => Err(format!(
            "{}_UNKNOWN_001: metadata target type is unknown",
            diagnostic_prefix
        )),
    }
}

fn phase12_metadata_type_from_single_arg(
    explicit_type_args: &[SemaType],
    callee: &str,
) -> Result<SemaType, String> {
    if explicit_type_args.len() != 1 {
        return Err(format!(
            "E_HIGH_TYPEINFO_001: {} expects exactly one explicit type argument",
            callee
        ));
    }
    Ok(explicit_type_args[0].clone())
}

fn phase12_find_function<'a>(
    program: &'a Program,
    current_container_name: &str,
    name: &str,
) -> Option<&'a FunctionDecl> {
    program
        .containers
        .iter()
        .find(|container| container.name == current_container_name)
        .into_iter()
        .chain(
            program
                .containers
                .iter()
                .filter(|container| container.name != current_container_name),
        )
        .flat_map(|container| container.sections.iter())
        .filter_map(|section| match section {
            Section::Fn(functions) => Some(functions.as_slice()),
            _ => None,
        })
        .flatten()
        .find(|function| function.name.eq_ignore_ascii_case(name))
}

fn phase12_fn_ref_name(expr: &Expr) -> Option<&str> {
    match expr {
        Expr::ContextRef(ctx)
            if matches!(ctx.origin, ncc_parser::ContextRefOrigin::FnSyntax)
                && ctx.path.len() == 1 =>
        {
            Some(ctx.path[0].as_str())
        }
        _ => None,
    }
}

fn compact_raw_function_address_name(expr: &Expr) -> Option<&str> {
    let Expr::Call { callee, args } = expr else {
        return None;
    };
    if !callee.eq_ignore_ascii_case("addrOf") || args.len() != 1 {
        return None;
    }
    match &args[0] {
        Expr::Identifier(name) => Some(name.as_str()),
        Expr::ContextRef(ctx) if ctx.path.len() == 1 => Some(ctx.path[0].as_str()),
        _ => None,
    }
}

fn function_returns_explicit_closure_storage(function: &FunctionDecl) -> bool {
    function.public_body.iter().any(|stmt| {
        matches!(
            stmt,
            Stmt::Return(Expr::Call { callee, args })
                if callee.split('<').next().unwrap_or(callee).eq_ignore_ascii_case("closureAt")
                    && matches!(args.len(), 2 | 4)
        )
    })
}

fn phase12_validate_visible_function(
    program: &Program,
    current_container_name: &str,
    expr: &Expr,
    diagnostic_prefix: &str,
) -> Result<(), String> {
    let Some(name) = phase12_fn_ref_name(expr) else {
        return Err(format!(
            "{}_UNKNOWN_001: metadata query expects @fn(symbol)",
            diagnostic_prefix
        ));
    };
    let Some(function) = phase12_find_function(program, current_container_name, name) else {
        return Err(format!(
            "{}_UNKNOWN_001: function '{}' is not visible",
            diagnostic_prefix, name
        ));
    };
    if matches!(function.visibility, Some(Visibility::Private)) {
        return Err(format!(
            "{}_PRIVATE_001: private function '{}' is not introspectable",
            diagnostic_prefix, name
        ));
    }
    if matches!(function.visibility, Some(Visibility::Internal)) {
        return Err(format!(
            "{}_INTERNAL_001: internal function '{}' is not introspectable outside package scope",
            diagnostic_prefix, name
        ));
    }
    Ok(())
}

fn phase12_forbidden_reflection_call(callee: &str) -> Option<&'static str> {
    match callee.to_ascii_lowercase().as_str() {
        "eval" | "dynamiceval" | "compiletimeeval" => Some(
            "E_HIGH_REFLECTION_EVAL_FORBIDDEN_001: dynamic eval is forbidden in High Level Fase 12",
        ),
        "reflectinvoke" | "invokeprivate" | "callbyname" => Some(
            "E_HIGH_REFLECT_INVOKE_DEFERRED_001: reflective invocation is deferred and not closed in Fase 12",
        ),
        "setfield" | "reflectset" | "reflectmutate" | "metadatawrite" => {
            Some("E_HIGH_REFLECTION_MUTATION_001: mutation through reflection is forbidden")
        }
        "typefromstring" | "typebyname" => Some(
            "E_HIGH_TYPE_FROM_STRING_DEFERRED_001: type construction from string is deferred",
        ),
        "reflectprivatefield" | "getprivatefield" | "privatefieldinfo" => {
            Some("E_HIGH_VISIBILITY_PRIVATE_LEAK_001: private fields cannot be reflected")
        }
        "reflectinternal" | "internalfieldinfo" => Some(
            "E_HIGH_VISIBILITY_INTERNAL_LEAK_001: internal metadata is package-scoped and not exposed here",
        ),
        "reflectcapturevalues" | "capturevalues" => Some(
            "E_HIGH_CLOSURE_CAPTURE_LEAK_001: closure metadata cannot expose captured values",
        ),
        "machineinfo" | "reflectmachine" | "basalinfo" | "reflectbasal" => Some(
            "E_HIGH_REFLECT_MODE_FORBIDDEN_001: machine/basal internals require their own doctors, not high-level reflection",
        ),
        "anymetadata" | "metadataany" => {
            Some("E_HIGH_METADATA_ANY_LEAK_001: metadata cannot use any")
        }
        "unsafeapisurface" | "apisurfaceall" => {
            Some("E_HIGH_API_SURFACE_PRIVATE_LEAK_001: API introspection is visibility-filtered")
        }
        _ => None,
    }
}

fn phase12_metadata_intrinsic_signature(
    program: &Program,
    current_container_name: &str,
    callee: &str,
    explicit_type_args: &[SemaType],
    args: &[Expr],
    arg_types: &[SemaType],
) -> Result<Option<SemaType>, String> {
    let base = callee.split('<').next().unwrap_or(callee);
    if let Some(message) = phase12_forbidden_reflection_call(base) {
        return Err(message.into());
    }
    match base.to_ascii_lowercase().as_str() {
        "sizeof" | "alignof" => {
            if !args.is_empty() {
                return Err(format!(
                    "E_LAYOUT_QUERY_001: {}<T>() takes no value arguments",
                    base
                ));
            }
            let target = phase12_metadata_type_from_single_arg(explicit_type_args, base)?;
            phase12_validate_metadata_target_type(program, &target, "E_LAYOUT_QUERY")?;
            Ok(Some(SemaType::Simple("int".into())))
        }
        "offsetof" => {
            let target = phase12_metadata_type_from_single_arg(explicit_type_args, "offsetOf")?;
            phase12_validate_metadata_target_type(program, &target, "E_LAYOUT_QUERY")?;
            if args.len() != 1 || !matches!(&args[0], Expr::Identifier(_) | Expr::String(_)) {
                return Err(
                    "E_LAYOUT_QUERY_001: offsetOf<T>(field) expects one field identifier or string"
                        .into(),
                );
            }
            Ok(Some(SemaType::Simple("int".into())))
        }
        "staticassert" => {
            if !(1..=2).contains(&args.len())
                || arg_types.first() != Some(&SemaType::Simple("bool".into()))
                || (args.len() == 2 && arg_types.get(1) != Some(&SemaType::Simple("str".into())))
            {
                return Err(
                    "E_STATIC_ASSERT_001: staticAssert expects bool and an optional str message"
                        .into(),
                );
            }
            match sema_eval_static_layout_expr(program, current_container_name, &args[0])? {
                SemaStaticValue::Bool(true) => {}
                SemaStaticValue::Bool(false) => {
                    return Err(
                        "E_STATIC_ASSERT_001: compile-time assertion evaluated to false".into(),
                    )
                }
                SemaStaticValue::Int(_) => {
                    return Err("E_STATIC_ASSERT_001: assertion must evaluate to bool".into())
                }
            }
            Ok(Some(SemaType::Simple("bool".into())))
        }
        "typeinfo" => {
            if !args.is_empty() {
                return Err("E_HIGH_TYPEINFO_001: typeInfo<T>() takes no value arguments".into());
            }
            let target = phase12_metadata_type_from_single_arg(explicit_type_args, "typeInfo")?;
            phase12_validate_metadata_target_type(program, &target, "E_HIGH_TYPEINFO")?;
            Ok(Some(SemaType::Generic {
                base: "TypeInfo".into(),
                args: vec![target],
            }))
        }
        "fieldcount" | "publicfieldcount" | "typefieldcount" => {
            if !args.is_empty() {
                return Err("E_HIGH_TYPEINFO_001: fieldCount<T>() takes no value arguments".into());
            }
            let target = phase12_metadata_type_from_single_arg(explicit_type_args, "fieldCount")?;
            phase12_validate_metadata_target_type(program, &target, "E_HIGH_TYPEINFO")?;
            Ok(Some(SemaType::Simple("int".into())))
        }
        "enumvariantcount" | "enumvariants" => {
            if !args.is_empty() {
                return Err(
                    "E_HIGH_ENUMINFO_001: enumVariantCount<T>() takes no value arguments".into(),
                );
            }
            let target =
                phase12_metadata_type_from_single_arg(explicit_type_args, "enumVariantCount")?;
            phase12_validate_metadata_target_type(program, &target, "E_HIGH_TYPEINFO")?;
            Ok(Some(SemaType::Simple("int".into())))
        }
        "typename" | "typekind" => {
            if arg_types.len() != 1 {
                return Err(format!(
                    "E_HIGH_TYPEINFO_001: {} expects one TypeInfo",
                    base
                ));
            }
            match &arg_types[0] {
                SemaType::Generic { base, args } if base.eq_ignore_ascii_case("TypeInfo") => {
                    for arg in args {
                        phase12_validate_metadata_target_type(program, arg, "E_HIGH_TYPEINFO")?;
                    }
                    Ok(Some(SemaType::Simple("str".into())))
                }
                other => Err(format!(
                    "E_HIGH_TYPEINFO_001: {} expects TypeInfo<T>, got {}",
                    base,
                    render_sema_type(other)
                )),
            }
        }
        "symbolinfo" => {
            if !explicit_type_args.is_empty() || args.len() != 1 {
                return Err("E_HIGH_SYMBOLINFO_001: symbolInfo expects one @fn(symbol)".into());
            }
            phase12_validate_visible_function(
                program,
                current_container_name,
                &args[0],
                "E_HIGH_SYMBOLINFO",
            )?;
            Ok(Some(SemaType::Simple("SymbolInfo".into())))
        }
        "functionname" | "symbolname" => {
            if arg_types.len() != 1
                || !matches!(&arg_types[0], SemaType::Simple(name) if name.eq_ignore_ascii_case("SymbolInfo"))
            {
                return Err(format!(
                    "E_HIGH_SYMBOLINFO_001: {} expects SymbolInfo",
                    base
                ));
            }
            Ok(Some(SemaType::Simple("str".into())))
        }
        "effectinfo" => {
            if args.len() != 1 {
                return Err("E_HIGH_EFFECTINFO_001: effectInfo expects one @fn(symbol)".into());
            }
            phase12_validate_visible_function(
                program,
                current_container_name,
                &args[0],
                "E_HIGH_EFFECTINFO",
            )?;
            Ok(Some(SemaType::Simple("EffectInfo".into())))
        }
        "moduleinfo" => {
            if !explicit_type_args.is_empty() || arg_types.len() != 1 {
                return Err("E_HIGH_MODULEINFO_001: moduleInfo expects one string path".into());
            }
            if !type_compatible(&arg_types[0], &SemaType::Simple("str".into())) {
                return Err("E_HIGH_MODULEINFO_001: moduleInfo path must be str".into());
            }
            Ok(Some(SemaType::Simple("ModuleInfo".into())))
        }
        "packageinfo" => {
            if !explicit_type_args.is_empty() || arg_types.len() != 1 {
                return Err("E_HIGH_PACKAGEINFO_001: packageInfo expects one string name".into());
            }
            if !type_compatible(&arg_types[0], &SemaType::Simple("str".into())) {
                return Err("E_HIGH_PACKAGEINFO_001: packageInfo name must be str".into());
            }
            Ok(Some(SemaType::Simple("PackageInfo".into())))
        }
        "apisurface" => {
            if !explicit_type_args.is_empty() || !args.is_empty() {
                return Err("E_HIGH_API_SURFACE_INFO_001: apiSurface takes no arguments".into());
            }
            Ok(Some(SemaType::Simple("ApiSurfaceInfo".into())))
        }
        "apiexportcount" => {
            if !explicit_type_args.is_empty() || !args.is_empty() {
                return Err(
                    "E_HIGH_API_SURFACE_INFO_001: apiExportCount takes no arguments".into(),
                );
            }
            Ok(Some(SemaType::Simple("int".into())))
        }
        "traitinfo" | "interfaceinfo" | "contractinfo" => {
            if !args.is_empty() {
                return Err(format!(
                    "E_HIGH_TRAITINFO_001: {}<T>() takes no value arguments",
                    base
                ));
            }
            let target = phase12_metadata_type_from_single_arg(explicit_type_args, base)?;
            phase12_validate_metadata_target_type(program, &target, "E_HIGH_TRAITINFO")?;
            let out = if base.eq_ignore_ascii_case("interfaceInfo") {
                "InterfaceInfo"
            } else if base.eq_ignore_ascii_case("contractInfo") {
                "ContractInfo"
            } else {
                "TraitInfo"
            };
            Ok(Some(SemaType::Simple(out.into())))
        }
        "closureinfo" => {
            if args.len() != 1 {
                return Err("E_HIGH_CLOSUREINFO_001: closureInfo expects one closure value".into());
            }
            let got = arg_types.first().cloned().unwrap_or(SemaType::Unknown);
            if closure_function_type_parts(&got).is_none() {
                return Err(format!(
                    "E_HIGH_CLOSUREINFO_001: closureInfo expects fn(...) type, got {}",
                    render_sema_type(&got)
                ));
            }
            Ok(Some(SemaType::Simple("ClosureInfo".into())))
        }
        "closureparamcount" | "closurecapturecount" => {
            if arg_types.len() != 1
                || !matches!(&arg_types[0], SemaType::Simple(name) if name.eq_ignore_ascii_case("ClosureInfo"))
            {
                return Err(format!(
                    "E_HIGH_CLOSUREINFO_001: {} expects ClosureInfo",
                    base
                ));
            }
            Ok(Some(SemaType::Simple("int".into())))
        }
        "metadatareport" => {
            if !explicit_type_args.is_empty() || !args.is_empty() {
                return Err("E_HIGH_METADATA_001: metadataReport takes no arguments".into());
            }
            Ok(Some(SemaType::Simple("MetadataReport".into())))
        }
        "metadataof" => {
            if !args.is_empty() {
                return Err("E_HIGH_METADATA_001: metadataOf<T>() takes no value arguments".into());
            }
            let target = phase12_metadata_type_from_single_arg(explicit_type_args, "metadataOf")?;
            phase12_validate_metadata_target_type(program, &target, "E_HIGH_METADATA")?;
            Ok(Some(SemaType::Simple("MetadataReport".into())))
        }
        _ => Ok(None),
    }
}

fn phase12_metadata_intrinsic_signature_pre_args(
    program: &Program,
    current_container_name: &str,
    callee: &str,
    explicit_type_args: &[SemaType],
    args: &[Expr],
) -> Result<Option<SemaType>, String> {
    let base = callee.split('<').next().unwrap_or(callee);
    if let Some(message) = phase12_forbidden_reflection_call(base) {
        return Err(message.into());
    }
    match base.to_ascii_lowercase().as_str() {
        "sizeof" | "alignof" => {
            if !args.is_empty() {
                return Err(format!(
                    "E_LAYOUT_QUERY_001: {}<T>() takes no value arguments",
                    base
                ));
            }
            let target = phase12_metadata_type_from_single_arg(explicit_type_args, base)?;
            phase12_validate_metadata_target_type(program, &target, "E_LAYOUT_QUERY")?;
            Ok(Some(SemaType::Simple("int".into())))
        }
        "offsetof" => {
            let target = phase12_metadata_type_from_single_arg(explicit_type_args, "offsetOf")?;
            phase12_validate_metadata_target_type(program, &target, "E_LAYOUT_QUERY")?;
            if args.len() != 1 || !matches!(&args[0], Expr::Identifier(_) | Expr::String(_)) {
                return Err(
                    "E_LAYOUT_QUERY_001: offsetOf<T>(field) expects one field identifier or string"
                        .into(),
                );
            }
            Ok(Some(SemaType::Simple("int".into())))
        }
        "typeinfo" => {
            if !args.is_empty() {
                return Err("E_HIGH_TYPEINFO_001: typeInfo<T>() takes no value arguments".into());
            }
            let target = phase12_metadata_type_from_single_arg(explicit_type_args, "typeInfo")?;
            phase12_validate_metadata_target_type(program, &target, "E_HIGH_TYPEINFO")?;
            Ok(Some(SemaType::Generic {
                base: "TypeInfo".into(),
                args: vec![target],
            }))
        }
        "fieldcount" | "publicfieldcount" | "typefieldcount" => {
            if !args.is_empty() {
                return Err("E_HIGH_TYPEINFO_001: fieldCount<T>() takes no value arguments".into());
            }
            let target = phase12_metadata_type_from_single_arg(explicit_type_args, "fieldCount")?;
            phase12_validate_metadata_target_type(program, &target, "E_HIGH_TYPEINFO")?;
            Ok(Some(SemaType::Simple("int".into())))
        }
        "enumvariantcount" | "enumvariants" => {
            if !args.is_empty() {
                return Err(
                    "E_HIGH_ENUMINFO_001: enumVariantCount<T>() takes no value arguments".into(),
                );
            }
            let target =
                phase12_metadata_type_from_single_arg(explicit_type_args, "enumVariantCount")?;
            phase12_validate_metadata_target_type(program, &target, "E_HIGH_TYPEINFO")?;
            Ok(Some(SemaType::Simple("int".into())))
        }
        "symbolinfo" => {
            if !explicit_type_args.is_empty() || args.len() != 1 {
                return Err("E_HIGH_SYMBOLINFO_001: symbolInfo expects one @fn(symbol)".into());
            }
            phase12_validate_visible_function(
                program,
                current_container_name,
                &args[0],
                "E_HIGH_SYMBOLINFO",
            )?;
            Ok(Some(SemaType::Simple("SymbolInfo".into())))
        }
        "effectinfo" => {
            if args.len() != 1 {
                return Err("E_HIGH_EFFECTINFO_001: effectInfo expects one @fn(symbol)".into());
            }
            phase12_validate_visible_function(
                program,
                current_container_name,
                &args[0],
                "E_HIGH_EFFECTINFO",
            )?;
            Ok(Some(SemaType::Simple("EffectInfo".into())))
        }
        "traitinfo" | "interfaceinfo" | "contractinfo" => {
            if !args.is_empty() {
                return Err(format!(
                    "E_HIGH_TRAITINFO_001: {}<T>() takes no value arguments",
                    base
                ));
            }
            let target = phase12_metadata_type_from_single_arg(explicit_type_args, base)?;
            phase12_validate_metadata_target_type(program, &target, "E_HIGH_TRAITINFO")?;
            let out = if base.eq_ignore_ascii_case("interfaceInfo") {
                "InterfaceInfo"
            } else if base.eq_ignore_ascii_case("contractInfo") {
                "ContractInfo"
            } else {
                "TraitInfo"
            };
            Ok(Some(SemaType::Simple(out.into())))
        }
        "apisurface" => {
            if !explicit_type_args.is_empty() || !args.is_empty() {
                return Err("E_HIGH_API_SURFACE_INFO_001: apiSurface takes no arguments".into());
            }
            Ok(Some(SemaType::Simple("ApiSurfaceInfo".into())))
        }
        "apiexportcount" => {
            if !explicit_type_args.is_empty() || !args.is_empty() {
                return Err(
                    "E_HIGH_API_SURFACE_INFO_001: apiExportCount takes no arguments".into(),
                );
            }
            Ok(Some(SemaType::Simple("int".into())))
        }
        "metadatareport" => {
            if !explicit_type_args.is_empty() || !args.is_empty() {
                return Err("E_HIGH_METADATA_001: metadataReport takes no arguments".into());
            }
            Ok(Some(SemaType::Simple("MetadataReport".into())))
        }
        "metadataof" => {
            if !args.is_empty() {
                return Err("E_HIGH_METADATA_001: metadataOf<T>() takes no value arguments".into());
            }
            let target = phase12_metadata_type_from_single_arg(explicit_type_args, "metadataOf")?;
            phase12_validate_metadata_target_type(program, &target, "E_HIGH_METADATA")?;
            Ok(Some(SemaType::Simple("MetadataReport".into())))
        }
        _ => Ok(None),
    }
}

fn phase12_validate_metadata_type_name(program: &Program, ty: &TypeName) -> Result<(), String> {
    match ty {
        TypeName::Simple(_) => Ok(()),
        TypeName::Array(inner) | TypeName::Vector(inner) => {
            phase12_validate_metadata_type_name(program, inner)
        }
        TypeName::Union(items) => {
            for item in items {
                phase12_validate_metadata_type_name(program, item)?;
            }
            Ok(())
        }
        TypeName::Generic { base, args } => {
            if phase12_metadata_base(base).is_some() {
                let lowered = SemaType::Generic {
                    base: base.clone(),
                    args: args.iter().map(lower_type).collect(),
                };
                phase12_validate_metadata_target_type(program, &lowered, "E_HIGH_METADATA")?;
            }
            for arg in args {
                phase12_validate_metadata_type_name(program, arg)?;
            }
            Ok(())
        }
    }
}

fn phase12_validate_expr(
    program: &Program,
    current_container_name: &str,
    expr: &Expr,
    scope: &HashMap<String, SemaType>,
    current_context: &Option<Context>,
) -> Result<(), String> {
    match expr {
        Expr::StructLiteral { fields, .. } => {
            for (_, value) in fields {
                phase12_validate_expr(
                    program,
                    current_container_name,
                    value,
                    scope,
                    current_context,
                )?;
            }
            Ok(())
        }
        Expr::Call { callee, args } => {
            let (base, explicit_type_args) = split_generic_callee(callee);
            if let Some(message) = phase12_forbidden_reflection_call(&base) {
                return Err(message.into());
            }
            for arg in args {
                phase12_validate_expr(
                    program,
                    current_container_name,
                    arg,
                    scope,
                    current_context,
                )?;
            }
            if phase12_metadata_intrinsic_signature_pre_args(
                program,
                current_container_name,
                callee,
                &explicit_type_args,
                args,
            )?
            .is_some()
            {
                return Ok(());
            }
            if phase12_metadata_base(&base).is_none() {
                return Ok(());
            }
            let arg_types = args
                .iter()
                .map(|arg| {
                    infer_expr_type(program, current_container_name, arg, scope, current_context)
                })
                .collect::<Result<Vec<_>, _>>()?;
            let _ = phase12_metadata_intrinsic_signature(
                program,
                current_container_name,
                callee,
                &explicit_type_args,
                args,
                &arg_types,
            )?;
            Ok(())
        }
        Expr::QualifiedCall { args, .. } => {
            for arg in args {
                phase12_validate_expr(
                    program,
                    current_container_name,
                    arg,
                    scope,
                    current_context,
                )?;
            }
            Ok(())
        }
        Expr::MethodCall { receiver, args, .. } => {
            phase12_validate_expr(
                program,
                current_container_name,
                receiver,
                scope,
                current_context,
            )?;
            for arg in args {
                phase12_validate_expr(
                    program,
                    current_container_name,
                    arg,
                    scope,
                    current_context,
                )?;
            }
            Ok(())
        }
        Expr::Index { target, index } => {
            phase12_validate_expr(
                program,
                current_container_name,
                target,
                scope,
                current_context,
            )?;
            phase12_validate_expr(
                program,
                current_container_name,
                index,
                scope,
                current_context,
            )
        }
        Expr::VectorLiteral(items) | Expr::ArrayLiteral(items) => {
            for item in items {
                phase12_validate_expr(
                    program,
                    current_container_name,
                    item,
                    scope,
                    current_context,
                )?;
            }
            Ok(())
        }
        Expr::StrictCheckExpr { ty, value, .. } => {
            phase12_validate_metadata_type_name(program, ty)?;
            phase12_validate_expr(
                program,
                current_container_name,
                value,
                scope,
                current_context,
            )
        }
        Expr::PostIncrement { .. }
        | Expr::FieldPostIncrement { .. }
        | Expr::PointerPostIncrementRead { .. } => {
            infer_expr_type(
                program,
                current_container_name,
                expr,
                scope,
                current_context,
            )?;
            Ok(())
        }
        Expr::Unary { expr, .. } => phase12_validate_expr(
            program,
            current_container_name,
            expr,
            scope,
            current_context,
        ),
        Expr::Binary { left, right, .. } => {
            phase12_validate_expr(
                program,
                current_container_name,
                left,
                scope,
                current_context,
            )?;
            phase12_validate_expr(
                program,
                current_container_name,
                right,
                scope,
                current_context,
            )
        }
        Expr::IfElse {
            condition,
            then_expr,
            else_expr,
        } => {
            phase12_validate_expr(
                program,
                current_container_name,
                condition,
                scope,
                current_context,
            )?;
            phase12_validate_expr(
                program,
                current_container_name,
                then_expr,
                scope,
                current_context,
            )?;
            phase12_validate_expr(
                program,
                current_container_name,
                else_expr,
                scope,
                current_context,
            )
        }
        Expr::Closure(closure) => {
            let mut closure_scope = scope.clone();
            for param in &closure.params {
                phase12_validate_metadata_type_name(program, &param.ty)?;
                closure_scope.insert(param.name.clone(), lower_type(&param.ty));
            }
            phase12_validate_metadata_type_name(program, &closure.return_type)?;
            for stmt in &closure.body {
                phase12_validate_stmt(
                    program,
                    current_container_name,
                    stmt,
                    &mut closure_scope,
                    current_context,
                )?;
            }
            Ok(())
        }
        Expr::Bool(_)
        | Expr::Number(_)
        | Expr::Char(_)
        | Expr::String(_)
        | Expr::Identifier(_)
        | Expr::ContextRef(_)
        | Expr::Dev(_) => Ok(()),
    }
}

fn phase12_validate_stmt(
    program: &Program,
    current_container_name: &str,
    stmt: &Stmt,
    scope: &mut HashMap<String, SemaType>,
    current_context: &Option<Context>,
) -> Result<(), String> {
    match stmt {
        Stmt::Projection { target, ty, value } | Stmt::StrictCheck { target, ty, value } => {
            let inferred_projection =
                matches!(stmt, Stmt::Projection { .. }) && ast_type_is_inferred_projection(ty);
            if !inferred_projection {
                phase12_validate_metadata_type_name(program, ty)?;
            }
            phase12_validate_expr(
                program,
                current_container_name,
                value,
                scope,
                current_context,
            )?;
            if let AssignTarget::Context(ctx) = target {
                if ctx.path.len() == 1 {
                    let target_ty = if inferred_projection {
                        resolve_projection_declared_type(program, scope, target)?
                    } else {
                        lower_type(ty)
                    };
                    scope.insert(ctx.path[0].clone(), target_ty);
                }
            }
            Ok(())
        }
        Stmt::Return(expr) | Stmt::Expr(expr) | Stmt::Print { value: expr, .. } => {
            phase12_validate_expr(
                program,
                current_container_name,
                expr,
                scope,
                current_context,
            )
        }
        Stmt::If {
            condition,
            then_block,
            else_block,
        } => {
            phase12_validate_expr(
                program,
                current_container_name,
                condition,
                scope,
                current_context,
            )?;
            let mut then_scope = scope.clone();
            for stmt in then_block {
                phase12_validate_stmt(
                    program,
                    current_container_name,
                    stmt,
                    &mut then_scope,
                    current_context,
                )?;
            }
            let mut else_scope = scope.clone();
            for stmt in else_block {
                phase12_validate_stmt(
                    program,
                    current_container_name,
                    stmt,
                    &mut else_scope,
                    current_context,
                )?;
            }
            Ok(())
        }
        Stmt::Unless { condition, body }
        | Stmt::While { condition, body }
        | Stmt::DoWhile { condition, body }
        | Stmt::RepeatUntil { condition, body } => {
            phase12_validate_expr(
                program,
                current_container_name,
                condition,
                scope,
                current_context,
            )?;
            for stmt in body {
                phase12_validate_stmt(
                    program,
                    current_container_name,
                    stmt,
                    scope,
                    current_context,
                )?;
            }
            Ok(())
        }
        Stmt::ForIn { iterable, body, .. } | Stmt::SameIn { iterable, body, .. } => {
            phase12_validate_expr(
                program,
                current_container_name,
                iterable,
                scope,
                current_context,
            )?;
            for stmt in body {
                phase12_validate_stmt(
                    program,
                    current_container_name,
                    stmt,
                    scope,
                    current_context,
                )?;
            }
            Ok(())
        }
        Stmt::ForRange {
            start,
            end,
            step,
            body,
            ..
        } => {
            phase12_validate_expr(
                program,
                current_container_name,
                start,
                scope,
                current_context,
            )?;
            phase12_validate_expr(program, current_container_name, end, scope, current_context)?;
            if let Some(step) = step {
                phase12_validate_expr(
                    program,
                    current_container_name,
                    step,
                    scope,
                    current_context,
                )?;
            }
            for stmt in body {
                phase12_validate_stmt(
                    program,
                    current_container_name,
                    stmt,
                    scope,
                    current_context,
                )?;
            }
            Ok(())
        }
        Stmt::Loop { body } => {
            for stmt in body {
                phase12_validate_stmt(
                    program,
                    current_container_name,
                    stmt,
                    scope,
                    current_context,
                )?;
            }
            Ok(())
        }
        Stmt::RepeatCount { count, body } => {
            phase12_validate_expr(
                program,
                current_container_name,
                count,
                scope,
                current_context,
            )?;
            for stmt in body {
                phase12_validate_stmt(
                    program,
                    current_container_name,
                    stmt,
                    scope,
                    current_context,
                )?;
            }
            Ok(())
        }
        Stmt::EachDoWhile {
            iterable,
            body,
            condition,
            ..
        } => {
            phase12_validate_expr(
                program,
                current_container_name,
                iterable,
                scope,
                current_context,
            )?;
            for stmt in body {
                phase12_validate_stmt(
                    program,
                    current_container_name,
                    stmt,
                    scope,
                    current_context,
                )?;
            }
            phase12_validate_expr(
                program,
                current_container_name,
                condition,
                scope,
                current_context,
            )
        }
        Stmt::ForClassic {
            init,
            condition,
            step,
            body,
        } => {
            if let Some(init) = init {
                phase12_validate_stmt(
                    program,
                    current_container_name,
                    init,
                    scope,
                    current_context,
                )?;
            }
            if let Some(condition) = condition {
                phase12_validate_expr(
                    program,
                    current_container_name,
                    condition,
                    scope,
                    current_context,
                )?;
            }
            if let Some(step) = step {
                phase12_validate_stmt(
                    program,
                    current_container_name,
                    step,
                    scope,
                    current_context,
                )?;
            }
            for stmt in body {
                phase12_validate_stmt(
                    program,
                    current_container_name,
                    stmt,
                    scope,
                    current_context,
                )?;
            }
            Ok(())
        }
        Stmt::Switch {
            value,
            cases,
            default,
        }
        | Stmt::Match {
            value,
            cases,
            default,
        } => {
            phase12_validate_expr(
                program,
                current_container_name,
                value,
                scope,
                current_context,
            )?;
            for (case, block) in cases {
                phase12_validate_expr(
                    program,
                    current_container_name,
                    case,
                    scope,
                    current_context,
                )?;
                for stmt in block {
                    phase12_validate_stmt(
                        program,
                        current_container_name,
                        stmt,
                        scope,
                        current_context,
                    )?;
                }
            }
            for stmt in default {
                phase12_validate_stmt(
                    program,
                    current_container_name,
                    stmt,
                    scope,
                    current_context,
                )?;
            }
            Ok(())
        }
        Stmt::PatternMatch { value, arms } => {
            phase12_validate_expr(
                program,
                current_container_name,
                value,
                scope,
                current_context,
            )?;
            for arm in arms {
                let mut arm_scope = scope.clone();
                let mut bindings = Vec::new();
                closure_pattern_bindings(&arm.pattern, &mut bindings);
                for binding in bindings {
                    arm_scope.insert(binding, SemaType::Unknown);
                }
                if let Some(guard) = &arm.guard {
                    phase12_validate_expr(
                        program,
                        current_container_name,
                        guard,
                        &arm_scope,
                        current_context,
                    )?;
                }
                for stmt in &arm.body {
                    phase12_validate_stmt(
                        program,
                        current_container_name,
                        stmt,
                        &mut arm_scope,
                        current_context,
                    )?;
                }
            }
            Ok(())
        }
        Stmt::GuardElse {
            condition,
            else_block,
        } => {
            phase12_validate_expr(
                program,
                current_container_name,
                condition,
                scope,
                current_context,
            )?;
            for stmt in else_block {
                phase12_validate_stmt(
                    program,
                    current_container_name,
                    stmt,
                    scope,
                    current_context,
                )?;
            }
            Ok(())
        }
        Stmt::Select { branches, default } => {
            for (condition, block) in branches {
                phase12_validate_expr(
                    program,
                    current_container_name,
                    condition,
                    scope,
                    current_context,
                )?;
                for stmt in block {
                    phase12_validate_stmt(
                        program,
                        current_container_name,
                        stmt,
                        scope,
                        current_context,
                    )?;
                }
            }
            for stmt in default {
                phase12_validate_stmt(
                    program,
                    current_container_name,
                    stmt,
                    scope,
                    current_context,
                )?;
            }
            Ok(())
        }
        Stmt::Labeled { stmt, .. } => phase12_validate_stmt(
            program,
            current_container_name,
            stmt,
            scope,
            current_context,
        ),
        Stmt::Defer { body } => {
            for stmt in body {
                phase12_validate_stmt(
                    program,
                    current_container_name,
                    stmt,
                    scope,
                    current_context,
                )?;
            }
            Ok(())
        }
        Stmt::Destructure { args, .. } | Stmt::Constructure { args, .. } => {
            for arg in args {
                phase12_validate_expr(
                    program,
                    current_container_name,
                    arg,
                    scope,
                    current_context,
                )?;
            }
            Ok(())
        }
        Stmt::Dev(_)
        | Stmt::Break { .. }
        | Stmt::Continue { .. }
        | Stmt::MainRefFn { .. }
        | Stmt::FunctionRelation { .. } => Ok(()),
    }
}

fn validate_high_phase12_limited_reflection_introspection(program: &Program) -> Result<(), String> {
    for container in &program.containers {
        if container.context.is_some() {
            continue;
        }
        let mut container_stc = HashMap::new();
        for section in &container.sections {
            if let Section::Stc(decls) = section {
                for decl in decls {
                    let StcDecl::Typed { name, ty, init, .. } = decl;
                    phase12_validate_metadata_type_name(program, ty)?;
                    container_stc.insert(name.clone(), lower_type(ty));
                    if let Some(init) = init {
                        phase12_validate_expr(
                            program,
                            &container.name,
                            init,
                            &container_stc,
                            &container.context,
                        )?;
                    }
                }
            }
        }
        for section in &container.sections {
            let Section::Fn(functions) = section else {
                continue;
            };
            for function in functions {
                for param in &function.params {
                    phase12_validate_metadata_type_name(program, &param.ty)?;
                }
                phase12_validate_metadata_type_name(program, &function.return_type)?;
                let mut scope = container_stc.clone();
                for param in &function.params {
                    scope.insert(param.name.clone(), lower_type(&param.ty));
                }
                for stmt in &function.public_body {
                    phase12_validate_stmt(
                        program,
                        &container.name,
                        stmt,
                        &mut scope,
                        &container.context,
                    )?;
                }
            }
        }
    }
    Ok(())
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum ConstValue {
    Int(i64),
    Bool(bool),
    String(String),
    EnumDiscriminant {
        enum_name: String,
        variant: String,
        index: i64,
    },
    EnumVariant {
        enum_name: String,
        variant: String,
    },
    Array(Vec<ConstValue>),
    TypeMetadata {
        name: String,
        kind: String,
    },
    Unit,
}

#[derive(Debug, Clone)]
struct ConstExpr;

#[derive(Debug, Clone)]
struct ConstEvalResult {
    name: String,
    ty: String,
    value: ConstValue,
}

#[derive(Debug, Clone)]
struct ConstEvalError {
    code: &'static str,
    message: String,
}

#[derive(Debug, Clone)]
struct ConstFunction {
    container: String,
    decl: FunctionDecl,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ConstPurity {
    Pure,
}

#[derive(Debug, Clone, Copy)]
struct ConstStepBudget {
    max_steps: usize,
}

#[derive(Debug, Clone, Copy)]
struct ConstRecursionBudget {
    max_depth: usize,
}

#[derive(Debug, Clone, Copy)]
enum ConstOverflowPolicy {
    CheckedI64,
}

#[derive(Debug, Clone, Copy)]
enum ConstVisibilityPolicy {
    PublicSafeOnly,
}

#[derive(Debug, Clone)]
struct ConstEvalContext {
    values: HashMap<String, ConstValue>,
    functions: HashMap<String, ConstFunction>,
    steps: usize,
    node_budget: usize,
    string_bytes: usize,
    aggregate_items: usize,
    step_budget: ConstStepBudget,
    recursion_budget: ConstRecursionBudget,
    overflow_policy: ConstOverflowPolicy,
    visibility_policy: ConstVisibilityPolicy,
    call_stack: Vec<String>,
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
enum ComptimeCapability {
    FilesystemRead,
    FilesystemWrite,
    FilesystemList,
    FilesystemCreate,
    FilesystemDelete,
    FilesystemMetadata,
    ProcessSpawn,
    ProcessStatus,
    SystemEnv,
    SystemUser,
    SystemPath,
    HeapMutate,
    ReflectionMutate,
    DynamicEval,
    PrivateMetadata,
    ConstructionLeak,
    SideEffects,
    UnboundedLoops,
    UnboundedRecursion,
}

#[derive(Debug, Clone)]
struct ComptimeEffect {
    kind: String,
    source_location: String,
    capability: String,
    deterministic: bool,
    cacheable: bool,
    reproducibility_impact: String,
    detail: String,
    no_limit_used: bool,
}

#[derive(Debug, Clone, Default)]
struct ComptimeEffectReport {
    effects: Vec<ComptimeEffect>,
    non_deterministic: bool,
    cache_disabled: bool,
    no_limit_used: bool,
}

#[derive(Debug, Clone)]
struct ComptimeNoLimitPolicy {
    enabled: bool,
}

#[derive(Debug, Clone)]
struct ComptimeFilesystemPolicy {
    allowed: HashSet<ComptimeCapability>,
}

#[derive(Debug, Clone)]
struct ComptimeProcessPolicy {
    allowed: HashSet<ComptimeCapability>,
}

#[derive(Debug, Clone)]
struct ComptimeSystemPolicy {
    allowed: HashSet<ComptimeCapability>,
}

#[derive(Debug, Clone)]
struct ComptimeHeapMutationPolicy {
    allowed: bool,
}

#[derive(Debug, Clone)]
struct ComptimeReflectionMutationPolicy {
    allowed: bool,
}

#[derive(Debug, Clone)]
struct ComptimeDynamicEvalPolicy {
    allowed: bool,
}

#[derive(Debug, Clone)]
struct ComptimePrivateMetadataPolicy {
    allowed: bool,
}

#[derive(Debug, Clone)]
struct ComptimeConstructionLeakPolicy {
    allowed: bool,
}

#[derive(Debug, Clone)]
struct ComptimeSideEffectPolicy {
    allowed: bool,
}

#[derive(Debug, Clone)]
struct ComptimeExecutionContext {
    allows: HashSet<ComptimeCapability>,
    no_limit: ComptimeNoLimitPolicy,
    filesystem: ComptimeFilesystemPolicy,
    process: ComptimeProcessPolicy,
    system: ComptimeSystemPolicy,
    heap: ComptimeHeapMutationPolicy,
    reflection: ComptimeReflectionMutationPolicy,
    dynamic_eval: ComptimeDynamicEvalPolicy,
    private_metadata: ComptimePrivateMetadataPolicy,
    construction_leak: ComptimeConstructionLeakPolicy,
    side_effects: ComptimeSideEffectPolicy,
    heap_state: HashMap<String, String>,
    metadata_state: HashMap<String, String>,
    report: ComptimeEffectReport,
}

#[derive(Debug, Clone)]
struct ComptimeAuthority {
    block_name: String,
    allows: HashSet<ComptimeCapability>,
    no_limit: bool,
}

#[derive(Debug, Clone)]
struct ComptimeAuditReport {
    block_name: String,
    authority: ComptimeAuthority,
    effects: Vec<ComptimeEffect>,
    reproducibility: ComptimeReproducibilityStatus,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum ComptimeReproducibilityStatus {
    DeterministicCacheable,
    NonDeterministicCacheDisabled,
}

