fn phase15_risk_report_digest(report: &HighRiskReport) -> String {
    let mut material = String::new();
    material.push_str(&format!(
        "nolimit:{}:{}:{}\n",
        report.no_limit.allowed,
        report.no_limit.cache_disabled,
        report.no_limit.termination_not_guaranteed
    ));
    for entry in &report.accepted {
        material.push_str(&format!(
            "{}:{}:{}:{}:{}:{}\n",
            phase15_risk_kind_label(&entry.kind),
            entry.detail,
            entry.risk,
            entry.deterministic,
            entry.line,
            entry.column
        ));
    }
    for bridge in &report.bridges {
        material.push_str(&format!(
            "bridge:{}:{}:{}:{}\n",
            bridge.target, bridge.reason, bridge.authority, bridge.status
        ));
    }
    for site in &report.site_reports {
        material.push_str(&format!(
            "site:{}:{}:{}:{}\n",
            site.site, site.trust, site.alias_risk, site.lifetime_risk
        ));
    }
    for effect in &report.effect_reports {
        material.push_str(&format!(
            "effect:{}:{}:{}\n",
            effect.effect, effect.erased, effect.deterministic
        ));
    }
    for diag in &report.diagnostics {
        material.push_str(&format!(
            "diag:{}:{}:{}:{}\n",
            diag.code, diag.message, diag.line, diag.column
        ));
    }
    for decl in &report.report_decls {
        material.push_str(&format!(
            "report:{}:{}:{}\n",
            decl.name, decl.line, decl.column
        ));
    }
    phase13_stable_hash_hex(&material)
}

fn infer_high_enum_constructor_type(
    program: &Program,
    current_container_name: &str,
    path: &[String],
    args: &[Expr],
    scope: &HashMap<String, SemaType>,
    current_context: &Option<Context>,
) -> Result<Option<SemaType>, String> {
    if path.len() != 2 {
        return Ok(None);
    }
    let enums = collect_high_enums(program)?;
    let Some(info) = enums.get(&path[0].to_ascii_lowercase()) else {
        return Ok(None);
    };
    let Some(variant) = info.variants.get(&path[1].to_ascii_lowercase()) else {
        return Err(format!(
            "E_HIGH_ENUM_VARIANT_UNKNOWN_001: unknown variant '{}.{}'",
            info.name, path[1]
        ));
    };
    if args.len() != variant.payload.len() {
        return Err(format!(
            "E_HIGH_ENUM_CONSTRUCTOR_ARITY_001: constructor '{}.{}' expects {} payload values, got {}",
            info.name,
            variant.name,
            variant.payload.len(),
            args.len()
        ));
    }

    let mut generic_bindings: HashMap<String, SemaType> = HashMap::new();
    let generic_params: HashSet<String> = info.generic_params.iter().cloned().collect();
    for ((_, expected), arg) in variant.payload.iter().zip(args.iter()) {
        let got = infer_expr_type(program, current_container_name, arg, scope, current_context)?;
        if let SemaType::Simple(name) = expected {
            if generic_params.contains(name) {
                generic_bindings.insert(name.clone(), got);
                continue;
            }
        }
        if !type_compatible(&got, expected) {
            return Err(format!(
                "E_HIGH_ENUM_CONSTRUCTOR_TYPE_001: constructor '{}.{}' payload expected {:?}, got {:?}",
                info.name, variant.name, expected, got
            ));
        }
    }

    if info.generic_params.is_empty() {
        Ok(Some(SemaType::Simple(info.name.clone())))
    } else {
        let args = info
            .generic_params
            .iter()
            .map(|name| {
                generic_bindings
                    .get(name)
                    .cloned()
                    .unwrap_or(SemaType::Unknown)
            })
            .collect();
        Ok(Some(SemaType::Generic {
            base: info.name.clone(),
            args,
        }))
    }
}

fn substitute_enum_payload_type(
    ty: &SemaType,
    scrutinee_ty: &SemaType,
    info: &HighEnumInfo,
) -> SemaType {
    let bindings: HashMap<String, SemaType> = match scrutinee_ty {
        SemaType::Generic { base, args } if base.eq_ignore_ascii_case(&info.name) => info
            .generic_params
            .iter()
            .cloned()
            .zip(args.iter().cloned())
            .collect(),
        _ => HashMap::new(),
    };
    match ty {
        SemaType::Simple(name) => bindings.get(name).cloned().unwrap_or_else(|| ty.clone()),
        SemaType::Array(inner) => SemaType::Array(Box::new(substitute_enum_payload_type(
            inner,
            scrutinee_ty,
            info,
        ))),
        SemaType::Vector(inner) => SemaType::Vector(Box::new(substitute_enum_payload_type(
            inner,
            scrutinee_ty,
            info,
        ))),
        SemaType::Generic { base, args } => SemaType::Generic {
            base: base.clone(),
            args: args
                .iter()
                .map(|arg| substitute_enum_payload_type(arg, scrutinee_ty, info))
                .collect(),
        },
        SemaType::Union(items) => SemaType::Union(
            items
                .iter()
                .map(|item| substitute_enum_payload_type(item, scrutinee_ty, info))
                .collect(),
        ),
        SemaType::Unknown => SemaType::Unknown,
    }
}

fn high_method_sig_matches_args(method: &FnSig, arg_types: &[SemaType]) -> bool {
    method.params.len() == arg_types.len()
        && method
            .params
            .iter()
            .zip(arg_types.iter())
            .all(|(expected, actual)| type_compatible(actual, expected))
}

fn resolve_high_static_dispatch_from_impls(
    callee: &str,
    arg_types: &[SemaType],
) -> Result<Option<FnSig>, String> {
    let matches = HIGH_IMPLS.with(|cell| {
        cell.borrow()
            .iter()
            .flat_map(|imp| imp.methods.iter())
            .filter(|method| {
                method.name == callee && high_method_sig_matches_args(method, arg_types)
            })
            .cloned()
            .collect::<Vec<_>>()
    });
    if matches.is_empty() {
        return Ok(None);
    }
    if matches.len() > 1 {
        return Err(format!(
            "E_HIGH_TRAIT_AMBIGUOUS_IMPL_001: static dispatch for '{}' is ambiguous",
            callee
        ));
    }
    Ok(matches.into_iter().next())
}

fn resolve_high_static_dispatch_from_bounds(
    callee: &str,
    arg_types: &[SemaType],
) -> Result<Option<FnSig>, String> {
    let Some(SemaType::Simple(first_param)) = arg_types.first() else {
        return Ok(None);
    };
    let bounds = CURRENT_HIGH_BOUNDS.with(|cell| cell.borrow().clone());
    if bounds.is_empty() {
        return Ok(None);
    }
    let surfaces = HIGH_SURFACES.with(|cell| cell.borrow().clone());
    let mut matches = Vec::new();
    for bound in bounds.iter().filter(|bound| bound.param == *first_param) {
        let Some(surface_name) = type_name_base(&bound.bound) else {
            continue;
        };
        let Some(surface) = surfaces.get(&surface_name.to_ascii_lowercase()) else {
            continue;
        };
        let bound_args = type_name_args(&bound.bound);
        if bound_args.len() != surface.generic_params.len() {
            continue;
        }
        let subst: HashMap<String, TypeName> = surface
            .generic_params
            .iter()
            .cloned()
            .zip(bound_args.iter().cloned())
            .collect();
        let associated: HashMap<String, TypeName> = surface
            .associated_types
            .iter()
            .map(|name| {
                (
                    name.clone(),
                    TypeName::Simple(format!("{}.{}", bound.param, name)),
                )
            })
            .collect();
        for method in surface
            .methods
            .iter()
            .filter(|method| method.name == callee)
        {
            let sig = method_signature_to_fn_sig(&surface.name, method, &subst, &associated);
            if high_method_sig_matches_args(&sig, arg_types) {
                matches.push(sig);
            }
        }
    }
    if matches.is_empty() {
        return Ok(None);
    }
    if matches.len() > 1 {
        return Err(format!(
            "E_HIGH_TRAIT_AMBIGUOUS_IMPL_001: bounded static dispatch for '{}' is ambiguous",
            callee
        ));
    }
    Ok(matches.into_iter().next())
}

fn resolve_high_phase4_static_dispatch(
    callee: &str,
    arg_types: &[SemaType],
) -> Result<Option<FnSig>, String> {
    if let Some(sig) = resolve_high_static_dispatch_from_impls(callee, arg_types)? {
        return Ok(Some(sig));
    }
    resolve_high_static_dispatch_from_bounds(callee, arg_types)
}

fn build_fn_pointer_effect_index(
    program: &Program,
    sig_index: &HashMap<String, Vec<FnSig>>,
) -> HashMap<String, FnPointerEffects> {
    let all_sigs: Vec<FnSig> = sig_index
        .values()
        .flat_map(|items| items.iter())
        .filter(|sig| function_signature_may_have_pointer_effects(sig))
        .cloned()
        .collect();

    let mut effects: HashMap<String, FnPointerEffects> = HashMap::new();
    for sig in &all_sigs {
        effects.entry(function_signature_key(sig)).or_default();
    }

    let max_iters = all_sigs.len().saturating_mul(8).max(8);
    for _ in 0..max_iters {
        let mut changed = false;

        for sig in &all_sigs {
            let key = function_signature_key(sig);
            let next = summarize_function_pointer_effects(program, sig, sig_index, &effects);
            let entry = effects.entry(key).or_default();
            if *entry != next {
                *entry = next;
                changed = true;
            }
        }

        if !changed {
            break;
        }
    }

    effects.retain(|_, effect| *effect != FnPointerEffects::default());
    effects
}

fn sema_type_may_carry_pointer_effect(ty: &SemaType, type_params: &[String]) -> bool {
    if is_pointer_family_type(ty) {
        return true;
    }
    match ty {
        SemaType::Simple(name) => type_params
            .iter()
            .any(|param| param.eq_ignore_ascii_case(name)),
        SemaType::Union(items) => items
            .iter()
            .any(|item| sema_type_may_carry_pointer_effect(item, type_params)),
        SemaType::Vector(inner) | SemaType::Array(inner) => {
            sema_type_may_carry_pointer_effect(inner, type_params)
        }
        SemaType::Generic { args, .. } => args
            .iter()
            .any(|arg| sema_type_may_carry_pointer_effect(arg, type_params)),
        SemaType::Unknown => !type_params.is_empty(),
    }
}

fn function_signature_may_have_pointer_effects(sig: &FnSig) -> bool {
    sig.params
        .iter()
        .any(|param| sema_type_may_carry_pointer_effect(param, &sig.type_params))
}

fn pointer_effect_function_names(
    sig_index: &HashMap<String, Vec<FnSig>>,
    pointer_effects: &HashMap<String, FnPointerEffects>,
) -> HashSet<String> {
    sig_index
        .iter()
        .filter(|(_, signatures)| {
            signatures
                .iter()
                .any(|sig| pointer_effects.contains_key(&function_signature_key(sig)))
        })
        .map(|(name, _)| name.clone())
        .collect()
}

fn refresh_function_indexes(program: &Program) {
    let sig_index = build_fn_sig_index(program);
    let pointer_effects = build_fn_pointer_effect_index(program, &sig_index);
    let pointer_effect_names = pointer_effect_function_names(&sig_index, &pointer_effects);

    FN_RESOLUTION_CACHE.with(|cell| cell.borrow_mut().clear());

    FN_SIGS.with(|cell| {
        *cell.borrow_mut() = sig_index;
    });

    FN_POINTER_EFFECTS.with(|cell| {
        *cell.borrow_mut() = pointer_effects;
    });

    FN_POINTER_EFFECT_NAMES.with(|cell| {
        *cell.borrow_mut() = pointer_effect_names;
    });
}

#[cfg(test)]
mod pointer_effect_worklist_tests {
    use super::*;

    fn parse(source: &str) -> Program {
        let tokens = ncc_lexer::lex(source).expect("pointer-effect source must lex");
        ncc_parser::parse(tokens).expect("pointer-effect source must parse")
    }

    #[test]
    fn scalar_only_call_graph_does_not_enter_pointer_effect_fixed_point() {
        let program = parse(
            r#"
scalarOnly {
    fn:
        add(value: int) -> int {
            public:
                return value + 1;
        }

        run() -> bool {
            public:
                current >> int = add(41);
                return current == 42;
        }

    ref main ->> @fn(run);
    fa:
        return true;
}
"#,
        );
        let signatures = build_fn_sig_index(&program);
        let effects = build_fn_pointer_effect_index(&program, &signatures);
        assert!(effects.is_empty());
        assert!(pointer_effect_function_names(&signatures, &effects).is_empty());
    }

    #[test]
    fn pointer_parameter_effects_remain_in_the_fixed_point() {
        let program = parse(
            r#"
use memory.heap.manager;

pointerEffects[@] {
    fn:
        release(address: addr) -> bool {
            public:
                memory.heap.manager.free(@address);
                return true;
        }

    fa:
        return true;
}
"#,
        );
        let signatures = build_fn_sig_index(&program);
        let effects = build_fn_pointer_effect_index(&program, &signatures);
        let names = pointer_effect_function_names(&signatures, &effects);
        assert!(names.contains("release"));
        assert!(effects.values().any(|effect| {
            effect.require_valid_params.contains(&0) && effect.invalidated_params.contains(&0)
        }));
    }
}

#[cfg(test)]
mod function_resolution_cache_tests {
    use super::*;

    #[test]
    fn cache_keeps_overloads_separate_and_reuses_identical_queries() {
        let tokens = ncc_lexer::lex(
            r#"
cacheOverloads {
    fn:
        choose(value: int) -> int {
            public:
                return @value;
        }

        choose(value: str) -> str {
            public:
                return @value;
        }

    fa:
        return true;
}
"#,
        )
        .expect("cache fixture must lex");
        let program = ncc_parser::parse(tokens).expect("cache fixture must parse");
        let index = build_fn_sig_index(&program);
        FN_RESOLUTION_CACHE.with(|cell| cell.borrow_mut().clear());

        let context = &program.containers[0].context;
        let int_args = vec![SemaType::Simple("int".into())];
        let str_args = vec![SemaType::Simple("str".into())];
        let first = find_function_signature(
            &program,
            "cacheOverloads",
            context,
            &program.uses,
            "choose",
            &int_args,
            &index,
        )
        .expect("int overload must resolve");
        let repeated = find_function_signature(
            &program,
            "cacheOverloads",
            context,
            &program.uses,
            "choose",
            &int_args,
            &index,
        )
        .expect("identical query must resolve from cache");
        let string = find_function_signature(
            &program,
            "cacheOverloads",
            context,
            &program.uses,
            "choose",
            &str_args,
            &index,
        )
        .expect("str overload must resolve independently");

        assert_eq!(first.return_type, SemaType::Simple("int".into()));
        assert_eq!(repeated.return_type, first.return_type);
        assert_eq!(string.return_type, SemaType::Simple("str".into()));
        FN_RESOLUTION_CACHE.with(|cell| assert_eq!(cell.borrow().len(), 2));
    }
}

fn render_sema_type(ty: &SemaType) -> String {
    match ty {
        SemaType::Vector(inner) => format!("vector<{}>", render_sema_type(inner)),
        SemaType::Simple(name) => name.clone(),
        SemaType::Union(items) => {
            let mut rendered = Vec::new();
            for item in items {
                rendered.push(render_sema_type(item));
            }
            format!("union<{}>", rendered.join("|"))
        }
        SemaType::Array(inner) => format!("array<{}>", render_sema_type(inner)),
        SemaType::Generic { base, args } if base.eq_ignore_ascii_case("fn") && !args.is_empty() => {
            let params = args[..args.len() - 1]
                .iter()
                .map(render_sema_type)
                .collect::<Vec<_>>()
                .join(", ");
            format!(
                "fn({}) -> {}",
                params,
                render_sema_type(args.last().unwrap())
            )
        }
        SemaType::Generic { base, args } => {
            let mut rendered = Vec::new();
            for item in args {
                rendered.push(render_sema_type(item));
            }
            format!("{base}<{}>", rendered.join(","))
        }
        SemaType::Unknown => "unknown".into(),
    }
}

fn type_name_base(ty: &TypeName) -> Option<&str> {
    match ty {
        TypeName::Simple(name) => Some(name.as_str()),
        TypeName::Generic { base, .. } => Some(base.as_str()),
        _ => None,
    }
}

fn render_type_name(ty: &TypeName) -> String {
    render_sema_type(&lower_type(ty))
}

fn type_name_args(ty: &TypeName) -> &[TypeName] {
    match ty {
        TypeName::Generic { args, .. } => args,
        _ => &[],
    }
}

fn sema_surface_ref_name_args(ty: &SemaType) -> Option<(&str, &[SemaType])> {
    match ty {
        SemaType::Simple(name) => Some((name.as_str(), &[])),
        SemaType::Generic { base, args } => Some((base.as_str(), args.as_slice())),
        _ => None,
    }
}

fn sema_dyn_surface_ref(ty: &SemaType) -> Option<&SemaType> {
    match ty {
        SemaType::Generic { base, args } if base.eq_ignore_ascii_case("dyn") && args.len() == 1 => {
            args.first()
        }
        _ => None,
    }
}

fn sema_type_contains_any(ty: &SemaType) -> bool {
    match ty {
        SemaType::Simple(name) => name.eq_ignore_ascii_case("any"),
        SemaType::Array(inner) | SemaType::Vector(inner) => sema_type_contains_any(inner),
        SemaType::Union(items) => items.iter().any(sema_type_contains_any),
        SemaType::Generic { args, .. } => args.iter().any(sema_type_contains_any),
        SemaType::Unknown => false,
    }
}

fn substitute_sema_surface_generics(ty: &SemaType, subst: &HashMap<String, SemaType>) -> SemaType {
    match ty {
        SemaType::Simple(name) => subst.get(name).cloned().unwrap_or_else(|| ty.clone()),
        SemaType::Array(inner) => {
            SemaType::Array(Box::new(substitute_sema_surface_generics(inner, subst)))
        }
        SemaType::Vector(inner) => {
            SemaType::Vector(Box::new(substitute_sema_surface_generics(inner, subst)))
        }
        SemaType::Union(items) => SemaType::Union(
            items
                .iter()
                .map(|item| substitute_sema_surface_generics(item, subst))
                .collect(),
        ),
        SemaType::Generic { base, args } => SemaType::Generic {
            base: base.clone(),
            args: args
                .iter()
                .map(|arg| substitute_sema_surface_generics(arg, subst))
                .collect(),
        },
        SemaType::Unknown => SemaType::Unknown,
    }
}

fn build_trait_object_ref(surface_ref: &SemaType) -> Result<TraitObjectRef, String> {
    if sema_type_contains_any(surface_ref) {
        return Err("E_HIGH_ANY_LEAK_001: any leak through dyn is forbidden".into());
    }
    let Some((surface_name, concrete_args)) = sema_surface_ref_name_args(surface_ref) else {
        return Err("E_HIGH_DYN_PARSE_001: dyn must name a trait/interface".into());
    };
    if high_generic_builtin_type(surface_name) {
        return Err(format!(
            "E_HIGH_DYN_NON_TRAIT_001: '{}' is not a trait/interface",
            surface_name
        ));
    }
    let surfaces = HIGH_SURFACES.with(|cell| cell.borrow().clone());
    let Some(surface) = surfaces.get(&surface_name.to_ascii_lowercase()) else {
        return Err(format!(
            "E_HIGH_DYN_TRAIT_UNKNOWN_001: unknown trait/interface '{}'",
            surface_name
        ));
    };
    if concrete_args.len() != surface.generic_params.len() {
        return Err(format!(
            "E_HIGH_TRAIT_OBJECT_PARSE_001: dyn '{}' expects {} type arguments, got {}",
            surface.name,
            surface.generic_params.len(),
            concrete_args.len()
        ));
    }
    if !surface.associated_types.is_empty() {
        return Err(format!(
            "E_HIGH_DYN_OBJECT_SAFETY_001: trait '{}' has associated types and is not object-safe in Phase 5",
            surface.name
        ));
    }
    if !surface.generic_default_methods.is_empty() {
        return Err(format!(
            "E_HIGH_DYN_GENERIC_METHOD_001: trait '{}' has generic default methods and is not object-safe",
            surface.name
        ));
    }
    if surface.methods.is_empty() {
        return Err(format!(
            "E_HIGH_DYN_OBJECT_SAFETY_001: trait '{}' has no dispatchable methods",
            surface.name
        ));
    }
    let subst: HashMap<String, SemaType> = surface
        .generic_params
        .iter()
        .cloned()
        .zip(concrete_args.iter().cloned())
        .collect();
    let methods = surface
        .methods
        .iter()
        .map(|method| FnSig {
            container: surface.name.clone(),
            name: method.name.clone(),
            type_params: Vec::new(),
            generic_bounds: Vec::new(),
            params: method
                .params
                .iter()
                .map(|param| substitute_sema_surface_generics(&lower_type(&param.ty), &subst))
                .collect(),
            return_type: substitute_sema_surface_generics(&lower_type(&method.return_type), &subst),
        })
        .collect::<Vec<_>>();
    Ok(TraitObjectRef {
        surface_name: surface.name.clone(),
        concrete_args: concrete_args.to_vec(),
        methods,
    })
}

fn vtable_layout_for_trait_object(object: &TraitObjectRef) -> VTableLayout {
    VTableLayout {
        surface_name: object.surface_name.clone(),
        method_slots: object
            .methods
            .iter()
            .cloned()
            .enumerate()
            .map(|(slot, signature)| VTableMethodSlot {
                name: signature.name.clone(),
                slot,
                signature,
            })
            .collect(),
    }
}

fn sorted_index_set(items: &HashSet<usize>) -> Vec<usize> {
    let mut out: Vec<usize> = items.iter().copied().collect();
    out.sort_unstable();
    out
}

fn sorted_index_pairs(items: &HashSet<(usize, usize)>) -> Vec<(usize, usize)> {
    let mut out: Vec<(usize, usize)> = items.iter().copied().collect();
    out.sort_unstable();
    out
}

pub fn collect_function_pointer_contracts(program: &Program) -> Vec<FunctionPointerContract> {
    let sig_index = build_fn_sig_index(program);
    let pointer_effects = build_fn_pointer_effect_index(program, &sig_index);

    let mut contracts = Vec::new();

    for container in &program.containers {
        let mut function_index = 0usize;

        for section in &container.sections {
            let Section::Fn(functions) = section else {
                continue;
            };

            for function in functions {
                let sig = FnSig {
                    container: container.name.clone(),
                    name: function.name.clone(),
                    type_params: function.generic_params.clone(),
                    generic_bounds: function.generic_bounds.clone(),
                    params: function.params.iter().map(|p| lower_type(&p.ty)).collect(),
                    return_type: lower_type(&function.return_type),
                };
                let key = function_signature_key(&sig);
                let effects = pointer_effects.get(&key).cloned().unwrap_or_default();

                contracts.push(FunctionPointerContract {
                    container: container.name.clone(),
                    function_index,
                    function_name: function.name.clone(),
                    param_types: sig.params.iter().map(render_sema_type).collect(),
                    return_type: render_sema_type(&sig.return_type),
                    require_valid_params: sorted_index_set(&effects.require_valid_params),
                    invalidated_params: sorted_index_set(&effects.invalidated_params),
                    invalidates_then_requires: sorted_index_pairs(
                        &effects.invalidates_then_requires,
                    ),
                    returned_params: sorted_index_set(&effects.returned_params),
                    invalidates_then_returns: sorted_index_pairs(&effects.invalidates_then_returns),
                });
                function_index += 1;
            }
        }
    }

    contracts
}

fn find_function_decl_by_signature<'a>(
    program: &'a Program,
    sig: &FnSig,
) -> Option<(&'a FunctionDecl, &'a Option<Context>)> {
    for container in &program.containers {
        if container.name != sig.container {
            continue;
        }

        for section in &container.sections {
            if let Section::Fn(funcs) = section {
                for f in funcs {
                    if f.name != sig.name || f.params.len() != sig.params.len() {
                        continue;
                    }

                    if !f.generic_params.is_empty() {
                        return Some((f, &container.context));
                    }

                    let params: Vec<SemaType> =
                        f.params.iter().map(|p| lower_type(&p.ty)).collect();
                    if params == sig.params {
                        return Some((f, &container.context));
                    }
                }
            }
        }
    }

    None
}

fn network_builtin_unqualified_signature(
    current_context: &Option<Context>,
    callee: &str,
    arg_types: &[SemaType],
) -> Option<Result<FnSig, String>> {
    if !matches!(current_context, Some(Context::Network)) {
        return None;
    }

    let params: Vec<SemaType> = match callee {
        "connect" => vec![
            SemaType::Simple("str".to_string()),
            SemaType::Simple("int".to_string()),
        ],
        "listen" => vec![],
        "accept" => vec![],
        "send" => vec![SemaType::Simple("str".to_string())],
        "recv" => vec![],
        "disconnect" => vec![],
        _ => return None,
    };

    if params.len() != arg_types.len() {
        return Some(Err(format!(
            "no matching function '{}' for {} arguments",
            callee,
            arg_types.len()
        )));
    }

    for (idx, (expected, got)) in params.iter().zip(arg_types.iter()).enumerate() {
        if !type_compatible(got, expected) {
            return Some(Err(format!(
                "no matching function '{}' for argument {}: expected {}, got {}",
                callee,
                idx,
                render_sema_type(expected),
                render_sema_type(got)
            )));
        }
    }

    Some(Ok(FnSig {
        container: "system.net.core".to_string(),
        name: callee.to_string(),
        type_params: Vec::new(),
        generic_bounds: Vec::new(),
        params,
        return_type: SemaType::Simple("bool".to_string()),
    }))
}

fn container_has_kernel_operational_contract(
    program: &Program,
    current_container_name: &str,
) -> bool {
    fn type_name_is_simple(ty: &TypeName, expected: &str) -> bool {
        matches!(ty, TypeName::Simple(name) if name.eq_ignore_ascii_case(expected))
    }

    let Some(container) = program
        .containers
        .iter()
        .find(|container| container.name == current_container_name)
    else {
        return false;
    };

    let mut has_scheduler_open = false;
    let mut has_panic_state = false;
    let mut has_quarantine_count = false;
    let mut has_last_task = false;
    let mut has_last_event = false;
    let mut has_legacy_open_state = false;
    let mut has_legacy_scheduled = false;
    let mut has_legacy_panicked = false;
    let mut has_legacy_quarantined = false;

    for section in &container.sections {
        let Section::Stc(decls) = section else {
            continue;
        };
        for decl in decls {
            let StcDecl::Typed { name, ty, .. } = decl;
            if name.eq_ignore_ascii_case("schedulerOpen") && type_name_is_simple(ty, "bool") {
                has_scheduler_open = true;
            } else if name.eq_ignore_ascii_case("panicState") && type_name_is_simple(ty, "bool") {
                has_panic_state = true;
            } else if name.eq_ignore_ascii_case("quarantineCount") && type_name_is_simple(ty, "int")
            {
                has_quarantine_count = true;
            } else if name.eq_ignore_ascii_case("lastTask") && type_name_is_simple(ty, "str") {
                has_last_task = true;
            } else if name.eq_ignore_ascii_case("lastEvent") && type_name_is_simple(ty, "str") {
                has_last_event = true;
            } else if name.eq_ignore_ascii_case("openState") && type_name_is_simple(ty, "bool") {
                has_legacy_open_state = true;
            } else if name.eq_ignore_ascii_case("scheduled") && type_name_is_simple(ty, "bool") {
                has_legacy_scheduled = true;
            } else if name.eq_ignore_ascii_case("panicked") && type_name_is_simple(ty, "bool") {
                has_legacy_panicked = true;
            } else if name.eq_ignore_ascii_case("quarantined") && type_name_is_simple(ty, "bool") {
                has_legacy_quarantined = true;
            }
        }
    }

    (has_scheduler_open
        && has_panic_state
        && has_quarantine_count
        && has_last_task
        && has_last_event)
        || (has_legacy_open_state
            && has_legacy_scheduled
            && has_legacy_panicked
            && has_legacy_quarantined)
}

fn kernel_operational_compat_allowed(
    program: &Program,
    current_container_name: &str,
    current_context: &Option<Context>,
) -> bool {
    match current_context {
        Some(Context::Kernel) => true,
        Some(Context::Root) | None => {
            container_has_kernel_operational_contract(program, current_container_name)
        }
        Some(_) => false,
    }
}

