    let normalized = name.trim().to_ascii_lowercase();
    normalized.starts_with("kernel.atomic.core.")
        || normalized.starts_with("kernel.mmio.core.")
        || normalized.starts_with("kernel.arch.core.")
        || normalized.starts_with("kernel.apic.core.")
