fn import_function_signature(path: &[String], fn_name: &str) -> Option<ImportSignature> {
    import_signatures_for_module(path)?
        .iter()
        .copied()
        .find(|sig| sig.name == fn_name)
}

#[derive(Clone, Copy)]
struct ImportArg {
    ty: &'static str,
}

#[derive(Clone, Copy)]
struct ImportSignatureExt {
    name: &'static str,
    args: &'static [ImportArg],
    return_ty: &'static str,
}

#[derive(Clone, Debug)]
struct ImportSignatureDyn {
    name: String,
    arg_types: Vec<String>,
    arity_min: usize,
    variadic: bool,
    return_ty: String,
}

