fn runtime_dynamic_signatures_for_module(module: &[String]) -> Option<Vec<ImportSignatureDyn>> {
    if path_equals(module, &["runtime", "list"]) {
        return Some(runtime_list_alias_signatures());
    }

    let fam = ncc_parser::runtime_api_find_family_by_source_module_path(module)?;
    let mut out: Vec<ImportSignatureDyn> = fam
        .functions
        .iter()
        .map(|f| ImportSignatureDyn {
            name: f.name.to_string(),
            arg_types: f.arg_types.to_vec(),
            arity_min: f.arity_min,
            variadic: f.variadic,
            return_ty: f.return_ty.to_string(),
        })
        .collect();

    if path_equals(module, &["runtime", "queue"]) {
        out.extend(runtime_list_alias_signatures());
    }

    Some(out)
}

fn runtime_dynamic_function_signature(
    module: &[String],
    fn_name: &str,
) -> Option<ImportSignatureDyn> {
    fn normalize_import_function_name(raw: &str) -> String {
        raw.split('<')
            .next()
            .unwrap_or(raw)
            .trim()
            .to_ascii_lowercase()
    }

    let wanted = normalize_import_function_name(fn_name);
    runtime_dynamic_signatures_for_module(module)?
        .into_iter()
        .find(|sig| {
            sig.name.eq_ignore_ascii_case(fn_name)
                || normalize_import_function_name(&sig.name) == wanted
        })
}

fn normalize_runtime_call_name(raw: &str) -> String {
    raw.split('<')
        .next()
        .unwrap_or(raw)
        .trim()
        .to_ascii_lowercase()
}

fn runtime_required_use_for_unqualified_function(fn_name: &str) -> Option<String> {
    let wanted = normalize_runtime_call_name(fn_name);
    if matches!(
        wanted.as_str(),
        "ok" | "err" | "isok" | "iserr" | "unwrap" | "unwrapor" | "errorof"
    ) {
        return None;
    }

    if runtime_list_alias_signatures()
        .iter()
        .any(|sig| normalize_runtime_call_name(&sig.name) == wanted)
    {
        return Some("nC.runtime.list".to_string());
    }

    ncc_parser::runtime_api_family_specs()
        .iter()
        .find(|fam| {
            fam.functions
                .iter()
                .any(|func| normalize_runtime_call_name(&func.name) == wanted)
        })
        .map(|fam| fam.import_path.clone())
}

fn runtime_auto_backend_module_for_function(fn_name: &str) -> Option<Vec<String>> {
    let wanted = normalize_runtime_call_name(fn_name);
    let module: &[&str] = match wanted.as_str() {
        "clear" | "movecursor" | "hidecursor" | "showcursor" | "enterrawmode" | "exitrawmode"
        | "readkeynonblocking" => &["runtime", "terminal"],
        "nowms" | "monotonicms" | "monotonicns" | "sleepuntilms" => &["runtime", "time"],
        "sleepms" => &["runtime", "sleep"],
        "randint" | "randomrange" | "randomint" | "randomfloat" | "randombool" => {
            &["runtime", "random"]
        }
        "sign" | "abs" => &["runtime", "math"],
        "renderint" | "renderuint" | "renderbinary" | "renderbin" | "renderfloat"
        | "renderft64" | "renderbool" | "renderchar" | "rendertype" | "renderdebug"
        | "renderstable" => &["runtime", "render"],
        "color" | "colorbold" | "bgcolor" | "style" => &["runtime", "output"],
        _ => return None,
    };
    Some(
        module
            .iter()
            .map(|segment| (*segment).to_string())
            .collect(),
    )
}

fn hosted_runtime_prelude_allowed_in_context(current_context: &Option<Context>) -> bool {
    matches!(
        current_context,
        None | Some(Context::Root | Context::Runtime)
    )
}

fn native_prelude_unqualified_signature(
    current_context: &Option<Context>,
    callee: &str,
    arg_types: &[SemaType],
) -> Option<Result<FnSig, String>> {
    let resolved = match ncc_parser::native_prelude_resolve_function(callee, arg_types.len()) {
        Ok(Some(resolved)) => resolved,
        Ok(None) => return None,
        Err(diagnostic) => {
            return Some(Err(format!("{}: {}", diagnostic.code, diagnostic.message)))
        }
    };
    if !resolved.available_in_context(current_context.as_ref()) {
        return None;
    }

    if resolved.lowering == ncc_parser::NativePreludeLowering::CompilerIntrinsic {
        if matches!(
            resolved.source_name.to_ascii_lowercase().as_str(),
            "sizeof" | "alignof" | "offsetof"
        ) {
            return None;
        }
        if resolved.source_name.eq_ignore_ascii_case("checkedAdd") {
            return Some(checked_add_builtin_signature(callee, arg_types));
        }
        return Some(
            runtime_compat_builtin_signature(callee, arg_types).ok_or_else(|| {
                format!(
                "E_NATIVE_PRELUDE_SIGNATURE_001: native intrinsic '{}' has no signature for {:?}",
                callee, arg_types
            )
            }),
        );
    }

    let Some((family, function)) =
        ncc_parser::runtime_api_find_function_by_runtime_symbol(resolved.canonical_symbol)
    else {
        return Some(Err(format!(
            "E_NATIVE_PRELUDE_CATALOG_001: canonical runtime symbol '{}' is absent from the runtime catalog",
            resolved.canonical_symbol
        )));
    };
    let module = family
        .module_path
        .split('.')
        .map(str::to_string)
        .collect::<Vec<_>>();
    let Some(signature) = runtime_dynamic_function_signature(&module, &function.name) else {
        return Some(Err(format!(
            "E_NATIVE_PRELUDE_CATALOG_001: signature '{}' is unavailable in module '{}'",
            function.name, family.module_path
        )));
    };
    Some(runtime_resolve_dynamic_import_call(
        &family.module_path,
        &function.name,
        &signature,
        arg_types,
    ))
}

fn hosted_runtime_prelude_unqualified_signature(
    current_context: &Option<Context>,
    callee: &str,
    arg_types: &[SemaType],
) -> Option<Result<FnSig, String>> {
    if !hosted_runtime_prelude_allowed_in_context(current_context) {
        return None;
    }

    let resolved =
        match ncc_parser::hosted_runtime_prelude_resolve_function(callee, arg_types.len()) {
            Ok(Some(resolved)) => resolved,
            Ok(None) => return None,
            Err(diagnostic) => {
                return Some(Err(format!("{}: {}", diagnostic.code, diagnostic.message)))
            }
        };

    let module = resolved
        .family
        .module_path
        .split('.')
        .map(str::to_string)
        .collect::<Vec<_>>();
    let Some(signature) = runtime_dynamic_function_signature(&module, callee) else {
        return Some(Err(format!(
            "E_RUNTIME_PRELUDE_CATALOG_001: catalog signature '{}' is unavailable in module '{}'",
            callee, resolved.family.module_path
        )));
    };
    Some(runtime_resolve_dynamic_import_call(
        &resolved.family.module_path,
        callee,
        &signature,
        arg_types,
    ))
}

fn runtime_auto_backend_unqualified_signature(
    callee: &str,
    arg_types: &[SemaType],
) -> Option<Result<FnSig, String>> {
    let module = runtime_auto_backend_module_for_function(callee)?;
    let sig = runtime_dynamic_function_signature(&module, callee)?;
    let module_label = module.join(".");
    Some(runtime_resolve_dynamic_import_call(
        &module_label,
        callee,
        &sig,
        arg_types,
    ))
}

fn runtime_generic_param_name(name: &str) -> bool {
    let mut chars = name.chars();
    let Some(first) = chars.next() else {
        return false;
    };
    if !first.is_ascii_uppercase() {
        return false;
    }
    let rest: String = chars.collect();
    rest.is_empty() || rest.chars().all(|ch| ch.is_ascii_digit())
}

fn runtime_collect_generic_params_from_type(ty: &SemaType, out: &mut Vec<String>) {
    match ty {
        SemaType::Simple(name)
            if runtime_generic_param_name(name) && !out.iter().any(|item| item == name) =>
        {
            out.push(name.clone());
        }
        SemaType::Union(items) => {
            for item in items {
                runtime_collect_generic_params_from_type(item, out);
            }
        }
        SemaType::Array(inner) | SemaType::Vector(inner) => {
            runtime_collect_generic_params_from_type(inner, out);
        }
        SemaType::Generic { args, .. } => {
            for arg in args {
                runtime_collect_generic_params_from_type(arg, out);
            }
        }
        _ => {}
    }
}

fn runtime_generic_params_from_name(name: &str) -> Vec<String> {
    let Some((_, suffix)) = name.split_once('<') else {
        return Vec::new();
    };
    let Some(inner) = suffix.strip_suffix('>') else {
        return Vec::new();
    };
    split_top_level_signature_args(inner)
        .into_iter()
        .filter(|item| runtime_generic_param_name(item))
        .collect()
}

fn runtime_generic_params_for_signature(sig: &ImportSignatureDyn) -> Vec<String> {
    let mut params = runtime_generic_params_from_name(&sig.name);
    for raw in sig.arg_types.iter().chain(std::iter::once(&sig.return_ty)) {
        let ty = parse_ffi_signature_type(raw);
        runtime_collect_generic_params_from_type(&ty, &mut params);
    }
    params
}

fn runtime_explicit_call_type_args(callee: &str) -> Vec<SemaType> {
    let Some((_, suffix)) = callee.split_once('<') else {
        return Vec::new();
    };
    let Some(inner) = suffix.strip_suffix('>') else {
        return Vec::new();
    };
    split_top_level_signature_args(inner)
        .iter()
        .map(|item| parse_ffi_signature_type(item))
        .collect()
}

fn runtime_bind_generic_param(
    name: &str,
    actual: &SemaType,
    bindings: &mut HashMap<String, SemaType>,
) -> Result<(), String> {
    if matches!(actual, SemaType::Unknown) {
        return Ok(());
    }
    if let Some(existing) = bindings.get(name) {
        if type_compatible(actual, existing) && type_compatible(existing, actual) {
            return Ok(());
        }
        return Err(format!(
            "E_RUNTIME_GENERIC_ARG_MISMATCH_001: runtime generic argument mismatch for {name}: expected {}, got {}",
            render_sema_type(existing),
            render_sema_type(actual)
        ));
    }
    bindings.insert(name.to_string(), actual.clone());
    Ok(())
}

fn runtime_bind_generic_type(
    expected: &SemaType,
    actual: &SemaType,
    bindings: &mut HashMap<String, SemaType>,
) -> Result<(), String> {
    match expected {
        SemaType::Simple(name) if name.eq_ignore_ascii_case("any") => Ok(()),
        SemaType::Simple(name) if runtime_generic_param_name(name) => {
            runtime_bind_generic_param(name, actual, bindings)
        }
        SemaType::Simple(_) => {
            if type_compatible(actual, expected) {
                Ok(())
            } else {
                Err(format!(
                    "E_RUNTIME_GENERIC_ARG_MISMATCH_001: runtime generic argument mismatch: expected {}, got {}",
                    render_sema_type(expected),
                    render_sema_type(actual)
                ))
            }
        }
        SemaType::Generic { base, args } => match actual {
            SemaType::Generic {
                base: actual_base,
                args: actual_args,
            } if base.eq_ignore_ascii_case(actual_base)
                && base.eq_ignore_ascii_case("array")
                && args.len() == 1
                && !actual_args.is_empty() =>
            {
                if let (SemaType::Simple(expected_name), SemaType::Simple(actual_name)) =
                    (&args[0], &actual_args[0])
                {
                    if !expected_name.eq_ignore_ascii_case("any")
                        && !runtime_generic_param_name(expected_name)
                        && !alias_eq(expected_name, actual_name)
                    {
                        return Err(format!(
                            "E_RUNTIME_GENERIC_ARG_MISMATCH_001: runtime generic argument mismatch: expected {}, got {}",
                            render_sema_type(&args[0]),
                            render_sema_type(&actual_args[0])
                        ));
                    }
                }
                runtime_bind_generic_type(&args[0], &actual_args[0], bindings)
            }
            SemaType::Generic {
                base: actual_base,
                args: actual_args,
            } if base.eq_ignore_ascii_case(actual_base) && args.len() == actual_args.len() => {
                for (expected_arg, actual_arg) in args.iter().zip(actual_args) {
                    runtime_bind_generic_type(expected_arg, actual_arg, bindings)?;
                }
                Ok(())
            }
            SemaType::Array(inner) | SemaType::Vector(inner)
                if (base.eq_ignore_ascii_case("array") || is_list_family(base))
                    && args.len() == 1 =>
            {
                runtime_bind_generic_type(&args[0], inner, bindings)
            }
            SemaType::Unknown => Ok(()),
            _ => Err(format!(
                "E_RUNTIME_GENERIC_ARG_MISMATCH_001: runtime generic argument mismatch: expected {}, got {}",
                render_sema_type(expected),
                render_sema_type(actual)
            )),
        },
        SemaType::Array(expected_inner) => match actual {
            SemaType::Array(actual_inner) | SemaType::Vector(actual_inner) => {
                runtime_bind_generic_type(expected_inner, actual_inner, bindings)
            }
            SemaType::Unknown => Ok(()),
            _ => Err(format!(
                "E_RUNTIME_GENERIC_ARG_MISMATCH_001: runtime generic argument mismatch: expected {}, got {}",
                render_sema_type(expected),
                render_sema_type(actual)
            )),
        },
        SemaType::Vector(expected_inner) => match actual {
            SemaType::Vector(actual_inner) | SemaType::Array(actual_inner) => {
                runtime_bind_generic_type(expected_inner, actual_inner, bindings)
            }
            SemaType::Unknown => Ok(()),
            _ => Err(format!(
                "E_RUNTIME_GENERIC_ARG_MISMATCH_001: runtime generic argument mismatch: expected {}, got {}",
                render_sema_type(expected),
                render_sema_type(actual)
            )),
        },
        SemaType::Union(items) => {
            if items.iter().any(|item| type_compatible(actual, item)) {
                Ok(())
            } else {
                Err(format!(
                    "E_RUNTIME_GENERIC_ARG_MISMATCH_001: runtime generic argument mismatch: expected {}, got {}",
                    render_sema_type(expected),
                    render_sema_type(actual)
                ))
            }
        }
        SemaType::Unknown => Ok(()),
    }
}

fn runtime_apply_generic_bindings(
    ty: &SemaType,
    bindings: &HashMap<String, SemaType>,
) -> Result<SemaType, String> {
    match ty {
        SemaType::Simple(name) if runtime_generic_param_name(name) => {
            Ok(bindings.get(name).cloned().unwrap_or(SemaType::Unknown))
        }
        SemaType::Union(items) => Ok(SemaType::Union(
            items
                .iter()
                .map(|item| runtime_apply_generic_bindings(item, bindings))
                .collect::<Result<Vec<_>, _>>()?,
        )),
        SemaType::Array(inner) => Ok(SemaType::Array(Box::new(runtime_apply_generic_bindings(
            inner, bindings,
        )?))),
        SemaType::Vector(inner) => Ok(SemaType::Vector(Box::new(runtime_apply_generic_bindings(
            inner, bindings,
        )?))),
        SemaType::Generic { base, args } => Ok(SemaType::Generic {
            base: base.clone(),
            args: args
                .iter()
                .map(|arg| runtime_apply_generic_bindings(arg, bindings))
                .collect::<Result<Vec<_>, _>>()?,
        }),
        other => Ok(other.clone()),
    }
}

fn runtime_resolve_dynamic_import_call(
    module_label: &str,
    callee: &str,
    sig: &ImportSignatureDyn,
    arg_types: &[SemaType],
) -> Result<FnSig, String> {
    let arity_ok = if sig.variadic {
        arg_types.len() >= sig.arity_min
    } else {
        arg_types.len() == sig.arity_min
    };
    if !arity_ok {
        return Err(format!(
            "no matching function '{}.{}' for {} arguments",
            module_label,
            callee,
            arg_types.len()
        ));
    }

    let params = runtime_generic_params_for_signature(sig);
    let explicit_args = runtime_explicit_call_type_args(callee);
    let has_generic_contract = !params.is_empty() || !explicit_args.is_empty();
    if !explicit_args.is_empty() && explicit_args.len() != params.len() {
        return Err(format!(
            "E_RUNTIME_GENERIC_INFERENCE_001: runtime generic type could not be inferred for '{}'",
            callee
        ));
    }

    let mut bindings: HashMap<String, SemaType> = HashMap::new();
    for (param, explicit) in params.iter().zip(explicit_args.iter()) {
        runtime_bind_generic_param(param, explicit, &mut bindings)?;
    }

    let module_normalized = module_label.trim().to_ascii_lowercase();
    let callee_base = callee
        .split('<')
        .next()
        .unwrap_or(callee)
        .trim()
        .to_string();

    for (idx, expected_raw) in sig.arg_types.iter().enumerate() {
        if let Some(actual_ty) = arg_types.get(idx) {
            let expected_ty = parse_ffi_signature_type(expected_raw);
            if let Err(err) = runtime_bind_generic_type(&expected_ty, actual_ty, &mut bindings) {
                if module_normalized == "runtime.render"
                    && callee_base.to_ascii_lowercase().starts_with("render")
                {
                    return Err(format!(
                        "E_RUNTIME_RENDER_TYPE_001: invalid render input type for '{}': expected {}, got {}",
                        callee_base,
                        render_sema_type(&expected_ty),
                        render_sema_type(actual_ty)
                    ));
                }
                if module_normalized == "runtime.concat" {
                    return Err(format!(
                        "E_RUNTIME_CONCAT_TYPE_001: explicit render required: concat function '{}' expects {}, got {}",
                        callee_base,
                        render_sema_type(&expected_ty),
                        render_sema_type(actual_ty)
                    ));
                }
                return Err(err);
            }
        }
    }

    let return_template = parse_ffi_signature_type(&sig.return_ty);
    let mut return_type = runtime_apply_generic_bindings(&return_template, &bindings)?;
    let callee_base_lower = callee_base.to_ascii_lowercase();
    let elem_ty = runtime_compat_explicit_or_inferred_elem(&explicit_args, arg_types);
    if module_normalized.ends_with("runtime.ptr") {
        return_type = match callee_base_lower.as_str() {
            "ptrread" | "volatileread" => elem_ty.clone(),
            "ptroffset" | "ptrfromaddr" | "ptrcast" => SemaType::Generic {
                base: "ptr".into(),
                args: vec![elem_ty.clone()],
            },
            "ptrdiff" => SemaType::Simple("int".into()),
            "ptrwrite" | "volatilewrite" | "ptrisnull" => SemaType::Simple("bool".into()),
            _ => return_type,
        };
    } else if module_normalized.ends_with("runtime.region") {
        return_type = match callee_base_lower.as_str() {
            "regionfromptr" => SemaType::Generic {
                base: "memRegion".into(),
                args: vec![elem_ty.clone()],
            },
            "regionptrat" => SemaType::Generic {
                base: "ptr".into(),
                args: vec![elem_ty.clone()],
            },
            _ => return_type,
        };
    }
    if has_generic_contract
        && matches!(return_type, SemaType::Simple(ref name) if name.eq_ignore_ascii_case("any"))
    {
        return Err(format!(
            "E_RUNTIME_ANY_LEAK_001: runtime generic leaked any into typed projection for '{}'",
            callee
        ));
    }

    let resolved_params = sig
        .arg_types
        .iter()
        .map(|arg| {
            let ty = parse_ffi_signature_type(arg);
            runtime_apply_generic_bindings(&ty, &bindings)
        })
        .collect::<Result<Vec<_>, _>>()?;

    Ok(FnSig {
        container: module_label.to_string(),
        name: callee.to_string(),
        type_params: params,
        generic_bounds: Vec::new(),
        params: resolved_params,
        return_type,
    })
}

fn import_exported_functions_any(module: &[String]) -> Option<Vec<String>> {
    let mut exports = Vec::new();
    if let Some(static_exports) = import_exported_functions(module) {
        static_exports
            .iter()
            .for_each(|symbol| exports.push(symbol.to_string()));
    }
    if let Some(runtime_suffix) = use_decl_runtime_family_suffix(module) {
        let dynamic_module = vec!["runtime".to_string(), runtime_suffix.to_string()];
        if let Some(sigs) = runtime_dynamic_signatures_for_module(&dynamic_module) {
            exports.extend(sigs.into_iter().map(|sig| sig.name));
        }
    }
    if let Some(sigs) = runtime_dynamic_signatures_for_module(module) {
        exports.extend(sigs.into_iter().map(|sig| sig.name));
    }
    exports.sort_unstable();
    exports.dedup();
    (!exports.is_empty()).then_some(exports)
}

fn import_function_arity_any(module: &[String], fn_name: &str) -> Option<(usize, bool)> {
    if let Some(arity) = import_function_arity(module, fn_name) {
        return Some((arity, false));
    }
    runtime_dynamic_function_signature(module, fn_name).map(|sig| (sig.arity_min, sig.variadic))
}

fn import_function_return_type_any(module: &[String], fn_name: &str) -> Option<String> {
    if let Some(sig) = import_function_signature(module, fn_name) {
        return Some(sig.return_type.to_string());
    }
    if let Some(sig) =
        import_signatures(module).and_then(|xs| xs.iter().find(|sig| sig.name == fn_name))
    {
        return Some(sig.return_ty.to_string());
    }
    runtime_dynamic_function_signature(module, fn_name).map(|sig| sig.return_ty)
}

