fn import_function_arity(path: &[String], fn_name: &str) -> Option<usize> {
    import_function_signature(path, fn_name).map(|sig| sig.arity)
}

fn import_module_context(path: &[String]) -> Option<Context> {
    if path_equals(path, &["system", "net", "core"]) || path_equals(path, &["alt", "net", "core"]) {
        Some(Context::Network)
    } else if path_equals(path, &["memory", "heap", "manager"])
        || is_runtime_family_module_path(path)
        || path_equals(path, &["runtime", "trace"])
        || path_equals(path, &["runtime", "alias"])
        || path_equals(path, &["runtime", "time"])
        || path_equals(path, &["math", "core"])
    {
        Some(Context::Runtime)
    } else if path_equals(path, &["system", "proc", "core"])
        || path_equals(path, &["system", "io", "core"])
        || path_equals(path, &["system", "service", "core"])
    {
        Some(Context::System)
    } else if path_equals(path, &["tooling", "build", "core"])
        || path_equals(path, &["tooling", "lint", "core"])
        || path_equals(path, &["tooling", "fmt", "core"])
        || path_equals(path, &["tooling", "pkg", "core"])
    {
        Some(Context::Tooling)
    } else if path_equals(path, &["compiler", "parse", "ast"])
        || path_equals(path, &["compiler", "semantic", "core"])
        || path_equals(path, &["compiler", "backend", "machine"])
    {
        Some(Context::Compiler)
    } else if path_equals(path, &["kernel", "task", "core"])
        || path_equals(path, &["kernel", "schedule", "core"])
        || path_equals(path, &["kernel", "cpu", "core"])
        || path_equals(path, &["kernel", "ipi", "core"])
        || path_equals(path, &["kernel", "control", "core"])
        || path_equals(path, &["kernel", "memory", "core"])
        || path_equals(path, &["kernel", "interrupt", "core"])
        || path_equals(path, &["kernel", "syscall", "core"])
        || path_equals(path, &["kernel", "driver", "core"])
        || path_equals(path, &["kernel", "user", "core"])
        || path_equals(path, &["kernel", "boot", "core"])
    {
        Some(Context::Kernel)
    } else if path_equals(path, &["ai", "session", "core"])
        || path_equals(path, &["ai", "model", "core"])
        || path_equals(path, &["ai", "agent", "core"])
        || path_equals(path, &["ai", "chat", "core"])
        || path_equals(path, &["ai", "memory", "core"])
    {
        Some(Context::Ai)
    } else if path_prefix_matches(path, &["security"]) {
        Some(Context::Security)
    } else {
        None
    }
}

fn import_context_link_target_label(module_path: &[String]) -> String {
    format!("import:{}", module_path.join("."))
}

fn module_path_targets_runtime_trace(path: &[String]) -> bool {
    path_equals(path, &["runtime", "trace"])
}

fn known_import_module_contexts_for_use_decl(use_decl: &UseDecl) -> Vec<Context> {
    let mut out = Vec::new();

    for module in known_import_modules() {
        if !import_matches_module(use_decl, &module) {
            continue;
        }
        if let Some(ctx) = import_module_context(&module) {
            out.push(ctx);
        }
    }

    if use_decl.wildcard
        && ((use_decl.path.len() == 2
            && use_decl.path[0].eq_ignore_ascii_case("nC")
            && use_decl.path[1].eq_ignore_ascii_case("runtime"))
            || (use_decl.path.len() == 1 && use_decl.path[0].eq_ignore_ascii_case("runtime")))
    {
        out.push(Context::Runtime);
    }

    if use_decl_runtime_family_suffix(&use_decl.path).is_some() {
        out.push(Context::Runtime);
    }

    out.sort_by_key(import_context_sort_key);
    out.dedup_by_key(|ctx| import_context_sort_key(ctx));
    out
}

fn import_context_sort_key(ctx: &Context) -> String {
    match ctx {
        Context::Root => "00-root".to_string(),
        Context::Machine => "01-machine".to_string(),
        Context::Runtime => "02-runtime".to_string(),
        Context::Network => "03-network".to_string(),
        Context::System => "04-system".to_string(),
        Context::Kernel => "05-kernel".to_string(),
        Context::Security => "06-security".to_string(),
        Context::Inspect => "07-inspect".to_string(),
        Context::Tooling => "08-tooling".to_string(),
        Context::Compiler => "09-compiler".to_string(),
        Context::Ai => "10-ai".to_string(),
        Context::Primitive => "11-primitive".to_string(),
        Context::Unknown(label) => format!("99-unknown-{}", label),
    }
}

fn render_import_context_set(contexts: &[Context]) -> String {
    let mut labels = contexts
        .iter()
        .map(|ctx| match ctx {
            Context::Root => "@".to_string(),
            Context::Machine => "@machine".to_string(),
            Context::Runtime => "@runtime".to_string(),
            Context::Network => "@network".to_string(),
            Context::System => "@system".to_string(),
            Context::Kernel => "@kernel".to_string(),
            Context::Security => "@security".to_string(),
            Context::Inspect => "@inspect".to_string(),
            Context::Tooling => "@tooling".to_string(),
            Context::Compiler => "@compiler".to_string(),
            Context::Ai => "@ai".to_string(),
            Context::Primitive => "@primitive".to_string(),
            Context::Unknown(label) => format!("@{}", label),
        })
        .collect::<Vec<_>>();
    labels.sort();
    labels.dedup();
    format!("[{}]", labels.join(", "))
}

fn render_use_decl_path(use_decl: &UseDecl) -> String {
    if use_decl.wildcard {
        format!("{}.*", use_decl.path.join("."))
    } else {
        use_decl.path.join(".")
    }
}

fn validate_import_declaration_context_authority_for_container(
    current_container_name: &str,
    current_context: &Option<Context>,
    use_decl: &UseDecl,
) -> Result<(), String> {
    if use_decl_targets_runtime_family_or_namespace(use_decl) {
        if matches!(current_context, Some(Context::Primitive)) {
            return Err("E_PRIMITIVE_RUNTIME_001: runtime is not available in primitive[@]".into());
        }
        if matches!(current_context, Some(Context::Root)) {
            let suffix = use_decl_runtime_family_suffix(&use_decl.path);
            let root_compatible = suffix.map(runtime_family_allowed_in_root).unwrap_or(false);
            if !root_compatible {
                return Err("runtime imports are not allowed inside [@]".into());
            }
        }
    }

    if use_decl_targets_runtime_trace_module(use_decl) {
        return Ok(());
    }

    let import_contexts = known_import_module_contexts_for_use_decl(use_decl);
    if import_contexts.is_empty() {
        return Ok(());
    }

    if import_contexts
        .iter()
        .any(|ctx| context_compatible(current_context, &Some(ctx.clone())))
    {
        return Ok(());
    }

    let from = context_label(current_container_name, current_context);
    let import_path = render_use_decl_path(use_decl);
    Err(format!(
        "invalid import declaration '{}' for context '{}': no compatible target context among {}",
        import_path,
        from,
        render_import_context_set(&import_contexts)
    ))
}

fn validate_import_context_authority_for_reference(
    current_container_name: &str,
    current_context: &Option<Context>,
    module_path: &[String],
    reference_name: &str,
) -> Result<(), String> {
    if module_path_targets_runtime_family_or_namespace(module_path)
        && matches!(current_context, Some(Context::Primitive))
    {
        return Err(format!(
            "E_PRIMITIVE_RUNTIME_PATH_001: explicit runtime.* path '{}' is forbidden in primitive[@]",
            module_path.join(".")
        ));
    }

    if module_path_targets_runtime_trace(module_path) {
        return Ok(());
    }

    let Some(module_ctx) = import_module_context(module_path) else {
        return Ok(());
    };
    let target_ctx = Some(module_ctx);

    if context_compatible(current_context, &target_ctx) {
        return Ok(());
    }

    let from = context_label(current_container_name, current_context);
    let target_name = import_context_link_target_label(module_path);
    let to = context_label(&target_name, &target_ctx);
    let official_ref = as_at_reference(reference_name);
    Err(format!(
        "invalid context linking '{}' -> '{}' for reference '{}'; reference '{}' crosses forbidden authority boundary",
        from, to, reference_name, official_ref
    ))
}

fn validate_import_context_authority_for_qualified_call(
    current_container_name: &str,
    current_context: &Option<Context>,
    module_path: &[String],
    full_target: &str,
) -> Result<(), String> {
    if module_path_targets_runtime_family_or_namespace(module_path)
        && matches!(current_context, Some(Context::Primitive))
    {
        return Err(format!(
            "E_PRIMITIVE_RUNTIME_PATH_001: explicit runtime.* path '{}' is forbidden in primitive[@]",
            module_path.join(".")
        ));
    }

    if module_path_targets_runtime_trace(module_path) {
        return Ok(());
    }

    let Some(module_ctx) = import_module_context(module_path) else {
        return Ok(());
    };
    let target_ctx = Some(module_ctx);

    if context_compatible(current_context, &target_ctx) {
        return Ok(());
    }

    let from = context_label(current_container_name, current_context);
    let target_name = import_context_link_target_label(module_path);
    let to = context_label(&target_name, &target_ctx);
    let official_ref = as_at_reference(full_target);
    Err(format!(
        "invalid context linking qualified call '{}' -> '{}' for target '{}'; reference '{}' crosses forbidden authority boundary",
        from, to, full_target, official_ref
    ))
}

fn validate_import_call(
    module: &[String],
    func: &str,
    arg_types: &[SemaType],
) -> Result<(), String> {
    if let Some(sigs) = import_signatures(module) {
        if let Some(sig) = sigs.iter().find(|s| s.name == func) {
            if sig.args.len() != arg_types.len() {
                return Err(format!(
                    "no matching function '{}.{}' for {} arguments",
                    module.join("."),
                    func,
                    arg_types.len()
                ));
            }

            for (i, (expected_arg, actual_ty)) in sig.args.iter().zip(arg_types.iter()).enumerate()
            {
                if !import_arg_type_compatible(expected_arg.ty, actual_ty) {
                    return Err(format!(
                        "no matching function '{}.{}' for argument {}: expected {}, got {}",
                        module.join("."),
                        func,
                        i,
                        expected_arg.ty,
                        render_sema_type(actual_ty)
                    ));
                }
            }
            return Ok(());
        }

        if let Some(sig) = runtime_dynamic_function_signature(module, func) {
            runtime_resolve_dynamic_import_call(&module.join("."), func, &sig, arg_types)?;
            return Ok(());
        }

        return Err(format!(
            "function '{}' not found in import '{}'",
            func,
            module.join(".")
        ));
    }

    let sig = runtime_dynamic_function_signature(module, func).ok_or_else(|| {
        format!(
            "function '{}' not found in import '{}'",
            func,
            module.join(".")
        )
    })?;

    runtime_resolve_dynamic_import_call(&module.join("."), func, &sig, arg_types)?;

    Ok(())
}

fn import_arg_type_compatible(expected_ty: &str, actual_ty: &SemaType) -> bool {
    match expected_ty {
        "addr" => import_addr_like_type(actual_ty),
        "ptr" => import_addr_like_type(actual_ty),
        "int" => is_integer_like(actual_ty),
        "ft" => type_compatible(actual_ty, &SemaType::Simple("ft".into())),
        "str" => type_compatible(actual_ty, &SemaType::Simple("str".into())),
        "text" => type_compatible(actual_ty, &SemaType::Simple("str".into())),
        "bool" => type_compatible(actual_ty, &SemaType::Simple("bool".into())),
        "any" | "result" | "option" | "void" => true,
        other => type_compatible(actual_ty, &SemaType::Simple(other.to_string())),
    }
}

fn import_addr_like_type(actual_ty: &SemaType) -> bool {
    match actual_ty {
        SemaType::Simple(s) => {
            s == "addr" || s == "ptr" || s == "skk*" || s == "skk**" || s == "region"
        }
        SemaType::Generic { base, args } if base == "ptr" && args.len() == 1 => true,
        SemaType::Union(items) => items
            .iter()
            .all(|item| is_bind_null_type(item) || import_addr_like_type(item)),
        _ => false,
    }
}

fn path_starts_with(full: &[String], prefix: &[String]) -> bool {
    ncc_parser::import_path_starts_with(full, prefix)
}

fn path_equals_path(path: &[String], expected: &[String]) -> bool {
    path.len() == expected.len()
        && path
            .iter()
            .zip(expected.iter())
            .all(|(segment, expected)| segment.eq_ignore_ascii_case(expected))
}

fn path_equals(path: &[String], expected: &[&str]) -> bool {
    ncc_parser::import_path_matches(path, expected)
}

fn use_decl_alias_matches_module(use_path: &[String], module_path: &[String]) -> bool {
    if let Some(family) = ncc_parser::runtime_api_find_family_by_source_module_path(module_path) {
        let import_path = family
            .import_path
            .split('.')
            .map(str::to_string)
            .collect::<Vec<_>>();
        let canonical_module = family
            .module_path
            .split('.')
            .map(str::to_string)
            .collect::<Vec<_>>();
        if path_equals_path(use_path, &import_path) || path_equals_path(use_path, &canonical_module)
        {
            return true;
        }
    }

    if let Some(runtime_suffix) = use_decl_runtime_family_suffix(use_path) {
        if module_path.len() == 2
            && module_path[0].eq_ignore_ascii_case("runtime")
            && module_path[1].eq_ignore_ascii_case(runtime_suffix)
        {
            return true;
        }
    }

    if path_equals(use_path, &["nC", "runtime", "heap"])
        || path_equals(use_path, &["runtime", "heap"])
    {
        return path_equals(module_path, &["memory", "heap", "manager"]);
    }

    if path_equals(use_path, &["nC", "runtime", "net"])
        || path_equals(use_path, &["runtime", "net"])
    {
        return path_equals(module_path, &["system", "net", "core"])
            || path_equals(module_path, &["alt", "net", "core"]);
    }

    if path_equals(use_path, &["nC", "runtime", "trace"])
        || path_equals(use_path, &["runtime", "trace"])
    {
        return path_equals(module_path, &["runtime", "trace"]);
    }

    if path_equals(use_path, &["nC", "runtime", "alias"])
        || path_equals(use_path, &["runtime", "alias"])
    {
        return path_equals(module_path, &["runtime", "alias"]);
    }

    if path_equals(use_path, &["nC", "runtime", "time"])
        || path_equals(use_path, &["runtime", "time"])
    {
        return path_equals(module_path, &["runtime", "time"]);
    }

    if use_path_targets_list_family(use_path) {
        return path_equals(module_path, &["runtime", "queue"]);
    }

    if path_equals(use_path, &["nC", "math", "core"]) {
        return path_equals(module_path, &["math", "core"]);
    }

    if path_equals(use_path, &["nC", "tooling", "build"]) {
        return path_equals(module_path, &["tooling", "build", "core"]);
    }

    if path_equals(use_path, &["nC", "tooling", "lint"]) {
        return path_equals(module_path, &["tooling", "lint", "core"]);
    }

    if path_equals(use_path, &["nC", "tooling", "fmt"]) {
        return path_equals(module_path, &["tooling", "fmt", "core"]);
    }

    if path_equals(use_path, &["nC", "tooling", "pkg"]) {
        return path_equals(module_path, &["tooling", "pkg", "core"]);
    }

    if path_equals(use_path, &["nC", "compiler", "parse"]) {
        return path_equals(module_path, &["compiler", "parse", "ast"]);
    }

    if path_equals(use_path, &["nC", "compiler", "semantic"]) {
        return path_equals(module_path, &["compiler", "semantic", "core"]);
    }

    if path_equals(use_path, &["nC", "compiler", "backend"]) {
        return path_equals(module_path, &["compiler", "backend", "machine"]);
    }

    if path_equals(use_path, &["nC", "kernel", "task"]) {
        return path_equals(module_path, &["kernel", "task", "core"]);
    }

    if path_equals(use_path, &["nC", "kernel", "schedule"]) {
        return path_equals(module_path, &["kernel", "schedule", "core"]);
    }

    if path_equals(use_path, &["nC", "kernel", "control"]) {
        return path_equals(module_path, &["kernel", "control", "core"]);
    }
    for family in [
        "cpu",
        "ipi",
        "memory",
        "interrupt",
        "syscall",
        "driver",
        "user",
        "boot",
    ] {
        if path_equals(use_path, &["nC", "kernel", family]) {
            return path_equals(module_path, &["kernel", family, "core"]);
        }
    }

    if path_equals(use_path, &["nC", "ai", "session"]) {
        return path_equals(module_path, &["ai", "session", "core"]);
    }

    if path_equals(use_path, &["nC", "ai", "model"]) {
        return path_equals(module_path, &["ai", "model", "core"]);
    }

    if path_equals(use_path, &["nC", "ai", "agent"]) {
        return path_equals(module_path, &["ai", "agent", "core"]);
    }

    if path_equals(use_path, &["nC", "ai", "chat"]) {
        return path_equals(module_path, &["ai", "chat", "core"]);
    }

    if path_equals(use_path, &["nC", "ai", "memory"]) {
        return path_equals(module_path, &["ai", "memory", "core"]);
    }

    false
}

fn wildcard_runtime_prefix_matches(use_path: &[String], module_path: &[String]) -> bool {
    if path_equals(use_path, &["nC", "runtime"]) || path_equals(use_path, &["runtime"]) {
        return is_runtime_family_module_path(module_path)
            || path_equals(module_path, &["memory", "heap", "manager"])
            || path_equals(module_path, &["system", "net", "core"])
            || path_equals(module_path, &["alt", "net", "core"])
            || path_equals(module_path, &["runtime", "trace"])
            || path_equals(module_path, &["runtime", "alias"])
            || path_equals(module_path, &["runtime", "time"]);
    }

    if use_path_targets_list_family(use_path) {
        return path_equals(module_path, &["runtime", "queue"]);
    }

    if path_equals(use_path, &["nC", "math"]) {
        return path_equals(module_path, &["math", "core"]);
    }

    if path_equals(use_path, &["nC", "tooling"]) {
        return path_equals(module_path, &["tooling", "build", "core"])
            || path_equals(module_path, &["tooling", "lint", "core"])
            || path_equals(module_path, &["tooling", "fmt", "core"])
            || path_equals(module_path, &["tooling", "pkg", "core"]);
    }

    if path_equals(use_path, &["nC", "compiler"]) {
        return path_equals(module_path, &["compiler", "parse", "ast"])
            || path_equals(module_path, &["compiler", "semantic", "core"])
            || path_equals(module_path, &["compiler", "backend", "machine"]);
    }

    if path_equals(use_path, &["nC", "kernel"]) {
        return path_equals(module_path, &["kernel", "task", "core"])
            || path_equals(module_path, &["kernel", "schedule", "core"])
            || path_equals(module_path, &["kernel", "cpu", "core"])
            || path_equals(module_path, &["kernel", "ipi", "core"])
            || path_equals(module_path, &["kernel", "control", "core"])
            || path_equals(module_path, &["kernel", "memory", "core"])
            || path_equals(module_path, &["kernel", "interrupt", "core"])
            || path_equals(module_path, &["kernel", "syscall", "core"])
            || path_equals(module_path, &["kernel", "driver", "core"])
            || path_equals(module_path, &["kernel", "user", "core"])
            || path_equals(module_path, &["kernel", "boot", "core"]);
    }

    if path_equals(use_path, &["nC", "ai"]) {
        return path_equals(module_path, &["ai", "session", "core"])
            || path_equals(module_path, &["ai", "model", "core"])
            || path_equals(module_path, &["ai", "agent", "core"])
            || path_equals(module_path, &["ai", "chat", "core"])
            || path_equals(module_path, &["ai", "memory", "core"]);
    }

    false
}

fn import_matches_module(use_decl: &UseDecl, module_path: &[String]) -> bool {
    fn export_matches_symbol(exports: &[String], symbol: &str) -> bool {
        let wanted = symbol
            .split('<')
            .next()
            .unwrap_or(symbol)
            .trim()
            .to_ascii_lowercase();
        exports.iter().any(|name| {
            name.eq_ignore_ascii_case(symbol)
                || name
                    .split('<')
                    .next()
                    .unwrap_or(name)
                    .trim()
                    .eq_ignore_ascii_case(&wanted)
        })
    }

    if use_decl.wildcard {
        path_starts_with(module_path, &use_decl.path)
            || wildcard_runtime_prefix_matches(&use_decl.path, module_path)
    } else {
        if path_equals_path(&use_decl.path, module_path)
            || use_decl_alias_matches_module(&use_decl.path, module_path)
        {
            return true;
        }

        // Support symbol-level imports such as `use nC.runtime.list.listCreate;` by
        // mapping the prefix to the module and validating the symbol against exports.
        if use_decl.path.len() >= 2 {
            let symbol = use_decl.path.last().expect("import symbol");
            let module_prefix: Vec<String> = use_decl.path[..use_decl.path.len() - 1].to_vec();
            let module_match = path_equals_path(&module_prefix, module_path)
                || use_decl_alias_matches_module(&module_prefix, module_path);
            if module_match {
                if let Some(exports) = import_exported_functions_any(module_path) {
                    return export_matches_symbol(&exports, symbol);
                }
            }
        }

        false
    }
}

fn has_visible_import_for_module(imported_uses: &[UseDecl], module_path: &[String]) -> bool {
    if ncc_parser::runtime_api_source_module_is_implicit(module_path) {
        return true;
    }
    // Linking soberano: un wildcard solo puede exponer módulos importables canónicos,
    // no subrutas arbitrarias bajo el prefijo.
    if import_exported_functions_any(module_path).is_none() {
        return false;
    }
    imported_uses
        .iter()
        .any(|use_decl| import_matches_module(use_decl, module_path))
}

fn known_import_modules() -> Vec<Vec<String>> {
    let mut modules = vec![
        vec!["system".into(), "net".into(), "core".into()],
        vec!["alt".into(), "net".into(), "core".into()],
        vec!["memory".into(), "heap".into(), "manager".into()],
        vec!["runtime".into(), "trace".into()],
        vec!["runtime".into(), "alias".into()],
        vec!["runtime".into(), "time".into()],
        vec!["security".into(), "policy".into(), "strict".into()],
        vec!["security".into(), "intel".into(), "attack".into()],
        vec!["security".into(), "policy".into()],
        vec!["security".into(), "policy".into(), "core".into()],
        vec!["security".into(), "identity".into()],
        vec!["security".into(), "identity".into(), "core".into()],
        vec!["security".into(), "hash".into()],
        vec!["security".into(), "tracekit".into()],
        vec!["security".into(), "attack".into(), "core".into()],
        vec!["security".into(), "defense".into(), "core".into()],
        vec!["security".into(), "forensics".into(), "core".into()],
        vec!["security".into(), "supply".into(), "core".into()],
        vec!["security".into(), "vuln".into(), "core".into()],
        vec!["system".into(), "proc".into(), "core".into()],
        vec!["system".into(), "io".into(), "core".into()],
        vec!["system".into(), "service".into(), "core".into()],
        vec!["tooling".into(), "build".into(), "core".into()],
        vec!["tooling".into(), "lint".into(), "core".into()],
        vec!["tooling".into(), "fmt".into(), "core".into()],
        vec!["tooling".into(), "pkg".into(), "core".into()],
        vec!["compiler".into(), "parse".into(), "ast".into()],
        vec!["compiler".into(), "semantic".into(), "core".into()],
        vec!["compiler".into(), "backend".into(), "machine".into()],
        vec!["kernel".into(), "task".into(), "core".into()],
        vec!["kernel".into(), "schedule".into(), "core".into()],
        vec!["kernel".into(), "cpu".into(), "core".into()],
        vec!["kernel".into(), "ipi".into(), "core".into()],
        vec!["kernel".into(), "control".into(), "core".into()],
        vec!["kernel".into(), "memory".into(), "core".into()],
        vec!["kernel".into(), "interrupt".into(), "core".into()],
        vec!["kernel".into(), "syscall".into(), "core".into()],
        vec!["kernel".into(), "driver".into(), "core".into()],
        vec!["kernel".into(), "user".into(), "core".into()],
        vec!["kernel".into(), "boot".into(), "core".into()],
        vec!["ai".into(), "session".into(), "core".into()],
        vec!["ai".into(), "model".into(), "core".into()],
        vec!["ai".into(), "agent".into(), "core".into()],
        vec!["ai".into(), "chat".into(), "core".into()],
        vec!["ai".into(), "memory".into(), "core".into()],
        vec!["math".into(), "core".into()],
    ];

    for fam in ncc_parser::runtime_api_family_specs() {
        let parts: Vec<String> = fam.module_path.split('.').map(|s| s.to_string()).collect();
        if !modules.iter().any(|m| path_equals_path(m, &parts)) {
            modules.push(parts);
        }
    }

    modules
}

fn imported_modules_visible_for_fn(
    imported_uses: &[UseDecl],
    fn_name: &str,
    current_context: &Option<Context>,
) -> (Vec<String>, Vec<Vec<String>>) {
    let mut allowed = Vec::new();
    let mut blocked = Vec::new();

    for use_decl in imported_uses {
        for module in known_import_modules() {
            if !import_matches_module(use_decl, &module) {
                continue;
            }
            if !import_exported_functions_any(&module)
                .map(|exports| {
                    let wanted = fn_name
                        .split('<')
                        .next()
                        .unwrap_or(fn_name)
                        .trim()
                        .to_ascii_lowercase();
                    exports.iter().any(|f| {
                        f.eq_ignore_ascii_case(fn_name)
                            || f.split('<')
                                .next()
                                .unwrap_or(f)
                                .trim()
                                .eq_ignore_ascii_case(&wanted)
                    })
                })
                .unwrap_or(false)
            {
                continue;
            }
            if context_compatible(current_context, &import_module_context(&module)) {
                allowed.push(module.join("."));
            } else {
                blocked.push(module.clone());
            }
        }
    }

    allowed.sort();
    allowed.dedup();
    blocked.sort();
    blocked.dedup();
    (allowed, blocked)
}

#[cfg(test)]
mod compact_runtime_import_visibility_tests {
    use super::*;

    #[test]
    fn full_text_pad_program_passes_semantic_analysis() {
        let tokens = ncc_lexer::lex(include_str!(
            "../../../examples/runtime/families/pad_basic.n"
        ))
        .expect("full pad fixture must lex");
        let program = ncc_parser::parse(tokens).expect("full pad fixture must parse");
        analyze(&program).expect("full pad fixture must pass semantic analysis");
    }

    #[test]
    fn text_pad_import_is_visible_to_runtime_calls() {
        let tokens = ncc_lexer::lex(
            r#"
use <text:pad>;

padVisibility :: runtime {
    fa:
        return true;
}
"#,
        )
        .expect("pad visibility fixture must lex");
        let program = ncc_parser::parse(tokens).expect("pad visibility fixture must parse");
        let (allowed, blocked) =
            imported_modules_visible_for_fn(&program.uses, "padLeft", &Some(Context::Runtime));
        assert_eq!(allowed, vec!["runtime.pad".to_string()]);
        assert!(
            blocked.is_empty(),
            "unexpected blocked modules: {blocked:?}"
        );

        let args = vec![
            SemaType::Simple("str".into()),
            SemaType::Simple("int".into()),
            SemaType::Simple("char".into()),
        ];
        let sig = find_function_signature_uncached(
            &program,
            "padVisibility",
            &Some(Context::Runtime),
            &program.uses,
            "padLeft",
            &args,
            &HashMap::new(),
        )
        .expect("imported padLeft call must resolve");
        assert_eq!(sig.container, "runtime.pad");
        assert_eq!(sig.return_type, SemaType::Simple("str".into()));
    }
}

fn render_candidate_list(items: &[String]) -> String {
    if items.is_empty() {
        "[]".to_string()
    } else {
        format!("[{}]", items.join(", "))
    }
}

fn as_at_reference(name: &str) -> String {
    if name.starts_with('@') {
        name.to_string()
    } else {
        format!("@{}", name)
    }
}

fn as_at_reference_path(path: &[String]) -> String {
    format!("@{}", path.join("."))
}

fn is_data_motion_qualified_call(path: &[String]) -> bool {
    if path.len() != 2 {
        return false;
    }
    let module = path[0].to_ascii_lowercase();
    let func = path[1].to_ascii_lowercase();
    if module == "copy" {
        return matches!(
            func.as_str(),
            "value" | "ref" | "ptr" | "fn" | "view" | "deep" | "binary" | "unbinary"
        );
    }
    if module == "clone" {
        return matches!(
            func.as_str(),
            "value" | "shallow" | "deep" | "pointee" | "region" | "binary" | "unbinary" | "fn"
        );
    }
    false
}

fn infer_data_motion_qualified_call_type(
    program: &Program,
    current_container_name: &str,
    path: &[String],
    args: &[Expr],
    scope: &HashMap<String, SemaType>,
    current_context: &Option<Context>,
) -> Result<Option<SemaType>, String> {
    if !is_data_motion_qualified_call(path) {
        return Ok(None);
    }

    let module = path[0].to_ascii_lowercase();
    let func = path[1].to_ascii_lowercase();
    let arg_types: Vec<SemaType> = args
        .iter()
        .map(|a| infer_expr_type(program, current_container_name, a, scope, current_context))
        .collect::<Result<Vec<_>, _>>()?;

    let ret = if module == "copy" {
        match func.as_str() {
            "ptr" => {
                return Err(
                    "E_COPY_PTR_ALIAS_001: copy.ptr creates alias and requires alias contract"
                        .to_string(),
                );
            }
            "fn" => {
                if arg_types.len() != 1 {
                    return Err("copy.fn expects exactly 1 argument".to_string());
                }
                let is_function_ref = matches!(
                    args.first(),
                    Some(Expr::ContextRef(ctx))
                        if matches!(
                            classify_context_ref_kind(program, current_container_name, scope, ctx),
                            ContextRefKind::Function
                        )
                );
                if !is_function_ref {
                    return Err("E_COPY_UNSUPPORTED_001: copy unsupported".to_string());
                }
                arg_types[0].clone()
            }
            "value" | "ref" | "view" | "deep" | "binary" | "unbinary" => {
                if arg_types.len() != 1 {
                    return Err(format!("copy.{} expects exactly 1 argument", func));
                }
                arg_types[0].clone()
            }
            _ => return Ok(None),
        }
    } else {
        match func.as_str() {
            "fn" => {
                return Err(
                    "E_CLONE_FN_CODE_001: function code cannot be cloned in runtime profile"
                        .to_string(),
                );
            }
            "pointee" => {
                if arg_types.len() != 2 {
                    return Err("clone.pointee expects pointer and len".to_string());
                }
                if !type_compatible(&arg_types[1], &SemaType::Simple("int".into())) {
                    return Err("clone.pointee len must be int".to_string());
                }
                SemaType::Vector(Box::new(SemaType::Unknown))
            }
            "region" | "value" | "shallow" | "deep" | "binary" | "unbinary" => {
                if arg_types.len() != 1 {
                    return Err(format!("clone.{} expects exactly 1 argument", func));
                }
                arg_types[0].clone()
            }
            _ => return Ok(None),
        }
    };

    Ok(Some(ret))
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ValueTransferOp {
    Copy,
    Clone,
    Move,
}

fn value_transfer_op_from_callee(callee: &str) -> Option<ValueTransferOp> {
    match callee
        .split('<')
        .next()
        .unwrap_or(callee)
        .trim()
        .to_ascii_lowercase()
        .as_str()
    {
        "copy" => Some(ValueTransferOp::Copy),
        "clone" => Some(ValueTransferOp::Clone),
        "move" => Some(ValueTransferOp::Move),
        _ => None,
    }
}

fn closure_moved_symbol_call_diagnostic(
    callee: &str,
    args: &[Expr],
    state: &ClosureFunctionState,
) -> Option<String> {
    let moved_symbol = args.iter().find_map(|arg| match arg {
        Expr::ContextRef(ctx) if ctx.path.len() == 1 && state.moved.contains(&ctx.path[0]) => {
            Some(ctx.path[0].as_str())
        }
        _ => None,
    })?;
    let callee_lower = callee
        .split('<')
        .next()
        .unwrap_or(callee)
        .trim()
        .to_ascii_lowercase();
    let code = if callee_lower.starts_with("list") {
        "E_LIST_MOVED_001: list was moved"
    } else if callee_lower.starts_with("memory") {
        "E_MEMORY_STALE_SITE_001: cannot move/copy from stale site"
    } else if callee_lower == "siteof" {
        "E_SITE_STALE_001: site is stale"
    } else {
        return None;
    };
    Some(format!("{code}: '{}'", moved_symbol))
}

fn direct_value_transfer_call(expr: &Expr) -> Option<(ValueTransferOp, &Expr)> {
    let Expr::Call { callee, args } = expr else {
        return None;
    };
    let op = value_transfer_op_from_callee(callee)?;
    (args.len() == 1).then_some((op, &args[0]))
}

fn type_name_contains_pointer_family(ty: &TypeName) -> bool {
    match ty {
        TypeName::Simple(name) => {
            matches!(
                name.to_ascii_lowercase().as_str(),
                "addr" | "ptr" | "ref" | "site" | "memregion" | "memregion<t>"
            )
        }
        TypeName::Array(inner) | TypeName::Vector(inner) => {
            type_name_contains_pointer_family(inner)
        }
        TypeName::Union(items) => items.iter().any(type_name_contains_pointer_family),
        TypeName::Generic { base, args } => {
            matches!(
                base.to_ascii_lowercase().as_str(),
                "ptr" | "ref" | "site" | "memregion" | "memregion<t>" | "owner"
            ) || args.iter().any(type_name_contains_pointer_family)
        }
    }
}

#[derive(Debug, Clone)]
struct ValueTransferContractInfo {
    name: String,
    has_pointer_field: bool,
    copy_items: Option<Vec<String>>,
    clone_items: Option<Vec<String>>,
    move_items: Option<Vec<String>>,
}

fn value_transfer_contract_info_for_type(
    program: &Program,
    ty: &SemaType,
) -> Option<ValueTransferContractInfo> {
    let ty_name = match ty {
        SemaType::Simple(name) => name,
        SemaType::Generic { base, .. } => base,
        _ => return None,
    };
    let wanted = ty_name.to_ascii_lowercase();

    for container in &program.containers {
        for section in &container.sections {
            let Section::TypeContracts(contracts) = section else {
                continue;
            };
            for contract in contracts {
                if !contract.name.eq_ignore_ascii_case(&wanted) {
                    continue;
                }

                let mut has_pointer_field = false;
                let mut copy_items = None;
                let mut clone_items = None;
                let mut move_items = None;

                for clause in &contract.clauses {
                    match clause {
                        TypeContractClause::Fields { fields, .. } => {
                            has_pointer_field |= fields
                                .iter()
                                .any(|field| type_name_contains_pointer_family(&field.ty));
                        }
                        TypeContractClause::Copy(items) => copy_items = Some(items.clone()),
                        TypeContractClause::Clone(items) => clone_items = Some(items.clone()),
                        TypeContractClause::Move(items) => move_items = Some(items.clone()),
                        _ => {}
                    }
                }

                return Some(ValueTransferContractInfo {
                    name: contract.name.clone(),
                    has_pointer_field,
                    copy_items,
                    clone_items,
                    move_items,
                });
            }
        }
    }

    None
}

fn value_transfer_contract_decision(items: &[String], mode: &str) -> Option<bool> {
    let normalized = items
        .join(" ")
        .to_ascii_lowercase()
        .chars()
        .filter(|c| c.is_ascii_alphanumeric() || *c == '_')
        .collect::<String>();
    let mode = mode.to_ascii_lowercase();
    if !mode.is_empty() {
        if normalized.contains(&format!("{mode}denied")) {
            return Some(false);
        }
        if normalized.contains(&format!("{mode}allowed")) {
            return Some(true);
        }
    }
    if normalized.contains("denied") && !normalized.contains("allowed") {
        return Some(false);
    }
    if normalized.contains("allowed") && !normalized.contains("denied") {
        return Some(true);
    }
    None
}

fn validate_value_transfer_contract(
    program: &Program,
    target_ty: &SemaType,
    value: &Expr,
) -> Result<(), String> {
    let Some((op, _inner)) = direct_value_transfer_call(value) else {
        return Ok(());
    };
    let Some(info) = value_transfer_contract_info_for_type(program, target_ty) else {
        return Ok(());
    };

    match op {
        ValueTransferOp::Copy => {
            if let Some(items) = &info.copy_items {
                if matches!(
                    value_transfer_contract_decision(items, "shallow"),
                    Some(false)
                ) {
                    return Err(format!(
                        "E_TYPE_COPY_DENIED_001: copy 'shallow' denied by type contract '{}'",
                        info.name
                    ));
                }
            }
        }
        ValueTransferOp::Clone => {
            let Some(items) = &info.clone_items else {
                if info.has_pointer_field {
                    return Err(format!(
                        "E_TYPE_CLONE_001: clone requires explicit deep clone contract for pointer-owning type '{}'",
                        info.name
                    ));
                }
                return Ok(());
            };
            if matches!(value_transfer_contract_decision(items, "deep"), Some(false)) {
                return Err(format!(
                    "E_TYPE_CLONE_DENIED_001: clone 'deep' denied by type contract '{}'",
                    info.name
                ));
            }
            if info.has_pointer_field
                && !matches!(value_transfer_contract_decision(items, "deep"), Some(true))
                && !matches!(value_transfer_contract_decision(items, ""), Some(true))
            {
                return Err(format!(
                    "E_TYPE_CLONE_001: clone requires deep clone contract for pointer-owning type '{}'",
                    info.name
                ));
            }
        }
        ValueTransferOp::Move => {
            if let Some(items) = &info.move_items {
                if matches!(value_transfer_contract_decision(items, ""), Some(false)) {
                    return Err(format!(
                        "E_TYPE_MOVE_DENIED_001: move denied by type contract '{}' for value transfer",
                        info.name
                    ));
                }
            }
        }
    }

    Ok(())
}

fn resolve_fn_ref_path(
    program: &Program,
    current_container_name: &str,
    current_context: &Option<Context>,
    fn_path: &[String],
    local_functions: &[String],
    same_file_functions: &HashMap<String, Vec<String>>,
    imported_uses: &[UseDecl],
) -> Result<(), String> {
    if fn_path.is_empty() {
        return Err("empty function reference".into());
    }

    if fn_path.len() >= 2 && fn_path[0] == "root" {
        validate_root_direct_reference(program, current_context, fn_path)?;
        return resolve_root_fn_path(program, fn_path);
    }

    if fn_path.len() >= 2 {
        let module = &fn_path[..fn_path.len() - 1];
        if ncc_parser::runtime_api_source_module_is_implicit(module) {
            if !hosted_runtime_prelude_allowed_in_context(current_context) {
                return Err(format!(
                    "runtime module '{}' is unavailable in {}",
                    module.join("."),
                    context_label(current_container_name, current_context)
                ));
            }
            let function = fn_path.last().expect("qualified runtime function");
            if runtime_dynamic_function_signature(module, function).is_some() {
                return Ok(());
            }
            return Err(format!(
                "function '{}' not found in runtime module '{}'",
                function,
                module.join(".")
            ));
        }
    }

    if fn_path.len() == 1 {
        let name = &fn_path[0];
        let official_ref = as_at_reference(name);

        if local_functions.iter().any(|f| f == name) {
            return Ok(());
        }

        let mut same_file_matches = Vec::new();
        let mut same_file_visibility_blocked = Vec::new();
        let mut same_file_context_blocked: Vec<(String, Option<Context>)> = Vec::new();
        for (container_name, funcs) in same_file_functions {
            if container_name != current_container_name && funcs.iter().any(|f| f == name) {
                if let Some((visibility, target_ctx)) =
                    find_same_file_function(program, container_name, name)
                {
                    if let Some(visibility_err) = visibility_access_error(
                        &visibility,
                        "function",
                        name,
                        &official_ref,
                        current_context,
                        &target_ctx,
                    ) {
                        same_file_visibility_blocked.push(visibility_err);
                    } else if !context_compatible(current_context, &target_ctx) {
                        same_file_context_blocked.push((container_name.clone(), target_ctx));
                    } else {
                        same_file_matches.push(container_name.clone());
                    }
                }
            }
        }
        same_file_matches.sort();
        same_file_matches.dedup();
        same_file_visibility_blocked.sort();
        same_file_visibility_blocked.dedup();
        same_file_context_blocked.sort_by(|a, b| a.0.cmp(&b.0));
        same_file_context_blocked.dedup_by(|a, b| a.0 == b.0);

        let (imported_matches, imported_context_blocked) =
            imported_modules_visible_for_fn(imported_uses, name, current_context);

        let total = same_file_matches.len() + imported_matches.len();

        if total == 0 {
            if same_file_visibility_blocked.len() == 1 && same_file_context_blocked.is_empty() {
                return Err(same_file_visibility_blocked[0].clone());
            }

            if same_file_context_blocked.len() == 1 && same_file_visibility_blocked.is_empty() {
                let (container_name, target_ctx) = &same_file_context_blocked[0];
                return Err(format!(
                    "invalid context linking '{}' -> '{}' for reference '{}'; reference '{}' crosses forbidden authority boundary",
                    context_label(current_container_name, current_context),
                    context_label(container_name, target_ctx),
                    name,
                    official_ref
                ));
            }

            if imported_context_blocked.len() == 1
                && same_file_context_blocked.is_empty()
                && same_file_visibility_blocked.is_empty()
            {
                return validate_import_context_authority_for_reference(
                    current_container_name,
                    current_context,
                    &imported_context_blocked[0],
                    name,
                );
            }

            return Err(format!(
                "function '{}' not found; unresolved reference '{}'",
                name, official_ref
            ));
        }
        if total > 1 {
            return Err(format!(
                "ambiguous reference '{}': same-file candidates {}, import candidates {}; reference '{}' is ambiguous",
                name,
                render_candidate_list(&same_file_matches),
                render_candidate_list(&imported_matches),
                official_ref
            ));
        }

        if let Some(container_name) = same_file_matches.first() {
            let _ = container_name;
            return Ok(());
        }

        return Ok(());
    }

    if fn_path.len() == 2 {
        if is_data_motion_qualified_call(fn_path) {
            return Ok(());
        }
        let container_name = &fn_path[0];
        let func_name = &fn_path[1];

        if same_file_functions.contains_key(container_name) {
            resolve_same_file_qualified_target(
                program,
                current_container_name,
                current_context,
                container_name,
                func_name,
            )?;
            return Ok(());
        }

        let looks_like_same_file_container = !container_name.contains('.');
        if looks_like_same_file_container {
            return Err(format!("container '{}' not found", container_name));
        }
    }

    if fn_path.len() >= 2 {
        let func_name = fn_path.last().unwrap();
        let module_path = &fn_path[..fn_path.len() - 1];
        let official_ref = as_at_reference_path(fn_path);

        if !has_visible_import_for_module(imported_uses, module_path) {
            return Err(format!(
                "unresolved function path '{}'; unresolved reference '{}'",
                fn_path.join("."),
                official_ref
            ));
        }

        if let Some(exports) = import_exported_functions_any(module_path) {
            let wanted = func_name
                .split('<')
                .next()
                .unwrap_or(func_name)
                .trim()
                .to_ascii_lowercase();
            if exports.iter().any(|f| {
                f.eq_ignore_ascii_case(func_name)
                    || f.split('<')
                        .next()
                        .unwrap_or(f)
                        .trim()
                        .eq_ignore_ascii_case(&wanted)
            }) {
                validate_import_context_authority_for_qualified_call(
                    current_container_name,
                    current_context,
                    module_path,
                    &fn_path.join("."),
                )?;
                return Ok(());
            }
        }

        return Err(format!(
            "function '{}' not found in import '{}'; unresolved reference '{}'",
            func_name,
            module_path.join("."),
            official_ref
        ));
    }

    Err("empty function reference".into())
}

fn analyze_main_entry_kind(
    program: &Program,
    kind: &MainEntryKind,
    current_container_name: &str,
    current_context: &Option<Context>,
    local_functions: &[String],
    same_file_functions: &HashMap<String, Vec<String>>,
    imported_uses: &[UseDecl],
) -> Result<(), String> {
    fn main_return_contract_ok(return_ty: &SemaType) -> bool {
        match return_ty {
            SemaType::Simple(name) => {
                let normalized = normalize_type_name(name);
                normalized == "bool"
                    || normalized == "void"
                    || normalized == "none"
                    || normalized == "int"
                    || normalized.starts_with("int")
                    || normalized.starts_with("uint")
            }
            _ => false,
        }
    }

    fn resolve_main_target_signature(
        program: &Program,
        current_container_name: &str,
        current_context: &Option<Context>,
        fn_path: &[String],
        imported_uses: &[UseDecl],
    ) -> Result<Option<(usize, SemaType)>, String> {
        if fn_path.is_empty() {
            return Err("empty function reference".into());
        }

        if fn_path.len() == 1 {
            let fn_name = &fn_path[0];
            let container = program
                .containers
                .iter()
                .find(|c| c.name == current_container_name)
                .ok_or_else(|| format!("container '{}' not found", current_container_name))?;

            for section in &container.sections {
                if let Section::Fn(funcs) = section {
                    for f in funcs {
                        if &f.name == fn_name {
                            return Ok(Some((f.params.len(), lower_type(&f.return_type))));
                        }
                    }
                }
            }

            // The path is already resolved by `resolve_fn_ref_path`.
            // If it is not a local function, keep sema non-destructive and
            // let runtime enforce final callable contract at execution time.
            return Ok(None);
        }

        if fn_path.len() == 2 {
            let container_name = &fn_path[0];
            let func_name = &fn_path[1];
            if program
                .containers
                .iter()
                .any(|container| container.name == *container_name)
            {
                let (f, _ctx) = resolve_same_file_qualified_target(
                    program,
                    current_container_name,
                    current_context,
                    container_name,
                    func_name,
                )?;
                return Ok(Some((f.params.len(), lower_type(&f.return_type))));
            }
            return Ok(None);
        }

        let _ = imported_uses;
        // Imported and root-qualified callable contracts are validated at runtime.
        // This preserves linking fixtures that intentionally exercise broad import
        // visibility without forcing callable signature materialization in sema.
        Ok(None)
    }

    match kind {
        MainEntryKind::RefFn(fn_ref) | MainEntryKind::SkkFn(fn_ref) => {
            let kind_label = match kind {
                MainEntryKind::RefFn(_) => "ref main",
                MainEntryKind::SkkFn(_) => "skkMain",
                _ => "main",
            };

            resolve_fn_ref_path(
                program,
                current_container_name,
                current_context,
                &fn_ref.path,
                local_functions,
                same_file_functions,
                imported_uses,
            )?;

            if let Some((arity, return_ty)) = resolve_main_target_signature(
                program,
                current_container_name,
                current_context,
                &fn_ref.path,
                imported_uses,
            )? {
                if arity != 0 {
                    return Err(format!(
                        "entry target has invalid signature for {}: expected 0 params, got {} in '{}'",
                        kind_label,
                        arity,
                        fn_ref.path.join(".")
                    ));
                }

                if !main_return_contract_ok(&return_ty) {
                    return Err(format!(
                        "entry target has invalid return contract for {}: expected bool/int/void, got {} in '{}'",
                        kind_label,
                        render_sema_type(&return_ty),
                        fn_ref.path.join(".")
                    ));
                }
            }

            Ok(())
        }
        _ => Ok(()),
    }
}

fn analyze_stmt_linking(
    program: &Program,
    stmt: &Stmt,
    current_container_name: &str,
    current_context: &Option<Context>,
    local_functions: &[String],
    same_file_functions: &HashMap<String, Vec<String>>,
    imported_uses: &[UseDecl],
) -> Result<(), String> {
    match stmt {
        Stmt::MainRefFn { fn_ref, .. } => resolve_fn_ref_path(
            program,
            current_container_name,
            current_context,
            &fn_ref.path,
            local_functions,
            same_file_functions,
            imported_uses,
        ),
        Stmt::FunctionRelation { fn_ref, .. } => resolve_fn_ref_path(
            program,
            current_container_name,
            current_context,
            &fn_ref.path,
            local_functions,
            same_file_functions,
            imported_uses,
        ),
        Stmt::If {
            then_block,
            else_block,
            ..
        } => {
            for s in then_block {
                analyze_stmt_linking(
                    program,
                    s,
                    current_container_name,
                    current_context,
                    local_functions,
                    same_file_functions,
                    imported_uses,
                )?;
            }
            for s in else_block {
                analyze_stmt_linking(
                    program,
                    s,
                    current_container_name,
                    current_context,
                    local_functions,
                    same_file_functions,
                    imported_uses,
                )?;
            }
            Ok(())
        }
        Stmt::While { body, .. } => {
            for s in body {
                analyze_stmt_linking(
                    program,
                    s,
                    current_container_name,
                    current_context,
                    local_functions,
                    same_file_functions,
                    imported_uses,
                )?;
            }
            Ok(())
        }
        Stmt::DoWhile { body, .. }
        | Stmt::Loop { body }
        | Stmt::RepeatUntil { body, .. }
        | Stmt::RepeatCount { body, .. } => {
            for s in body {
                analyze_stmt_linking(
                    program,
                    s,
                    current_container_name,
                    current_context,
                    local_functions,
                    same_file_functions,
                    imported_uses,
                )?;
            }
            Ok(())
        }
        Stmt::ForClassic {
            init, step, body, ..
        } => {
            if let Some(init_stmt) = init {
                analyze_stmt_linking(
                    program,
                    init_stmt,
                    current_container_name,
                    current_context,
                    local_functions,
                    same_file_functions,
                    imported_uses,
                )?;
            }
            if let Some(step_stmt) = step {
                analyze_stmt_linking(
                    program,
                    step_stmt,
                    current_container_name,
                    current_context,
                    local_functions,
                    same_file_functions,
                    imported_uses,
                )?;
            }
            for s in body {
                analyze_stmt_linking(
                    program,
                    s,
                    current_container_name,
                    current_context,
                    local_functions,
                    same_file_functions,
                    imported_uses,
                )?;
            }
            Ok(())
        }
        Stmt::ForIn { body, .. }
        | Stmt::SameIn { body, .. }
        | Stmt::ForRange { body, .. }
        | Stmt::EachDoWhile { body, .. } => {
            for s in body {
                analyze_stmt_linking(
                    program,
                    s,
                    current_container_name,
                    current_context,
                    local_functions,
                    same_file_functions,
                    imported_uses,
                )?;
            }
            Ok(())
        }
        Stmt::Switch { cases, default, .. } | Stmt::Match { cases, default, .. } => {
            for (_, block) in cases {
                for s in block {
                    analyze_stmt_linking(
                        program,
                        s,
                        current_container_name,
                        current_context,
                        local_functions,
                        same_file_functions,
                        imported_uses,
                    )?;
                }
            }
            for s in default {
                analyze_stmt_linking(
                    program,
                    s,
                    current_container_name,
                    current_context,
                    local_functions,
                    same_file_functions,
                    imported_uses,
                )?;
            }
            Ok(())
        }
        Stmt::PatternMatch { arms, .. } => {
            for arm in arms {
                for s in &arm.body {
                    analyze_stmt_linking(
                        program,
                        s,
                        current_container_name,
                        current_context,
                        local_functions,
                        same_file_functions,
                        imported_uses,
                    )?;
                }
            }
            Ok(())
        }
        Stmt::GuardElse { else_block, .. } => {
            for s in else_block {
                analyze_stmt_linking(
                    program,
                    s,
                    current_container_name,
                    current_context,
                    local_functions,
                    same_file_functions,
                    imported_uses,
                )?;
            }
            Ok(())
        }
        Stmt::Select { branches, default } => {
            for (_, block) in branches {
                for s in block {
                    analyze_stmt_linking(
                        program,
                        s,
                        current_container_name,
                        current_context,
                        local_functions,
                        same_file_functions,
                        imported_uses,
                    )?;
                }
            }
            for s in default {
                analyze_stmt_linking(
                    program,
                    s,
                    current_container_name,
                    current_context,
                    local_functions,
                    same_file_functions,
                    imported_uses,
                )?;
            }
            Ok(())
        }
        Stmt::Labeled { stmt, .. } => analyze_stmt_linking(
            program,
            stmt,
            current_container_name,
            current_context,
            local_functions,
            same_file_functions,
            imported_uses,
        ),
        Stmt::Break { .. } | Stmt::Continue { .. } => Ok(()),
        _ => Ok(()),
    }
}

fn fn_path_may_use_import(path: &[String]) -> bool {
    path.len() >= 3 && !path[0].eq_ignore_ascii_case("root")
}

fn expr_may_use_import(expr: &Expr) -> bool {
    match expr {
        Expr::Index { target, index } => expr_may_use_import(target) || expr_may_use_import(index),
        Expr::ArrayLiteral(items) | Expr::VectorLiteral(items) => {
            items.iter().any(expr_may_use_import)
        }
        Expr::MethodCall { receiver, args, .. } => {
            expr_may_use_import(receiver) || args.iter().any(expr_may_use_import)
        }
        Expr::QualifiedCall { path, args } => {
            fn_path_may_use_import(path) || args.iter().any(expr_may_use_import)
        }
        Expr::StrictCheckExpr { value, .. } => expr_may_use_import(value),
        Expr::Unary { expr, .. } => expr_may_use_import(expr),
        Expr::Binary { left, right, .. } => expr_may_use_import(left) || expr_may_use_import(right),
        Expr::IfElse {
            condition,
            then_expr,
            else_expr,
        } => {
            expr_may_use_import(condition)
                || expr_may_use_import(then_expr)
                || expr_may_use_import(else_expr)
        }
        Expr::Call { .. } => true,
        _ => false,
    }
}

fn stmt_may_use_import(stmt: &Stmt) -> bool {
    match stmt {
        Stmt::Return(expr) => expr_may_use_import(expr),
        Stmt::Projection { value, .. } | Stmt::StrictCheck { value, .. } => {
            expr_may_use_import(value)
        }
        Stmt::If {
            condition,
            then_block,
            else_block,
        } => {
            expr_may_use_import(condition)
                || then_block.iter().any(stmt_may_use_import)
                || else_block.iter().any(stmt_may_use_import)
        }
        Stmt::Unless { condition, body } => {
            expr_may_use_import(condition) || body.iter().any(stmt_may_use_import)
        }
        Stmt::While { condition, body } => {
            expr_may_use_import(condition) || body.iter().any(stmt_may_use_import)
        }
        Stmt::DoWhile { condition, body } => {
            expr_may_use_import(condition) || body.iter().any(stmt_may_use_import)
        }
        Stmt::ForClassic {
            init,
            condition,
            step,
            body,
        } => {
            init.as_deref().map(stmt_may_use_import).unwrap_or(false)
                || condition.as_ref().map(expr_may_use_import).unwrap_or(false)
                || step.as_deref().map(stmt_may_use_import).unwrap_or(false)
                || body.iter().any(stmt_may_use_import)
        }
        Stmt::ForIn { iterable, body, .. } | Stmt::SameIn { iterable, body, .. } => {
            expr_may_use_import(iterable) || body.iter().any(stmt_may_use_import)
        }
        Stmt::ForRange {
            start,
            end,
            step,
            body,
            ..
        } => {
            expr_may_use_import(start)
                || expr_may_use_import(end)
                || step.as_ref().map(expr_may_use_import).unwrap_or(false)
                || body.iter().any(stmt_may_use_import)
        }
        Stmt::Loop { body } => body.iter().any(stmt_may_use_import),
        Stmt::RepeatUntil { body, condition } => {
            body.iter().any(stmt_may_use_import) || expr_may_use_import(condition)
        }
        Stmt::RepeatCount { count, body } => {
            expr_may_use_import(count) || body.iter().any(stmt_may_use_import)
        }
        Stmt::EachDoWhile {
            iterable,
            body,
            condition,
            ..
        } => {
            expr_may_use_import(iterable)
                || body.iter().any(stmt_may_use_import)
                || expr_may_use_import(condition)
        }
        Stmt::Switch {
            value,
            cases,
            default,
        }
        | Stmt::Match {
            value,
            cases,
            default,
        } => {
            expr_may_use_import(value)
                || cases.iter().any(|(case_expr, block)| {
                    expr_may_use_import(case_expr) || block.iter().any(stmt_may_use_import)
                })
                || default.iter().any(stmt_may_use_import)
        }
        Stmt::PatternMatch { value, arms } => {
            expr_may_use_import(value)
                || arms.iter().any(|arm| {
                    let pattern_uses = match &arm.pattern {
                        Pattern::Literal(expr) => expr_may_use_import(expr),
                        _ => false,
                    };
                    let guard_uses = arm.guard.as_ref().is_some_and(expr_may_use_import);
                    pattern_uses || guard_uses || arm.body.iter().any(stmt_may_use_import)
                })
        }
        Stmt::GuardElse {
            condition,
            else_block,
        } => expr_may_use_import(condition) || else_block.iter().any(stmt_may_use_import),
        Stmt::Select { branches, default } => {
            branches.iter().any(|(cond, block)| {
                expr_may_use_import(cond) || block.iter().any(stmt_may_use_import)
            }) || default.iter().any(stmt_may_use_import)
        }
        Stmt::Labeled { stmt, .. } => stmt_may_use_import(stmt),
        Stmt::Defer { body } => body.iter().any(stmt_may_use_import),
        Stmt::Break { .. } | Stmt::Continue { .. } => false,
        Stmt::MainRefFn { fn_ref, .. } | Stmt::FunctionRelation { fn_ref, .. } => {
            fn_path_may_use_import(&fn_ref.path)
        }
        Stmt::Print { value, .. } | Stmt::Expr(value) => expr_may_use_import(value),
        Stmt::Destructure { kind, args } => {
            let expr = destructure_stmt_as_call_expr(*kind, args);
            expr_may_use_import(&expr)
        }
        Stmt::Constructure { kind, args } => {
            let expr = constructure_stmt_as_call_expr(*kind, args);
            expr_may_use_import(&expr)
        }
        Stmt::Dev(_) => false,
    }
}

fn container_may_use_imports(container: &ncc_parser::Container) -> bool {
    for section in &container.sections {
        match section {
            Section::Stc(decls) => {
                for decl in decls {
                    let StcDecl::Typed { init, .. } = decl;
                    if init.as_ref().map(expr_may_use_import).unwrap_or(false) {
                        return true;
                    }
                }
            }
            Section::Binary(stmts)
            | Section::Probe(stmts)
            | Section::Structure(stmts)
            | Section::Final(stmts)
            | Section::Bind(stmts)
            | Section::Raw(stmts)
                if stmts.iter().any(stmt_may_use_import) =>
            {
                return true;
            }
            Section::Fn(items) | Section::MoveFn(items) => {
                for f in items {
                    if f.public_body.iter().any(stmt_may_use_import) {
                        return true;
                    }
                }
            }
            Section::MainEntry { body, .. } if body.iter().any(stmt_may_use_import) => {
                return true;
            }
            _ => {}
        }
    }
    false
}

fn is_trivial_final_sentinel(section: &Section) -> bool {
    match section {
        Section::Final(stmts) => matches!(stmts.as_slice(), [Stmt::Return(Expr::Bool(true))]),
        _ => false,
    }
}

fn destructure_kind_to_legacy_callee(kind: DestructureKind) -> &'static str {
    match kind {
        DestructureKind::Default => "destructure",
        DestructureKind::Static => "destructureStatic",
        DestructureKind::Move => "destructureMove",
        DestructureKind::Ref => "destructureRef",
        DestructureKind::Region => "destructureRegion",
        DestructureKind::Binary => "destructureBinary",
        DestructureKind::Result => "destructureResult",
        DestructureKind::Ownership => "destructureOwnership",
    }
}

fn constructure_kind_to_legacy_callee(kind: ConstructureKind) -> &'static str {
    match kind {
        ConstructureKind::Default => "constructure",
        ConstructureKind::Static => "constructureStatic",
        ConstructureKind::Move => "constructureMove",
        ConstructureKind::Copy => "constructureCopy",
        ConstructureKind::Region => "constructureRegion",
        ConstructureKind::Binary => "constructureBinary",
        ConstructureKind::Unbinary => "constructureUnbinary",
    }
}

fn destructure_stmt_as_call_expr(kind: DestructureKind, args: &[Expr]) -> Expr {
    Expr::Call {
        callee: destructure_kind_to_legacy_callee(kind).to_string(),
        args: args.to_vec(),
    }
}

fn constructure_stmt_as_call_expr(kind: ConstructureKind, args: &[Expr]) -> Expr {
    Expr::Call {
        callee: constructure_kind_to_legacy_callee(kind).to_string(),
        args: args.to_vec(),
    }
}

fn type_name_is_binary_stable(ty: &TypeName) -> bool {
    match ty {
        TypeName::Simple(name) => matches!(
            name.as_str(),
            "int" | "u64" | "byte" | "bool" | "char" | "word" | "dword" | "qword" | "ft64" | "addr"
        ),
        TypeName::Array(inner) => type_name_is_binary_stable(inner),
        TypeName::Union(items) => items.iter().all(type_name_is_binary_stable),
        TypeName::Vector(inner) => type_name_is_binary_stable(inner),
        TypeName::Generic { base, args } => match base.as_str() {
            "array" => args.first().is_some_and(type_name_is_binary_stable),
            "dinArray.binary" => args.first().is_some_and(type_name_is_binary_stable),
            "ptr" => true,
            "list" | "dinArray.unbinary" | "text" => false,
            _ => false,
        },
    }
}

fn type_contract_builtin_type(name: &str) -> bool {
    ncc_stage0_bridge::integer_class(name, 64) != 0
        || matches!(
        name,
        "int"
            | "u64"
            | "byte"
            | "word"
            | "dword"
            | "qword"
            | "bool"
            | "str"
            | "text"
            | "char"
            | "ft64"
            | "addr"
            | "isize"
            | "usize"
            | "void"
            | "null"
            | "cpu"
            | "mmio"
            | "physical"
            | "phys"
            | "dma"
            | "iommu"
            | "iova"
            | "gpu"
            | "device"
            | "firmware"
            | "fw"
            | "target"
            | "native"
    )
}

fn type_name_is_known_for_contract(
    ty: &TypeName,
    contract_names: &HashSet<String>,
    contract_generic_arity: &HashMap<String, usize>,
    generic_params: &HashSet<String>,
) -> Result<(), String> {
    match ty {
        TypeName::Simple(name) => {
            if name.chars().all(|c| c.is_ascii_digit())
                || type_contract_builtin_type(name)
                || generic_params.contains(name)
                || contract_names.contains(&name.to_ascii_lowercase())
            {
                Ok(())
            } else {
                Err("E_TYPE_FIELD_001: invalid or unknown type field".into())
            }
        }
        TypeName::Array(inner) | TypeName::Vector(inner) => type_name_is_known_for_contract(
            inner,
            contract_names,
            contract_generic_arity,
            generic_params,
        ),
        TypeName::Union(items) => {
            for item in items {
                type_name_is_known_for_contract(
                    item,
                    contract_names,
                    contract_generic_arity,
                    generic_params,
                )?;
            }
            Ok(())
        }
        TypeName::Generic { base, args } => {
            let base_ok = matches!(
                base.as_str(),
                "array"
                    | "array2"
                    | "array3"
                    | "xy"
                    | "xyz"
                    | "x2y2"
                    | "x2y2z2"
                    | "x3y3"
                    | "x3y3z3"
                    | "matrix"
                    | "tensor"
                    | "ptr"
                    | "ptr mut"
                    | "cap"
                    | "member"
                    | "pm"
                    | "fn"
                    | "memRegion"
                    | "list"
                    | "Result"
                    | "Option"
                    | "dinArray"
                    | "dinArray.binary"
                    | "dinArray.unbinary"
            ) || contract_names.contains(&base.to_ascii_lowercase());
            if !base_ok {
                return Err("E_TYPE_FIELD_001: invalid or unknown type field".into());
            }

            if let Some(expected_arity) = contract_generic_arity.get(&base.to_ascii_lowercase()) {
                if args.len() != *expected_arity {
                    return Err("E_TYPE_GENERIC_ARITY_001: invalid type generic arity".into());
                }
            }

            for arg in args {
                type_name_is_known_for_contract(
                    arg,
                    contract_names,
                    contract_generic_arity,
                    generic_params,
                )?;
            }
            Ok(())
        }
    }
}

fn high_generic_builtin_type(name: &str) -> bool {
    matches!(
        name,
        "int"
            | "uint"
            | "short"
            | "long"
            | "byte"
            | "word"
            | "dword"
            | "qword"
            | "sbyte"
            | "sword"
            | "sdword"
            | "sqword"
            | "i8"
            | "i16"
            | "i32"
            | "i64"
            | "u8"
            | "u16"
            | "u32"
            | "u64"
            | "int8"
            | "int16"
            | "int32"
            | "int64"
            | "uint8"
            | "uint16"
            | "uint32"
            | "uint64"
            | "bool"
            | "str"
            | "text"
            | "char"
            | "ft"
            | "ft32"
            | "ft64"
            | "addr"
            | "void"
            | "null"
    )
}

fn high_generic_known_base(name: &str, contract_names: &HashSet<String>) -> bool {
    matches!(
        name,
        "array"
            | "vector"
            | "ptr"
            | "memRegion"
            | "list"
            | "arrayList"
            | "linkedList"
            | "queue"
            | "stack"
            | "deque"
            | "priorityList"
            | "ringList"
            | "safeList"
            | "rawList"
            | "jumpList"
            | "indexList"
            | "traceList"
            | "cacheList"
            | "branchList"
            | "flowList"
            | "packetList"
            | "routeList"
            | "nodeList"
            | "chainList"
            | "watchList"
            | "dbList"
            | "memList"
            | "Result"
            | "Option"
            | "Iterator"
            | "Iterable"
            | "IntoIterator"
            | "Collection"
            | "Future"
            | "Task"
            | "channel"
            | "Mutex"
            | "Atomic"
            | "fn"
            | "dinArray"
            | "dinArray.binary"
            | "dinArray.unbinary"
    ) || contract_names.contains(&name.to_ascii_lowercase())
}

fn validate_associated_type_projection_decl(
    raw: &str,
    params: &HashSet<String>,
    bounds: &[GenericBound],
) -> Result<(), String> {
    let Some((param, item)) = raw.split_once('.') else {
        return Ok(());
    };
    if !params.contains(param) {
        return Err(format!(
            "E_HIGH_ASSOC_TYPE_PROJECTION_001: associated type projection '{}' does not start with a declared generic parameter",
            raw
        ));
    }
    let surfaces = HIGH_SURFACES.with(|cell| cell.borrow().clone());
    let matches = bounds
        .iter()
        .filter(|bound| bound.param == param)
        .filter_map(|bound| type_name_base(&bound.bound))
        .filter_map(|surface_name| surfaces.get(&surface_name.to_ascii_lowercase()))
        .filter(|surface| surface.associated_types.iter().any(|name| name == item))
        .count();
    if matches == 0 {
        return Err(format!(
            "E_HIGH_ASSOC_TYPE_UNKNOWN_001: associated type projection '{}' is not declared by any bound",
            raw
        ));
    }
    if matches > 1 {
        return Err(format!(
            "E_HIGH_ASSOC_TYPE_AMBIGUOUS_001: associated type projection '{}' is ambiguous",
            raw
        ));
    }
    Ok(())
}

fn validate_dyn_type_name(
    ty: &TypeName,
    params: &HashSet<String>,
    bounds: &[GenericBound],
    dyn_in_storage: bool,
) -> Result<(), String> {
    let TypeName::Generic { base, args } = ty else {
        return Ok(());
    };
    if !base.eq_ignore_ascii_case("dyn") {
        return Ok(());
    }
    if dyn_in_storage {
        return Err(
            "E_HIGH_DYN_UNSIZED_PLACEMENT_001: trait objects are unsized and cannot be stored directly"
                .into(),
        );
    }
    if args.len() != 1 {
        return Err("E_HIGH_TRAIT_OBJECT_PARSE_001: dyn expects exactly one trait".into());
    }
    let surface_ref = &args[0];
    if type_name_contains_any(surface_ref) {
        return Err("E_HIGH_ANY_LEAK_001: any leak through dyn is forbidden".into());
    }
    let Some(surface_name) = type_name_base(surface_ref) else {
        return Err("E_HIGH_DYN_PARSE_001: dyn must name a trait/interface".into());
    };
    if high_generic_builtin_type(surface_name) {
        return Err(format!(
            "E_HIGH_DYN_NON_TRAIT_001: '{}' is not a trait/interface",
            surface_name
        ));
    }
    let surfaces = HIGH_SURFACES.with(|cell| cell.borrow().clone());
    let Some(surface) = surfaces.get(&surface_name.to_ascii_lowercase()) else {
        return Err(format!(
            "E_HIGH_DYN_TRAIT_UNKNOWN_001: unknown trait/interface '{}'",
            surface_name
        ));
    };
    let type_args = type_name_args(surface_ref);
    if type_args.len() != surface.generic_params.len() {
        return Err(format!(
            "E_HIGH_TRAIT_OBJECT_PARSE_001: dyn '{}' expects {} type arguments, got {}",
            surface.name,
            surface.generic_params.len(),
            type_args.len()
        ));
    }
    if !surface.associated_types.is_empty() {
        return Err(format!(
            "E_HIGH_DYN_OBJECT_SAFETY_001: trait '{}' has associated types and is not object-safe in Phase 5",
            surface.name
        ));
    }
    if surface.methods.is_empty() {
        return Err(format!(
            "E_HIGH_DYN_OBJECT_SAFETY_001: trait '{}' has no dispatchable methods",
            surface.name
        ));
    }
    if !surface.generic_default_methods.is_empty() {
        return Err(format!(
            "E_HIGH_DYN_GENERIC_METHOD_001: trait '{}' has generic default methods and is not object-safe",
            surface.name
        ));
    }
    for arg in type_args {
        validate_high_generic_type_name(arg, params, bounds, &HashSet::new(), &HashMap::new())?;
    }
    Ok(())
}

fn type_name_contains_any(ty: &TypeName) -> bool {
    match ty {
        TypeName::Simple(name) => name.eq_ignore_ascii_case("any"),
        TypeName::Array(inner) | TypeName::Vector(inner) => type_name_contains_any(inner),
        TypeName::Union(items) => items.iter().any(type_name_contains_any),
        TypeName::Generic { args, .. } => args.iter().any(type_name_contains_any),
    }
}

fn validate_high_generic_type_name(
    ty: &TypeName,
    params: &HashSet<String>,
    bounds: &[GenericBound],
    contract_names: &HashSet<String>,
    contract_generic_arity: &HashMap<String, usize>,
) -> Result<(), String> {
    if let Some((contract, value_type)) = split_storage_contract(ty) {
        contract.validate(false, false)?;
        return validate_high_generic_type_name(
            value_type,
            params,
            bounds,
            contract_names,
            contract_generic_arity,
        );
    }
    match ty {
        TypeName::Simple(name) => {
            if name.contains('.') {
                return validate_associated_type_projection_decl(name, params, bounds);
            }
            if name.chars().all(|ch| ch.is_ascii_digit())
                || params.contains(name)
                || high_generic_builtin_type(name)
                || contract_names.contains(&name.to_ascii_lowercase())
            {
                return Ok(());
            }
            if name.eq_ignore_ascii_case("any") {
                return Err("E_HIGH_GENERIC_ANY_LEAK_001: generic any leak is forbidden".into());
            }
            if runtime_generic_param_name(name) {
                return Err(format!(
                    "E_HIGH_GENERIC_UNKNOWN_PARAM_001: generic parameter '{}' is not declared",
                    name
                ));
            }
            Ok(())
        }
        TypeName::Array(inner) | TypeName::Vector(inner) => validate_high_generic_type_name(
            inner,
            params,
            bounds,
            contract_names,
            contract_generic_arity,
        ),
        TypeName::Union(items) => {
            for item in items {
                validate_high_generic_type_name(
                    item,
                    params,
                    bounds,
                    contract_names,
                    contract_generic_arity,
                )?;
            }
            Ok(())
        }
        TypeName::Generic { base, args } => {
            if base.eq_ignore_ascii_case("dyn") {
                return validate_dyn_type_name(ty, params, bounds, false);
            }
            if params.contains(base) {
                return Err(
                    "E_HIGH_GENERIC_HKT_DEFERRED_001: higher-kinded generic parameters are deferred"
                        .into(),
                );
            }
            if !high_generic_known_base(base, contract_names) {
                if runtime_generic_param_name(base) {
                    return Err(
                        "E_HIGH_GENERIC_HKT_DEFERRED_001: higher-kinded generic parameters are deferred"
                            .into(),
                    );
                }
                return Err(format!(
                    "E_HIGH_GENERIC_UNKNOWN_BASE_001: generic type base '{}' is not known",
                    base
                ));
            }
            if let Some(expected_arity) = contract_generic_arity.get(&base.to_ascii_lowercase()) {
                if args.len() != *expected_arity {
                    return Err(format!(
                        "E_HIGH_GENERIC_ARITY_001: generic type '{}' expects {} arguments, got {}",
                        base,
                        expected_arity,
                        args.len()
                    ));
                }
            }
            for arg in args {
                validate_high_generic_type_name(
                    arg,
                    params,
                    bounds,
                    contract_names,
                    contract_generic_arity,
                )?;
            }
            Ok(())
        }
    }
}

fn collect_type_contract_metadata(program: &Program) -> (HashSet<String>, HashMap<String, usize>) {
    let mut contract_names = HashSet::new();
    let mut contract_generic_arity = HashMap::new();
    for container in &program.containers {
        for section in &container.sections {
            if let Section::TypeContracts(contracts) = section {
                for contract in contracts {
                    contract_names.insert(contract.name.to_ascii_lowercase());
                    contract_generic_arity.insert(
                        contract.name.to_ascii_lowercase(),
                        contract.generic_params.len(),
                    );
                }
            }
        }
    }
    (contract_names, contract_generic_arity)
}

fn validate_high_contract_expr(
    program: &Program,
    current_container_name: &str,
    expr: &Expr,
    const_functions: &HashMap<String, ConstFunction>,
) -> Result<(), String> {
    let mut ctx = phase13_new_const_context(const_functions.clone());
    match phase13_const_eval_expr(program, current_container_name, expr, &mut ctx) {
        Ok(ConstValue::Bool(true)) => Ok(()),
        Ok(ConstValue::Bool(false)) => {
            Err("E_HIGH_CONTRACT_REQUIRE_FAIL_001: contract requirement is false".into())
        }
        Ok(_) => Err(
            "E_HIGH_CONTRACT_REQUIRE_UNVERIFIABLE_001: contract requirement must evaluate to bool"
                .into(),
        ),
        Err(reason) => Err(format!(
            "E_HIGH_CONTRACT_REQUIRE_UNVERIFIABLE_001: contract expression is not statically verifiable: {reason}"
        )),
    }
}

fn validate_high_contracts(program: &Program) -> Result<(), String> {
    let surfaces = HIGH_SURFACES.with(|cell| cell.borrow().clone());
    let const_functions = phase13_collect_const_functions(program)?;
    let mut names = HashSet::new();
    for container in &program.containers {
        for section in &container.sections {
            let Section::Contracts(contracts) = section else {
                continue;
            };
            for contract in contracts {
                if !names.insert(contract.name.to_ascii_lowercase()) {
                    return Err(format!(
                        "E_HIGH_CONTRACT_DUP_001: duplicate contract '{}'",
                        contract.name
                    ));
                }
                let mut seen_params = HashSet::new();
                for param in &contract.generic_params {
                    if !seen_params.insert(param.clone()) {
                        return Err(format!(
                            "E_HIGH_CONTRACT_BOUND_001: duplicate contract type parameter '{}'",
                            param
                        ));
                    }
                }
                for bound in &contract.bounds {
                    validate_high_bound_decl(bound, &seen_params, &surfaces)?;
                }
                for require in &contract.requires {
                    validate_high_contract_expr(
                        program,
                        &container.name,
                        require,
                        &const_functions,
                    )?;
                }
                if !contract.ensures.is_empty() {
                    return Err(
                        "E_HIGH_CONTRACT_ENSURE_DEFERRED_001: ensure clauses are deferred past Phase 4"
                            .into(),
                    );
                }
                if !contract.invariants.is_empty() {
                    return Err(
                        "E_HIGH_CONTRACT_INVARIANT_DEFERRED_001: invariant clauses are deferred past Phase 4"
                            .into(),
                    );
                }
            }
        }
    }
    Ok(())
}

fn validate_high_generic_functions(program: &Program) -> Result<(), String> {
    let (contract_names, contract_generic_arity) = collect_type_contract_metadata(program);
    let surfaces = HIGH_SURFACES.with(|cell| cell.borrow().clone());
    for container in &program.containers {
        for section in &container.sections {
            let Section::Fn(functions) = section else {
                continue;
            };
            for function in functions {
                let mut seen = HashSet::new();
                for param in &function.generic_params {
                    if !seen.insert(param.clone()) {
                        return Err(format!(
                            "E_HIGH_GENERIC_DUP_PARAM_001: duplicate generic parameter '{}'",
                            param
                        ));
                    }
                }
                if function.generic_params.is_empty() {
                    continue;
                }
                let params: HashSet<String> = function.generic_params.iter().cloned().collect();
                for param in &function.params {
                    validate_high_generic_type_name(
                        &param.ty,
                        &params,
                        &function.generic_bounds,
                        &contract_names,
                        &contract_generic_arity,
                    )?;
                }
                validate_high_generic_type_name(
                    &function.return_type,
                    &params,
                    &function.generic_bounds,
                    &contract_names,
                    &contract_generic_arity,
                )?;
                for bound in &function.generic_bounds {
                    validate_high_bound_decl(bound, &params, &surfaces)?;
                }
            }
        }
    }
    Ok(())
}

fn validate_high_phase5_value_type(
    ty: &TypeName,
    params: &HashSet<String>,
    bounds: &[GenericBound],
    dyn_in_storage: bool,
) -> Result<(), String> {
    match ty {
        TypeName::Simple(name) => {
            if name.contains('.') && params.contains(name.split('.').next().unwrap_or_default()) {
                return validate_associated_type_projection_decl(name, params, bounds);
            }
            Ok(())
        }
        TypeName::Array(inner) | TypeName::Vector(inner) => {
            validate_high_phase5_value_type(inner, params, bounds, dyn_in_storage)
        }
        TypeName::Union(items) => {
            for item in items {
                validate_high_phase5_value_type(item, params, bounds, dyn_in_storage)?;
            }
            Ok(())
        }
        TypeName::Generic { base, args: _ } if base.eq_ignore_ascii_case("dyn") => {
            validate_dyn_type_name(ty, params, bounds, dyn_in_storage)
        }
        TypeName::Generic { base, args } => {
            let surfaces = HIGH_SURFACES.with(|cell| cell.borrow().clone());
            if surfaces.contains_key(&base.to_ascii_lowercase()) {
                return Err(format!(
                    "E_HIGH_DYN_IMPLICIT_001: trait/interface '{}' in value position requires explicit dyn",
                    base
                ));
            }
            for arg in args {
                validate_high_phase5_value_type(arg, params, bounds, dyn_in_storage)?;
            }
            Ok(())
        }
    }
}

fn validate_high_phase5_surface(program: &Program) -> Result<(), String> {
    for container in &program.containers {
        if matches!(
            container.context,
            Some(Context::Machine | Context::Primitive | Context::Runtime)
        ) {
            continue;
        }
        for section in &container.sections {
            match section {
                Section::Stc(decls) => {
                    for decl in decls {
                        let StcDecl::Typed { ty, .. } = decl;
                        validate_high_phase5_value_type(ty, &HashSet::new(), &[], true)?;
                    }
                }
                Section::Fn(functions) | Section::MoveFn(functions) => {
                    for function in functions {
                        let params: HashSet<String> =
                            function.generic_params.iter().cloned().collect();
                        for param in &function.params {
                            validate_high_phase5_value_type(
                                &param.ty,
                                &params,
                                &function.generic_bounds,
                                false,
                            )?;
                        }
                        validate_high_phase5_value_type(
                            &function.return_type,
                            &params,
                            &function.generic_bounds,
                            false,
                        )?;
                    }
                }
                Section::Traits(traits) => {
                    for trait_decl in traits {
                        let params: HashSet<String> =
                            trait_decl.generic_params.iter().cloned().collect();
                        for method in &trait_decl.required_methods {
                            for param in &method.params {
                                validate_high_phase5_value_type(&param.ty, &params, &[], false)?;
                            }
                            validate_high_phase5_value_type(
                                &method.return_type,
                                &params,
                                &[],
                                false,
                            )?;
                        }
                    }
                }
                _ => {}
            }
        }
    }
    Ok(())
}

fn parse_keyed_contract_value(item: &str, key: &str) -> Option<String> {
    for segment in item.split(';') {
        let Some((lhs, rhs)) = segment.split_once(':') else {
            continue;
        };
        if lhs.trim().eq_ignore_ascii_case(key) {
            let value = rhs
                .trim()
                .split(|c: char| c.is_whitespace() || c == ',' || c == '}')
                .next()
                .unwrap_or_default()
                .trim();
            if value.is_empty() {
                return None;
            }
            return Some(value.to_string());
        }
    }
    None
}

fn extract_destructure_field_names(item: &str) -> Vec<String> {
    let Some(open) = item.find('{') else {
        return Vec::new();
    };
    let Some(close) = item[open + 1..].find('}') else {
        return Vec::new();
    };
    let body = &item[open + 1..open + 1 + close];
    body.split(',')
        .map(str::trim)
        .filter(|name| !name.is_empty())
        .map(|name| name.to_string())
        .collect()
}

fn contract_items_joined(items: &[String]) -> String {
    items.join(" ").to_ascii_lowercase()
}

fn sema_binary_layout_field_input(field: &TypeContractField) -> Option<BinaryLayoutFieldInput> {
    fn shape(ty: &TypeName) -> Option<(usize, usize, Option<u16>)> {
        match ty {
            TypeName::Simple(name) => {
                let scalar = scalar_type_contract(name, 8)?;
                let integer_bits = matches!(
                    scalar.class,
                    ScalarTypeClass::SignedInteger | ScalarTypeClass::UnsignedInteger
                )
                .then_some(scalar.bit_width)
                .flatten();
                Some((scalar.size_bytes, scalar.align_bytes, integer_bits))
            }
            TypeName::Array(inner) => {
                let (size, align, _) = shape(inner)?;
                Some((size, align, None))
            }
            TypeName::Generic { base, args } if base.eq_ignore_ascii_case("ptr") => {
                Some((8, 8, None))
            }
            TypeName::Generic { base, args }
                if base.eq_ignore_ascii_case("array") && args.len() == 2 =>
            {
                let (element_size, element_align, _) = shape(&args[0])?;
                let TypeName::Simple(length) = &args[1] else {
                    return None;
                };
                let length = length.parse::<usize>().ok()?;
                Some((element_size.saturating_mul(length), element_align, None))
            }
            _ => None,
        }
    }

    let (size_bytes, align_bytes, integer_bits) = shape(&field.ty)?;
    Some(BinaryLayoutFieldInput {
        name: field.name.clone(),
        size_bytes,
        align_bytes,
        integer_bits,
    })
}

fn validate_structured_binary_layout(
    contract: &TypeContractDecl,
    layout: &BinaryLayoutContract,
    fields: &[&TypeContractField],
) -> Result<(), String> {
    if !layout.explicit {
        return Ok(());
    }
    if matches!(
        contract.kind,
        TypeContractKind::Enum | TypeContractKind::TaggedUnion
    ) && (!layout.bitfields.is_empty() || layout.flexible_field.is_some())
    {
        return Err(
            "E_LAYOUT_UNION_001: enum/tagged-union layouts cannot declare struct bitfields or flexible members"
                .into(),
        );
    }
    let names = fields
        .iter()
        .map(|field| field.name.as_str())
        .collect::<HashSet<_>>();
    if let Some(flexible) = &layout.flexible_field {
        if !names.contains(flexible.as_str()) {
            return Err(format!(
                "E_LAYOUT_FLEXIBLE_ARRAY_001: unknown flexible member '{}'",
                flexible
            ));
        }
        let field = fields
            .iter()
            .find(|field| field.name == *flexible)
            .expect("the flexible member name was validated above");
        if fields.last().map(|field| field.name.as_str()) != Some(flexible.as_str()) {
            return Err(
                "E_LAYOUT_FLEXIBLE_ARRAY_001: a flexible array member must be the final field"
                    .into(),
            );
        }
        let is_unsized_array = match &field.ty {
            TypeName::Array(_) => true,
            TypeName::Generic { base, args } if base.eq_ignore_ascii_case("array") => {
                args.len() == 1
                    || (args.len() == 2
                        && matches!(&args[1], TypeName::Simple(size) if size == "0"))
            }
            _ => false,
        };
        if !is_unsized_array {
            return Err(format!(
                "E_LAYOUT_FLEXIBLE_ARRAY_001: flexible member '{}' must use array<T> or array<T, 0>",
                flexible
            ));
        }
    }
    for bitfield in &layout.bitfields {
        if !names.contains(bitfield.field.as_str()) || !names.contains(bitfield.storage.as_str()) {
            return Err(format!(
                "E_LAYOUT_BITFIELD_001: bitfield '{}' or storage '{}' is not declared",
                bitfield.field, bitfield.storage
            ));
        }
    }
    let inputs = fields
        .iter()
        .map(|field| sema_binary_layout_field_input(field))
        .collect::<Option<Vec<_>>>();
    if let Some(inputs) = inputs {
        compute_binary_layout(contract.kind, layout, &inputs)?;
    }
    Ok(())
}

#[derive(Debug, Clone)]
struct SemaComputedLayout {
    size_bytes: usize,
    align_bytes: usize,
    fields: HashMap<String, usize>,
}

fn sema_find_type_contract<'a>(
    program: &'a Program,
    current_container: &str,
    name: &str,
) -> Option<(&'a str, &'a TypeContractDecl)> {
    let compact = name.trim().replace(' ', "");
    let qualified = compact.rsplit_once('.');
    let wanted_container = qualified.map(|(container, _)| container);
    let wanted_name = qualified.map(|(_, name)| name).unwrap_or(&compact);
    let mut fallback = None;
    for container in &program.containers {
        if wanted_container.is_some_and(|wanted| wanted != container.name) {
            continue;
        }
        for section in &container.sections {
            let Section::TypeContracts(contracts) = section else {
                continue;
            };
            for contract in contracts {
                if !contract.name.eq_ignore_ascii_case(wanted_name) {
                    continue;
                }
                if container.name == current_container || wanted_container.is_some() {
                    return Some((&container.name, contract));
                }
                if fallback.is_some() {
                    return None;
                }
                fallback = Some((container.name.as_str(), contract));
            }
        }
    }
    fallback
}

fn sema_type_layout_shape(
    program: &Program,
    current_container: &str,
    ty: &TypeName,
    visiting: &mut HashSet<String>,
) -> Result<(usize, usize, Option<u16>), String> {
    match ty {
        TypeName::Simple(name) => {
            if let Some(scalar) = scalar_type_contract(name, 8) {
                let integer_bits = matches!(
                    scalar.class,
                    ScalarTypeClass::SignedInteger | ScalarTypeClass::UnsignedInteger
                )
                .then_some(scalar.bit_width)
                .flatten();
                return Ok((scalar.size_bytes, scalar.align_bytes, integer_bits));
            }
            let layout = sema_compute_named_layout(program, current_container, name, visiting)?;
            Ok((layout.size_bytes, layout.align_bytes, None))
        }
        TypeName::Generic { base, .. } if base.eq_ignore_ascii_case("ptr") => Ok((8, 8, None)),
        TypeName::Generic { base, args }
            if base.eq_ignore_ascii_case("array") && args.len() >= 2 =>
        {
            let (element_size, element_align, _) =
                sema_type_layout_shape(program, current_container, &args[0], visiting)?;
            let mut length = 1usize;
            for dimension in &args[1..] {
                let TypeName::Simple(dimension) = dimension else {
                    return Err("E_LAYOUT_QUERY_001: array dimensions must be integers".into());
                };
                let dimension = dimension.parse::<usize>().map_err(|_| {
                    "E_LAYOUT_QUERY_001: array dimensions must be integers".to_string()
                })?;
                length = length.checked_mul(dimension).ok_or_else(|| {
                    "E_LAYOUT_QUERY_001: array dimensions overflow addressable size".to_string()
                })?;
            }
            Ok((element_size.saturating_mul(length), element_align, None))
        }
        TypeName::Union(items) => {
            let mut size = 0usize;
            let mut align = 1usize;
            for item in items {
                let (item_size, item_align, _) =
                    sema_type_layout_shape(program, current_container, item, visiting)?;
                size = size.max(item_size);
                align = align.max(item_align);
            }
            Ok((size.div_ceil(align) * align, align, None))
        }
        _ => Err("E_LAYOUT_QUERY_001: type has no static binary layout".into()),
    }
}

fn sema_compute_named_layout(
    program: &Program,
    current_container: &str,
    name: &str,
    visiting: &mut HashSet<String>,
) -> Result<SemaComputedLayout, String> {
    if let Some(scalar) = scalar_type_contract(name, 8) {
        return Ok(SemaComputedLayout {
            size_bytes: scalar.size_bytes,
            align_bytes: scalar.align_bytes,
            fields: HashMap::new(),
        });
    }
    let Some((container, contract)) = sema_find_type_contract(program, current_container, name)
    else {
        return Err(format!("E_LAYOUT_QUERY_001: unknown layout type '{name}'"));
    };
    let key = format!("{}.{}", container, contract.name);
    if !visiting.insert(key.clone()) {
        return Err(format!(
            "E_LAYOUT_QUERY_001: recursive by-value layout cycle at '{key}'"
        ));
    }

    let result = match contract.kind {
        TypeContractKind::Enum => SemaComputedLayout {
            size_bytes: 4,
            align_bytes: 4,
            fields: HashMap::from([("tag".into(), 0)]),
        },
        TypeContractKind::TaggedUnion => {
            let mut payload_size = 0usize;
            let mut payload_align = 1usize;
            for variant in &contract.variants {
                let mut offset = 0usize;
                let mut align = 1usize;
                for field in &variant.payload {
                    let (size, field_align, _) =
                        sema_type_layout_shape(program, container, &field.ty, visiting)?;
                    offset = offset.div_ceil(field_align) * field_align + size;
                    align = align.max(field_align);
                }
                payload_size = payload_size.max(offset.div_ceil(align) * align);
                payload_align = payload_align.max(align);
            }
            let align = payload_align.max(4);
            let payload_offset = 4usize.div_ceil(payload_align) * payload_align;
            SemaComputedLayout {
                size_bytes: (payload_offset + payload_size).div_ceil(align) * align,
                align_bytes: align,
                fields: HashMap::from([("tag".into(), 0), ("payload".into(), payload_offset)]),
            }
        }
        TypeContractKind::Struct | TypeContractKind::Union => {
            let fields = contract
                .clauses
                .iter()
                .filter_map(|clause| match clause {
                    TypeContractClause::Fields { fields, .. } => Some(fields.as_slice()),
                    _ => None,
                })
                .flatten()
                .collect::<Vec<_>>();
            let mut inputs = Vec::with_capacity(fields.len());
            for field in fields {
                let (size_bytes, align_bytes, integer_bits) =
                    sema_type_layout_shape(program, container, &field.ty, visiting)?;
                inputs.push(BinaryLayoutFieldInput {
                    name: field.name.clone(),
                    size_bytes,
                    align_bytes,
                    integer_bits,
                });
            }
            let layout = contract
                .clauses
                .iter()
                .find_map(|clause| match clause {
                    TypeContractClause::Layout(items) => Some(parse_binary_layout_contract(items)),
                    _ => None,
                })
                .transpose()?
                .unwrap_or_default();
            let computed = compute_binary_layout(contract.kind, &layout, &inputs)?;
            SemaComputedLayout {
                size_bytes: computed.size_bytes,
                align_bytes: computed.align_bytes,
                fields: computed
                    .fields
                    .into_iter()
                    .map(|field| (field.name, field.offset_bytes))
                    .collect(),
            }
        }
    };
    visiting.remove(&key);
    Ok(result)
}

#[derive(Debug, Clone, Copy)]
enum SemaStaticValue {
    Int(i64),
    Bool(bool),
}

fn sema_eval_static_layout_expr(
    program: &Program,
    current_container: &str,
    expr: &Expr,
) -> Result<SemaStaticValue, String> {
    match expr {
        Expr::Number(raw) => sema_parse_integer_literal(raw)
            .map(SemaStaticValue::Int)
            .ok_or_else(|| "E_STATIC_ASSERT_001: invalid integer constant".into()),
        Expr::Bool(value) => Ok(SemaStaticValue::Bool(*value)),
        Expr::Unary { op, expr } => {
            let value = sema_eval_static_layout_expr(program, current_container, expr)?;
            match (op, value) {
                (UnaryOp::Plus, SemaStaticValue::Int(value)) => Ok(SemaStaticValue::Int(value)),
                (UnaryOp::Minus, SemaStaticValue::Int(value)) => value
                    .checked_neg()
                    .map(SemaStaticValue::Int)
                    .ok_or_else(|| "E_STATIC_ASSERT_001: integer constant overflow".into()),
                (UnaryOp::Not, SemaStaticValue::Bool(value)) => Ok(SemaStaticValue::Bool(!value)),
                (UnaryOp::NotBin, SemaStaticValue::Int(value)) => Ok(SemaStaticValue::Int(!value)),
                _ => Err("E_STATIC_ASSERT_001: unsupported constant unary operation".into()),
            }
        }
        Expr::Binary { left, op, right } => {
            let left = sema_eval_static_layout_expr(program, current_container, left)?;
            let right = sema_eval_static_layout_expr(program, current_container, right)?;
            match (left, op, right) {
                (SemaStaticValue::Bool(a), BinaryOp::AndAnd, SemaStaticValue::Bool(b)) => {
                    Ok(SemaStaticValue::Bool(a && b))
                }
                (SemaStaticValue::Bool(a), BinaryOp::OrOr, SemaStaticValue::Bool(b)) => {
                    Ok(SemaStaticValue::Bool(a || b))
                }
                (SemaStaticValue::Bool(a), BinaryOp::EqEq, SemaStaticValue::Bool(b)) => {
                    Ok(SemaStaticValue::Bool(a == b))
                }
                (SemaStaticValue::Bool(a), BinaryOp::NotEq, SemaStaticValue::Bool(b)) => {
                    Ok(SemaStaticValue::Bool(a != b))
                }
                (SemaStaticValue::Int(a), BinaryOp::Plus, SemaStaticValue::Int(b)) => a
                    .checked_add(b)
                    .map(SemaStaticValue::Int)
                    .ok_or_else(|| "E_STATIC_ASSERT_001: integer constant overflow".into()),
                (SemaStaticValue::Int(a), BinaryOp::Minus, SemaStaticValue::Int(b)) => a
                    .checked_sub(b)
                    .map(SemaStaticValue::Int)
                    .ok_or_else(|| "E_STATIC_ASSERT_001: integer constant overflow".into()),
                (SemaStaticValue::Int(a), BinaryOp::Star, SemaStaticValue::Int(b)) => a
                    .checked_mul(b)
                    .map(SemaStaticValue::Int)
                    .ok_or_else(|| "E_STATIC_ASSERT_001: integer constant overflow".into()),
                (SemaStaticValue::Int(a), BinaryOp::EqEq, SemaStaticValue::Int(b)) => {
                    Ok(SemaStaticValue::Bool(a == b))
                }
                (SemaStaticValue::Int(a), BinaryOp::NotEq, SemaStaticValue::Int(b)) => {
                    Ok(SemaStaticValue::Bool(a != b))
                }
                (SemaStaticValue::Int(a), BinaryOp::Less, SemaStaticValue::Int(b)) => {
                    Ok(SemaStaticValue::Bool(a < b))
                }
                (SemaStaticValue::Int(a), BinaryOp::LessEq, SemaStaticValue::Int(b)) => {
                    Ok(SemaStaticValue::Bool(a <= b))
                }
                (SemaStaticValue::Int(a), BinaryOp::Greater, SemaStaticValue::Int(b)) => {
                    Ok(SemaStaticValue::Bool(a > b))
                }
                (SemaStaticValue::Int(a), BinaryOp::GreaterEq, SemaStaticValue::Int(b)) => {
                    Ok(SemaStaticValue::Bool(a >= b))
                }
                _ => Err("E_STATIC_ASSERT_001: unsupported constant binary operation".into()),
            }
        }
        Expr::Call { callee, args } => {
            let (base, type_args) = split_generic_callee(callee);
            if !matches!(
                base.to_ascii_lowercase().as_str(),
                "sizeof" | "alignof" | "offsetof"
            ) || type_args.len() != 1
            {
                return Err(
                    "E_STATIC_ASSERT_001: expression is not a compile-time layout constant".into(),
                );
            }
            let type_name = render_sema_type(&type_args[0]);
            let layout = sema_compute_named_layout(
                program,
                current_container,
                &type_name,
                &mut HashSet::new(),
            )?;
            let value = match base.to_ascii_lowercase().as_str() {
                "sizeof" if args.is_empty() => layout.size_bytes,
                "alignof" if args.is_empty() => layout.align_bytes,
                "offsetof" if args.len() == 1 => {
                    let field = match &args[0] {
                        Expr::Identifier(field) | Expr::String(field) => field,
                        _ => return Err(
                            "E_LAYOUT_QUERY_001: offsetOf field must be an identifier or string"
                                .into(),
                        ),
                    };
                    *layout
                        .fields
                        .get(field)
                        .ok_or_else(|| format!("E_LAYOUT_QUERY_001: unknown field '{field}'"))?
                }
                _ => return Err("E_LAYOUT_QUERY_001: invalid layout query arguments".into()),
            };
            i64::try_from(value)
                .map(SemaStaticValue::Int)
                .map_err(|_| "E_LAYOUT_QUERY_001: layout value exceeds int".into())
        }
        _ => Err("E_STATIC_ASSERT_001: expression is not compile-time constant".into()),
    }
}

fn validate_type_contracts(contracts: &[TypeContractDecl]) -> Result<(), String> {
    let contract_names: HashSet<String> = contracts
        .iter()
        .map(|contract| contract.name.to_ascii_lowercase())
        .collect();
    let contract_generic_arity: HashMap<String, usize> = contracts
        .iter()
        .map(|contract| {
            (
                contract.name.to_ascii_lowercase(),
                contract.generic_params.len(),
            )
        })
        .collect();

    for contract in contracts {
        let generic_params: HashSet<String> = contract.generic_params.iter().cloned().collect();
        let mut field_names = HashSet::new();
        let mut fields: Vec<&TypeContractField> = Vec::new();
        let mut has_layout = false;
        let mut has_ffi = false;
        let mut binary_layout = false;
        let mut variant_names = HashSet::new();
        let mut variant_payload_fields: Vec<&TypeContractField> = Vec::new();
        let mut structured_layout = BinaryLayoutContract::default();

        for variant in &contract.variants {
            if !variant_names.insert(variant.name.to_ascii_lowercase()) {
                return Err("E_TYPE_VARIANT_001: invalid type variant".into());
            }
            for payload_field in &variant.payload {
                type_name_is_known_for_contract(
                    &payload_field.ty,
                    &contract_names,
                    &contract_generic_arity,
                    &generic_params,
                )?;
                variant_payload_fields.push(payload_field);
            }
        }

        for clause in &contract.clauses {
            match clause {
                TypeContractClause::Fields {
                    fields: clause_fields,
                    ..
                } => {
                    if clause_fields.is_empty() {
                        return Err("E_TYPE_FIELD_001: invalid or unknown type field".into());
                    }
                    for field in clause_fields {
                        type_name_is_known_for_contract(
                            &field.ty,
                            &contract_names,
                            &contract_generic_arity,
                            &generic_params,
                        )?;
                        if !field_names.insert(field.name.clone()) {
                            return Err(format!(
                                "E_TYPE_FIELD_DUPLICATE_001: duplicate field in type contract '{}'",
                                field.name
                            ));
                        }
                        fields.push(field);
                    }
                }
                TypeContractClause::Layout(items) => {
                    has_layout = true;
                    structured_layout = parse_binary_layout_contract(items)?;
                    if items.iter().any(|item| {
                        let normalized = item.to_ascii_lowercase().replace(' ', "");
                        (normalized == "binary"
                            || normalized.contains("kind:binary")
                            || normalized.ends_with(":binary"))
                            && !normalized.contains("unbinary")
                    }) {
                        binary_layout = true;
                    }
                }
                TypeContractClause::Invariant(items) => {
                    if items.is_empty() {
                        return Err("E_TYPE_INVARIANT_001: invalid type invariant".into());
                    }
                    for item in items {
                        let trimmed = item.trim();
                        if trimmed.is_empty() {
                            return Err("E_TYPE_INVARIANT_001: invalid type invariant".into());
                        }
                        let normalized = trimmed.to_ascii_lowercase().replace(' ', "");
                        if normalized == "false" || normalized.ends_with("==false") {
                            return Err("E_TYPE_INVARIANT_001: invalid type invariant".into());
                        }
                    }
                }
                TypeContractClause::Bounds(items)
                    if items.is_empty()
                        || items
                            .iter()
                            .any(|item| !item.contains(':') || item.trim().ends_with(':')) =>
                {
                    return Err("E_TYPE_BOUNDS_001: invalid type bounds contract".into());
                }
                TypeContractClause::Bounds(_) => {}
                TypeContractClause::Constructure(items) => {
                    if items.is_empty() {
                        return Err("E_TYPE_CONSTRUCTURE_001: invalid constructure contract".into());
                    }
                    for item in items {
                        let Some((_, rhs)) = item.split_once("->") else {
                            return Err(
                                "E_TYPE_CONSTRUCTURE_001: invalid constructure contract".into()
                            );
                        };
                        let ret_name = rhs
                            .trim()
                            .split(|c: char| c.is_whitespace() || c == ';')
                            .next()
                            .unwrap_or_default();
                        let ret_base = ret_name
                            .split('<')
                            .next()
                            .map(str::trim)
                            .unwrap_or(ret_name);
                        if !ret_base.eq_ignore_ascii_case(&contract.name) {
                            return Err(
                                "E_TYPE_CONSTRUCTURE_001: invalid constructure contract".into()
                            );
                        }
                    }
                }
                TypeContractClause::Destructure(items) => {
                    if items.is_empty() {
                        return Err("E_TYPE_DESTRUCTURE_001: invalid destructure contract".into());
                    }
                    for item in items {
                        for field in extract_destructure_field_names(item) {
                            if !field_names.contains(&field) {
                                return Err(
                                    "E_TYPE_DESTRUCTURE_001: invalid destructure contract".into()
                                );
                            }
                        }
                    }
                }
                TypeContractClause::Copy(items) => {
                    let joined = contract_items_joined(items);
                    if items.is_empty()
                        || !(joined.contains("shallow")
                            || joined.contains("deep")
                            || joined.contains("view")
                            || joined.contains("binary")
                            || joined.contains("unbinary")
                            || joined.contains("allowed")
                            || joined.contains("denied"))
                    {
                        return Err("E_TYPE_COPY_001: invalid copy contract".into());
                    }
                }
                TypeContractClause::Clone(items) => {
                    let joined = contract_items_joined(items);
                    if items.is_empty()
                        || !(joined.contains("shallow")
                            || joined.contains("deep")
                            || joined.contains("region")
                            || joined.contains("binary")
                            || joined.contains("unbinary")
                            || joined.contains("allowed")
                            || joined.contains("denied"))
                    {
                        return Err("E_TYPE_CLONE_001: invalid clone contract".into());
                    }
                }
                TypeContractClause::Move(items) => {
                    let joined = contract_items_joined(items);
                    if items.is_empty()
                        || !(joined.contains("allowed") || joined.contains("denied"))
                    {
                        return Err("E_TYPE_MOVE_001: invalid move contract".into());
                    }
                }
                TypeContractClause::Ffi(_) => {
                    has_ffi = true;
                }
                TypeContractClause::Ownership(items) => {
                    if items.is_empty()
                        || items
                            .iter()
                            .any(|item| !item.contains(':') || item.trim().ends_with(':'))
                    {
                        return Err("E_TYPE_OWNERSHIP_001: type ownership contract invalid".into());
                    }
                }
                TypeContractClause::Nullability(items) => {
                    if items.is_empty()
                        || items
                            .iter()
                            .any(|item| !item.contains(':') || item.trim().ends_with(':'))
                    {
                        return Err(
                            "E_TYPE_NULLABILITY_001: type nullability contract invalid".into()
                        );
                    }
                }
                TypeContractClause::Methods(items) => {
                    if items.is_empty() {
                        return Err("E_TYPE_METHOD_001: invalid type method contract".into());
                    }
                    for item in items {
                        let normalized = item.to_ascii_lowercase();
                        if !normalized.contains("self") {
                            return Err("E_TYPE_METHOD_001: invalid type method contract".into());
                        }
                    }
                }
                TypeContractClause::Associated(items) => {
                    if items.is_empty() {
                        return Err("E_TYPE_CONTRACT_001: invalid type associated contract".into());
                    }
                }
                TypeContractClause::Validate(items) => {
                    if items.is_empty() {
                        return Err("E_TYPE_CONTRACT_001: invalid type validate contract".into());
                    }
                }
                TypeContractClause::Drop(items) => {
                    if items.is_empty() {
                        return Err("E_TYPE_DROP_001: invalid type drop contract".into());
                    }
                }
                TypeContractClause::Default(items) => {
                    if items.is_empty() {
                        return Err("E_TYPE_CONTRACT_001: invalid type default contract".into());
                    }
                }
                TypeContractClause::Compare(items) => {
                    if items.is_empty() {
                        return Err("E_TYPE_CONTRACT_001: invalid type compare contract".into());
                    }
                }
                TypeContractClause::Hash(items) => {
                    if items.is_empty() {
                        return Err("E_TYPE_CONTRACT_001: invalid type hash contract".into());
                    }
                }
                TypeContractClause::Debug(items) => {
                    if items.is_empty() {
                        return Err("E_TYPE_CONTRACT_001: invalid type debug contract".into());
                    }
                }
                TypeContractClause::Stable(items) => {
                    if items.is_empty() {
                        return Err(
                            "E_TYPE_STABLE_LAYOUT_001: type stable layout contract invalid".into(),
                        );
                    }
                }
            }
        }

        match contract.kind {
            TypeContractKind::Struct => {
                if fields.is_empty() {
                    return Err("E_TYPE_FIELD_001: invalid or unknown type field".into());
                }
            }
            TypeContractKind::Union => {
                if fields.is_empty() {
                    return Err("E_TYPE_UNION_001: a union requires at least one field".into());
                }
            }
            TypeContractKind::Enum => {
                if contract.variants.is_empty() {
                    return Err("E_TYPE_ENUM_001: invalid enum type contract".into());
                }
            }
            TypeContractKind::TaggedUnion => {
                if contract.variants.is_empty() {
                    return Err("E_TYPE_UNION_001: invalid tagged union type contract".into());
                }
            }
        }

        validate_structured_binary_layout(contract, &structured_layout, &fields)?;

        if has_ffi && !has_layout {
            return Err("E_TYPE_FFI_REPR_001: type FFI representation invalid".into());
        }

        for clause in &contract.clauses {
            if let TypeContractClause::Ffi(items) = clause {
                let mut found_repr = false;
                for item in items {
                    if let Some(repr) = parse_keyed_contract_value(item, "repr") {
                        found_repr = true;
                        let repr_lc = repr.to_ascii_lowercase();
                        if !matches!(repr_lc.as_str(), "c" | "rust" | "cpp" | "c++") {
                            return Err(
                                "E_TYPE_FFI_REPR_001: invalid FFI representation contract".into()
                            );
                        }
                    }
                }
                if !found_repr {
                    return Err("E_TYPE_FFI_REPR_001: invalid FFI representation contract".into());
                }
            }
        }

        if binary_layout {
            for field in fields {
                if !type_name_is_binary_stable(&field.ty) {
                    return Err(
                        "E_TYPE_BINARY_LAYOUT_001: type cannot satisfy binary layout".into(),
                    );
                }
            }
            for payload_field in variant_payload_fields {
                if !type_name_is_binary_stable(&payload_field.ty) {
                    return Err(
                        "E_TYPE_BINARY_LAYOUT_001: type cannot satisfy binary layout".into(),
                    );
                }
            }
        }
    }
    Ok(())
}

fn validate_local_surface(program: &Program) -> Result<(), String> {
    for container in &program.containers {
        if matches!(
            container.context,
            Some(Context::Machine | Context::Primitive | Context::Kernel)
        ) && container
            .sections
            .iter()
            .any(|section| matches!(section, Section::Local(_)))
        {
            return Err(
                "E_LOCAL_MODE_FORBIDDEN_001: local section is not allowed in machine, primitive or kernel contexts"
                    .into(),
            );
        }

        let mut value_names = HashSet::new();
        let mut type_names = container
            .sections
            .iter()
            .flat_map(|section| match section {
                Section::TypeContracts(contracts) => contracts
                    .iter()
                    .map(|contract| contract.name.clone())
                    .collect::<Vec<_>>(),
                Section::Enums(enums) => enums
                    .iter()
                    .map(|declaration| declaration.name.clone())
                    .collect::<Vec<_>>(),
                _ => Vec::new(),
            })
            .collect::<HashSet<_>>();
        let mut const_names = HashSet::new();

        for section in &container.sections {
            let Section::Local(local) = section else {
                continue;
            };
            for decl in &local.decls {
                match decl {
                    LocalDecl::Var { name, ty, init, .. } => {
                        if !value_names.insert(name.clone()) {
                            return Err(format!(
                                "E_LOCAL_DUP_SYMBOL_001: duplicate local symbol '{}'",
                                name
                            ));
                        }
                        if type_names.contains(name) {
                            return Err(format!(
                                "E_LOCAL_NAME_COLLISION_001: local symbol '{}' collides with local type",
                                name
                            ));
                        }
                        validate_local_type_name(ty, &type_names, &const_names)?;
                        if let Some(init) = init {
                            validate_local_expr(init)?;
                        }
                    }
                    LocalDecl::Const {
                        name, ty, value, ..
                    } => {
                        if !value_names.insert(name.clone()) {
                            return Err(format!(
                                "E_LOCAL_DUP_SYMBOL_001: duplicate local symbol '{}'",
                                name
                            ));
                        }
                        const_names.insert(name.clone());
                        if type_names.contains(name) {
                            return Err(format!(
                                "E_LOCAL_NAME_COLLISION_001: local const '{}' collides with local type",
                                name
                            ));
                        }
                        validate_local_type_name(ty, &type_names, &const_names)?;
                        validate_local_expr(value)?;
                    }
                    LocalDecl::TypeAlias {
                        name,
                        ty,
                        visibility,
                    } => {
                        if !type_names.insert(name.clone()) {
                            return Err(format!(
                                "E_LOCAL_TYPE_DUP_001: duplicate local type '{}'",
                                name
                            ));
                        }
                        if value_names.contains(name) {
                            return Err(format!(
                                "E_LOCAL_NAME_COLLISION_001: local type '{}' collides with local symbol",
                                name
                            ));
                        }
                        if type_name_references(ty, name) {
                            return Err(format!(
                                "E_LOCAL_TYPE_RECURSIVE_001: local type '{}' is recursively defined",
                                name
                            ));
                        }
                        validate_local_visibility(visibility, ty)?;
                        validate_local_type_name(ty, &type_names, &const_names)?;
                    }
                    LocalDecl::TypeRecord {
                        name,
                        fields,
                        visibility,
                    } => {
                        if !type_names.insert(name.clone()) {
                            return Err(format!(
                                "E_LOCAL_TYPE_DUP_001: duplicate local type '{}'",
                                name
                            ));
                        }
                        if value_names.contains(name) {
                            return Err(format!(
                                "E_LOCAL_NAME_COLLISION_001: local type '{}' collides with local symbol",
                                name
                            ));
                        }
                        let mut field_names = HashSet::new();
                        for field in fields {
                            if !field_names.insert(field.name.clone()) {
                                return Err(format!(
                                    "E_LOCAL_DUP_SYMBOL_001: duplicate local type field '{}.{}'",
                                    name, field.name
                                ));
                            }
                            if type_name_references_by_value(&field.ty, name) {
                                return Err(format!(
                                    "E_LOCAL_TYPE_RECURSIVE_001: local type '{}' recursively contains itself",
                                    name
                                ));
                            }
                            validate_local_visibility(visibility, &field.ty)?;
                            validate_local_type_name(&field.ty, &type_names, &const_names)?;
                        }
                    }
                    LocalDecl::Metadata { name, value, .. } => {
                        if !value_names.insert(format!("metadata.{name}")) {
                            return Err(format!(
                                "E_LOCAL_DUP_SYMBOL_001: duplicate local metadata '{}'",
                                name
                            ));
                        }
                        validate_local_expr(value)?;
                    }
                }
            }
        }

        if !const_names.is_empty() {
            for section in &container.sections {
                match section {
                    Section::Fn(funcs) | Section::MoveFn(funcs) | Section::ConstFn(funcs) => {
                        for func in funcs {
                            validate_local_const_not_mutated(&func.public_body, &const_names)?;
                        }
                    }
                    Section::Probe(stmts)
                    | Section::Final(stmts)
                    | Section::Raw(stmts)
                    | Section::Binary(stmts)
                    | Section::Bind(stmts)
                    | Section::Structure(stmts) => {
                        validate_local_const_not_mutated(stmts, &const_names)?;
                    }
                    Section::MainEntry { body, .. } => {
                        validate_local_const_not_mutated(body, &const_names)?;
                    }
                    _ => {}
                }
            }
        }
    }
    Ok(())
}

fn collect_local_type_aliases(container: &Container) -> HashMap<String, TypeName> {
    let mut aliases = HashMap::new();
    for section in &container.sections {
        let Section::Local(local) = section else {
            continue;
        };
        for decl in &local.decls {
            if let LocalDecl::TypeAlias { name, ty, .. } = decl {
                aliases.insert(name.clone(), ty.clone());
            }
        }
    }
    aliases
}

fn resolve_container_local_type_aliases(
    program: &Program,
    container_name: &str,
    ty: &TypeName,
) -> Result<TypeName, String> {
    let Some(container) = program
        .containers
        .iter()
        .find(|container| container.name == container_name)
    else {
        return Ok(ty.clone());
    };
    resolve_local_type_aliases(ty, &collect_local_type_aliases(container))
}

fn resolve_local_type_aliases(
    ty: &TypeName,
    aliases: &HashMap<String, TypeName>,
) -> Result<TypeName, String> {
    resolve_local_type_aliases_inner(ty, aliases, &mut Vec::new())
}

fn resolve_local_type_aliases_inner(
    ty: &TypeName,
    aliases: &HashMap<String, TypeName>,
    stack: &mut Vec<String>,
) -> Result<TypeName, String> {
    match ty {
        TypeName::Simple(name) => {
            let Some(target) = aliases.get(name) else {
                return Ok(ty.clone());
            };
            if stack.iter().any(|item| item == name) {
                return Err(format!(
                    "E_LOCAL_TYPE_RECURSIVE_001: local type alias cycle at '{}'",
                    name
                ));
            }
            stack.push(name.clone());
            let resolved = resolve_local_type_aliases_inner(target, aliases, stack);
            stack.pop();
            resolved
        }
        TypeName::Vector(inner) => Ok(TypeName::Vector(Box::new(
            resolve_local_type_aliases_inner(inner, aliases, stack)?,
        ))),
        TypeName::Array(inner) => Ok(TypeName::Array(Box::new(resolve_local_type_aliases_inner(
            inner, aliases, stack,
        )?))),
        TypeName::Union(items) => Ok(TypeName::Union(
            items
                .iter()
                .map(|item| resolve_local_type_aliases_inner(item, aliases, stack))
                .collect::<Result<Vec<_>, _>>()?,
        )),
        TypeName::Generic { base, args } => Ok(TypeName::Generic {
            base: base.clone(),
            args: args
                .iter()
                .map(|arg| resolve_local_type_aliases_inner(arg, aliases, stack))
                .collect::<Result<Vec<_>, _>>()?,
        }),
    }
}

fn local_decl_value_parts(decl: &LocalDecl) -> Option<(&String, &TypeName, Option<&Expr>, bool)> {
    match decl {
        LocalDecl::Var { name, ty, init, .. } => Some((name, ty, init.as_ref(), false)),
        LocalDecl::Const {
            name, ty, value, ..
        } => Some((name, ty, Some(value), true)),
        _ => None,
    }
}

fn validate_local_expr(expr: &Expr) -> Result<(), String> {
    phase13_validate_const_expr_static(expr).map_err(|err| format!("E_LOCAL_CONST_EVAL_001: {err}"))
}

fn validate_local_visibility(visibility: &Option<Visibility>, ty: &TypeName) -> Result<(), String> {
    if matches!(visibility, Some(Visibility::Public)) && local_type_contains_private_marker(ty) {
        return Err(
            "E_LOCAL_PUBLIC_PRIVATE_TYPE_001: public local type cannot expose private marker"
                .into(),
        );
    }
    Ok(())
}

fn validate_local_type_name(
    ty: &TypeName,
    local_types: &HashSet<String>,
    local_consts: &HashSet<String>,
) -> Result<(), String> {
    if let Some((contract, value_type)) = split_storage_contract(ty) {
        contract.validate(true, false)?;
        return validate_local_type_name(value_type, local_types, local_consts);
    }
    if local_type_contains_any(ty) {
        return Err("E_LOCAL_TYPE_ANY_LEAK_001: local type cannot leak Any".into());
    }
    if local_type_known(ty, local_types, local_consts) {
        Ok(())
    } else {
        Err(format!(
            "E_LOCAL_TYPE_UNKNOWN_001: unknown local type '{}'",
            render_type_name(ty)
        ))
    }
}

fn local_type_known(
    ty: &TypeName,
    local_types: &HashSet<String>,
    local_consts: &HashSet<String>,
) -> bool {
    match ty {
        TypeName::Simple(name) => {
            name.chars().all(|ch| ch.is_ascii_digit())
                || high_generic_builtin_type(name)
                || matches!(
                    name.as_str(),
                    "str"
                        | "ft"
                        | "float"
                        | "double"
                        | "array"
                        | "list"
                        | "queue"
                        | "ptr"
                        | "addr"
                        | "ref"
                        | "site"
                        | "memRegion"
                        | "Option"
                        | "Result"
                )
                || local_types.contains(name)
                || local_consts.contains(name)
        }
        TypeName::Vector(inner) | TypeName::Array(inner) => {
            local_type_known(inner, local_types, local_consts)
        }
        TypeName::Union(items) => items
            .iter()
            .all(|item| local_type_known(item, local_types, local_consts)),
        TypeName::Generic { base, args } => {
            local_type_known(&TypeName::Simple(base.clone()), local_types, local_consts)
                && args
                    .iter()
                    .all(|arg| local_type_known(arg, local_types, local_consts))
        }
    }
}

fn local_type_contains_any(ty: &TypeName) -> bool {
    match ty {
        TypeName::Simple(name) => name.eq_ignore_ascii_case("any"),
        TypeName::Vector(inner) | TypeName::Array(inner) => local_type_contains_any(inner),
        TypeName::Union(items) => items.iter().any(local_type_contains_any),
        TypeName::Generic { base, args } => {
            base.eq_ignore_ascii_case("any") || args.iter().any(local_type_contains_any)
        }
    }
}

fn local_type_contains_private_marker(ty: &TypeName) -> bool {
    match ty {
        TypeName::Simple(name) => name.contains("Private") || name.contains("private"),
        TypeName::Vector(inner) | TypeName::Array(inner) => {
            local_type_contains_private_marker(inner)
        }
        TypeName::Union(items) => items.iter().any(local_type_contains_private_marker),
        TypeName::Generic { base, args } => {
            base.contains("Private")
                || base.contains("private")
                || args.iter().any(local_type_contains_private_marker)
        }
    }
}

fn type_name_references(ty: &TypeName, target: &str) -> bool {
    match ty {
        TypeName::Simple(name) => name == target,
        TypeName::Vector(inner) | TypeName::Array(inner) => type_name_references(inner, target),
        TypeName::Union(items) => items.iter().any(|item| type_name_references(item, target)),
        TypeName::Generic { base, args } => {
            base == target || args.iter().any(|arg| type_name_references(arg, target))
        }
    }
}

fn type_name_references_by_value(ty: &TypeName, target: &str) -> bool {
    match ty {
        TypeName::Simple(name) => name == target,
        TypeName::Array(inner) => type_name_references_by_value(inner, target),
        // Dynamic vectors and raw/reference pointer families store a descriptor or
        // address, so a recursive payload does not make the record infinitely sized.
        TypeName::Vector(_) => false,
        TypeName::Union(items) => items
            .iter()
            .any(|item| type_name_references_by_value(item, target)),
        TypeName::Generic { base, args } => {
            let indirect = matches!(
                base.to_ascii_lowercase().as_str(),
                "p" | "ptr" | "ref" | "vector" | "list" | "queue" | "dinarray" | "slice"
            );
            !indirect
                && (base == target
                    || args
                        .iter()
                        .any(|arg| type_name_references_by_value(arg, target)))
        }
    }
}

fn validate_local_const_not_mutated(
    stmts: &[Stmt],
    const_names: &HashSet<String>,
) -> Result<(), String> {
    for stmt in stmts {
        validate_local_const_stmt_not_mutated(stmt, const_names)?;
    }
    Ok(())
}

fn validate_local_const_stmt_not_mutated(
    stmt: &Stmt,
    const_names: &HashSet<String>,
) -> Result<(), String> {
    match stmt {
        Stmt::Projection { target, .. } | Stmt::StrictCheck { target, .. } => {
            if let AssignTarget::Context(context) = target {
                if let Some(name) = context.path.first() {
                    if const_names.contains(name) {
                        return Err(format!(
                            "E_LOCAL_CONST_MUTATION_001: local const '{}' cannot be mutated",
                            name
                        ));
                    }
                }
            }
        }
        Stmt::If {
            then_block,
            else_block,
            ..
        } => {
            validate_local_const_not_mutated(then_block, const_names)?;
            validate_local_const_not_mutated(else_block, const_names)?;
        }
        Stmt::Unless { body, .. }
        | Stmt::While { body, .. }
        | Stmt::DoWhile { body, .. }
        | Stmt::Loop { body }
        | Stmt::RepeatUntil { body, .. }
        | Stmt::RepeatCount { body, .. } => {
            validate_local_const_not_mutated(body, const_names)?;
        }
        Stmt::ForClassic {
            init, step, body, ..
        } => {
            if let Some(init) = init {
                validate_local_const_stmt_not_mutated(init, const_names)?;
            }
            if let Some(step) = step {
                validate_local_const_stmt_not_mutated(step, const_names)?;
            }
            validate_local_const_not_mutated(body, const_names)?;
        }
        Stmt::ForIn { body, .. }
        | Stmt::SameIn { body, .. }
        | Stmt::ForRange { body, .. }
        | Stmt::EachDoWhile { body, .. } => {
            validate_local_const_not_mutated(body, const_names)?;
        }
        Stmt::Labeled { stmt, .. } => validate_local_const_stmt_not_mutated(stmt, const_names)?,
        Stmt::Switch { cases, default, .. } | Stmt::Match { cases, default, .. } => {
            for (_, body) in cases {
                validate_local_const_not_mutated(body, const_names)?;
            }
            validate_local_const_not_mutated(default, const_names)?;
        }
        Stmt::PatternMatch { arms, .. } => {
            for arm in arms {
                validate_local_const_not_mutated(&arm.body, const_names)?;
            }
        }
        Stmt::GuardElse { else_block, .. } => {
            validate_local_const_not_mutated(else_block, const_names)?;
        }
        Stmt::Select { branches, .. } => {
            for (_, body) in branches {
                validate_local_const_not_mutated(body, const_names)?;
            }
        }
        _ => {}
    }
    Ok(())
}

/// Runs the optional pointer-state auditor explicitly. Normal compilation uses
/// [`analyze`] and keeps manual/raw C-like memory behavior unchecked.
pub fn analyze_with_explicit_pointer_checks(program: &Program) -> Result<SemanticResult, String> {
    let _guard = enter_explicit_pointer_checks();
    analyze(program)
}

fn timed_semantic_phase<T>(
    timings: &mut Vec<SemanticPhaseTiming>,
    phase: &'static str,
    operation: impl FnOnce() -> T,
) -> T {
    let started = Instant::now();
    let result = operation();
    timings.push(SemanticPhaseTiming {
        phase,
        elapsed_us: started.elapsed().as_micros(),
    });
    result
}

fn validate_manual_abi_contracts(program: &Program) -> Result<(), String> {
    let mut contracts = HashMap::new();
    let mut bindings = Vec::new();
    let mut functions = HashSet::new();

    for container in &program.containers {
        for section in &container.sections {
            match section {
                Section::Fn(items) | Section::ConstFn(items) | Section::MoveFn(items) => {
                    functions.extend(
                        items
                            .iter()
                            .map(|function| function.name.to_ascii_lowercase()),
                    );
                }
                Section::ManualAbi(items) => {
                    for item in items {
                        match item {
                            ncc_parser::ManualAbiItem::Contract(contract) => {
                                let key = contract.name.to_ascii_lowercase();
                                if contracts.insert(key.clone(), contract).is_some() {
                                    return Err(format!(
                                        "E_V2_ABI_DUPLICATE_001: duplicate manual ABI '{}'",
                                        contract.name
                                    ));
                                }

                                if !matches!(contract.pointer_bits, 16 | 32 | 64 | 128) {
                                    return Err(format!(
                                        "E_V2_ABI_POINTER_001: ABI '{}' pointer.bits must be 16, 32, 64 or 128",
                                        contract.name
                                    ));
                                }
                                if contract.stack_align_bytes == 0
                                    || !contract.stack_align_bytes.is_power_of_two()
                                {
                                    return Err(format!(
                                        "E_V2_ABI_STACK_ALIGN_001: ABI '{}' stack.align must be a non-zero power of two",
                                        contract.name
                                    ));
                                }
                                let word = usize::from(contract.pointer_bits).div_ceil(8);
                                if contract.shadow_space_bytes % word != 0
                                    || contract.red_zone_bytes % word != 0
                                {
                                    return Err(format!(
                                        "E_V2_ABI_STACK_UNIT_001: ABI '{}' shadow/redzone must be multiples of its pointer width",
                                        contract.name
                                    ));
                                }
                                let target = contract.target.to_ascii_lowercase();
                                let expected_bits = if target.starts_with("x86_64")
                                    || target.starts_with("aarch64")
                                    || target.starts_with("riscv64")
                                {
                                    Some(64)
                                } else if target.starts_with("i386")
                                    || target.starts_with("i486")
                                    || target.starts_with("i586")
                                    || target.starts_with("i686")
                                    || target.starts_with("armv7")
                                    || target.starts_with("thumbv7")
                                    || target.starts_with("riscv32")
                                {
                                    Some(32)
                                } else {
                                    None
                                };
                                let Some(expected_bits) = expected_bits else {
                                    return Err(format!(
                                        "E_V2_ABI_TARGET_001: ABI '{}' target '{}' is not materialized by machine",
                                        contract.name, contract.target
                                    ));
                                };
                                if usize::from(contract.pointer_bits) != expected_bits {
                                    return Err(format!(
                                        "E_V2_ABI_POINTER_TARGET_001: ABI '{}' declares {}-bit pointers for a {}-bit target",
                                        contract.name, contract.pointer_bits, expected_bits
                                    ));
                                }

                                let register_sets = [
                                    &contract.integer_argument_registers,
                                    &contract.float_argument_registers,
                                    &contract.integer_return_registers,
                                    &contract.float_return_registers,
                                    &contract.callee_saved_registers,
                                    &contract.clobbered_registers,
                                ];
                                for registers in register_sets {
                                    let mut seen = HashSet::new();
                                    for register in registers {
                                        if register.is_empty()
                                            || !seen.insert(register.to_ascii_lowercase())
                                        {
                                            return Err(format!(
                                                "E_V2_ABI_REGISTER_001: ABI '{}' contains an empty or duplicate register '{}'",
                                                contract.name, register
                                            ));
                                        }
                                    }
                                }
                                let preserved = contract
                                    .callee_saved_registers
                                    .iter()
                                    .map(|register| register.to_ascii_lowercase())
                                    .collect::<HashSet<_>>();
                                if let Some(register) =
                                    contract.clobbered_registers.iter().find(|register| {
                                        preserved.contains(&register.to_ascii_lowercase())
                                    })
                                {
                                    return Err(format!(
                                        "E_V2_ABI_REGISTER_CLASS_001: ABI '{}' register '{}' cannot be both preserved and clobbered",
                                        contract.name, register
                                    ));
                                }
                            }
                            ncc_parser::ManualAbiItem::Binding(binding) => bindings.push(binding),
                        }
                    }
                }
                _ => {}
            }
        }
    }

    let mut symbols = HashSet::new();
    for binding in bindings {
        let abi = binding.abi.to_ascii_lowercase();
        if !contracts.contains_key(&abi) {
            return Err(format!(
                "E_V2_ABI_BIND_UNKNOWN_001: binding '{}' references unknown ABI '{}'",
                binding.symbol.join("."),
                binding.abi
            ));
        }
        let symbol = binding.symbol.join(".").to_ascii_lowercase();
        if !symbols.insert(symbol.clone()) {
            return Err(format!(
                "E_V2_ABI_BIND_DUPLICATE_001: symbol '{}' has more than one ABI binding",
                binding.symbol.join(".")
            ));
        }
        let Some(function) = binding.function.last() else {
            return Err("E_V2_ABI_BIND_FUNCTION_001: ABI binding requires a function".into());
        };
        if !functions.contains(&function.to_ascii_lowercase()) {
            return Err(format!(
                "E_V2_ABI_BIND_FUNCTION_001: binding '{}' references unknown function '{}'",
                binding.symbol.join("."),
                binding.function.join(".")
            ));
        }
    }
    Ok(())
}

pub fn analyze(program: &Program) -> Result<SemanticResult, String> {
    RECORD_TYPE_LAYOUT_CACHE.with(|cell| *cell.borrow_mut() = None);
    let mut phase_timings = Vec::new();
    timed_semantic_phase(&mut phase_timings, "manual_abi", || {
        validate_manual_abi_contracts(program)
    })?;
    let _source_contract = timed_semantic_phase(&mut phase_timings, "source_contract", || {
        resolve_source_execution_contract(program)
    })?;
    let has_machine_bridge = program_has_machine_bridge(program);
    timed_semantic_phase(&mut phase_timings, "imports", || -> Result<(), String> {
        for use_decl in &program.uses {
            validate_foreign_import_form(use_decl)?;
            validate_foreign_asm_bridge(use_decl, has_machine_bridge)?;
            if let Some(symbol) = unresolved_list_symbol_import(&use_decl.path) {
                return Err(format!(
                    "E_LIST_EXPORT_001: list symbol not exported: '{}'",
                    symbol
                ));
            }
            if !is_known_use_path(&use_decl.path)
                && !phase10_use_may_target_declared_module(program, use_decl)
            {
                return Err(format!(
                    "unresolved import path '{}'",
                    use_decl.path.join(".")
                ));
            }
        }
        Ok(())
    })?;

    let same_file_functions =
        timed_semantic_phase(&mut phase_timings, "same_file_function_index", || {
            collect_same_file_functions(program)
        });
    timed_semantic_phase(&mut phase_timings, "trait_indexes", || {
        refresh_high_phase4_indexes(program)
    })?;
    timed_semantic_phase(&mut phase_timings, "function_pointer_indexes", || {
        refresh_function_indexes(program)
    });
    timed_semantic_phase(&mut phase_timings, "local_surface", || {
        validate_local_surface(program)
    })?;
    timed_semantic_phase(&mut phase_timings, "high_contracts", || {
        validate_high_contracts(program)
    })?;
    timed_semantic_phase(&mut phase_timings, "high_generics", || {
        validate_high_generic_functions(program)
    })?;
    timed_semantic_phase(&mut phase_timings, "traits", || {
        validate_high_phase5_surface(program)
    })?;
    timed_semantic_phase(&mut phase_timings, "result_option", || {
        validate_high_phase7_result_option(program)
    })?;
    timed_semantic_phase(&mut phase_timings, "iterators_collections", || {
        validate_high_phase8_iterators_ranges_collections(program)
    })?;
    timed_semantic_phase(&mut phase_timings, "async_concurrency", || {
        validate_high_phase9_async_effects_concurrency(program)
    })?;
    timed_semantic_phase(&mut phase_timings, "modules_packages", || {
        validate_high_phase10_modules_packages_api_surface(program)
    })?;
    timed_semantic_phase(&mut phase_timings, "closures", || {
        validate_high_closures_lambdas_captures(program)
    })?;
    timed_semantic_phase(&mut phase_timings, "reflection", || {
        validate_high_phase12_limited_reflection_introspection(program)
    })?;
    timed_semantic_phase(&mut phase_timings, "comptime", || {
        validate_high_phase13_compile_time_evaluation_model(program)
    })?;
    timed_semantic_phase(&mut phase_timings, "macros", || {
        validate_high_phase14_macros_codegen_model(program)
    })?;
    timed_semantic_phase(&mut phase_timings, "risk_authority", || {
        validate_high_phase15_risk_authority_model(program)
    })?;
    timed_semantic_phase(&mut phase_timings, "enum_index", || {
        collect_high_enums(program)
    })?;
    timed_semantic_phase(&mut phase_timings, "control_flow", || {
        validate_program_control_flow(program)
    })?;

    let containers_started = Instant::now();
    for container in &program.containers {
        validate_root_container(container)?;
        validate_inspect_container(container)?;
        validate_network_container(program, container)?;
        validate_system_container(program, container)?;
        validate_kernel_container(program, container)?;
        validate_ai_container(program, container)?;
        validate_tooling_container(program, container)?;
        validate_compiler_container(program, container)?;
        validate_f10_container(container)?;
        validate_security_container(program, container)?;
        validate_primitive_container(program, container)?;
        validate_machine_container(program, container)?;
        let should_validate_import_decls = container_may_use_imports(container)
            || (matches!(container.context, Some(Context::Security))
                && program.uses.iter().any(use_decl_targets_security_module))
            || program
                .uses
                .iter()
                .any(use_decl_targets_runtime_family_or_namespace);
        if should_validate_import_decls {
            for use_decl in &program.uses {
                validate_import_declaration_context_authority_for_container(
                    &container.name,
                    &container.context,
                    use_decl,
                )?;
            }
        }

        let finals: Vec<&Section> = container
            .sections
            .iter()
            .filter(|section| matches!(section, Section::Final(_)))
            .collect();
        let final_count = finals.len();

        if final_count > 1 {
            let trivial_count = finals
                .iter()
                .filter(|section| is_trivial_final_sentinel(section))
                .count();
            let allow_compat_pair = final_count == 2 && trivial_count == 1;
            if !allow_compat_pair {
                return Err(
                    "multiple fa/final sections are not allowed in the same container".into(),
                );
            }
        }

        let mut strict_ctx = StrictContext::default();
        let mut container_scope: HashMap<String, SemaType> = HashMap::new();
        let mut container_pointer_states: HashMap<String, PointerState> = HashMap::new();
        let mut container_alias_map: AliasMap = HashMap::new();
        let local_type_aliases = collect_local_type_aliases(container);

        let local_functions = collect_local_functions(container);
        // Normal compilation is always manual/raw. Pointer-state checks only
        // become authoritative inside the explicit, codegen-neutral auditor.
        let _raw_pointer_guard =
            enter_silent_pointer_acceptance(!explicit_pointer_checks_enabled());

        for section in &container.sections {
            if let Section::Stc(decls) = section {
                for decl in decls {
                    let StcDecl::Typed {
                        strictly,
                        name,
                        ty,
                        init,
                        ..
                    } = decl;

                    if let Some((storage, _)) = split_storage_contract(ty) {
                        storage.validate(false, init.is_some())?;
                        if storage.section == ncc_parser::StorageSection::ReadOnlyData {
                            strict_ctx.immutable_names.insert(name.clone());
                        }
                    }

                    let resolved_ty = resolve_local_type_aliases(ty, &local_type_aliases)?;
                    let sem_ty = lower_type(&resolved_ty);
                    container_scope.insert(name.clone(), sem_ty.clone());

                    if is_pointer_family_type(&sem_ty) {
                        container_pointer_states.insert(name.clone(), PointerState::Uninit);
                    }

                    if *strictly {
                        strict_ctx.names.insert(name.clone());
                    }
                }
            }
            if let Section::Local(local) = section {
                for decl in &local.decls {
                    if let Some((name, ty, _init, _is_const)) = local_decl_value_parts(decl) {
                        if let Some((storage, _)) = split_storage_contract(ty) {
                            storage.validate(true, _init.is_some())?;
                        }
                        let resolved_ty = resolve_local_type_aliases(ty, &local_type_aliases)?;
                        let sem_ty = lower_type(&resolved_ty);
                        container_scope.insert(name.clone(), sem_ty.clone());

                        if is_pointer_family_type(&sem_ty) {
                            container_pointer_states.insert(name.clone(), PointerState::Uninit);
                        }
                    }
                }
            }
            if let Section::ConstEval(decls) = section {
                for decl in decls {
                    let resolved_ty = resolve_local_type_aliases(&decl.ty, &local_type_aliases)?;
                    let sem_ty = lower_type(&resolved_ty);
                    container_scope.insert(decl.name.clone(), sem_ty);
                }
            }
        }

        for section in &container.sections {
            match section {
                Section::Stc(decls) => {
                    for decl in decls {
                        let StcDecl::Typed { name, ty, init, .. } = decl;
                        let Some(init_value) = init.clone() else {
                            continue;
                        };

                        let init_stmt = Stmt::Projection {
                            target: AssignTarget::Context(ContextRef::plain(vec![name.clone()])),
                            ty: ty.clone(),
                            value: init_value,
                        };

                        let mut init_strict_ctx = strict_ctx.clone();
                        init_strict_ctx.names.remove(name);
                        init_strict_ctx.immutable_names.remove(name);
                        let _ = analyze_stmt(
                            program,
                            &container.name,
                            &init_stmt,
                            &mut container_scope,
                            &mut container_pointer_states,
                            &mut container_alias_map,
                            &SemaType::Simple("bool".into()),
                            &init_strict_ctx,
                            &container.context,
                        )?;
                    }
                }
                Section::Local(local) => {
                    for decl in &local.decls {
                        let Some((name, ty, init, _is_const)) = local_decl_value_parts(decl) else {
                            continue;
                        };
                        let Some(init_value) = init.cloned() else {
                            continue;
                        };
                        let resolved_ty = resolve_local_type_aliases(ty, &local_type_aliases)?;

                        let init_stmt = Stmt::Projection {
                            target: AssignTarget::Context(ContextRef::plain(vec![name.clone()])),
                            ty: resolved_ty,
                            value: init_value,
                        };

                        let _ = analyze_stmt(
                            program,
                            &container.name,
                            &init_stmt,
                            &mut container_scope,
                            &mut container_pointer_states,
                            &mut container_alias_map,
                            &SemaType::Simple("bool".into()),
                            &strict_ctx,
                            &container.context,
                        )?;
                    }
                }
                Section::Binary(stmts) => {
                    if matches!(container.context, Some(Context::Root)) {
                        analyze_binary_section(
                            stmts,
                            &mut container_scope,
                            &mut container_pointer_states,
                        )?;
                    } else {
                        return Err("binary section is only allowed in [@] root context".into());
                    }
                }
                Section::Bind(stmts) => {
                    if matches!(container.context, Some(Context::Root)) {
                        analyze_bind_section(
                            program,
                            &container.name,
                            &container.context,
                            stmts,
                            &mut container_scope,
                            &mut container_pointer_states,
                            &mut container_alias_map,
                        )?;
                    } else {
                        return Err("bind section is only allowed in [@] root context".into());
                    }
                }
                Section::Raw(_) if !matches!(container.context, Some(Context::Root)) => {
                    return Err("raw section is only allowed in [@] root context".into());
                }
                Section::MoveFn(_) => {
                    if matches!(container.context, Some(Context::Root)) {
                        return Err("move fn section is not allowed in [@] root context".into());
                    }
                }
                Section::Probe(stmts) => {
                    if matches!(container.context, Some(Context::Root)) {
                        for stmt in stmts {
                            analyze_stmt_linking(
                                program,
                                stmt,
                                &container.name,
                                &container.context,
                                &local_functions,
                                &same_file_functions,
                                &program.uses,
                            )?;
                        }
                    } else if matches!(container.context, Some(Context::Inspect)) {
                        for stmt in stmts {
                            let _ = analyze_stmt(
                                program,
                                &container.name,
                                stmt,
                                &mut container_scope,
                                &mut container_pointer_states,
                                &mut container_alias_map,
                                &SemaType::Simple("bool".into()),
                                &strict_ctx,
                                &container.context,
                            )?;
                            analyze_stmt_linking(
                                program,
                                stmt,
                                &container.name,
                                &container.context,
                                &local_functions,
                                &same_file_functions,
                                &program.uses,
                            )?;
                        }
                    }
                }
                Section::Final(stmts) => {
                    if matches!(container.context, Some(Context::Inspect)) {
                        for stmt in stmts {
                            let _ = analyze_stmt(
                                program,
                                &container.name,
                                stmt,
                                &mut container_scope,
                                &mut container_pointer_states,
                                &mut container_alias_map,
                                &SemaType::Simple("bool".into()),
                                &strict_ctx,
                                &container.context,
                            )?;
                            analyze_stmt_linking(
                                program,
                                stmt,
                                &container.name,
                                &container.context,
                                &local_functions,
                                &same_file_functions,
                                &program.uses,
                            )?;
                        }
                    }
                }
                Section::Structure(stmts) => {
                    if matches!(container.context, Some(Context::Root)) {
                        for stmt in stmts {
                            let _ = analyze_stmt(
                                program,
                                &container.name,
                                stmt,
                                &mut container_scope,
                                &mut container_pointer_states,
                                &mut container_alias_map,
                                &SemaType::Simple("bool".into()),
                                &strict_ctx,
                                &container.context,
                            )?;
                            analyze_stmt_linking(
                                program,
                                stmt,
                                &container.name,
                                &container.context,
                                &local_functions,
                                &same_file_functions,
                                &program.uses,
                            )?;
                        }
                    }
                }
                Section::TypeContracts(contracts) => {
                    validate_type_contracts(contracts)?;
                }
                Section::Interfaces(_) | Section::Contracts(_) | Section::Enums(_) => {}
                Section::Traits(traits) => {
                    for trait_decl in traits {
                        for default_method in &trait_decl.default_methods {
                            analyze_function(
                                program,
                                &container.name,
                                default_method,
                                &container_scope,
                                &container_pointer_states,
                                &strict_ctx,
                                &container.context,
                            )?;
                        }
                    }
                }
                Section::ImplBlocks(impls) => {
                    for impl_decl in impls {
                        for method in &impl_decl.methods {
                            analyze_function(
                                program,
                                &container.name,
                                method,
                                &container_scope,
                                &container_pointer_states,
                                &strict_ctx,
                                &container.context,
                            )?;
                        }
                    }
                }
                Section::Foreign(decls) => {
                    validate_foreign_section_for_container(container, decls)?;
                }
                Section::MainEntry { kind, body } => {
                    analyze_main_entry_kind(
                        program,
                        kind,
                        &container.name,
                        &container.context,
                        &local_functions,
                        &same_file_functions,
                        &program.uses,
                    )?;
                    let inline_return_contract = match kind {
                        MainEntryKind::ToMain | MainEntryKind::ToMainProfile(_) => {
                            SemaType::Union(vec![
                                SemaType::Simple("bool".into()),
                                SemaType::Simple("int".into()),
                                SemaType::Simple("void".into()),
                            ])
                        }
                        MainEntryKind::RefFn(_) | MainEntryKind::SkkFn(_) => SemaType::Unknown,
                    };
                    for stmt in body {
                        let analyzed = analyze_stmt(
                            program,
                            &container.name,
                            stmt,
                            &mut container_scope,
                            &mut container_pointer_states,
                            &mut container_alias_map,
                            &inline_return_contract,
                            &strict_ctx,
                            &container.context,
                        );
                        if let Err(err) = analyzed {
                            let return_contract_error = err.starts_with("return type mismatch:")
                                || err.starts_with("E_VOID_RETURN_001:")
                                || err.starts_with("E_VOID_VALUE_001:");
                            if return_contract_error {
                                let kind_label = match kind {
                                    MainEntryKind::ToMain => "to main".to_string(),
                                    MainEntryKind::ToMainProfile(profile) => {
                                        format!("to main@<{}>", profile)
                                    }
                                    MainEntryKind::RefFn(_) => "ref main".to_string(),
                                    MainEntryKind::SkkFn(_) => "skkMain".to_string(),
                                };
                                return Err(format!(
                                    "entry target has invalid return contract for {}: expected bool/int/void ({})",
                                    kind_label, err
                                ));
                            }
                            return Err(err);
                        }
                        analyze_stmt_linking(
                            program,
                            stmt,
                            &container.name,
                            &container.context,
                            &local_functions,
                            &same_file_functions,
                            &program.uses,
                        )?;
                    }
                }
                Section::Fn(funcs) => {
                    for func in funcs {
                        analyze_function(
                            program,
                            &container.name,
                            func,
                            &container_scope,
                            &container_pointer_states,
                            &strict_ctx,
                            &container.context,
                        )?;

                        for stmt in &func.public_body {
                            analyze_stmt_linking(
                                program,
                                stmt,
                                &container.name,
                                &container.context,
                                &local_functions,
                                &same_file_functions,
                                &program.uses,
                            )?;
                        }
                    }
                }
                _ => {}
            }
        }
    }
    phase_timings.push(SemanticPhaseTiming {
        phase: "container_bodies",
        elapsed_us: containers_started.elapsed().as_micros(),
    });

    timed_semantic_phase(&mut phase_timings, "main_entries", || {
        validate_main_entries(program, MainEntryRequirement::Optional)
    })?;
    let warnings = timed_semantic_phase(&mut phase_timings, "deprecations", || {
        collect_deprecation_warnings(program)
    });

    Ok(SemanticResult {
        ok: true,
        warnings,
        phase_timings,
    })
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ControlScopeKind {
    Loop,
    Switch,
}

#[derive(Debug, Clone)]
struct ControlScope {
    label: Option<String>,
    kind: ControlScopeKind,
}

fn stmt_is_control_loop(stmt: &Stmt) -> bool {
    matches!(
        stmt,
        Stmt::While { .. }
            | Stmt::DoWhile { .. }
            | Stmt::ForClassic { .. }
            | Stmt::ForIn { .. }
            | Stmt::SameIn { .. }
            | Stmt::ForRange { .. }
            | Stmt::Loop { .. }
            | Stmt::RepeatUntil { .. }
            | Stmt::RepeatCount { .. }
            | Stmt::EachDoWhile { .. }
    )
}

fn validate_program_control_flow(program: &Program) -> Result<(), String> {
    for container in &program.containers {
        for section in &container.sections {
            match section {
                Section::Fn(functions)
                | Section::MoveFn(functions)
                | Section::ConstFn(functions) => {
                    for function in functions {
                        validate_control_flow_root(&function.public_body).map_err(|err| {
                            format!("{} in function '{}.{}'", err, container.name, function.name)
                        })?;
                    }
                }
                Section::Traits(traits) => {
                    for trait_decl in traits {
                        for function in &trait_decl.default_methods {
                            validate_control_flow_root(&function.public_body).map_err(|err| {
                                format!(
                                    "{} in trait default '{}.{}'",
                                    err, trait_decl.name, function.name
                                )
                            })?;
                        }
                    }
                }
                Section::ImplBlocks(impls) => {
                    for impl_decl in impls {
                        for function in &impl_decl.methods {
                            validate_control_flow_root(&function.public_body).map_err(|err| {
                                format!("{} in impl method '{}'", err, function.name)
                            })?;
                        }
                    }
                }
                Section::Binary(stmts)
                | Section::Probe(stmts)
                | Section::Structure(stmts)
                | Section::Final(stmts)
                | Section::Bind(stmts)
                | Section::Raw(stmts) => {
                    validate_control_flow_root(stmts)
                        .map_err(|err| format!("{} in container '{}'", err, container.name))?;
                }
                Section::MainEntry { body, .. } => {
                    validate_control_flow_root(body)
                        .map_err(|err| format!("{} in main entry for '{}'", err, container.name))?;
                }
                Section::ComptimeUnsafe(blocks) => {
                    for block in blocks {
                        validate_control_flow_root(&block.body).map_err(|err| {
                            format!("{} in comptime unsafe block '{}'", err, block.name)
                        })?;
                    }
                }
                _ => {}
            }
        }
    }
    Ok(())
}

fn validate_control_flow_root(stmts: &[Stmt]) -> Result<(), String> {
    let mut scopes = Vec::new();
    let mut labels = HashSet::new();
    validate_control_flow_block(stmts, &mut scopes, &mut labels)
}

fn validate_control_flow_block(
    stmts: &[Stmt],
    scopes: &mut Vec<ControlScope>,
    labels: &mut HashSet<String>,
) -> Result<(), String> {
    for stmt in stmts {
        validate_control_flow_stmt(stmt, scopes, labels, None)?;
    }
    Ok(())
}

fn validate_control_flow_stmt(
    stmt: &Stmt,
    scopes: &mut Vec<ControlScope>,
    labels: &mut HashSet<String>,
    pending_label: Option<String>,
) -> Result<(), String> {
    match stmt {
        Stmt::Labeled { label, stmt } if label.starts_with("__ncc_loop_flavor_") => {
            validate_control_flow_stmt(stmt, scopes, labels, pending_label)
        }
        Stmt::Labeled { label, stmt } => {
            if !labels.insert(label.clone()) {
                return Err(format!(
                    "E_CONTROL_LABEL_DUPLICATE_001: duplicate control-flow label '{}'",
                    label
                ));
            }
            if !stmt_is_control_loop(stmt)
                && !matches!(stmt.as_ref(), Stmt::Switch { .. } | Stmt::Match { .. })
            {
                return Err(format!(
                    "E_CONTROL_LABEL_TARGET_001: label '{}' must target a loop, switch or match",
                    label
                ));
            }
            validate_control_flow_stmt(stmt, scopes, labels, Some(label.clone()))
        }
        Stmt::If {
            then_block,
            else_block,
            ..
        } => {
            validate_control_flow_block(then_block, scopes, labels)?;
            validate_control_flow_block(else_block, scopes, labels)
        }
        Stmt::Unless { body, .. } => validate_control_flow_block(body, scopes, labels),
        Stmt::While { body, .. }
        | Stmt::DoWhile { body, .. }
        | Stmt::ForIn { body, .. }
        | Stmt::SameIn { body, .. }
        | Stmt::ForRange { body, .. }
        | Stmt::Loop { body }
        | Stmt::RepeatUntil { body, .. }
        | Stmt::RepeatCount { body, .. }
        | Stmt::EachDoWhile { body, .. } => {
            scopes.push(ControlScope {
                label: pending_label,
                kind: ControlScopeKind::Loop,
            });
            let result = validate_control_flow_block(body, scopes, labels);
            scopes.pop();
            result
        }
        Stmt::ForClassic {
            init, step, body, ..
        } => {
            if let Some(init) = init {
                validate_control_flow_stmt(init, scopes, labels, None)?;
            }
            scopes.push(ControlScope {
                label: pending_label,
                kind: ControlScopeKind::Loop,
            });
            validate_control_flow_block(body, scopes, labels)?;
            if let Some(step) = step {
                validate_control_flow_stmt(step, scopes, labels, None)?;
            }
            scopes.pop();
            Ok(())
        }
        Stmt::Switch { cases, default, .. } | Stmt::Match { cases, default, .. } => {
            scopes.push(ControlScope {
                label: pending_label,
                kind: ControlScopeKind::Switch,
            });
            let result = (|| {
                for (_, body) in cases {
                    validate_control_flow_block(body, scopes, labels)?;
                }
                validate_control_flow_block(default, scopes, labels)
            })();
            scopes.pop();
            result
        }
        Stmt::PatternMatch { arms, .. } => {
            for arm in arms {
                validate_control_flow_block(&arm.body, scopes, labels)?;
            }
            Ok(())
        }
        Stmt::Defer { body } => {
            let mut deferred_scopes = Vec::new();
            validate_control_flow_block(body, &mut deferred_scopes, labels)
        }
        Stmt::GuardElse { else_block, .. } => {
            validate_control_flow_block(else_block, scopes, labels)
        }
        Stmt::Select { branches, default } => {
            for (_, body) in branches {
                validate_control_flow_block(body, scopes, labels)?;
            }
            validate_control_flow_block(default, scopes, labels)
        }
        Stmt::Break { label } => {
            let target = if let Some(label) = label {
                scopes
                    .iter()
                    .rev()
                    .find(|scope| scope.label.as_deref() == Some(label.as_str()))
            } else {
                scopes.last()
            };
            if target.is_none() {
                return Err(match label {
                    Some(label) => format!(
                        "E_CONTROL_BREAK_LABEL_001: break label '{}' has no active target",
                        label
                    ),
                    None => {
                        "E_CONTROL_BREAK_SCOPE_001: break requires an active loop, switch or match"
                            .to_string()
                    }
                });
            }
            Ok(())
        }
        Stmt::Continue { label } => {
            let matching_label = label.as_ref().and_then(|label| {
                scopes
                    .iter()
                    .rev()
                    .find(|scope| scope.label.as_deref() == Some(label.as_str()))
            });
            let target = if label.is_some() {
                matching_label.filter(|scope| scope.kind == ControlScopeKind::Loop)
            } else {
                scopes
                    .iter()
                    .rev()
                    .find(|scope| scope.kind == ControlScopeKind::Loop)
            };
            if target.is_none() {
                return Err(match (label, matching_label) {
                    (Some(label), Some(_)) => format!(
                        "E_CONTROL_CONTINUE_TARGET_001: continue label '{}' does not target a loop",
                        label
                    ),
                    (Some(label), None) => format!(
                        "E_CONTROL_CONTINUE_LABEL_001: continue label '{}' has no active loop",
                        label
                    ),
                    (None, _) => {
                        "E_CONTROL_CONTINUE_SCOPE_001: continue requires an active loop".to_string()
                    }
                });
            }
            Ok(())
        }
        Stmt::Return(_)
        | Stmt::Dev(_)
        | Stmt::Projection { .. }
        | Stmt::StrictCheck { .. }
        | Stmt::MainRefFn { .. }
        | Stmt::FunctionRelation { .. }
        | Stmt::Print { .. }
        | Stmt::Destructure { .. }
        | Stmt::Constructure { .. }
        | Stmt::Expr(_) => Ok(()),
    }
}

fn analyze_function(
    program: &Program,
    current_container_name: &str,
    function: &FunctionDecl,
    container_scope: &HashMap<String, SemaType>,
    container_pointer_states: &HashMap<String, PointerState>,
    strict_ctx: &StrictContext,
    current_context: &Option<Context>,
) -> Result<(), String> {
    validate_module_lifecycle_function(function)?;
    let mut scope: HashMap<String, SemaType> = container_scope.clone();
    let mut pointer_states: HashMap<String, PointerState> = container_pointer_states.clone();
    let mut flow_alias_map: FlowAliasMap = HashMap::new();

    for param in &function.params {
        let param_ty = lower_type(&param.ty);
        validate_list_imports(program, &param_ty)?;
        scope.insert(param.name.clone(), param_ty.clone());

        if is_pointer_family_type(&param_ty) {
            pointer_states.insert(param.name.clone(), PointerState::Bound);
        }
    }

    for generic_param in &function.generic_params {
        if let Some(const_type) = const_generic_param_type(&function.generic_bounds, generic_param)
        {
            scope.insert(generic_param.clone(), const_type);
        }
    }

    let expected_return = lower_type(&function.return_type);
    validate_list_imports(program, &expected_return)?;

    let previous_bounds = CURRENT_HIGH_BOUNDS
        .with(|cell| std::mem::replace(&mut *cell.borrow_mut(), function.generic_bounds.clone()));
    let previous_return =
        CURRENT_FUNCTION_RETURN.with(|cell| cell.replace(Some(expected_return.clone())));
    let previous_pointer_region_bounds =
        CURRENT_POINTER_REGION_BOUNDS.with(|cell| std::mem::take(&mut *cell.borrow_mut()));
    let previous_pointer_addr_literals =
        CURRENT_POINTER_ADDR_LITERALS.with(|cell| std::mem::take(&mut *cell.borrow_mut()));
    let result = analyze_stmt_block(
        program,
        current_container_name,
        &function.public_body,
        &mut scope,
        &mut pointer_states,
        &mut flow_alias_map,
        &expected_return,
        strict_ctx,
        current_context,
    );
    CURRENT_HIGH_BOUNDS.with(|cell| {
        *cell.borrow_mut() = previous_bounds;
    });
    CURRENT_FUNCTION_RETURN.with(|cell| {
        cell.replace(previous_return);
    });
    CURRENT_POINTER_REGION_BOUNDS.with(|cell| {
        *cell.borrow_mut() = previous_pointer_region_bounds;
    });
    CURRENT_POINTER_ADDR_LITERALS.with(|cell| {
        *cell.borrow_mut() = previous_pointer_addr_literals;
    });
    if let Err(err) = result {
        if function.is_async && err.contains("return type mismatch") {
            return Err(format!("E_HIGH_ASYNC_RETURN_001: {err}"));
        }
        return Err(err);
    }

    Ok(())
}

fn validate_module_lifecycle_function(function: &FunctionDecl) -> Result<(), String> {
    let has_init = function
        .effects
        .iter()
        .any(|effect| effect.eq_ignore_ascii_case("module.init"));
    let has_fini = function
        .effects
        .iter()
        .any(|effect| effect.eq_ignore_ascii_case("module.fini"));
    if !has_init && !has_fini {
        return Ok(());
    }
    if has_init && has_fini {
        return Err(format!(
            "E_STORAGE_LIFECYCLE_KIND_001: function '{}' cannot be both module.init and module.fini",
            function.name
        ));
    }
    if function.is_async || !function.generic_params.is_empty() || !function.params.is_empty() {
        return Err(format!(
            "E_STORAGE_LIFECYCLE_ABI_001: lifecycle function '{}' must be synchronous, monomorphic and parameterless",
            function.name
        ));
    }
    if !matches!(&function.return_type, TypeName::Simple(name) if name.eq_ignore_ascii_case("void"))
    {
        return Err(format!(
            "E_STORAGE_LIFECYCLE_RETURN_001: lifecycle function '{}' must return void",
            function.name
        ));
    }
    Ok(())
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum FlowOutcome {
    FallsThrough,
    Terminated,
}

#[allow(clippy::too_many_arguments)]
fn analyze_stmt_block(
    program: &Program,
    current_container_name: &str,
    stmts: &[Stmt],
    scope: &mut HashMap<String, SemaType>,
    pointer_states: &mut HashMap<String, PointerState>,
    flow_alias_map: &mut FlowAliasMap,
    expected_return: &SemaType,
    strict_ctx: &StrictContext,
    current_context: &Option<Context>,
) -> Result<FlowOutcome, String> {
    let mut outcome = FlowOutcome::FallsThrough;
    for stmt in stmts {
        if matches!(outcome, FlowOutcome::Terminated) {
            break;
        }
        outcome = analyze_stmt(
            program,
            current_container_name,
            stmt,
            scope,
            pointer_states,
            flow_alias_map,
            expected_return,
            strict_ctx,
            current_context,
        )?;
    }
    Ok(outcome)
}

fn immutable_assignment_root(target: &AssignTarget) -> Option<&str> {
    fn expr_root(expr: &Expr) -> Option<&str> {
        match expr {
            Expr::ContextRef(ctx) => ctx.path.first().map(String::as_str),
            Expr::Index { target, .. } => expr_root(target),
            Expr::Unary { expr, .. } => expr_root(expr),
            _ => None,
        }
    }

    match target {
        AssignTarget::Context(ctx) => ctx.path.first().map(String::as_str),
        AssignTarget::Mem { addr } => expr_root(addr),
    }
}

fn defer_stmt_has_control_escape(stmt: &Stmt) -> bool {
    match stmt {
        Stmt::Return(_) | Stmt::Break { .. } | Stmt::Continue { .. } => true,
        Stmt::If {
            then_block,
            else_block,
            ..
        } => {
            then_block.iter().any(defer_stmt_has_control_escape)
                || else_block.iter().any(defer_stmt_has_control_escape)
        }
        Stmt::Unless { body, .. }
        | Stmt::While { body, .. }
        | Stmt::DoWhile { body, .. }
        | Stmt::ForIn { body, .. }
        | Stmt::SameIn { body, .. }
        | Stmt::ForRange { body, .. }
        | Stmt::Loop { body }
        | Stmt::RepeatUntil { body, .. }
        | Stmt::RepeatCount { body, .. }
        | Stmt::EachDoWhile { body, .. }
        | Stmt::Defer { body } => body.iter().any(defer_stmt_has_control_escape),
        Stmt::ForClassic {
            init, step, body, ..
        } => {
            init.as_deref().is_some_and(defer_stmt_has_control_escape)
                || step.as_deref().is_some_and(defer_stmt_has_control_escape)
                || body.iter().any(defer_stmt_has_control_escape)
        }
        Stmt::Labeled { stmt, .. } => defer_stmt_has_control_escape(stmt),
        Stmt::Switch { cases, default, .. } | Stmt::Match { cases, default, .. } => {
            cases
                .iter()
                .any(|(_, body)| body.iter().any(defer_stmt_has_control_escape))
                || default.iter().any(defer_stmt_has_control_escape)
        }
        Stmt::PatternMatch { arms, .. } => arms
            .iter()
            .any(|arm| arm.body.iter().any(defer_stmt_has_control_escape)),
        Stmt::GuardElse { else_block, .. } => else_block.iter().any(defer_stmt_has_control_escape),
        Stmt::Select { branches, default } => {
            branches
                .iter()
                .any(|(_, body)| body.iter().any(defer_stmt_has_control_escape))
                || default.iter().any(defer_stmt_has_control_escape)
        }
        Stmt::Dev(_)
        | Stmt::Projection { .. }
        | Stmt::StrictCheck { .. }
        | Stmt::MainRefFn { .. }
        | Stmt::FunctionRelation { .. }
        | Stmt::Print { .. }
        | Stmt::Destructure { .. }
        | Stmt::Constructure { .. }
        | Stmt::Expr(_) => false,
    }
}

fn propagated_payload_type(source: &SemaType) -> Result<SemaType, String> {
    match source {
        SemaType::Generic { base, args }
            if base.eq_ignore_ascii_case("Option") && args.len() == 1 =>
        {
            Ok(args[0].clone())
        }
        SemaType::Generic { base, args }
            if base.eq_ignore_ascii_case("Result") && args.len() == 2 =>
        {
            Ok(args[0].clone())
        }
        other => Err(format!(
            "E_HIGH_TRY_OPERAND_001: '?' and 'try' require Option<T> or Result<T,E>, got {}",
            render_sema_type(other)
        )),
    }
}

fn validate_propagation_return_contract(source: &SemaType) -> Result<(), String> {
    let expected = CURRENT_FUNCTION_RETURN.with(|cell| cell.borrow().clone());
    let Some(expected) = expected else {
        return Ok(());
    };
    match (source, &expected) {
        (
            SemaType::Generic {
                base: source_base, ..
            },
            SemaType::Generic {
                base: return_base, ..
            },
        ) if source_base.eq_ignore_ascii_case("Option")
            && return_base.eq_ignore_ascii_case("Option") =>
        {
            Ok(())
        }
        (
            SemaType::Generic {
                base: source_base,
                args: source_args,
            },
            SemaType::Generic {
                base: return_base,
                args: return_args,
            },
        ) if source_base.eq_ignore_ascii_case("Result")
            && return_base.eq_ignore_ascii_case("Result")
            && source_args.len() == 2
            && return_args.len() == 2
            && type_compatible(&source_args[1], &return_args[1]) =>
        {
            Ok(())
        }
        _ => Err(format!(
            "E_HIGH_TRY_CONTEXT_001: cannot propagate {} from function returning {}",
            render_sema_type(source),
            render_sema_type(&expected)
        )),
    }
}

fn join_pointer_state(left: PointerState, right: PointerState) -> PointerState {
    if left == right {
        return left;
    }
    if matches!(left, PointerState::Invalid) || matches!(right, PointerState::Invalid) {
        return PointerState::Invalid;
    }

    // Any divergent pointer state across branches is treated as non-trustable after merge.
    PointerState::Invalid
}

fn merge_pointer_states_for_cfg(
    then_states: &HashMap<String, PointerState>,
    else_states: &HashMap<String, PointerState>,
) -> HashMap<String, PointerState> {
    let keys: HashSet<String> = then_states
        .keys()
        .chain(else_states.keys())
        .cloned()
        .collect();
    let mut out = HashMap::new();

    for key in keys {
        let state = match (then_states.get(&key), else_states.get(&key)) {
            (Some(left), Some(right)) => join_pointer_state(*left, *right),
            (Some(single), None) | (None, Some(single)) => *single,
            (None, None) => continue,
        };
        out.insert(key, state);
    }

    out
}

fn merge_scope_for_cfg(
    base_scope: &HashMap<String, SemaType>,
    then_scope: &HashMap<String, SemaType>,
    else_scope: &HashMap<String, SemaType>,
) -> HashMap<String, SemaType> {
    let keys: HashSet<String> = then_scope
        .keys()
        .chain(else_scope.keys())
        .cloned()
        .collect();
    let mut out = base_scope.clone();

    for key in keys {
        match (then_scope.get(&key), else_scope.get(&key)) {
            (Some(left), Some(right)) if left == right => {
                out.insert(key, left.clone());
            }
            (Some(_), Some(_)) | (Some(_), None) | (None, Some(_)) => {
                if let Some(base_ty) = base_scope.get(&key) {
                    out.insert(key, base_ty.clone());
                } else {
                    out.remove(&key);
                }
            }
            (None, None) => {}
        }
    }

    out
}

fn merge_flow_alias_maps_for_cfg(
    then_alias: &FlowAliasMap,
    else_alias: &FlowAliasMap,
    pointer_states: &mut HashMap<String, PointerState>,
) -> FlowAliasMap {
    let mut out = HashMap::new();
    let symbols: Vec<String> = pointer_states.keys().cloned().collect();

    for sym in symbols {
        let then_root = flow_alias_root(&sym, then_alias);
        let else_root = flow_alias_root(&sym, else_alias);

        if then_root == else_root {
            if then_root != sym {
                out.insert(sym, then_root);
            }
        } else {
            pointer_states.insert(sym, PointerState::Invalid);
        }
    }

    out
}

fn validate_dev_errors_against_return(
    expected_return: &SemaType,
    errors: &[String],
) -> Result<(), String> {
    if let SemaType::Union(items) = expected_return {
        for err_name in errors {
            let dev_ty = SemaType::Simple(err_name.clone());
            let valid = items.iter().any(|t| type_compatible(&dev_ty, t));
            if !valid {
                return Err(format!(
                    "dev() type {:?} not allowed by return type {:?}",
                    dev_ty, expected_return
                ));
            }
        }
    }
    Ok(())
}

fn sema_type_is_void(ty: &SemaType) -> bool {
    matches!(ty, SemaType::Simple(name) if normalize_type_name(name) == "void")
}

fn sema_type_contains_null(ty: &SemaType) -> bool {
    match ty {
        SemaType::Simple(name) => name == "null",
        SemaType::Union(items) => items.iter().any(sema_type_contains_null),
        _ => false,
    }
}

fn sema_type_is_nullable_like(ty: &SemaType) -> bool {
    sema_type_contains_null(ty)
}

fn sema_parse_integer_literal(raw: &str) -> Option<i64> {
    let compact: String = raw.chars().filter(|ch| *ch != '_').collect();
    if compact.is_empty() {
        return None;
    }
    if let Some(hex) = compact
        .strip_prefix("0x")
        .or_else(|| compact.strip_prefix("0X"))
    {
        return i64::from_str_radix(hex, 16).ok();
    }
    if let Some(bin) = compact
        .strip_prefix("0b")
        .or_else(|| compact.strip_prefix("0B"))
    {
        return i64::from_str_radix(bin, 2).ok();
    }
    compact.parse::<i64>().ok()
}

fn sema_expr_integer_literal_value(expr: &Expr) -> Option<i64> {
    match expr {
        Expr::Number(raw) => sema_parse_integer_literal(raw),
        Expr::Unary {
            op: UnaryOp::Minus,
            expr: nested,
        } => sema_expr_integer_literal_value(nested).map(|value| -value),
        Expr::Unary {
            op: UnaryOp::Plus,
            expr: nested,
        } => sema_expr_integer_literal_value(nested),
        _ => None,
    }
}

fn sema_type_is_unknown(ty: &SemaType) -> bool {
    matches!(ty, SemaType::Unknown)
}

fn sema_type_is_memregion_family(ty: &SemaType) -> bool {
    match ty {
        SemaType::Generic { base, .. } => base.eq_ignore_ascii_case("memRegion"),
        SemaType::Union(items) => items.iter().all(sema_type_is_memregion_family),
        _ => false,
    }
}

fn sema_type_has_stable_binary_layout(ty: &SemaType) -> bool {
    match ty {
        SemaType::Unknown => false,
        SemaType::Simple(name) => {
            let normalized = normalize_type_name(name);
            normalized.starts_with("int")
                || normalized.starts_with("uint")
                || matches!(
                    normalized,
                    "bool" | "byte" | "word" | "dword" | "qword" | "char" | "addr"
                )
        }
        SemaType::Array(inner) | SemaType::Vector(inner) => {
            sema_type_has_stable_binary_layout(inner)
        }
        SemaType::Generic { base, args } => {
            (base.eq_ignore_ascii_case("array") || base.eq_ignore_ascii_case("dinArray.binary"))
                && args.iter().all(sema_type_has_stable_binary_layout)
        }
        SemaType::Union(items) => items.iter().all(sema_type_has_stable_binary_layout),
    }
}

fn validate_destructure_contract(
    kind: DestructureKind,
    args: &[Expr],
    arg_types: &[SemaType],
) -> Result<(), String> {
    if matches!(kind, DestructureKind::Default) || args.is_empty() {
        return Err(
            "E_DESTRUCTURE_UNSUPPORTED_001: destructure unsupported for this type/shape"
                .to_string(),
        );
    }

    if matches!(kind, DestructureKind::Move)
        && arg_types
            .first()
            .is_some_and(|ty| sema_type_is_nullable_like(ty) || sema_type_is_unknown(ty))
    {
        return Err("E_DESTRUCTURE_MOVE_001: invalid move destructure".to_string());
    }

    if matches!(kind, DestructureKind::Ownership)
        && arg_types.first().is_some_and(sema_type_is_nullable_like)
    {
        return Err(
            "E_DESTRUCTURE_OWNERSHIP_001: destructure violates ownership contract".to_string(),
        );
    }

    if matches!(kind, DestructureKind::Region) {
        let valid_region = arg_types.first().is_some_and(sema_type_is_memregion_family);
        let bad_start = args
            .get(1)
            .and_then(sema_expr_integer_literal_value)
            .is_some_and(|value| value < 0);
        let bad_len = args
            .get(2)
            .and_then(sema_expr_integer_literal_value)
            .is_some_and(|value| value <= 0);
        if !valid_region || bad_start || bad_len {
            return Err(
                "E_DESTRUCTURE_REGION_BOUNDS_001: region destructure out of bounds or invalid region"
                    .to_string(),
            );
        }
    }

    if matches!(kind, DestructureKind::Binary)
        && arg_types
            .first()
            .is_some_and(|ty| !sema_type_has_stable_binary_layout(ty))
    {
        return Err(
            "E_DESTRUCTURE_BINARY_LAYOUT_001: binary destructure requires stable layout"
                .to_string(),
        );
    }

    Ok(())
}

fn validate_constructure_contract(
    kind: ConstructureKind,
    args: &[Expr],
    arg_types: &[SemaType],
) -> Result<(), String> {
    if args.is_empty() {
        return Err(
            "E_CONSTRUCTURE_FIELD_MISSING_001: constructure missing required field".to_string(),
        );
    }

    if matches!(kind, ConstructureKind::Move)
        && arg_types
            .first()
            .is_some_and(|ty| sema_type_is_nullable_like(ty) || sema_type_is_unknown(ty))
    {
        return Err("E_CONSTRUCTURE_MOVE_001: invalid move constructure".to_string());
    }

    if matches!(kind, ConstructureKind::Region)
        && arg_types
            .first()
            .is_some_and(|ty| !sema_type_is_memregion_family(ty))
    {
        return Err("E_CONSTRUCTURE_REGION_001: invalid region constructure".to_string());
    }

    if matches!(kind, ConstructureKind::Binary)
        && arg_types
            .first()
            .is_some_and(|ty| !sema_type_has_stable_binary_layout(ty))
    {
        return Err(
            "E_CONSTRUCTURE_BINARY_LAYOUT_001: binary constructure layout invalid".to_string(),
        );
    }

    Ok(())
}

fn official_condition_type_error(kind: &str, ty: &SemaType) -> String {
    if sema_type_is_nullable_like(ty) {
        return format!(
            "E_NULL_CONDITION_001: nullable value must be refined before {kind} condition"
        );
    }
    format!(
        "E_CONDITION_BOOL_REQUIRED_001: {kind} condition must be bool, got {:?}",
        ty
    )
}

fn match_case_key(expr: &Expr) -> Option<String> {
    match expr {
        Expr::Bool(value) => Some(format!("bool:{value}")),
        Expr::Number(value) => Some(format!("number:{value}")),
        Expr::String(value) => Some(format!("string:{value}")),
        Expr::Identifier(value) => Some(format!("ident:{value}")),
        _ => None,
    }
}

#[derive(Debug, Clone)]
struct RecordPatternLayout {
    name: String,
    fields: HashMap<String, SemaType>,
    is_union: bool,
}

#[derive(Debug, Clone, Default)]
struct PatternAnalysis {
    irrefutable: bool,
    requires_guard: bool,
    enum_variant: Option<String>,
    scalar_interval: Option<(i128, i128)>,
    scalar_key: Option<String>,
}

fn collect_record_pattern_layouts(program: &Program) -> HashMap<String, RecordPatternLayout> {
    let mut layouts = HashMap::new();
    for (name, fields) in collect_record_type_layouts(program).iter() {
        layouts.insert(
            name.to_ascii_lowercase(),
            RecordPatternLayout {
                name: name.clone(),
                fields: fields.clone(),
                is_union: false,
            },
        );
    }
    for container in &program.containers {
        for section in &container.sections {
            let Section::TypeContracts(contracts) = section else {
                continue;
            };
            for contract in contracts {
                if !matches!(
                    contract.kind,
                    TypeContractKind::Struct | TypeContractKind::Union
                ) {
                    continue;
                }
                let mut fields = HashMap::new();
                for clause in &contract.clauses {
                    if let TypeContractClause::Fields {
                        fields: declarations,
                        ..
                    } = clause
                    {
                        for field in declarations {
                            fields.insert(field.name.clone(), lower_type(&field.ty));
                        }
                    }
                }
                layouts.insert(
                    contract.name.to_ascii_lowercase(),
                    RecordPatternLayout {
                        name: contract.name.clone(),
                        fields,
                        is_union: matches!(contract.kind, TypeContractKind::Union),
                    },
                );
            }
        }
    }
    layouts
}

fn pattern_type_name_matches(expected: &SemaType, pattern_name: &str) -> bool {
    match expected {
        SemaType::Simple(name) => name.eq_ignore_ascii_case(pattern_name),
        SemaType::Generic { base, .. } => base.eq_ignore_ascii_case(pattern_name),
        _ => false,
    }
}

fn pattern_array_shape(ty: &SemaType) -> Option<(SemaType, Option<usize>)> {
    match ty {
        SemaType::Array(inner) | SemaType::Vector(inner) => Some(((**inner).clone(), None)),
        SemaType::Generic { base, args }
            if (base.eq_ignore_ascii_case("array")
                || base.eq_ignore_ascii_case("vector")
                || base.eq_ignore_ascii_case("list"))
                && !args.is_empty() =>
        {
            let fixed_len = args.get(1).and_then(|arg| match arg {
                SemaType::Simple(raw) => {
                    sema_parse_integer_literal(raw).and_then(|value| usize::try_from(value).ok())
                }
                _ => None,
            });
            Some((args[0].clone(), fixed_len))
        }
        _ => None,
    }
}

fn pattern_scalar_value(expr: &Expr) -> Option<i128> {
    match expr {
        Expr::Number(raw) => {
            let compact = raw.replace('_', "");
            if let Some(hex) = compact
                .strip_prefix("0x")
                .or_else(|| compact.strip_prefix("0X"))
            {
                i128::from_str_radix(hex, 16).ok()
            } else if let Some(bin) = compact
                .strip_prefix("0b")
                .or_else(|| compact.strip_prefix("0B"))
            {
                i128::from_str_radix(bin, 2).ok()
            } else if let Some(oct) = compact
                .strip_prefix("0o")
                .or_else(|| compact.strip_prefix("0O"))
            {
                i128::from_str_radix(oct, 8).ok()
            } else {
                compact.parse::<i128>().ok()
            }
        }
        Expr::Char(ch) => Some(i128::from(*ch as u32)),
        Expr::Bool(value) => Some(i128::from(*value)),
        Expr::Unary {
            op: UnaryOp::Minus,
            expr,
        } => pattern_scalar_value(expr).and_then(i128::checked_neg),
        Expr::Unary {
            op: UnaryOp::Plus,
            expr,
        } => pattern_scalar_value(expr),
        _ => None,
    }
}

fn pattern_scalar_domain(ty: &SemaType) -> Option<(i128, i128)> {
    let SemaType::Simple(name) = ty else {
        return None;
    };
    match normalize_type_name(name) {
        "bool" => Some((0, 1)),
        "byte" | "u8" => Some((0, u8::MAX.into())),
        "sbyte" | "i8" => Some((i8::MIN.into(), i8::MAX.into())),
        "word" | "u16" => Some((0, u16::MAX.into())),
        "sword" | "i16" => Some((i16::MIN.into(), i16::MAX.into())),
        "dword" | "u32" => Some((0, u32::MAX.into())),
        "sdword" | "i32" | "int" => Some((i32::MIN.into(), i32::MAX.into())),
        "qword" | "u64" => Some((0, u64::MAX.into())),
        "sqword" | "i64" => Some((i64::MIN.into(), i64::MAX.into())),
        "char" => Some((0, 0x10ffff)),
        _ => None,
    }
}

fn insert_pattern_binding(
    raw: &str,
    expected: &SemaType,
    scope: &mut HashMap<String, SemaType>,
    binding_names: &mut HashSet<String>,
) -> Result<(), String> {
    let name = pattern_binding_name(raw);
    if name == "_" {
        return Ok(());
    }
    if !binding_names.insert(name.to_string()) {
        return Err(format!(
            "E_HIGH_PATTERN_BINDING_DUP_001: duplicate binding '{}'",
            name
        ));
    }
    if let Some(annotation) = pattern_binding_annotation(raw) {
        if !type_compatible(expected, &annotation) && !type_compatible(&annotation, expected) {
            return Err(format!(
                "E_HIGH_PATTERN_TYPE_001: binding '{}' expected {}, got {}",
                name,
                render_sema_type(&annotation),
                render_sema_type(expected)
            ));
        }
    }
    scope.insert(name.to_string(), expected.clone());
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn analyze_typed_pattern(
    program: &Program,
    current_container_name: &str,
    pattern: &Pattern,
    expected: &SemaType,
    scope: &mut HashMap<String, SemaType>,
    current_context: &Option<Context>,
    enums: &HashMap<String, HighEnumInfo>,
    records: &HashMap<String, RecordPatternLayout>,
    binding_names: &mut HashSet<String>,
) -> Result<PatternAnalysis, String> {
    match pattern {
        Pattern::Wildcard => Ok(PatternAnalysis {
            irrefutable: true,
            ..PatternAnalysis::default()
        }),
        Pattern::Binding(raw) => {
            insert_pattern_binding(raw, expected, scope, binding_names)?;
            Ok(PatternAnalysis {
                irrefutable: true,
                ..PatternAnalysis::default()
            })
        }
        Pattern::Literal(expr) => {
            let literal_ty = infer_expr_type_with_expected(
                program,
                current_container_name,
                expr,
                Some(expected),
                scope,
                current_context,
            )?;
            if !type_compatible(&literal_ty, expected) && !type_compatible(expected, &literal_ty) {
                return Err(format!(
                    "E_HIGH_PATTERN_TYPE_001: literal pattern expected {}, got {}",
                    render_sema_type(expected),
                    render_sema_type(&literal_ty)
                ));
            }
            let scalar = pattern_scalar_value(expr);
            Ok(PatternAnalysis {
                scalar_interval: scalar.map(|value| (value, value)),
                scalar_key: match_case_key(expr),
                ..PatternAnalysis::default()
            })
        }
        Pattern::Range {
            start,
            end,
            inclusive,
        } => {
            let start_ty = infer_expr_type_with_expected(
                program,
                current_container_name,
                start,
                Some(expected),
                scope,
                current_context,
            )?;
            let end_ty = infer_expr_type_with_expected(
                program,
                current_container_name,
                end,
                Some(expected),
                scope,
                current_context,
            )?;
            if pattern_scalar_domain(expected).is_none()
                || !type_compatible(&start_ty, expected)
                || !type_compatible(&end_ty, expected)
            {
                return Err(format!(
                    "E_HIGH_PATTERN_RANGE_TYPE_001: range pattern requires a compatible integer or char scrutinee, got {}",
                    render_sema_type(expected)
                ));
            }
            let start = pattern_scalar_value(start).ok_or_else(|| {
                "E_HIGH_PATTERN_RANGE_001: range start must be a compile-time integer or char literal"
                    .to_string()
            })?;
            let raw_end = pattern_scalar_value(end).ok_or_else(|| {
                "E_HIGH_PATTERN_RANGE_001: range end must be a compile-time integer or char literal"
                    .to_string()
            })?;
            let end = if *inclusive {
                raw_end
            } else {
                raw_end.checked_sub(1).ok_or_else(|| {
                    "E_HIGH_PATTERN_RANGE_EMPTY_001: exclusive range has no values".to_string()
                })?
            };
            if start > end {
                return Err(format!(
                    "E_HIGH_PATTERN_RANGE_EMPTY_001: empty pattern range {}..{}{}",
                    start,
                    if *inclusive { "=" } else { "" },
                    raw_end
                ));
            }
            let domain = pattern_scalar_domain(expected).expect("domain checked above");
            if start < domain.0 || end > domain.1 {
                return Err(format!(
                    "E_HIGH_PATTERN_RANGE_BOUNDS_001: range {}..={} exceeds {} domain {}..={} ",
                    start,
                    end,
                    render_sema_type(expected),
                    domain.0,
                    domain.1
                ));
            }
            Ok(PatternAnalysis {
                scalar_interval: Some((start, end)),
                ..PatternAnalysis::default()
            })
        }
        Pattern::Variant {
            enum_name,
            variant_name,
            bindings,
        } => {
            let items = bindings
                .iter()
                .cloned()
                .map(Pattern::Binding)
                .collect::<Vec<_>>();
            analyze_variant_pattern(
                program,
                current_container_name,
                enum_name,
                variant_name,
                &items,
                expected,
                scope,
                current_context,
                enums,
                records,
                binding_names,
            )
        }
        Pattern::VariantPattern {
            enum_name,
            variant_name,
            items,
        } => analyze_variant_pattern(
            program,
            current_container_name,
            enum_name,
            variant_name,
            items,
            expected,
            scope,
            current_context,
            enums,
            records,
            binding_names,
        ),
        Pattern::Struct {
            type_name,
            fields,
            has_rest,
        } => {
            let Some(layout) = records.get(&type_name.to_ascii_lowercase()) else {
                return Err(format!(
                    "E_HIGH_PATTERN_STRUCT_UNKNOWN_001: unknown struct or union '{}'",
                    type_name
                ));
            };
            if !pattern_type_name_matches(expected, &layout.name) {
                return Err(format!(
                    "E_HIGH_PATTERN_TYPE_001: pattern '{}' cannot match {}",
                    layout.name,
                    render_sema_type(expected)
                ));
            }
            let mut seen_fields = HashSet::new();
            let mut all_irrefutable = true;
            for field in fields {
                let key = field.name.to_ascii_lowercase();
                if !seen_fields.insert(key.clone()) {
                    return Err(format!(
                        "E_HIGH_PATTERN_FIELD_DUP_001: duplicate field '{}.{}'",
                        layout.name, field.name
                    ));
                }
                let Some((_, field_ty)) = layout
                    .fields
                    .iter()
                    .find(|(name, _)| name.eq_ignore_ascii_case(&field.name))
                else {
                    return Err(format!(
                        "E_HIGH_PATTERN_FIELD_UNKNOWN_001: unknown field '{}.{}'",
                        layout.name, field.name
                    ));
                };
                let analysis = analyze_typed_pattern(
                    program,
                    current_container_name,
                    &field.pattern,
                    field_ty,
                    scope,
                    current_context,
                    enums,
                    records,
                    binding_names,
                )?;
                all_irrefutable &= analysis.irrefutable;
            }
            let covers_all_fields = *has_rest || seen_fields.len() == layout.fields.len();
            Ok(PatternAnalysis {
                irrefutable: !layout.is_union && covers_all_fields && all_irrefutable,
                requires_guard: layout.is_union,
                ..PatternAnalysis::default()
            })
        }
        Pattern::Array { items, rest } => {
            let Some((item_ty, fixed_len)) = pattern_array_shape(expected) else {
                return Err(format!(
                    "E_HIGH_PATTERN_ARRAY_TYPE_001: array pattern cannot match {}",
                    render_sema_type(expected)
                ));
            };
            if let Some(len) = fixed_len {
                if rest.is_none() && items.len() != len {
                    return Err(format!(
                        "E_HIGH_PATTERN_ARRAY_ARITY_001: fixed array pattern expects {} items, got {}",
                        len,
                        items.len()
                    ));
                }
                if rest.is_some() && items.len() > len {
                    return Err(format!(
                        "E_HIGH_PATTERN_ARRAY_ARITY_001: fixed array pattern has {} leading items for length {}",
                        items.len(), len
                    ));
                }
            }
            let mut all_irrefutable = true;
            for item in items {
                let analysis = analyze_typed_pattern(
                    program,
                    current_container_name,
                    item,
                    &item_ty,
                    scope,
                    current_context,
                    enums,
                    records,
                    binding_names,
                )?;
                all_irrefutable &= analysis.irrefutable;
            }
            if let Some(rest_name) = rest {
                insert_pattern_binding(rest_name, expected, scope, binding_names)?;
            }
            let length_irrefutable = match fixed_len {
                Some(len) => {
                    (rest.is_some() && items.len() <= len) || (rest.is_none() && items.len() == len)
                }
                None => rest.is_some() && items.is_empty(),
            };
            Ok(PatternAnalysis {
                irrefutable: length_irrefutable && all_irrefutable,
                ..PatternAnalysis::default()
            })
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn analyze_variant_pattern(
    program: &Program,
    current_container_name: &str,
    enum_name: &str,
    variant_name: &str,
    items: &[Pattern],
    expected: &SemaType,
    scope: &mut HashMap<String, SemaType>,
    current_context: &Option<Context>,
    enums: &HashMap<String, HighEnumInfo>,
    records: &HashMap<String, RecordPatternLayout>,
    binding_names: &mut HashSet<String>,
) -> Result<PatternAnalysis, String> {
    let Some(enum_info) = enums.get(&enum_name.to_ascii_lowercase()) else {
        return Err(format!(
            "E_HIGH_ENUM_UNKNOWN_001: unknown pattern enum '{}'",
            enum_name
        ));
    };
    if !high_enum_type_matches(&enum_info.name, expected) {
        return Err(format!(
            "E_HIGH_MATCH_SCRUTINEE_001: enum pattern '{}.{}' cannot match {}",
            enum_name,
            variant_name,
            render_sema_type(expected)
        ));
    }
    let Some(variant) = enum_info.variants.get(&variant_name.to_ascii_lowercase()) else {
        return Err(format!(
            "E_HIGH_ENUM_VARIANT_UNKNOWN_001: unknown variant '{}.{}'",
            enum_info.name, variant_name
        ));
    };
    if items.len() != variant.payload.len() {
        return Err(format!(
            "E_HIGH_PATTERN_ARITY_001: pattern '{}.{}' expects {} items, got {}",
            enum_info.name,
            variant.name,
            variant.payload.len(),
            items.len()
        ));
    }
    let mut payload_irrefutable = true;
    for (item, (_, payload_ty)) in items.iter().zip(&variant.payload) {
        let resolved = substitute_enum_payload_type(payload_ty, expected, enum_info);
        let analysis = analyze_typed_pattern(
            program,
            current_container_name,
            item,
            &resolved,
            scope,
            current_context,
            enums,
            records,
            binding_names,
        )?;
        payload_irrefutable &= analysis.irrefutable;
    }
    Ok(PatternAnalysis {
        irrefutable: false,
        enum_variant: payload_irrefutable.then(|| variant.name.to_ascii_lowercase()),
        ..PatternAnalysis::default()
    })
}

fn interval_is_covered(intervals: &[(i128, i128)], wanted: (i128, i128)) -> bool {
    let mut cursor = wanted.0;
    let mut ordered = intervals.to_vec();
    ordered.sort_unstable_by_key(|interval| interval.0);
    for (start, end) in ordered {
        if end < cursor {
            continue;
        }
        if start > cursor {
            return false;
        }
        if end >= wanted.1 {
            return true;
        }
        let Some(next) = end.checked_add(1) else {
            return true;
        };
        cursor = next;
    }
    false
}

#[allow(clippy::too_many_arguments)]
fn analyze_pattern_match_stmt(
    program: &Program,
    current_container_name: &str,
    value: &Expr,
    arms: &[MatchArm],
    scope: &mut HashMap<String, SemaType>,
    pointer_states: &mut HashMap<String, PointerState>,
    flow_alias_map: &mut FlowAliasMap,
    expected_return: &SemaType,
    strict_ctx: &StrictContext,
    current_context: &Option<Context>,
) -> Result<FlowOutcome, String> {
    if arms.is_empty() {
        return Err("E_HIGH_MATCH_EMPTY_001: match requires at least one arm".into());
    }

    let value_ty = infer_expr_type(
        program,
        current_container_name,
        value,
        scope,
        current_context,
    )?;
    if sema_type_contains_any(&value_ty) {
        return Err("E_HIGH_ANY_LEAK_001: any leak through match is forbidden".into());
    }
    let enums = collect_high_enums(program)?;
    let records = collect_record_pattern_layouts(program);
    let enum_info = enums
        .values()
        .find(|info| high_enum_type_matches(&info.name, &value_ty));

    let base_scope = scope.clone();
    let mut covered_variants: HashSet<String> = HashSet::new();
    let mut seen_scalar_literal_arms: HashSet<String> = HashSet::new();
    let mut seen_unguarded_patterns: HashSet<String> = HashSet::new();
    let mut covered_intervals: Vec<(i128, i128)> = Vec::new();
    let mut wildcard_seen = false;
    let mut scalar_exhaustive = false;
    let mut any_fallthrough = false;
    let mut merged_scope = base_scope.clone();
    let mut merged_pointer_states = pointer_states.clone();
    let mut merged_flow_alias_map = flow_alias_map.clone();

    for (idx, arm) in arms.iter().enumerate() {
        if wildcard_seen {
            return Err(format!(
                "E_HIGH_MATCH_UNREACHABLE_ARM_001: arm {} is unreachable after wildcard",
                idx + 1
            ));
        }

        let mut arm_scope = base_scope.clone();
        let mut binding_names = HashSet::new();
        let analysis = analyze_typed_pattern(
            program,
            current_container_name,
            &arm.pattern,
            &value_ty,
            &mut arm_scope,
            current_context,
            &enums,
            &records,
            &mut binding_names,
        )?;
        let pattern_key = format!("{:?}", arm.pattern);
        if seen_unguarded_patterns.contains(&pattern_key) {
            return Err(format!(
                "E_HIGH_MATCH_UNREACHABLE_ARM_001: arm {} repeats an already complete pattern",
                idx + 1
            ));
        }
        if let Some(interval) = analysis.scalar_interval {
            if interval_is_covered(&covered_intervals, interval) {
                return Err(format!(
                    "E_HIGH_MATCH_UNREACHABLE_ARM_001: scalar arm {} is covered by previous ranges",
                    idx + 1
                ));
            }
        }
        if let Some(variant) = &analysis.enum_variant {
            if covered_variants.contains(variant) {
                return Err(format!(
                    "E_HIGH_MATCH_UNREACHABLE_ARM_001: arm {} is covered by the previous '{}.{}' arm",
                    idx + 1,
                    enum_info.map(|info| info.name.as_str()).unwrap_or("enum"),
                    variant
                ));
            }
        }
        if analysis.requires_guard && arm.guard.is_none() {
            return Err(format!(
                "E_HIGH_PATTERN_UNION_GUARD_001: raw union arm {} requires an explicit bool guard because the union has no active tag",
                idx + 1
            ));
        }

        let guard_always_true = matches!(arm.guard, Some(Expr::Bool(true)));
        if let Some(guard) = &arm.guard {
            if matches!(guard, Expr::Bool(false)) {
                return Err(format!(
                    "E_HIGH_MATCH_UNREACHABLE_ARM_001: arm {} has an always-false guard",
                    idx + 1
                ));
            }
            let guard_ty = infer_expr_type(
                program,
                current_container_name,
                guard,
                &arm_scope,
                current_context,
            )?;
            if !is_bool_like_condition(&guard_ty) {
                return Err(format!(
                    "E_HIGH_GUARD_TYPE_001: match guard must be bool, got {:?}",
                    guard_ty
                ));
            }
        }

        let arm_covers = arm.guard.is_none() || guard_always_true;
        if arm_covers {
            seen_unguarded_patterns.insert(pattern_key);
            if analysis.irrefutable {
                wildcard_seen = true;
                if enum_info.is_none() {
                    scalar_exhaustive = true;
                }
            }
            if let Some(variant_key) = analysis.enum_variant {
                covered_variants.insert(variant_key);
            }
            if let Some(interval) = analysis.scalar_interval {
                covered_intervals.push(interval);
            }
            if let Some(key) = analysis.scalar_key {
                seen_scalar_literal_arms.insert(key);
            }
        }

        if let Some(Stmt::Return(expr)) = arm.body.first() {
            let ret_ty = infer_expr_type_with_expected(
                program,
                current_container_name,
                expr,
                Some(expected_return),
                &arm_scope,
                current_context,
            )?;
            if !return_abi_coercible(&ret_ty, expected_return) {
                return Err(format!(
                    "E_HIGH_MATCH_ARM_TYPE_001: match arm return expected {:?}, got {:?}",
                    expected_return, ret_ty
                ));
            }
        }

        let mut arm_pointer_states = pointer_states.clone();
        let mut arm_flow_alias_map = flow_alias_map.clone();
        let outcome = analyze_stmt_block(
            program,
            current_container_name,
            &arm.body,
            &mut arm_scope,
            &mut arm_pointer_states,
            &mut arm_flow_alias_map,
            expected_return,
            strict_ctx,
            current_context,
        )?;
        if matches!(outcome, FlowOutcome::FallsThrough) {
            any_fallthrough = true;
        }
        merged_scope = merge_scope_for_cfg(&merged_scope, &arm_scope, &merged_scope);
        merged_pointer_states =
            merge_pointer_states_for_cfg(&merged_pointer_states, &arm_pointer_states);
        merged_flow_alias_map = merge_flow_alias_maps_for_cfg(
            &merged_flow_alias_map,
            &arm_flow_alias_map,
            &mut merged_pointer_states,
        );
    }

    if let Some(enum_info) = enum_info {
        if !wildcard_seen {
            let missing = enum_info
                .variants
                .values()
                .filter(|variant| !covered_variants.contains(&variant.name.to_ascii_lowercase()))
                .map(|variant| variant.name.clone())
                .collect::<Vec<_>>();
            if !missing.is_empty() {
                return Err(format!(
                    "E_HIGH_MATCH_NON_EXHAUSTIVE_001: match missing variants {}",
                    missing.join(", ")
                ));
            }
        }
    } else if !scalar_exhaustive {
        let bool_exhaustive = matches!(&value_ty, SemaType::Simple(name) if name == "bool")
            && seen_scalar_literal_arms.contains("bool:true")
            && seen_scalar_literal_arms.contains("bool:false");
        let interval_exhaustive = pattern_scalar_domain(&value_ty)
            .is_some_and(|domain| interval_is_covered(&covered_intervals, domain));
        if !bool_exhaustive && !interval_exhaustive {
            return Err(
                "E_HIGH_MATCH_NON_EXHAUSTIVE_001: match requires a wildcard/binding or complete enum, bool, integer or char coverage"
                    .into(),
            );
        }
    }

    *scope = merged_scope;
    *pointer_states = merged_pointer_states;
    *flow_alias_map = merged_flow_alias_map;

    if any_fallthrough {
        Ok(FlowOutcome::FallsThrough)
    } else {
        Ok(FlowOutcome::Terminated)
    }
}

#[cfg(test)]
mod exhaustive_pattern_semantics_tests {
    use super::*;

    fn check(source: &str) -> Result<SemanticResult, String> {
        let tokens = ncc_lexer::lex(source).expect("pattern fixture must lex");
        let program = ncc_parser::parse(tokens).expect("pattern fixture must parse");
        analyze(&program)
    }

    #[test]
    fn ranges_structs_arrays_nested_variants_and_effectful_guards_are_typed() {
        let source = r#"
patternComplete {
    type:
        Point {
            public:
                x: int;
                y: int;
        }

    enum:
        MaybePair {
            Pair(value: array<int, 2>);
            Empty;
        }

    fn:
        positive(value: byte) -> bool {
            public:
                return @value > 0;
        }

        classify(value: byte) -> int {
            public:
                match (@value) {
                    0..=9 if positive(@value) => return 1;
                    0..=9 => return 2;
                    10..=255 => return 3;
                }
        }

        pointValue(point: Point) -> int {
            public:
                match (@point) {
                    Point { x, y } => return @x + @y;
                }
        }

        arrayValue(values: array<int, 3>) -> int {
            public:
                match (@values) {
                    [0, value, _] => return @value;
                    [_, _, _] => return 0;
                }
        }

        nested(value: MaybePair) -> int {
            public:
                match (@value) {
                    MaybePair.Pair([0, item]) => return @item;
                    MaybePair.Pair([_, _]) => return 1;
                    MaybePair.Empty => return 0;
                }
        }

    fa:
        return true;
}
"#;
        check(source).expect("complete structural pattern surface must pass sema");
    }

    #[test]
    fn scalar_gap_is_rejected() {
        let source = r#"
patternGap {
    fn:
        classify(value: byte) -> int {
            public:
                match (@value) {
                    0..=9 => return 1;
                    11..=255 => return 2;
                }
        }
    fa:
        return true;
}
"#;
        let error = check(source).expect_err("range gap must be diagnosed");
        assert!(error.contains("E_HIGH_MATCH_NON_EXHAUSTIVE_001"), "{error}");
    }

    #[test]
    fn covered_range_arm_is_rejected_as_unreachable() {
        let source = r#"
patternUnreachable {
    fn:
        classify(value: byte) -> int {
            public:
                match (@value) {
                    0..=20 => return 1;
                    5..=10 => return 2;
                    21..=255 => return 3;
                }
        }
    fa:
        return true;
}
"#;
        let error = check(source).expect_err("covered interval must be diagnosed");
        assert!(
            error.contains("E_HIGH_MATCH_UNREACHABLE_ARM_001"),
            "{error}"
        );
    }

    #[test]
    fn raw_union_needs_an_explicit_catch_all() {
        let source = r#"
patternUnion {
    type:
        Value union {
            public:
                word: int;
                wide: qword;
        }

    fn:
        useWord(value: Value) -> bool {
            public:
                return true;
        }

        inspect(value: Value) -> int {
            public:
                match (@value) {
                    Value { word } if useWord(@value) => return @word;
                }
        }
    fa:
        return true;
}
"#;
        let error = check(source).expect_err("raw union cannot prove total active-field coverage");
        assert!(error.contains("E_HIGH_MATCH_NON_EXHAUSTIVE_001"), "{error}");
    }
}

#[allow(clippy::too_many_arguments)]
fn analyze_stmt(
    program: &Program,
    current_container_name: &str,
    stmt: &Stmt,
    scope: &mut HashMap<String, SemaType>,
    pointer_states: &mut HashMap<String, PointerState>,
    flow_alias_map: &mut FlowAliasMap,
    expected_return: &SemaType,
    strict_ctx: &StrictContext,
    current_context: &Option<Context>,
) -> Result<FlowOutcome, String> {
    match stmt {
        Stmt::Return(expr) => {
            let got = if let Expr::Closure(closure) = expr {
                let declared_return = lower_type(&closure.return_type);
                let callable_return = if closure.is_async {
                    SemaType::Generic {
                        base: "Future".into(),
                        args: vec![declared_return],
                    }
                } else {
                    declared_return
                };
                closure_function_type(
                    closure
                        .params
                        .iter()
                        .map(|param| lower_type(&param.ty))
                        .collect(),
                    callable_return,
                )
            } else {
                infer_expr_type_with_expected(
                    program,
                    current_container_name,
                    expr,
                    Some(expected_return),
                    scope,
                    current_context,
                )?
            };
            if sema_type_is_void(expected_return) {
                // The expression is still analyzed and evaluated for effects;
                // the declared void ABI deliberately discards its material value.
            } else {
                if sema_type_is_void(&got) {
                    return Err(format!(
                        "E_VOID_VALUE_001: void cannot be used as value for return type {:?}",
                        expected_return
                    ));
                }
                if is_null_expr(expr)
                    && !allows_null_assignment_type(expected_return)
                    && !silent_pointer_accepts_null_target(expected_return)
                {
                    return Err(pointer_diag(
                        E_PTR_NULL_DEREF,
                        format!(
                            "null requires explicit nullable return type, got {:?}",
                            expected_return
                        ),
                    ));
                }
            }

            let raw_null_pointer_return = silent_pointer_acceptance_enabled()
                && is_null_expr(expr)
                && is_raw_pointer_type(expected_return);
            if !raw_null_pointer_return && !return_abi_coercible(&got, expected_return) {
                return Err(format!(
                    "return type mismatch: expected {:?}, got {:?}",
                    expected_return, got
                ));
            }

            if is_pointer_family_type(expected_return) {
                if let Some(source_name) = root_context_name_from_expr(expr) {
                    validate_return_pointer_state(&source_name, expected_return, pointer_states)?;
                }
            }

            apply_heap_manager_effects_in_expr(
                program,
                current_container_name,
                expr,
                scope,
                current_context,
                pointer_states,
                flow_alias_map,
            )?;
            return Ok(FlowOutcome::Terminated);
        }

        Stmt::If {
            condition,
            then_block,
            else_block,
        } => {
            let cond_ty = infer_expr_type(
                program,
                current_container_name,
                condition,
                scope,
                current_context,
            )?;
            if !is_bool_like_condition(&cond_ty) {
                return Err(official_condition_type_error("if", &cond_ty));
            }

            apply_heap_manager_effects_in_expr(
                program,
                current_container_name,
                condition,
                scope,
                current_context,
                pointer_states,
                flow_alias_map,
            )?;

            let condition_narrows_scope = match condition {
                Expr::StrictCheckExpr { target, .. } => target.path.len() == 1,
                Expr::Binary {
                    op: BinaryOp::AndAnd,
                    left,
                    right,
                } => [&**left, &**right].iter().any(|part| {
                    matches!(part, Expr::StrictCheckExpr { target, .. } if target.path.len() == 1)
                }),
                _ => false,
            };

            // A very common lookup-table shape is a sequence of
            // `if (key == literal) { return value; }`.  The false branch keeps
            // the current state verbatim, so constructing and merging three
            // complete scope snapshots only adds quadratic-looking overhead
            // to large source files.
            if else_block.is_empty() && !condition_narrows_scope {
                let mut then_scope = scope.clone();
                let mut then_pointer_states = pointer_states.clone();
                let mut then_flow_alias_map = flow_alias_map.clone();
                let then_outcome = analyze_stmt_block(
                    program,
                    current_container_name,
                    then_block,
                    &mut then_scope,
                    &mut then_pointer_states,
                    &mut then_flow_alias_map,
                    expected_return,
                    strict_ctx,
                    current_context,
                )?;

                if matches!(then_outcome, FlowOutcome::Terminated) {
                    return Ok(FlowOutcome::FallsThrough);
                }

                let merged_scope = merge_scope_for_cfg(scope, &then_scope, scope);
                let mut merged_pointer_states =
                    merge_pointer_states_for_cfg(&then_pointer_states, pointer_states);
                let merged_flow_alias_map = merge_flow_alias_maps_for_cfg(
                    &then_flow_alias_map,
                    flow_alias_map,
                    &mut merged_pointer_states,
                );
                *scope = merged_scope;
                *pointer_states = merged_pointer_states;
                *flow_alias_map = merged_flow_alias_map;
                return Ok(FlowOutcome::FallsThrough);
            }

            let base_scope = scope.clone();
            let mut then_scope = scope.clone();
            let mut else_scope = scope.clone();
            let mut then_pointer_states = pointer_states.clone();
            let mut else_pointer_states = pointer_states.clone();
            let mut then_flow_alias_map = flow_alias_map.clone();
            let mut else_flow_alias_map = flow_alias_map.clone();

            match condition {
                Expr::StrictCheckExpr { target, ty, .. } if target.path.len() == 1 => {
                    let name = &target.path[0];
                    if let Some(orig_ty) = scope.get(name) {
                        let target_ty = lower_type(ty);
                        let narrowed_then = narrow_type(orig_ty, &target_ty);
                        then_scope.insert(name.clone(), narrowed_then);
                        let narrowed_else = exclude_type(orig_ty, &target_ty);
                        else_scope.insert(name.clone(), narrowed_else);
                    }
                }

                Expr::Binary {
                    op: BinaryOp::AndAnd,
                    left,
                    right,
                } => {
                    if let Expr::StrictCheckExpr { target, ty, .. } = &**left {
                        if target.path.len() == 1 {
                            let name = &target.path[0];
                            if let Some(orig_ty) = scope.get(name) {
                                let target_ty = lower_type(ty);
                                let narrowed = narrow_type(orig_ty, &target_ty);
                                then_scope.insert(name.clone(), narrowed);
                            }
                        }
                    }

                    if let Expr::StrictCheckExpr { target, ty, .. } = &**right {
                        if target.path.len() == 1 {
                            let name = &target.path[0];
                            if let Some(orig_ty) = then_scope.get(name) {
                                let target_ty = lower_type(ty);
                                let narrowed = narrow_type(orig_ty, &target_ty);
                                then_scope.insert(name.clone(), narrowed);
                            }
                        }
                    }
                }

                Expr::Binary {
                    op: BinaryOp::OrOr, ..
                } => {}

                _ => {}
            }

            let then_outcome = analyze_stmt_block(
                program,
                current_container_name,
                then_block,
                &mut then_scope,
                &mut then_pointer_states,
                &mut then_flow_alias_map,
                expected_return,
                strict_ctx,
                current_context,
            )?;

            let else_outcome = analyze_stmt_block(
                program,
                current_container_name,
                else_block,
                &mut else_scope,
                &mut else_pointer_states,
                &mut else_flow_alias_map,
                expected_return,
                strict_ctx,
                current_context,
            )?;

            match (then_outcome, else_outcome) {
                (FlowOutcome::FallsThrough, FlowOutcome::FallsThrough) => {
                    *scope = merge_scope_for_cfg(&base_scope, &then_scope, &else_scope);
                    *pointer_states =
                        merge_pointer_states_for_cfg(&then_pointer_states, &else_pointer_states);
                    *flow_alias_map = merge_flow_alias_maps_for_cfg(
                        &then_flow_alias_map,
                        &else_flow_alias_map,
                        pointer_states,
                    );
                    return Ok(FlowOutcome::FallsThrough);
                }
                (FlowOutcome::FallsThrough, FlowOutcome::Terminated) => {
                    *scope = then_scope;
                    *pointer_states = then_pointer_states;
                    *flow_alias_map = then_flow_alias_map;
                    return Ok(FlowOutcome::FallsThrough);
                }
                (FlowOutcome::Terminated, FlowOutcome::FallsThrough) => {
                    *scope = else_scope;
                    *pointer_states = else_pointer_states;
                    *flow_alias_map = else_flow_alias_map;
                    return Ok(FlowOutcome::FallsThrough);
                }
                (FlowOutcome::Terminated, FlowOutcome::Terminated) => {
                    return Ok(FlowOutcome::Terminated);
                }
            }
        }

        Stmt::Unless { condition, body } => {
            if matches!(
                current_context,
                Some(Context::Machine) | Some(Context::Primitive) | Some(Context::Root)
            ) {
                return Err(
                    "E_CONDITION_UNLESS_INVALID_MODE_001: unless is not allowed in this mode"
                        .into(),
                );
            }

            let cond_ty = infer_expr_type(
                program,
                current_container_name,
                condition,
                scope,
                current_context,
            )?;
            if !is_bool_like_condition(&cond_ty) {
                return Err(official_condition_type_error("unless", &cond_ty));
            }

            apply_heap_manager_effects_in_expr(
                program,
                current_container_name,
                condition,
                scope,
                current_context,
                pointer_states,
                flow_alias_map,
            )?;

            let base_scope = scope.clone();
            let base_pointer_states = pointer_states.clone();
            let base_flow_alias_map = flow_alias_map.clone();

            let mut unless_scope = scope.clone();
            let mut unless_pointer_states = pointer_states.clone();
            let mut unless_flow_alias_map = flow_alias_map.clone();

            let body_outcome = analyze_stmt_block(
                program,
                current_container_name,
                body,
                &mut unless_scope,
                &mut unless_pointer_states,
                &mut unless_flow_alias_map,
                expected_return,
                strict_ctx,
                current_context,
            )?;

            return match body_outcome {
                FlowOutcome::FallsThrough => {
                    *scope = merge_scope_for_cfg(&base_scope, &unless_scope, &base_scope);
                    *pointer_states =
                        merge_pointer_states_for_cfg(&unless_pointer_states, &base_pointer_states);
                    *flow_alias_map = merge_flow_alias_maps_for_cfg(
                        &unless_flow_alias_map,
                        &base_flow_alias_map,
                        pointer_states,
                    );
                    Ok(FlowOutcome::FallsThrough)
                }
                FlowOutcome::Terminated => Ok(FlowOutcome::FallsThrough),
            };
        }

        Stmt::While { condition, body } => {
            let cond_ty = infer_expr_type(
                program,
                current_container_name,
                condition,
                scope,
                current_context,
            )?;
            if !is_bool_like_condition(&cond_ty) {
                return Err(official_condition_type_error("while", &cond_ty));
            }

            apply_heap_manager_effects_in_expr(
                program,
                current_container_name,
                condition,
                scope,
                current_context,
                pointer_states,
                flow_alias_map,
            )?;

            let base_scope = scope.clone();
            let base_pointer_states = pointer_states.clone();
            let base_flow_alias_map = flow_alias_map.clone();

            let mut loop_scope = scope.clone();
            let mut loop_pointer_states = pointer_states.clone();
            let mut loop_flow_alias_map = flow_alias_map.clone();

            let loop_outcome = analyze_stmt_block(
                program,
                current_container_name,
                body,
                &mut loop_scope,
                &mut loop_pointer_states,
                &mut loop_flow_alias_map,
                expected_return,
                strict_ctx,
                current_context,
            )?;

            match loop_outcome {
                FlowOutcome::FallsThrough => {
                    *scope = merge_scope_for_cfg(&base_scope, &loop_scope, &base_scope);
                    *pointer_states =
                        merge_pointer_states_for_cfg(&loop_pointer_states, &base_pointer_states);
                    *flow_alias_map = merge_flow_alias_maps_for_cfg(
                        &loop_flow_alias_map,
                        &base_flow_alias_map,
                        pointer_states,
                    );
                }
                FlowOutcome::Terminated => {
                    *scope = base_scope;
                    *pointer_states = base_pointer_states;
                    *flow_alias_map = base_flow_alias_map;
                }
            }

            return Ok(FlowOutcome::FallsThrough);
        }

        Stmt::DoWhile { body, condition } => {
            let cond_ty = infer_expr_type(
                program,
                current_container_name,
                condition,
                scope,
                current_context,
            )?;
            if !is_bool_like_condition(&cond_ty) {
                return Err(official_condition_type_error("do-while", &cond_ty));
            }
            apply_heap_manager_effects_in_expr(
                program,
                current_container_name,
                condition,
                scope,
                current_context,
                pointer_states,
                flow_alias_map,
            )?;
            let mut loop_scope = scope.clone();
            let mut loop_pointer_states = pointer_states.clone();
            let mut loop_flow_alias_map = flow_alias_map.clone();
            let _ = analyze_stmt_block(
                program,
                current_container_name,
                body,
                &mut loop_scope,
                &mut loop_pointer_states,
                &mut loop_flow_alias_map,
                expected_return,
                strict_ctx,
                current_context,
            )?;
            return Ok(FlowOutcome::FallsThrough);
        }

        Stmt::ForClassic {
            init,
            condition,
            step,
            body,
        } => {
            if let Some(init_stmt) = init {
                let _ = analyze_stmt(
                    program,
                    current_container_name,
                    init_stmt,
                    scope,
                    pointer_states,
                    flow_alias_map,
                    expected_return,
                    strict_ctx,
                    current_context,
                )?;
            }
            if let Some(cond_expr) = condition {
                let cond_ty = infer_expr_type(
                    program,
                    current_container_name,
                    cond_expr,
                    scope,
                    current_context,
                )?;
                if !is_bool_like_condition(&cond_ty) {
                    return Err(official_condition_type_error("for", &cond_ty));
                }
            }
            let mut loop_scope = scope.clone();
            let mut loop_pointer_states = pointer_states.clone();
            let mut loop_flow_alias_map = flow_alias_map.clone();
            let _ = analyze_stmt_block(
                program,
                current_container_name,
                body,
                &mut loop_scope,
                &mut loop_pointer_states,
                &mut loop_flow_alias_map,
                expected_return,
                strict_ctx,
                current_context,
            )?;
            if let Some(step_stmt) = step {
                let _ = analyze_stmt(
                    program,
                    current_container_name,
                    step_stmt,
                    &mut loop_scope,
                    &mut loop_pointer_states,
                    &mut loop_flow_alias_map,
                    expected_return,
                    strict_ctx,
                    current_context,
                )?;
            }
            return Ok(FlowOutcome::FallsThrough);
        }

        Stmt::ForIn {
            item,
            iterable,
            body,
        }
        | Stmt::SameIn {
            item,
            iterable,
            body,
        } => {
            let iter_ty = infer_expr_type(
                program,
                current_container_name,
                iterable,
                scope,
                current_context,
            )?;
            let elem_ty = match iter_ty {
                SemaType::Vector(inner) | SemaType::Array(inner) => *inner,
                SemaType::Generic { base, args }
                    if base.eq_ignore_ascii_case("array") && !args.is_empty() =>
                {
                    args[0].clone()
                }
                SemaType::Generic { base, args } if is_list_family(&base) && args.len() == 1 => {
                    args[0].clone()
                }
                other => {
                    return Err(format!(
                        "E_HIGH_FOR_IN_ITERABLE_001: for-in iterable must be list/vector/array-like, got {:?}",
                        other
                    ))
                }
            };
            if sema_type_contains_any(&elem_ty) {
                return Err("E_HIGH_ANY_LEAK_001: for-in item type cannot be any".into());
            }

            let mut loop_scope = scope.clone();
            loop_scope.insert(item.clone(), elem_ty);
            let mut loop_pointer_states = pointer_states.clone();
            let mut loop_flow_alias_map = flow_alias_map.clone();
            let _ = analyze_stmt_block(
                program,
                current_container_name,
                body,
                &mut loop_scope,
                &mut loop_pointer_states,
                &mut loop_flow_alias_map,
                expected_return,
                strict_ctx,
                current_context,
            )?;
            return Ok(FlowOutcome::FallsThrough);
        }

        Stmt::ForRange {
            item,
            start,
            end,
            step,
            body,
            ..
        } => {
            let start_ty = infer_expr_type(
                program,
                current_container_name,
                start,
                scope,
                current_context,
            )?;
            if !is_integer_like(&start_ty) {
                return Err(format!(
                    "E_HIGH_RANGE_BOUND_001: for-range start must be integer-like, got {:?}",
                    start_ty
                ));
            }
            let end_ty =
                infer_expr_type(program, current_container_name, end, scope, current_context)?;
            if !is_integer_like(&end_ty) {
                return Err(format!(
                    "E_HIGH_RANGE_BOUND_001: for-range end must be integer-like, got {:?}",
                    end_ty
                ));
            }
            if let Some(step_expr) = step {
                if phase8_literal_zero(step_expr) {
                    return Err("E_HIGH_RANGE_STEP_ZERO_001: for-range step cannot be zero".into());
                }
                let step_ty = infer_expr_type(
                    program,
                    current_container_name,
                    step_expr,
                    scope,
                    current_context,
                )?;
                if !is_integer_like(&step_ty) {
                    return Err(format!(
                        "E_HIGH_RANGE_STEP_001: for-range step must be integer-like, got {:?}",
                        step_ty
                    ));
                }
            }
            let mut loop_scope = scope.clone();
            loop_scope.insert(item.clone(), SemaType::Simple("int".into()));
            let mut loop_pointer_states = pointer_states.clone();
            let mut loop_flow_alias_map = flow_alias_map.clone();
            let _ = analyze_stmt_block(
                program,
                current_container_name,
                body,
                &mut loop_scope,
                &mut loop_pointer_states,
                &mut loop_flow_alias_map,
                expected_return,
                strict_ctx,
                current_context,
            )?;
            return Ok(FlowOutcome::FallsThrough);
        }

        Stmt::Loop { body } => {
            let mut loop_scope = scope.clone();
            let mut loop_pointer_states = pointer_states.clone();
            let mut loop_flow_alias_map = flow_alias_map.clone();
            let _ = analyze_stmt_block(
                program,
                current_container_name,
                body,
                &mut loop_scope,
                &mut loop_pointer_states,
                &mut loop_flow_alias_map,
                expected_return,
                strict_ctx,
                current_context,
            )?;
            return Ok(FlowOutcome::FallsThrough);
        }

        Stmt::RepeatUntil { body, condition } => {
            let cond_ty = infer_expr_type(
                program,
                current_container_name,
                condition,
                scope,
                current_context,
            )?;
            if !is_bool_like_condition(&cond_ty) {
                return Err(official_condition_type_error("until", &cond_ty));
            }
            let mut loop_scope = scope.clone();
            let mut loop_pointer_states = pointer_states.clone();
            let mut loop_flow_alias_map = flow_alias_map.clone();
            let _ = analyze_stmt_block(
                program,
                current_container_name,
                body,
                &mut loop_scope,
                &mut loop_pointer_states,
                &mut loop_flow_alias_map,
                expected_return,
                strict_ctx,
                current_context,
            )?;
            return Ok(FlowOutcome::FallsThrough);
        }

        Stmt::RepeatCount { count, body } => {
            let count_ty = infer_expr_type(
                program,
                current_container_name,
                count,
                scope,
                current_context,
            )?;
            if !is_integer_like(&count_ty) {
                return Err(format!(
                    "repeat count must be integer-like, got {:?}",
                    count_ty
                ));
            }
            if sema_expr_integer_literal_value(count).is_some_and(|value| value < 0) {
                return Err(
                    "E_HIGH_REPEAT_COUNT_NEGATIVE_001: repeat count cannot be negative".into(),
                );
            }
            let mut loop_scope = scope.clone();
            let mut loop_pointer_states = pointer_states.clone();
            let mut loop_flow_alias_map = flow_alias_map.clone();
            let _ = analyze_stmt_block(
                program,
                current_container_name,
                body,
                &mut loop_scope,
                &mut loop_pointer_states,
                &mut loop_flow_alias_map,
                expected_return,
                strict_ctx,
                current_context,
            )?;
            return Ok(FlowOutcome::FallsThrough);
        }

        Stmt::EachDoWhile {
            item,
            iterable,
            body,
            condition,
        } => {
            let iter_ty = infer_expr_type(
                program,
                current_container_name,
                iterable,
                scope,
                current_context,
            )?;
            let elem_ty = match iter_ty {
                SemaType::Vector(inner) | SemaType::Array(inner) => *inner,
                SemaType::Generic { base, args }
                    if base.eq_ignore_ascii_case("array") && !args.is_empty() =>
                {
                    args[0].clone()
                }
                SemaType::Generic { base, args } if is_list_family(&base) && args.len() == 1 => {
                    args[0].clone()
                }
                other => {
                    return Err(format!(
                        "each iterable must be list/vector/array-like, got {:?}",
                        other
                    ))
                }
            };
            let mut loop_scope = scope.clone();
            loop_scope.insert(item.clone(), elem_ty);
            let cond_ty = infer_expr_type(
                program,
                current_container_name,
                condition,
                &loop_scope,
                current_context,
            )?;
            if !is_bool_like_condition(&cond_ty) {
                return Err(official_condition_type_error("each do-while", &cond_ty));
            }
            let mut loop_pointer_states = pointer_states.clone();
            let mut loop_flow_alias_map = flow_alias_map.clone();
            let _ = analyze_stmt_block(
                program,
                current_container_name,
                body,
                &mut loop_scope,
                &mut loop_pointer_states,
                &mut loop_flow_alias_map,
                expected_return,
                strict_ctx,
                current_context,
            )?;
            return Ok(FlowOutcome::FallsThrough);
        }

        Stmt::PatternMatch { value, arms } => {
            return analyze_pattern_match_stmt(
                program,
                current_container_name,
                value,
                arms,
                scope,
                pointer_states,
                flow_alias_map,
                expected_return,
                strict_ctx,
                current_context,
            );
        }

        Stmt::Switch {
            value,
            cases,
            default,
        }
        | Stmt::Match {
            value,
            cases,
            default,
        } => {
            let value_ty = infer_expr_type(
                program,
                current_container_name,
                value,
                scope,
                current_context,
            )?;
            if matches!(stmt, Stmt::Match { .. }) && default.is_empty() {
                return Err("E_CONDITION_MATCH_NON_EXHAUSTIVE_001: match is non-exhaustive".into());
            }
            let mut seen_case_keys: HashSet<String> = HashSet::new();
            let base_scope = scope.clone();
            let mut any_fallthrough = false;
            let mut merged_scope = base_scope.clone();
            let mut merged_pointer_states = pointer_states.clone();
            let mut merged_flow_alias_map = flow_alias_map.clone();

            for (case_expr, block) in cases {
                if let Some(key) = match_case_key(case_expr) {
                    if !seen_case_keys.insert(key.clone()) {
                        return Err(format!(
                            "E_CONDITION_MATCH_UNREACHABLE_ARM_001: duplicate/unreachable match arm '{}'",
                            key
                        ));
                    }
                }
                let case_ty = infer_expr_type(
                    program,
                    current_container_name,
                    case_expr,
                    scope,
                    current_context,
                )?;
                if !type_compatible(&case_ty, &value_ty) && !type_compatible(&value_ty, &case_ty) {
                    return Err(format!(
                        "case type mismatch in switch/match: value is {:?}, case is {:?}",
                        value_ty, case_ty
                    ));
                }
                let mut case_scope = base_scope.clone();
                let mut case_pointer_states = pointer_states.clone();
                let mut case_flow_alias_map = flow_alias_map.clone();
                let outcome = analyze_stmt_block(
                    program,
                    current_container_name,
                    block,
                    &mut case_scope,
                    &mut case_pointer_states,
                    &mut case_flow_alias_map,
                    expected_return,
                    strict_ctx,
                    current_context,
                )?;
                if matches!(outcome, FlowOutcome::FallsThrough) {
                    any_fallthrough = true;
                }
                merged_scope = merge_scope_for_cfg(&merged_scope, &case_scope, &merged_scope);
                merged_pointer_states =
                    merge_pointer_states_for_cfg(&merged_pointer_states, &case_pointer_states);
                merged_flow_alias_map = merge_flow_alias_maps_for_cfg(
                    &merged_flow_alias_map,
                    &case_flow_alias_map,
                    &mut merged_pointer_states,
                );
            }

            let mut default_scope = base_scope.clone();
            let mut default_pointer_states = pointer_states.clone();
            let mut default_flow_alias_map = flow_alias_map.clone();
            let default_outcome = analyze_stmt_block(
                program,
                current_container_name,
                default,
                &mut default_scope,
                &mut default_pointer_states,
                &mut default_flow_alias_map,
                expected_return,
                strict_ctx,
                current_context,
            )?;
            if matches!(default_outcome, FlowOutcome::FallsThrough) {
                any_fallthrough = true;
            }

            *scope = merge_scope_for_cfg(&merged_scope, &default_scope, &base_scope);
            *pointer_states =
                merge_pointer_states_for_cfg(&merged_pointer_states, &default_pointer_states);
            *flow_alias_map = merge_flow_alias_maps_for_cfg(
                &merged_flow_alias_map,
                &default_flow_alias_map,
                pointer_states,
            );

            return if any_fallthrough {
                Ok(FlowOutcome::FallsThrough)
            } else {
                Ok(FlowOutcome::Terminated)
            };
        }

        Stmt::GuardElse {
            condition,
            else_block,
        } => {
            let cond_ty = infer_expr_type(
                program,
                current_container_name,
                condition,
                scope,
                current_context,
            )?;
            if !is_bool_like_condition(&cond_ty) {
                return Err(official_condition_type_error("guard", &cond_ty));
            }
            let mut else_scope = scope.clone();
            let mut else_pointer_states = pointer_states.clone();
            let mut else_flow_alias_map = flow_alias_map.clone();
            let _ = analyze_stmt_block(
                program,
                current_container_name,
                else_block,
                &mut else_scope,
                &mut else_pointer_states,
                &mut else_flow_alias_map,
                expected_return,
                strict_ctx,
                current_context,
            )?;
            return Ok(FlowOutcome::FallsThrough);
        }

        Stmt::Select { branches, default } => {
            for (condition, block) in branches {
                let cond_ty = infer_expr_type(
                    program,
                    current_container_name,
                    condition,
                    scope,
                    current_context,
                )?;
                if !is_bool_like_condition(&cond_ty) {
                    return Err(official_condition_type_error("select/when", &cond_ty));
                }
                let mut branch_scope = scope.clone();
                let mut branch_pointer_states = pointer_states.clone();
                let mut branch_flow_alias_map = flow_alias_map.clone();
                let _ = analyze_stmt_block(
                    program,
                    current_container_name,
                    block,
                    &mut branch_scope,
                    &mut branch_pointer_states,
                    &mut branch_flow_alias_map,
                    expected_return,
                    strict_ctx,
                    current_context,
                )?;
            }
            let mut default_scope = scope.clone();
            let mut default_pointer_states = pointer_states.clone();
            let mut default_flow_alias_map = flow_alias_map.clone();
            let _ = analyze_stmt_block(
                program,
                current_container_name,
                default,
                &mut default_scope,
                &mut default_pointer_states,
                &mut default_flow_alias_map,
                expected_return,
                strict_ctx,
                current_context,
            )?;
            return Ok(FlowOutcome::FallsThrough);
        }

        Stmt::Labeled { stmt, .. } => {
            return analyze_stmt(
                program,
                current_container_name,
                stmt,
                scope,
                pointer_states,
                flow_alias_map,
                expected_return,
                strict_ctx,
                current_context,
            );
        }

        Stmt::Break { .. } | Stmt::Continue { .. } => {
            return Ok(FlowOutcome::Terminated);
        }

        Stmt::Dev(errors) => {
            validate_dev_errors_against_return(expected_return, errors)?;
            return Ok(FlowOutcome::Terminated);
        }

        Stmt::Projection { target, ty, value } => {
            let initializes_immutable = split_storage_contract(ty).is_some_and(|(storage, _)| {
                storage.section == ncc_parser::StorageSection::ReadOnlyData
            });
            if !initializes_immutable {
                if let Some(root) = immutable_assignment_root(target) {
                    if strict_ctx.immutable_names.contains(root) {
                        return Err(format!(
                            "E_IMMUTABLE_WRITE_001: immutable storage '{}' cannot be modified after initialization",
                            root
                        ));
                    }
                }
            }
            if let Some((storage, _)) = split_storage_contract(ty) {
                let declares_function_static = matches!(
                    target,
                    AssignTarget::Context(ctx)
                        if ctx.path.len() == 1 && !scope.contains_key(&ctx.path[0])
                );
                if declares_function_static {
                    storage.validate(true, true)?;
                    if !is_static_storage_initializer_expr(value) {
                        return Err(
                            "E_STORAGE_FUNCTION_INIT_001: function-static storage requires an object-materializable constant initializer; move dynamic initialization into an explicit function"
                                .into(),
                        );
                    }
                }
            }
            let target_ty = if ast_type_is_inferred_projection(ty) {
                resolve_projection_declared_type(program, scope, target)?
            } else {
                lower_type(&resolve_container_local_type_aliases(
                    program,
                    current_container_name,
                    ty,
                )?)
            };
            validate_list_imports(program, &target_ty)?;
            validate_no_implicit_collection_backing(ty, value)?;
            if !ast_type_is_inferred_projection(ty) {
                validate_explicit_array_literal_len(ty, value)?;
            }
            validate_no_implicit_aggregate_copy(
                program,
                current_container_name,
                &target_ty,
                value,
                scope,
            )?;

            let value_ty = match (target, value) {
                // Keep official root/list fixtures stable: allow self-typed bootstrap
                // projection forms like `@m >> memList<int> : @m;` when the symbol
                // is being introduced by this projection.
                (AssignTarget::Context(target_ctx), Expr::ContextRef(source_ctx))
                    if target_ctx.path.len() == 1
                        && source_ctx.path.len() == 1
                        && source_ctx.path[0] == target_ctx.path[0]
                        && !scope.contains_key(&source_ctx.path[0]) =>
                {
                    target_ty.clone()
                }
                _ => infer_expr_type_with_expected(
                    program,
                    current_container_name,
                    value,
                    Some(&target_ty),
                    scope,
                    current_context,
                )?,
            };

            match target {
                AssignTarget::Mem { addr } => {
                    let addr_ty = infer_expr_type(
                        program,
                        current_container_name,
                        addr,
                        scope,
                        current_context,
                    )?;
                    if !is_memory_addr_like(&addr_ty) {
                        return Err(format!(
                            "mem index must be addr/int-like, got {:?}",
                            addr_ty
                        ));
                    }

                    if mem_region_generic_projection_mismatch(&target_ty, &value_ty) {
                        return Err(projection_type_error_message(&target_ty, &value_ty));
                    }
                    if uses_pointer_compat_path(&target_ty, &value_ty) {
                        validate_pointer_alignment_for_cast(&target_ty, value)?;
                        if !pointer_types_compatible(&target_ty, &value_ty, value) {
                            return Err(format!(
                                "pointer projection type mismatch: cannot assign {:?} to {:?}",
                                value_ty, target_ty
                            ));
                        }
                    } else {
                        if implicit_narrowing_projection(&target_ty, &value_ty)
                            && !integer_literal_fits_narrow_projection(&target_ty, value)
                        {
                            return Err("implicit narrowing projection is not allowed".into());
                        }
                        if !type_compatible(&value_ty, &target_ty)
                            && !integer_literal_fits_narrow_projection(&target_ty, value)
                            && !vector_literal_matches_target(&target_ty, value)
                            && !projection_allows_array_zero_fill(&target_ty, value, &value_ty)
                        {
                            return Err(projection_type_error_message(&target_ty, &value_ty));
                        }
                    }

                    apply_heap_manager_effects_in_expr(
                        program,
                        current_container_name,
                        addr,
                        scope,
                        current_context,
                        pointer_states,
                        flow_alias_map,
                    )?;
                    apply_heap_manager_effects_in_expr(
                        program,
                        current_container_name,
                        value,
                        scope,
                        current_context,
                        pointer_states,
                        flow_alias_map,
                    )?;
                }
                AssignTarget::Context(target_ctx) => {
                    if !target_ctx.path.is_empty() && strict_ctx.names.contains(&target_ctx.path[0])
                    {
                        return Err("cannot reproject strictly protected target".into());
                    }

                    if target_ctx.path.len() > 1 {
                        let field_target_ty = resolve_projection_context_path_type(
                            program,
                            scope,
                            &target_ctx.path,
                            "projection",
                        )?;

                        if !type_compatible(&field_target_ty, &target_ty)
                            && !type_compatible(&target_ty, &field_target_ty)
                        {
                            return Err(format!(
                                "projection target type mismatch for '{}': target is {:?}, projection declares {:?}",
                                target_ctx.path.join("."),
                                field_target_ty,
                                target_ty
                            ));
                        }

                        if is_null_expr(value) {
                            match &target_ty {
                                SemaType::Simple(t) if t == "region" => {
                                    return Err("region cannot be null".into());
                                }
                                _ if !allows_null_assignment_type(&target_ty)
                                    && !silent_pointer_accepts_null_target(&target_ty) =>
                                {
                                    return Err(pointer_diag(
                                        E_PTR_NULL_DEREF,
                                        "cannot project null into non-nullable target",
                                    ));
                                }
                                _ => {}
                            }
                        }

                        apply_heap_manager_effects_in_expr(
                            program,
                            current_container_name,
                            value,
                            scope,
                            current_context,
                            pointer_states,
                            flow_alias_map,
                        )?;

                        if mem_region_generic_projection_mismatch(&target_ty, &value_ty) {
                            return Err(projection_type_error_message(&target_ty, &value_ty));
                        }
                        if uses_pointer_compat_path(&target_ty, &value_ty) {
                            if !pointer_types_compatible(&target_ty, &value_ty, value) {
                                return Err(format!(
                                    "pointer projection type mismatch: cannot assign {:?} to {:?}",
                                    value_ty, target_ty
                                ));
                            }
                        } else {
                            if implicit_narrowing_projection(&target_ty, &value_ty)
                                && !integer_literal_fits_narrow_projection(&target_ty, value)
                            {
                                return Err("implicit narrowing projection is not allowed".into());
                            }
                            if !type_compatible(&value_ty, &target_ty)
                                && !integer_literal_fits_narrow_projection(&target_ty, value)
                                && !vector_literal_matches_target(&target_ty, value)
                                && !projection_allows_array_zero_fill(&target_ty, value, &value_ty)
                            {
                                return Err(projection_type_error_message(&target_ty, &value_ty));
                            }
                        }

                        return Ok(FlowOutcome::FallsThrough);
                    }

                    let target_name = target_ctx.path[0].clone();
                    let mut alias_source_name: Option<String> = None;

                    if is_null_expr(value) {
                        match &target_ty {
                            SemaType::Simple(t) if t == "region" => {
                                return Err("region cannot be null".into());
                            }
                            _ if allows_null_assignment_type(&target_ty)
                                || silent_pointer_accepts_null_target(&target_ty) =>
                            {
                                scope.insert(target_name.clone(), target_ty.clone());
                                pointer_states.insert(target_name.clone(), PointerState::Null);
                                return Ok(FlowOutcome::FallsThrough);
                            }
                            _ => {
                                return Err(pointer_diag(
                                    E_PTR_NULL_DEREF,
                                    "cannot project null into non-nullable target",
                                ));
                            }
                        }
                    }

                    let mut resulting_state = PointerState::Bound;
                    if let Expr::ContextRef(ctx) = value {
                        if ctx.path.len() == 1 {
                            let source_name = &ctx.path[0];
                            let source_ty =
                                scope.get(source_name).cloned().unwrap_or(SemaType::Unknown);

                            if is_pointer_family_type(&target_ty)
                                || is_pointer_family_type(&source_ty)
                            {
                                if source_name != &target_name
                                    && !check_alias_compat(&target_ty, &source_ty)
                                    && !silent_pointer_accepts_pointer_family(
                                        &target_ty, &source_ty,
                                    )
                                {
                                    return Err(pointer_diag(
                                        E_PTR_ALIAS_MUT,
                                        format!(
                                            "invalid aliasing between {:?} and {:?}",
                                            target_ty, source_ty
                                        ),
                                    ));
                                }

                                if is_pointer_family_type(&target_ty)
                                    && is_pointer_family_type(&source_ty)
                                {
                                    alias_source_name = Some(source_name.clone());
                                }
                            }

                            let state = if is_pointer_family_type(&target_ty)
                                && source_name == &target_name
                            {
                                alias_source_name = None;
                                pointer_state_for_self_bootstrap(
                                    source_name,
                                    &target_ty,
                                    pointer_states,
                                )?
                            } else {
                                source_pointer_state_for_alias_projection(
                                    source_name,
                                    &target_ty,
                                    pointer_states,
                                )?
                            };
                            if matches!(state, PointerState::Invalid)
                                && !(silent_pointer_acceptance_enabled()
                                    && is_raw_pointer_type(&target_ty))
                            {
                                return Err(pointer_diag(
                                    E_PTR_STALE_SITE,
                                    format!(
                                        "use of invalid pointer '{}' (stale site)",
                                        source_name
                                    ),
                                ));
                            }
                            resulting_state = state;
                        }
                    }

                    apply_heap_manager_effects_in_expr(
                        program,
                        current_container_name,
                        value,
                        scope,
                        current_context,
                        pointer_states,
                        flow_alias_map,
                    )?;

                    if mem_region_generic_projection_mismatch(&target_ty, &value_ty) {
                        return Err(projection_type_error_message(&target_ty, &value_ty));
                    }
                    if uses_pointer_compat_path(&target_ty, &value_ty) {
                        validate_pointer_alignment_for_cast(&target_ty, value)?;
                        if !pointer_types_compatible(&target_ty, &value_ty, value) {
                            return Err(format!(
                                "pointer projection type mismatch: cannot assign {:?} to {:?}",
                                value_ty, target_ty
                            ));
                        }
                    } else {
                        if implicit_narrowing_projection(&target_ty, &value_ty)
                            && !integer_literal_fits_narrow_projection(&target_ty, value)
                        {
                            return Err("implicit narrowing projection is not allowed".into());
                        }
                        if !type_compatible(&value_ty, &target_ty)
                            && !integer_literal_fits_narrow_projection(&target_ty, value)
                            && !vector_literal_matches_target(&target_ty, value)
                            && !projection_allows_array_zero_fill(&target_ty, value, &value_ty)
                        {
                            return Err(projection_type_error_message(&target_ty, &value_ty));
                        }
                    }

                    let scope_ty = refine_projection_container_type(&target_ty, &value_ty);
                    scope.insert(target_name.clone(), scope_ty);
                    record_pointer_region_bound(&target_name, &target_ty, value);
                    record_pointer_addr_literal(&target_name, &target_ty, value);
                    if is_pointer_family_type(&target_ty) {
                        pointer_states.insert(target_name.clone(), resulting_state);
                        if let Some(source_name) = alias_source_name {
                            flow_set_alias(&target_name, &source_name, flow_alias_map);
                        } else {
                            flow_clear_alias(&target_name, flow_alias_map);
                        }
                    } else {
                        flow_clear_alias(&target_name, flow_alias_map);
                    }
                }
            }
        }

        Stmt::StrictCheck { target, ty, value } => {
            let target_ty = lower_type(ty);

            if let Expr::Dev(errors) = value {
                validate_dev_errors_against_return(expected_return, errors)?;
                match target {
                    AssignTarget::Mem { .. } => {
                        return Err(
                            "strict check with dev(...) only allows simple symbol targets".into(),
                        );
                    }
                    AssignTarget::Context(target_ctx) => {
                        let source_ty = resolve_projection_context_path_type(
                            program,
                            scope,
                            &target_ctx.path,
                            "strict conversion",
                        )?;
                        if !union_contains_target(&source_ty, &target_ty)
                            && !union_contains_target(&target_ty, &source_ty)
                        {
                            return Err(format!(
                                "strict check failed: value {:?} does not satisfy {:?}",
                                source_ty, target_ty
                            ));
                        }

                        if target_ctx.path.len() == 1 && is_pointer_family_type(&target_ty) {
                            let target_name = target_ctx.path[0].clone();
                            if let Some(state) = pointer_states.get(&target_name).copied() {
                                match state {
                                    PointerState::Invalid
                                        if !(silent_pointer_acceptance_enabled()
                                            && is_raw_pointer_type(&target_ty)) =>
                                    {
                                        return Err(pointer_diag(
                                            E_PTR_STALE_SITE,
                                            format!(
                                                "use of invalid pointer '{}' (stale site)",
                                                target_name
                                            ),
                                        ));
                                    }
                                    PointerState::Uninit => {
                                        pointer_states
                                            .insert(target_name.clone(), PointerState::Bound);
                                    }
                                    PointerState::Invalid
                                    | PointerState::Null
                                    | PointerState::Bound => {}
                                }
                            }
                            flow_clear_alias(&target_name, flow_alias_map);
                        }
                    }
                }
                return Ok(FlowOutcome::FallsThrough);
            }

            let value_ty = infer_expr_type(
                program,
                current_container_name,
                value,
                scope,
                current_context,
            )?;

            match target {
                AssignTarget::Mem { addr } => {
                    let addr_ty = infer_expr_type(
                        program,
                        current_container_name,
                        addr,
                        scope,
                        current_context,
                    )?;
                    if !is_memory_addr_like(&addr_ty) {
                        return Err(format!(
                            "mem index must be addr/int-like, got {:?}",
                            addr_ty
                        ));
                    }

                    if uses_pointer_compat_path(&target_ty, &value_ty) {
                        validate_pointer_alignment_for_cast(&target_ty, value)?;
                        if !pointer_explicit_cast_allowed(&target_ty, &value_ty) {
                            return Err(format!(
                                "explicit pointer cast not allowed: {:?} !> {:?}",
                                value_ty, target_ty
                            ));
                        }
                    } else if !type_compatible(&value_ty, &target_ty) {
                        return Err(format!(
                            "strict check failed: value {:?} does not satisfy {:?}",
                            value_ty, target_ty
                        ));
                    }

                    apply_heap_manager_effects_in_expr(
                        program,
                        current_container_name,
                        addr,
                        scope,
                        current_context,
                        pointer_states,
                        flow_alias_map,
                    )?;
                    apply_heap_manager_effects_in_expr(
                        program,
                        current_container_name,
                        value,
                        scope,
                        current_context,
                        pointer_states,
                        flow_alias_map,
                    )?;
                }
                AssignTarget::Context(target_ctx) => {
                    if target_ctx.path.len() > 1 {
                        let field_target_ty = resolve_projection_context_path_type(
                            program,
                            scope,
                            &target_ctx.path,
                            "strict conversion",
                        )?;

                        if !type_compatible(&field_target_ty, &target_ty)
                            && !type_compatible(&target_ty, &field_target_ty)
                        {
                            return Err(format!(
                                "strict conversion target type mismatch for '{}': target is {:?}, strict conversion declares {:?}",
                                target_ctx.path.join("."),
                                field_target_ty,
                                target_ty
                            ));
                        }

                        if is_null_expr(value) {
                            match &target_ty {
                                SemaType::Simple(t) if t == "region" => {
                                    return Err("region cannot be null".into());
                                }
                                _ if !allows_null_assignment_type(&target_ty)
                                    && !silent_pointer_accepts_null_target(&target_ty) =>
                                {
                                    return Err(pointer_diag(
                                        E_PTR_NULL_DEREF,
                                        format!(
                                            "null requires an explicit nullable pointer/address type, got {:?}",
                                            target_ty
                                        ),
                                    ));
                                }
                                _ => {}
                            }
                        }

                        if uses_pointer_compat_path(&target_ty, &value_ty) {
                            if !pointer_explicit_cast_allowed(&target_ty, &value_ty) {
                                return Err(format!(
                                    "explicit pointer cast not allowed: {:?} !> {:?}",
                                    value_ty, target_ty
                                ));
                            }
                        } else if !type_compatible(&value_ty, &target_ty)
                            && !projection_allows_array_zero_fill(&target_ty, value, &value_ty)
                        {
                            return Err(format!(
                                "strict check failed: value {:?} does not satisfy {:?}",
                                value_ty, target_ty
                            ));
                        }

                        apply_heap_manager_effects_in_expr(
                            program,
                            current_container_name,
                            value,
                            scope,
                            current_context,
                            pointer_states,
                            flow_alias_map,
                        )?;
                        return Ok(FlowOutcome::FallsThrough);
                    }

                    let target_name = target_ctx.path[0].clone();
                    let mut alias_source_name: Option<String> = None;

                    if is_null_expr(value) {
                        match &target_ty {
                            SemaType::Simple(t) if t == "region" => {
                                return Err("region cannot be null".into());
                            }
                            _ if allows_null_assignment_type(&target_ty)
                                || silent_pointer_accepts_null_target(&target_ty) =>
                            {
                                scope.insert(target_name.clone(), target_ty.clone());
                                pointer_states.insert(target_name.clone(), PointerState::Null);
                                return Ok(FlowOutcome::FallsThrough);
                            }
                            _ => {
                                return Err(pointer_diag(
                                    E_PTR_NULL_DEREF,
                                    format!(
                                        "null requires an explicit nullable pointer/address type, got {:?}",
                                        target_ty
                                    ),
                                ));
                            }
                        }
                    }

                    let mut resulting_state = PointerState::Bound;
                    if let Some(source_name) = root_context_name_from_expr(value) {
                        let state =
                            if is_pointer_family_type(&target_ty) && source_name == target_name {
                                alias_source_name = None;
                                pointer_state_for_self_bootstrap(
                                    &source_name,
                                    &target_ty,
                                    pointer_states,
                                )?
                            } else {
                                source_pointer_state_for_alias_projection(
                                    &source_name,
                                    &target_ty,
                                    pointer_states,
                                )?
                            };
                        if matches!(state, PointerState::Invalid)
                            && !(silent_pointer_acceptance_enabled()
                                && is_raw_pointer_type(&target_ty))
                        {
                            return Err(pointer_diag(
                                E_PTR_STALE_SITE,
                                format!("use of invalid pointer '{}' (stale site)", source_name),
                            ));
                        }
                        resulting_state = state;
                        if alias_source_name.is_none() {
                            alias_source_name = Some(source_name);
                        }
                    }

                    if uses_pointer_compat_path(&target_ty, &value_ty) {
                        validate_pointer_alignment_for_cast(&target_ty, value)?;
                        if !pointer_explicit_cast_allowed(&target_ty, &value_ty) {
                            return Err(format!(
                                "explicit pointer cast not allowed: {:?} !> {:?}",
                                value_ty, target_ty
                            ));
                        }

                        apply_heap_manager_effects_in_expr(
                            program,
                            current_container_name,
                            value,
                            scope,
                            current_context,
                            pointer_states,
                            flow_alias_map,
                        )?;
                        scope.insert(target_name.clone(), target_ty.clone());
                        record_pointer_region_bound(&target_name, &target_ty, value);
                        record_pointer_addr_literal(&target_name, &target_ty, value);
                        if is_pointer_family_type(&target_ty) {
                            pointer_states.insert(target_name.clone(), resulting_state);
                            if let Some(source_name) = alias_source_name {
                                flow_set_alias(&target_name, &source_name, flow_alias_map);
                            } else {
                                flow_clear_alias(&target_name, flow_alias_map);
                            }
                        } else {
                            flow_clear_alias(&target_name, flow_alias_map);
                        }
                    } else if !type_compatible(&value_ty, &target_ty)
                        && !projection_allows_array_zero_fill(&target_ty, value, &value_ty)
                    {
                        return Err(format!(
                            "strict check failed: value {:?} does not satisfy {:?}",
                            value_ty, target_ty
                        ));
                    } else {
                        apply_heap_manager_effects_in_expr(
                            program,
                            current_container_name,
                            value,
                            scope,
                            current_context,
                            pointer_states,
                            flow_alias_map,
                        )?;
                        flow_clear_alias(&target_name, flow_alias_map);
                    }
                }
            }
        }

        Stmt::MainRefFn { .. } => {}
        Stmt::FunctionRelation { .. } => {}

        Stmt::Print { kind, value } => {
            if matches!(kind, PrintKind::Std | PrintKind::Ln) {
                let output_module = vec!["runtime".to_string(), "output".to_string()];
                if !has_visible_import_for_module(&program.uses, &output_module) {
                    return Err(format!(
                        "E_RUNTIME_USE_001: runtime call '{}' requires explicit use/import 'nC.runtime.output'",
                        runtime_print_kind_label(kind)
                    ));
                }
            }

            if matches!(current_context, Some(Context::Primitive))
                && !matches!(
                    kind,
                    PrintKind::Raw
                        | PrintKind::Stable
                        | PrintKind::Addr
                        | PrintKind::Phys
                        | PrintKind::Dump
                        | PrintKind::Peek
                        | PrintKind::Mmio
                        | PrintKind::Port
                        | PrintKind::Sensory
                )
            {
                return Err(format!(
                    "E_PRIMITIVE_OUTPUT_001: human output operation '{}' is forbidden in primitive[@]; use print.raw/print.stable/print.addr/print.phys/print.dump/print.peek/print.mmio/print.port/print.sensory",
                    runtime_print_kind_label(kind)
                ));
            }

            if matches!(kind, PrintKind::Sensory)
                && !matches!(current_context, Some(Context::Primitive))
            {
                return Err(
                    "E_PRIMITIVE_OUTPUT_001: print.sensory is only allowed in primitive[@]".into(),
                );
            }

            if matches!(kind, PrintKind::Sensory)
                && matches!(current_context, Some(Context::Primitive))
                && !primitive_container_has_bridge_section(program, current_container_name)
            {
                return Err(
                    "E_PRIMITIVE_SENSORY_BRIDGE_MISSING_001: print.sensory requires a bridge section in primitive[@]".into(),
                );
            }

            if matches!(kind, PrintKind::Mmio | PrintKind::Port)
                && !matches!(
                    current_context,
                    Some(Context::Root) | Some(Context::Machine) | Some(Context::Primitive)
                )
            {
                return Err(format!(
                    "{} is only allowed in [@], [@machine], or primitive[@]",
                    match kind {
                        PrintKind::Mmio => "print.mmio",
                        PrintKind::Port => "print.port",
                        _ => "print",
                    }
                ));
            }

            if matches!(
                kind,
                PrintKind::Addr | PrintKind::Phys | PrintKind::Dump | PrintKind::Peek
            ) && matches!(
                current_context,
                Some(Context::Runtime)
                    | Some(Context::System)
                    | Some(Context::Network)
                    | Some(Context::Tooling)
                    | Some(Context::Compiler)
                    | Some(Context::Ai)
            ) {
                return Err(format!(
                    "{} is restricted in high-level contexts; use print.inspect/print.stable instead",
                    match kind {
                        PrintKind::Addr => "print.addr",
                        PrintKind::Phys => "print.phys",
                        PrintKind::Dump => "print.dump",
                        PrintKind::Peek => "print.peek",
                        _ => "print",
                    }
                ));
            }

            if matches!(current_context, Some(Context::Security))
                && matches!(
                    kind,
                    PrintKind::Raw | PrintKind::Dump | PrintKind::Addr | PrintKind::Phys
                )
            {
                return Err(format!(
                    "{} is restricted in [@security]; use redacted structured output",
                    match kind {
                        PrintKind::Raw => "print.raw",
                        PrintKind::Dump => "print.dump",
                        PrintKind::Addr => "print.addr",
                        PrintKind::Phys => "print.phys",
                        _ => "print",
                    }
                ));
            }

            let (value_exprs, expects_two_args) = match kind {
                PrintKind::Dump | PrintKind::Peek | PrintKind::Mmio | PrintKind::Port => {
                    if let Expr::ArrayLiteral(items) = value {
                        if items.len() != 2 {
                            return Err("console builtin expects 2 arguments".into());
                        }
                        (items.as_slice(), true)
                    } else {
                        return Err("console builtin expects 2 arguments".into());
                    }
                }
                _ => {
                    if let Expr::ArrayLiteral(items) = value {
                        if items.len() == 2 {
                            return Err("console builtin accepts exactly 1 argument".into());
                        }
                    }
                    (std::slice::from_ref(value), false)
                }
            };

            if let Some(Expr::ContextRef(ctx)) = value_exprs.first() {
                if ctx.path.len() > 1 {
                    let Some(path) = inspect_runtime_path_from_segments(&ctx.path) else {
                        return Err(format!(
                            "invalid inspect path '{}': expected {}",
                            ctx.path.join("."),
                            inspect_runtime_expected_paths_diagnostic()
                        ));
                    };
                    validate_inspect_runtime_path_contract_imports(program, &ctx.path, path)?;
                }
            }

            for (idx, expr) in value_exprs.iter().enumerate() {
                if expects_two_args
                    && idx == 1
                    && matches!(
                        expr,
                        Expr::Identifier(name)
                            if matches!(name.as_str(), "byte" | "word" | "dword" | "qword")
                    )
                {
                    continue;
                }
                let _ = infer_expr_type(
                    program,
                    current_container_name,
                    expr,
                    scope,
                    current_context,
                )?;
                apply_heap_manager_effects_in_expr(
                    program,
                    current_container_name,
                    expr,
                    scope,
                    current_context,
                    pointer_states,
                    flow_alias_map,
                )?;
            }

            if expects_two_args {
                let second = &value_exprs[1];
                if matches!(
                    second,
                    Expr::Identifier(name)
                        if matches!(name.as_str(), "byte" | "word" | "dword" | "qword")
                ) {
                    return Ok(FlowOutcome::FallsThrough);
                }
                let second_ty = infer_expr_type(
                    program,
                    current_container_name,
                    second,
                    scope,
                    current_context,
                )?;
                if !is_integer_like(&second_ty)
                    && !matches!(second_ty, SemaType::Simple(ref s) if s == "str")
                {
                    return Err("second argument must be width/format descriptor".into());
                }
            }
        }

        Stmt::Expr(expr) => {
            if let Expr::Call { callee, args } = expr {
                if callee.eq_ignore_ascii_case("swap") {
                    if args.len() != 2 {
                        return Err("swap expects exactly two symbol arguments".into());
                    }
                    let left = compact_swap_symbol(&args[0])
                        .ok_or_else(|| "swap first argument must be a simple symbol".to_string())?;
                    let right = compact_swap_symbol(&args[1]).ok_or_else(|| {
                        "swap second argument must be a simple symbol".to_string()
                    })?;
                    let left_ty = scope
                        .get(left)
                        .cloned()
                        .ok_or_else(|| format!("swap first symbol '{}' is not declared", left))?;
                    let right_ty = scope
                        .get(right)
                        .cloned()
                        .ok_or_else(|| format!("swap second symbol '{}' is not declared", right))?;
                    if strict_ctx.immutable_names.contains(left)
                        || strict_ctx.immutable_names.contains(right)
                    {
                        return Err(
                            "E_IMMUTABLE_WRITE_001: swap cannot modify immutable storage".into(),
                        );
                    }
                    if !type_compatible(&left_ty, &right_ty)
                        || !type_compatible(&right_ty, &left_ty)
                    {
                        return Err(format!(
                            "swap type mismatch: '{}' is {:?}, '{}' is {:?}",
                            left, left_ty, right, right_ty
                        ));
                    }
                    return Ok(FlowOutcome::FallsThrough);
                }
            }

            if let Expr::MethodCall {
                receiver, method, ..
            } = expr
            {
                if let Expr::ContextRef(ctx) = &**receiver {
                    if ctx.path.len() == 1
                        && strict_ctx.immutable_names.contains(&ctx.path[0])
                        && is_mutating_method(method)
                    {
                        return Err(format!(
                            "E_IMMUTABLE_WRITE_001: immutable storage '{}' cannot call mutating method '{}'",
                            ctx.path[0], method
                        ));
                    }
                    if ctx.path.len() == 1
                        && strict_ctx.names.contains(&ctx.path[0])
                        && is_mutating_method(method)
                    {
                        return Err(format!(
                            "cannot call mutating method '{}' on strictly symbol '{}'",
                            method, ctx.path[0]
                        ));
                    }
                }
            }

            let _ = infer_expr_type(
                program,
                current_container_name,
                expr,
                scope,
                current_context,
            )?;
            apply_heap_manager_effects_in_expr(
                program,
                current_container_name,
                expr,
                scope,
                current_context,
                pointer_states,
                flow_alias_map,
            )?;
        }
        Stmt::Destructure { kind, args } => {
            let mut arg_types = Vec::with_capacity(args.len());
            for arg in args {
                let ty =
                    infer_expr_type(program, current_container_name, arg, scope, current_context)?;
                apply_heap_manager_effects_in_expr(
                    program,
                    current_container_name,
                    arg,
                    scope,
                    current_context,
                    pointer_states,
                    flow_alias_map,
                )?;
                arg_types.push(ty);
            }
            validate_destructure_contract(*kind, args, &arg_types)?;
        }
        Stmt::Constructure { kind, args } => {
            let mut arg_types = Vec::with_capacity(args.len());
            for arg in args {
                let ty =
                    infer_expr_type(program, current_container_name, arg, scope, current_context)?;
                apply_heap_manager_effects_in_expr(
                    program,
                    current_container_name,
                    arg,
                    scope,
                    current_context,
                    pointer_states,
                    flow_alias_map,
                )?;
                arg_types.push(ty);
            }
            validate_constructure_contract(*kind, args, &arg_types)?;
        }
        Stmt::Defer { body } => {
            if body.iter().any(defer_stmt_has_control_escape) {
                return Err("E_HIGH_DEFER_CONTROL_FLOW_001: deferred cleanup cannot return, break or continue".into());
            }
            let _ = analyze_stmt_block(
                program,
                current_container_name,
                body,
                scope,
                pointer_states,
                flow_alias_map,
                expected_return,
                strict_ctx,
                current_context,
            )?;
        }
    }

    Ok(FlowOutcome::FallsThrough)
}

fn is_pointer_family_type(ty: &SemaType) -> bool {
    match ty {
        SemaType::Simple(name) => {
            matches!(
                name.as_str(),
                "addr" | "ptr" | "ref" | "skk*" | "skk**" | "region"
            ) || matches!(
                name.to_ascii_lowercase().as_str(),
                "object" | "networkserver" | "networkclient" | "mobileresponse"
            )
        }
        SemaType::Generic { base, args } => is_pointer_generic_base(base) && !args.is_empty(),
        SemaType::Union(items) => {
            !items.is_empty()
                && items
                    .iter()
                    .any(|item| !is_bind_null_type(item) && is_pointer_family_type(item))
                && items
                    .iter()
                    .all(|item| is_bind_null_type(item) || is_pointer_family_type(item))
        }
        _ => false,
    }
}

fn type_contains_null(ty: &SemaType) -> bool {
    match ty {
        SemaType::Simple(name) => name == "null",
        SemaType::Union(items) => items.iter().any(type_contains_null),
        _ => false,
    }
}

fn is_opaque_runtime_handle_type(ty: &SemaType) -> bool {
    matches!(
        ty,
        SemaType::Simple(name)
            if matches!(
                name.to_ascii_lowercase().as_str(),
                "object" | "networkserver" | "networkclient" | "mobileresponse"
            )
    )
}

fn pointer_family_index_inner_type(ty: &SemaType) -> Option<SemaType> {
    match ty {
        SemaType::Union(items) => items
            .iter()
            .filter(|item| !is_bind_null_type(item))
            .find_map(pointer_family_index_inner_type),
        SemaType::Generic { base, args } if is_pointer_generic_base(base) && !args.is_empty() => {
            Some(args[0].clone())
        }
        SemaType::Simple(name)
            if matches!(
                name.as_str(),
                "addr" | "ptr" | "ref" | "skk*" | "skk**" | "region"
            ) =>
        {
            Some(SemaType::Unknown)
        }
        _ => None,
    }
}

fn is_number_literal_expr(expr: &Expr) -> bool {
    matches!(expr, Expr::Number(_))
}

fn is_static_storage_initializer_expr(expr: &Expr) -> bool {
    match expr {
        Expr::StructLiteral { fields, .. } => fields
            .iter()
            .all(|(_, value)| is_static_storage_initializer_expr(value)),
        Expr::Bool(_) | Expr::Number(_) | Expr::Char(_) | Expr::String(_) => true,
        Expr::Identifier(name) => name.eq_ignore_ascii_case("null"),
        Expr::VectorLiteral(items) | Expr::ArrayLiteral(items) => {
            items.iter().all(is_static_storage_initializer_expr)
        }
        Expr::Unary { expr, .. } => is_static_storage_initializer_expr(expr),
        Expr::Binary { left, right, .. } => {
            is_static_storage_initializer_expr(left) && is_static_storage_initializer_expr(right)
        }
        Expr::IfElse {
            condition,
            then_expr,
            else_expr,
        } => {
            is_static_storage_initializer_expr(condition)
                && is_static_storage_initializer_expr(then_expr)
                && is_static_storage_initializer_expr(else_expr)
        }
        Expr::StrictCheckExpr { value, .. } => is_static_storage_initializer_expr(value),
        Expr::Index { .. }
        | Expr::Closure(_)
        | Expr::ContextRef(_)
        | Expr::MethodCall { .. }
        | Expr::QualifiedCall { .. }
        | Expr::Dev(_)
        | Expr::PostIncrement { .. }
        | Expr::FieldPostIncrement { .. }
        | Expr::PointerPostIncrementRead { .. }
        | Expr::Call { .. } => false,
    }
}

fn root_context_name_from_expr(expr: &Expr) -> Option<String> {
    match expr {
        Expr::ContextRef(ctx) if ctx.path.len() == 1 => Some(ctx.path[0].clone()),
        Expr::Index { target, .. } => root_context_name_from_expr(target),
        Expr::Call { callee, args } if value_transfer_op_from_callee(callee).is_some() => {
            args.first().and_then(root_context_name_from_expr)
        }
        _ => None,
    }
}

fn pointer_region_bound_from_expr(expr: &Expr) -> Option<usize> {
    let args = match expr {
        Expr::Call { callee, args }
            if callee
                .split('<')
                .next()
                .is_some_and(|base| base.eq_ignore_ascii_case("regionFromPtr")) =>
        {
            args
        }
        Expr::QualifiedCall { path, args }
            if path
                .last()
                .and_then(|segment| segment.split('<').next())
                .is_some_and(|base| base.eq_ignore_ascii_case("regionFromPtr")) =>
        {
            args
        }
        Expr::StrictCheckExpr { value, .. } => return pointer_region_bound_from_expr(value),
        _ => return None,
    };

    args.get(1)
        .and_then(sema_expr_integer_literal_value)
        .and_then(|value| usize::try_from(value).ok())
}

fn record_pointer_region_bound(target_name: &str, target_ty: &SemaType, value: &Expr) {
    if !sema_type_is_memregion_family(target_ty) {
        return;
    }
    let key = target_name.to_ascii_lowercase();
    CURRENT_POINTER_REGION_BOUNDS.with(|cell| {
        let mut bounds = cell.borrow_mut();
        if let Some(len) = pointer_region_bound_from_expr(value) {
            bounds.insert(key, len);
        } else {
            bounds.remove(&key);
        }
    });
}

fn record_pointer_addr_literal(target_name: &str, target_ty: &SemaType, value: &Expr) {
    if !is_addr_type(target_ty) {
        return;
    }
    let key = target_name.to_ascii_lowercase();
    CURRENT_POINTER_ADDR_LITERALS.with(|cell| {
        let mut addrs = cell.borrow_mut();
        if let Some(addr) = sema_expr_integer_literal_value(value) {
            addrs.insert(key, addr);
        } else {
            addrs.remove(&key);
        }
    });
}

fn pointer_value_known_addr(value: &Expr) -> Option<i64> {
    match value {
        Expr::Number(_) | Expr::Unary { .. } => sema_expr_integer_literal_value(value),
        Expr::ContextRef(ctx) if ctx.path.len() == 1 => {
            CURRENT_POINTER_ADDR_LITERALS.with(|cell| {
                cell.borrow()
                    .get(&ctx.path[0].to_ascii_lowercase())
                    .copied()
            })
        }
        Expr::StrictCheckExpr { value, .. } => pointer_value_known_addr(value),
        _ => None,
    }
}

fn pointer_type_alignment_bytes(ty: &SemaType) -> Option<i64> {
    match ty {
        SemaType::Union(items) => items
            .iter()
            .filter(|item| !is_bind_null_type(item))
            .filter_map(pointer_type_alignment_bytes)
            .max(),
        SemaType::Generic { base, args } if is_pointer_generic_base(base) && args.len() == 1 => {
            pointer_pointee_alignment_bytes(&args[0])
        }
        _ => None,
    }
}

fn pointer_pointee_alignment_bytes(ty: &SemaType) -> Option<i64> {
    match ty {
        SemaType::Simple(name) => match normalize_type_name(name) {
            "byte" | "sbyte" | "bool" | "char" | "int8" | "uint8" => Some(1),
            "word" | "sword" | "int16" | "uint16" => Some(2),
            "dword" | "sdword" | "int32" | "uint32" => Some(4),
            "qword" | "sqword" | "int64" | "uint64" | "addr" => Some(8),
            _ => None,
        },
        _ => None,
    }
}

fn validate_pointer_alignment_for_cast(target_ty: &SemaType, value: &Expr) -> Result<(), String> {
    if silent_pointer_acceptance_enabled() && is_raw_pointer_type(target_ty) {
        return Ok(());
    }
    let Some(align) = pointer_type_alignment_bytes(target_ty) else {
        return Ok(());
    };
    if align <= 1 {
        return Ok(());
    }
    let Some(addr) = pointer_value_known_addr(value) else {
        return Ok(());
    };
    if addr < 0 || addr % align != 0 {
        return Err(pointer_diag(
            E_PTR_ALIGNMENT,
            format!(
                "address literal 0x{:x} is not aligned for {:?} (required {} bytes)",
                addr, target_ty, align
            ),
        ));
    }
    Ok(())
}

fn validate_pointer_region_index_bounds(target: &Expr, axis_exprs: &[&Expr]) -> Result<(), String> {
    let Some(index) = axis_exprs
        .first()
        .and_then(|expr| sema_expr_integer_literal_value(expr))
    else {
        return Ok(());
    };
    let Some(target_name) = root_context_name_from_expr(target) else {
        return Ok(());
    };
    let Some(len) = CURRENT_POINTER_REGION_BOUNDS.with(|cell| {
        cell.borrow()
            .get(&target_name.to_ascii_lowercase())
            .copied()
    }) else {
        return Ok(());
    };
    if index < 0 || usize::try_from(index).map_or(true, |idx| idx >= len) {
        return Err(pointer_diag(
            E_PTR_OUT_OF_BOUNDS,
            format!(
                "memRegion '{}' index {} is out of known bounds 0..{}",
                target_name,
                index,
                len.saturating_sub(1)
            ),
        ));
    }
    Ok(())
}

fn pointer_explicit_cast_allowed(target_ty: &SemaType, value_ty: &SemaType) -> bool {
    if silent_pointer_accepts_pointer_family(target_ty, value_ty) {
        return true;
    }

    if !matches!(
        pointer_compat_kind(target_ty, value_ty),
        CompatKind::Forbidden
    ) {
        return true;
    }

    match (target_ty, value_ty) {
        // mismo tipo
        (SemaType::Simple(t), SemaType::Simple(v)) if t == v => true,

        // conversiones explícitas permitidas
        (SemaType::Simple(t), SemaType::Simple(v)) if t == "ptr" && v == "addr" => true,
        (SemaType::Simple(t), SemaType::Simple(v)) if t == "addr" && v == "ptr" => true,
        (SemaType::Simple(t), SemaType::Simple(v)) if t == "addr" && v == "skk*" => true,
        (SemaType::Simple(t), SemaType::Simple(v)) if t == "ptr" && v == "skk*" => true,

        // memoria regional y simbólica desde dirección base, SOLO por !>
        (SemaType::Simple(t), SemaType::Simple(v)) if t == "region" && v == "addr" => true,
        (SemaType::Simple(t), SemaType::Simple(v)) if t == "skk*" && v == "addr" => true,
        (SemaType::Simple(t), SemaType::Simple(v)) if t == "skk**" && v == "addr" => true,

        _ => false,
    }
}

fn pointer_types_compatible(target_ty: &SemaType, value_ty: &SemaType, value_expr: &Expr) -> bool {
    if matches!(target_ty, SemaType::Unknown) || matches!(value_ty, SemaType::Unknown) {
        return true;
    }
    if is_opaque_runtime_handle_type(target_ty) && is_opaque_runtime_handle_type(value_ty) {
        return true;
    }
    if silent_pointer_acceptance_enabled()
        && is_null_expr(value_expr)
        && is_raw_pointer_type(target_ty)
    {
        return true;
    }
    if silent_pointer_accepts_pointer_family(target_ty, value_ty) && !is_null_expr(value_expr) {
        return true;
    }

    if let SemaType::Union(items) = target_ty {
        return items.iter().any(|item| {
            if is_bind_null_type(item) {
                return is_null_expr(value_expr);
            }
            pointer_types_compatible(item, value_ty, value_expr)
        });
    }

    if let SemaType::Union(items) = value_ty {
        return items.iter().all(|item| {
            if is_bind_null_type(item) {
                return true;
            }
            pointer_types_compatible(target_ty, item, value_expr)
        });
    }

    if bind_source_matches_mem_region_target(target_ty, value_ty) {
        return true;
    }

    match (target_ty, value_ty) {
        // addr acepta literal numérico explícito (0b/0x/decimal)
        (SemaType::Simple(t), _) if t == "addr" && is_number_literal_expr(value_expr) => true,

        _ => !matches!(
            pointer_compat_kind(target_ty, value_ty),
            CompatKind::Forbidden
        ),
    }
}

fn uses_pointer_compat_path(target_ty: &SemaType, value_ty: &SemaType) -> bool {
    is_pointer_family_type(target_ty)
        || is_pointer_family_type(value_ty)
        || bind_source_matches_mem_region_target(target_ty, value_ty)
}

fn mem_region_generic_projection_mismatch(target_ty: &SemaType, value_ty: &SemaType) -> bool {
    match (target_ty, value_ty) {
        (
            SemaType::Generic { base, args },
            SemaType::Generic {
                base: value_base,
                args: value_args,
            },
        ) if base.eq_ignore_ascii_case("memRegion")
            && value_base.eq_ignore_ascii_case("memRegion") =>
        {
            args.len() != value_args.len()
                || args
                    .iter()
                    .zip(value_args)
                    .any(|(target_arg, value_arg)| !type_compatible(value_arg, target_arg))
        }
        (SemaType::Union(items), value) => items
            .iter()
            .filter(|item| !is_bind_null_type(item))
            .any(|item| mem_region_generic_projection_mismatch(item, value)),
        (target, SemaType::Union(items)) => items
            .iter()
            .filter(|item| !is_bind_null_type(item))
            .any(|item| mem_region_generic_projection_mismatch(target, item)),
        _ => false,
    }
}

fn vector_literal_matches_target(target_ty: &SemaType, value_expr: &Expr) -> bool {
    match (target_ty, value_expr) {
        (SemaType::Vector(inner), Expr::VectorLiteral(items)) => match &**inner {
            SemaType::Simple(name) if name == "addr" => items.iter().all(is_number_literal_expr),
            SemaType::Vector(_) => items
                .iter()
                .all(|item| vector_literal_matches_target(inner, item)),
            _ => false,
        },
        _ => false,
    }
}

fn projection_allows_array_zero_fill(
    target_ty: &SemaType,
    value_expr: &Expr,
    value_ty: &SemaType,
) -> bool {
    let SemaType::Generic { base, args } = target_ty else {
        return false;
    };
    if !base.eq_ignore_ascii_case("array") || args.is_empty() {
        return false;
    }
    let elem_ty = &args[0];
    if sema_type_is_scalar_storage(elem_ty) {
        return false;
    }
    let SemaType::Vector(inner) = value_ty else {
        return false;
    };
    if !type_compatible(inner, &SemaType::Simple("int".into())) {
        return false;
    }
    matches!(
        value_expr,
        Expr::ArrayLiteral(items) | Expr::VectorLiteral(items)
            if items.len() == 1 && matches!(&items[0], Expr::Number(raw) if sema_expr_integer_literal_value(&Expr::Number(raw.clone())) == Some(0))
    )
}

fn sema_type_is_scalar_storage(ty: &SemaType) -> bool {
    match ty {
        SemaType::Simple(name) => {
            let norm = normalize_type_name(name);
            integer_scalar_type_name(norm)
                || matches!(
                    norm,
                    "bool"
                        | "char"
                        | "str"
                        | "ft"
                        | "ft32"
                        | "ft64"
                        | "float"
                        | "addr"
                        | "result"
                        | "option"
                )
        }
        SemaType::Generic { base, .. } => {
            is_pointer_generic_base(base)
                || base.eq_ignore_ascii_case("memRegion")
                || base.eq_ignore_ascii_case("Result")
                || base.eq_ignore_ascii_case("Option")
                || is_list_family(base)
        }
        SemaType::Array(_) | SemaType::Vector(_) | SemaType::Union(_) | SemaType::Unknown => false,
    }
}

fn numeric_scalar_width_bits(name: &str) -> Option<u32> {
    match normalize_type_name(name) {
        "int8" | "uint8" | "byte" => Some(8),
        "int16" | "uint16" | "word" => Some(16),
        "int32" | "uint32" | "dword" | "ft32" => Some(32),
        "int64" | "uint64" | "qword" | "ft64" | "float" => Some(64),
        _ => None,
    }
}

fn numeric_scalar_literal_range(name: &str) -> Option<(i64, i64)> {
    match normalize_type_name(name) {
        "byte" | "uint8" => Some((0, 255)),
        "sbyte" | "int8" => Some((-128, 127)),
        "word" | "uint16" => Some((0, 65_535)),
        "sword" | "int16" => Some((-32_768, 32_767)),
        "dword" | "uint32" | "uint" => Some((0, i64::from(u32::MAX))),
        "int32" | "int" => Some((i64::from(i32::MIN), i64::from(i32::MAX))),
        "qword" | "uint64" | "addr" => Some((0, i64::MAX)),
        "sqword" | "int64" => Some((i64::MIN, i64::MAX)),
        _ => None,
    }
}

fn integer_scalar_type_name(name: &str) -> bool {
    matches!(
        normalize_type_name(name),
        "byte"
            | "sbyte"
            | "word"
            | "sword"
            | "dword"
            | "qword"
            | "sqword"
            | "int"
            | "uint"
            | "int8"
            | "uint8"
            | "int16"
            | "uint16"
            | "int32"
            | "uint32"
            | "int64"
            | "uint64"
    )
}

fn integer_literal_fits_narrow_projection(target_ty: &SemaType, value_expr: &Expr) -> bool {
    let SemaType::Simple(target) = target_ty else {
        return false;
    };
    let Some(value) = sema_expr_integer_literal_value(value_expr) else {
        return false;
    };
    let Some((min, max)) = numeric_scalar_literal_range(target) else {
        return false;
    };
    value >= min && value <= max
}

fn implicit_narrowing_projection(target_ty: &SemaType, value_ty: &SemaType) -> bool {
    match (target_ty, value_ty) {
        (SemaType::Simple(target), SemaType::Simple(source)) => {
            match (
                numeric_scalar_width_bits(target),
                numeric_scalar_width_bits(source),
            ) {
                (Some(target_bits), Some(source_bits)) => source_bits > target_bits,
                _ => false,
            }
        }
        (target, SemaType::Union(items)) => items
            .iter()
            .any(|item| implicit_narrowing_projection(target, item)),
        _ => false,
    }
}

fn projection_source_has_unresolved_union(target_ty: &SemaType, value_ty: &SemaType) -> bool {
    let SemaType::Union(items) = value_ty else {
        return false;
    };

    items.iter().any(|item| !type_compatible(item, target_ty))
}

fn projection_type_error_message(target_ty: &SemaType, value_ty: &SemaType) -> String {
    if projection_source_has_unresolved_union(target_ty, value_ty) {
        return "projection source has unresolved union type".into();
    }

    if implicit_narrowing_projection(target_ty, value_ty) {
        return "implicit narrowing projection is not allowed".into();
    }

    format!(
        "projection type mismatch: cannot assign {:?} to {:?}",
        value_ty, target_ty
    )
}

fn render_primitive_bridge_target(target: &PrimitiveBridgeTarget) -> String {
    match target {
        PrimitiveBridgeTarget::RootPath(path) | PrimitiveBridgeTarget::MachinePath(path) => {
            path.join(".")
        }
    }
}

