    #[test]
    fn primitive_directive_kind_matrix_is_officially_mapped() {
        let words = [
            "id",
            "module",
            "type",
            "version",
            "clock",
            "edge",
            "cycle",
            "domain",
            "latency",
            "timeout",
            "voltage",
            "current",
            "noise",
            "metastability",
            "power",
            "powerGate",
            "temperature",
            "thermalState",
            "throttleState",
            "watchdog",
            "pin",
            "port",
            "wire",
            "register",
            "width",
            "interruptLine",
            "addr",
            "map",
            "read",
            "write",
            "volatile",
            "dmaChannel",
            "cacheState",
            "tlbState",
            "firmwareRegion",
            "bootRomRegion",
            "route",
            "valid",
            "ready",
            "ack",
            "trigger",
            "guard",
            "irq",
            "fault",
            "error",
            "retry",
            "fallback",
            "atomic",
            "barrier",
            "commit",
            "reset",
            "trace",
            "ptr",
            "load",
            "store",
            "mmio",
            "trap",
            "fence",
            "comb",
            "seq",
            "assign",
            "always",
            "transition",
            "drive",
            "release",
            "mux",
            "decode",
            "encode",
            "pipeline",
            "pipelineState",
            "branchPredictorState",
            "reorderState",
            "outOfOrder",
            "hazard",
            "controller",
            "peripheral",
            "phy",
            "lane",
            "channel",
            "protocol",
            "physicalFault",
            "busFault",
            "signalLoss",
            "timingViolation",
            "thermalViolation",
            "metastabilityRisk",
            "dmaViolation",
            "cacheCoherenceViolation",
            "mmioSideEffectViolation",
        ];

        for word in words {
            let kind = primitive_directive_kind_from_word(word)
                .unwrap_or_else(|| panic!("expected directive word '{word}' to map"));
            assert_eq!(
                primitive_directive_kind_name(&kind),
                word,
                "expected directive name roundtrip for '{word}'"
            );

            let policy = primitive_directive_scalar_policy(&kind);
            assert!(
                policy.allow_symbol || policy.allow_number || policy.allow_text,
                "expected scalar policy for '{word}' to allow at least one scalar class"
            );
        }
    }

