    #[test]
    fn root_operator_surface_extended_passes_in_sema() {
        let src = r#"
rootOperatorSurface[@] {
    stc:
        x: int;
        y: int;
        b: bool;
        out: int;
        ok: bool;

    fn:
        public run() -> bool {
            public:
                @x >> int : 7;
                @y >> int : 3;
                @b >> bool : true;
                @out >> int : (~@x & @y) | (@x ^ @y);
                @ok >> bool : !@b || (@x % @y == 1);
                @out >> int : (@x + @y) << 1;
                @out >> int : @out >> 1;
                @out >> int : @out >>> 1;
                return @ok;
        }

    ref main ->> @fn(run);

    fa:
        return true;
}
"#;
        let tokens = ncc_lexer::lex(src).unwrap();
        let program = ncc_parser::parse(tokens).unwrap();
        let result = analyze(&program);
        assert!(
            result.is_ok(),
            "expected extended root operator surface to pass, got {:?}",
            result
        );
    }

    #[test]
    fn root_control_flow_surface_v1_0_1_passes_in_sema() {
        let src = r#"
rootControlFlowSema[@] {
    stc:
        items: list<int>;
        run: bool;
        i: int;
        out: int;

    fn:
        flow() -> bool {
            public:
                @run >> bool : true;
                @i >> int : 0;
                @out >> int : 0;

                while (@run) {
                    break;
                }

                do {
                    @i >> int : @i + 1;
                } while (@i < 2);

                for (@i >> int : 0; @i < 2; @i >> int : @i + 1) {
                    continue;
                }

                for item in @items {
                    @out >> int : @item;
                }

                for j in 0..2 {
                    @out >> int : @j;
                }

                for k in 0..=2 step 1 {
                    @out >> int : @k;
                }

                loop {
                    break;
                }

                repeat {
                    @i >> int : @i + 1;
                } until (@i > 3);

                same for (2) {
                    @out >> int : @out + 1;
                }

                same in v : @items {
                    @out >> int : @v;
                }

                each e in @items do {
                    print(@e);
                } while (@run);

                Notif (@run) {
                    @out >> int : 0;
                } else {
                    @out >> int : 1;
                }

                switch (@i) {
                    case 0 {
                        @out >> int : 0;
                    }
                    default {
                        @out >> int : 1;
                    }
                }

                match (@i) {
                    case 0 => {
                        @out >> int : 2;
                    }
                    default => {
                        @out >> int : 3;
                    }
                }

                guard (@run) else {
                    dev(irregular);
                }

                select {
                    when (@run) {
                        @out >> int : 4;
                    }
                    default {
                        @out >> int : 5;
                    }
                }

                @out >> int : if (@run) { 6 } else { 7 };
                return true;
        }

    ref main ->> @fn(flow);

    fa:
        return true;
}
"#;
        let tokens = ncc_lexer::lex(src).unwrap();
        let program = ncc_parser::parse(tokens).unwrap();
        let result = analyze(&program);
        assert!(
            result.is_ok(),
            "expected v1.0.1 control-flow surface to pass in sema, got {:?}",
            result
        );
    }

