    #[test]
    fn root_l2k_s7_memory_runtime_error_fixtures_report_official_diagnostics() {
        let cases = [
            (
                "l2k_s7a_arity_fail.n",
                "no matching function 'system.net.core.connect' for 1 arguments",
            ),
            (
                "l2k_s7b_runtime_alloc_typed_ok.n",
                "memory.heap.manager.free cannot use invalid pointer 'a'",
            ),
            (
                "l2k_s7b_runtime_send_type_fail.n",
                "no matching function 'system.net.core.send' for argument 0: expected str, got int",
            ),
            (
                "l2k_s7c_runtime_free_dead_block_fail.n",
                "memory.heap.manager.free cannot use invalid pointer 'a'",
            ),
            (
                "l2k_s7c_runtime_realloc_dead_block_fail.n",
                "memory.heap.manager.realloc cannot use invalid pointer 'a'",
            ),
            (
                "l2k_s7e_runtime_free_stale_block_fail.n",
                "memory.heap.manager.free cannot use invalid pointer 'a'",
            ),
            (
                "l2k_s7e_runtime_realloc_old_symbol_fail.n",
                "memory.heap.manager.zero cannot use invalid pointer 'a'",
            ),
            (
                "l2k_s7e_runtime_use_after_free_fail.n",
                "memory.heap.manager.zero cannot use invalid pointer 'a'",
            ),
            (
                "l2k_s7e_runtime_zero_freed_block_fail.n",
                "memory.heap.manager.zero cannot use invalid pointer 'a'",
            ),
            (
                "l2k_s7e_runtime_zero_stale_block_fail.n",
                "memory.heap.manager.zero cannot use invalid pointer 'a'",
            ),
            (
                "l2k_s7f_runtime_heap_alias_zero_via_alias_fail.n",
                "memory.heap.manager.zero cannot use invalid pointer 'b'",
            ),
            (
                "l2k_s7g_runtime_zero_old_alias_after_realloc_fail.n",
                "memory.heap.manager.zero cannot use invalid pointer 'b'",
            ),
        ];

        for (fixture, expected) in cases {
            let program = checked_memory_program(load_program(examples_fixture_path(fixture)));
            let result = analyze_with_explicit_pointer_checks(&program);
            assert!(
                result.is_err(),
                "expected l2k_s7 fixture '{}' to fail sema, got {:?}",
                fixture,
                result
            );
            let msg = result.unwrap_err();
            assert!(
                msg.contains(expected),
                "fixture '{}' expected diagnostic containing {:?}, got {:?}",
                fixture,
                expected,
                msg
            );
        }
    }

