    #[test]
    fn kernel_operational_imports_and_qualified_calls_pass_end_to_end_sema() {
        let src = r#"
use kernel.task.core;
use kernel.schedule.core;
use kernel.control.core;
use kernel.memory.core;
use kernel.interrupt.core;
use kernel.syscall.core;
use kernel.driver.core;
use kernel.user.core;
use kernel.boot.core;

kernelQualified[@] {
    stc:
        schedulerOpen >> bool : false;
        panicState >> bool : false;
        quarantineCount >> int : 0;
        lastTask >> str : "none";
        lastEvent >> str : "boot";

    fn:
        run() -> bool {
            public:
                base >> addr : 1048576;
                page >> addr : 2097152;
                handler >> addr : 4096;
                zero >> addr : 0;
                frameReady >> bool : kernel.memory.core.frameInit(base, 16384);
                frame >> addr : kernel.memory.core.frameAlloc(1);
                mapped >> bool : kernel.memory.core.pageMap(page, frame, 3);
                translated >> addr : kernel.memory.core.pageTranslate(page);
                taskReady >> bool : kernel.task.core.register(1, "idle");
                schedulerReady >> bool : kernel.schedule.core.open();
                scheduled >> bool : kernel.schedule.core.next();
                irqReady >> bool : kernel.interrupt.core.register(32, handler);
                syscallReady >> bool : kernel.syscall.core.register(1, handler);
                driverReady >> bool : kernel.driver.core.register(1, page, 8);
                copied >> bool : kernel.user.core.copyFromUser(frame, frame, 0);
                bootInfo >> addr : kernel.boot.core.info();
                return frameReady && frame != zero && mapped && translated == frame &&
                    taskReady && schedulerReady && scheduled && irqReady &&
                    syscallReady && driverReady && copied && bootInfo != zero &&
                    !kernel.control.core.panicState();
        }

    ref main ->> @fn(run);

    final:
        return true;
}
"#;
        let program = parse_src(src);
        let result = analyze(&program);
        assert!(
            result.is_ok(),
            "all operational kernel imports/calls must pass sema: {:?}",
            result.err()
        );
    }

