    #[test]
    fn memory_pointer_contracts_capture_transitive_consume_require() {
        let src = r#"
use memory.heap.manager;

entry[@] {
    fn:
        public consume_then_scrub(p: addr, q: addr) -> bool {
            public:
                memory.heap.manager.free(@p);
                memory.heap.manager.zero(@q, 64);
                return true;
        }

        public middle(x: addr, y: addr) -> bool {
            public:
                consume_then_scrub(@x, @y);
                return true;
        }

        public boot() -> bool {
            public:
                return middle(memory.heap.manager.alloc(64), memory.heap.manager.alloc(64));
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let program = parse_src(src);
        let contracts = collect_function_pointer_contracts(&program);
        let middle = contracts
            .iter()
            .find(|item| item.container == "entry" && item.function_name == "middle")
            .expect("middle contract");

        assert_eq!(middle.invalidated_params, vec![0]);
        assert_eq!(middle.require_valid_params, vec![0, 1]);
        assert_eq!(middle.invalidates_then_requires, vec![(0, 1)]);
    }

