    #[test]
    fn linking_unqualified_ambiguous_between_same_file_and_import_fails_in_sema() {
        let src = r#"
use system.net.core;

provider[@] {
    fn:
        public connect() -> bool {
            public:
                return true;
        }

    fa:
        return true;
}

entry[@] {
    ref main ->> @fn(connect);

    fa:
        return true;
}
"#;
        let tokens = ncc_lexer::lex(src).unwrap();
        let program = ncc_parser::parse(tokens).unwrap();
        let result = analyze(&program);
        assert!(result.is_err());
        let msg = result.unwrap_err();
        assert!(
            msg.contains("ambiguous reference 'connect'"),
            "unexpected error: {}",
            msg
        );
        assert!(
            msg.contains("reference '@connect' is ambiguous"),
            "unexpected error: {}",
            msg
        );
        assert!(
            msg.contains("same-file candidates [provider]"),
            "unexpected error: {}",
            msg
        );
        assert!(
            msg.contains("import candidates [system.net.core]"),
            "unexpected error: {}",
            msg
        );
    }

