    #[test]
    fn linking_unqualified_cross_official_context_matrix_fails_in_sema() {
        const CTXS: &[&str] = &["system", "runtime", "network", "tooling", "compiler", "ai"];

        for from_ctx in CTXS {
            for to_ctx in CTXS {
                if from_ctx == to_ctx {
                    continue;
                }

                let src = format!(
                    r#"
worker[@{to_ctx}] {{
    fn:
        public boot() -> bool {{
            public:
                return true;
        }}

    fa:
        return true;
}}

entry[@{from_ctx}] {{
    ref main ->> @fn(boot);

    fa:
        return true;
}}
"#
                );
                let tokens = ncc_lexer::lex(&src).unwrap();
                let program = ncc_parser::parse(tokens).unwrap();
                let result = analyze(&program);
                assert!(
                    result.is_err(),
                    "expected cross official contexts '{from_ctx}' -> '{to_ctx}' to fail"
                );
                let msg = result.unwrap_err();
                assert!(
                    msg.contains(&format!(
                        "invalid context linking 'entry[@{from_ctx}]' -> 'worker[@{to_ctx}]' for reference 'boot'"
                    )),
                    "unexpected error for '{from_ctx}' -> '{to_ctx}': {}",
                    msg
                );
            }
        }
    }

