    #[test]
    fn import_use_unknown_path_by_family_reports_official_diagnostic() {
        let invalid_paths = [
            "Root.memory.ghost",
            "Runtime.heap.ghost",
            "System.net.ghost",
            "Machine.ghost",
            "Security.ghost",
            "Inspect.ghost",
            "Compiler.parse.ghost",
            "Tooling.fmt.ghost",
            "nC.list.ghostFamily",
            "nC.math.ghost",
            "nC.vector.ghost",
            "nC.mem.ghost",
        ];

        for bad in invalid_paths {
            let src = format!(
                "use {};\n\nentry[@] {{\n    ref main ->> @fn(root.policy.bind);\n\n    fa:\n        return true;\n}}\n",
                bad
            );
            let tokens = ncc_lexer::lex(&src).unwrap();
            let program = ncc_parser::parse(tokens).unwrap();
            let result = analyze(&program);
            assert!(result.is_err(), "expected '{}' to fail in sema", bad);
            let msg = result.unwrap_err();
            assert!(
                msg.contains(&format!("unresolved import path '{}'", bad)),
                "expected official unresolved-import diagnostic for '{}', got: {}",
                bad,
                msg
            );
        }
    }

