    #[test]
    fn import_runtime_family_output_fails_in_primitive_context() {
        let src = r#"
use runtime.output;

primitive[@]:
    anchor boot0 at physaddr(0x0000_7C00)
        size bytes(512)
        align 16;

    window boot_sector:
        base physaddr(0x0000_7C00);
        size bytes(512);
        access rx;
        cache uncached;
        owner boot.loader;

    signature boot_magic:
        window boot_sector;
        offset 510;
        width 16;
        value 0x55AA;
        endian little;
        required true;

    entry boot_entry:
        anchor boot0;
        offset 0;
        mode real16;
        requires boot_magic;

    bridge:
        root.policy.bind;
        machine.machineCore;

    seal:
        primitiveClosed;
"#;
        let tokens = ncc_lexer::lex(src).unwrap();
        let program = ncc_parser::parse(tokens).unwrap();
        let result = analyze(&program);
        assert!(result.is_err());
        let msg = result.unwrap_err();
        assert!(
            msg.contains("E_PRIMITIVE_RUNTIME_001")
                && msg.contains("runtime is not available in primitive[@]"),
            "unexpected error: {}",
            msg
        );
    }

